class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }

  componentDidCatch(error, errorInfo) {
    console.error("ErrorBoundary caught an error", error, errorInfo);
    
    // Automatically reload on Vite dynamic import failure (new deployment pushed)
    if (error && error.message && error.message.includes('Failed to fetch dynamically imported module')) {
      if (!sessionStorage.getItem('billqyro_chunk_failed_reload')) {
        sessionStorage.setItem('billqyro_chunk_failed_reload', 'true');
        window.location.reload();
        return;
      }
    }
    
    sendEmpireError({
      errorType: "app_crash",
      message: error?.toString() || "Unknown error",
      severity: "Critical",
      page: window.location.pathname
    });

    this.setState({ errorInfo });
  }

  render() {
    if (this.state.hasError) {
      return (
        <div style={{ padding: '20px', backgroundColor: '#fee2e2', color: '#991b1b', minHeight: '100vh', fontFamily: 'system-ui' }}>
          <h1 style={{ fontSize: '24px', fontWeight: 'bold' }}>Something went wrong.</h1>
          <p style={{ marginTop: '10px', fontWeight: 'bold' }}>Error: {this.state.error?.toString()}</p>
          <pre style={{ marginTop: '20px', padding: '10px', backgroundColor: '#fecaca', overflowX: 'auto', fontSize: '12px' }}>
            {this.state.errorInfo?.componentStack}
          </pre>
          <button onClick={() => window.location.reload()} style={{ marginTop: '20px', padding: '10px 20px', backgroundColor: '#dc2626', color: 'white', borderRadius: '5px', cursor: 'pointer' }}>
            Reload Page
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}



const AdminRouteGuard = ({ setCurrentTab, children }) => {
  const session = authEngine.getAuthSession();
  const [isUnlocked, setIsUnlocked] = useState(
    localStorage.getItem('billqyro_admin_unlocked') === 'true'
  );

  useEffect(() => {
    // Only block access if the user is not an admin and hasn't unlocked the admin panel via PIN
    if (!adminEngine.isAdminUser(session) && !isUnlocked) {
      toast.error('Unauthorized access. Owner privileges required.');
      setCurrentTab('dashboard');
    }
  }, [session, setCurrentTab, isUnlocked]);

  // If not admin and not unlocked, show PIN login
  if (!adminEngine.isAdminUser(session) && !isUnlocked) {
    return (
      <AdminPINLogin
        onPinSuccess={() => setIsUnlocked(true)}
        onCancel={() => setCurrentTab('dashboard')}
      />
    );
  }

  return children;
};

function App() {

  // --- STATE SYSTEM (must be declared before any useEffect that references them) ---
  const [showWelcomeAnimation, setShowWelcomeAnimation] = useState(false);
  const [showConfetti, setShowConfetti] = useState(false);
  const [showCommandPalette, setShowCommandPalette] = useState(false);

  useEffect(() => {
    const handleConfetti = () => {
      setShowConfetti(true);
      setTimeout(() => setShowConfetti(false), 5000);
    };
    const handleCommandPalette = () => {
      setShowCommandPalette(true);
    };
    window.addEventListener('trigger-confetti', handleConfetti);
    window.addEventListener('open-command-palette', handleCommandPalette);
    return () => {
      window.removeEventListener('trigger-confetti', handleConfetti);
      window.removeEventListener('open-command-palette', handleCommandPalette);
    };
  }, []);

  const [isAuthenticated, setIsAuthenticated] = useState(() => {
    const realAuth = !!authEngine.getAuthSession();
    const demoAuth = localStorage.getItem('billqyro_demo_session_active') === 'true' && 
                     localStorage.getItem('billqyro_demo_journey_mode') === 'true' && 
                     localStorage.getItem('billqyro_demo_logged_in') === 'true';
    return realAuth || demoAuth;
  });
  const [syncStatus, setSyncStatus] = useState('Synced');
  const [isDemoSessionActive, setIsDemoSessionActive] = useState(false);
  const [isVideoCreatorMode, setIsVideoCreatorMode] = useState(false);
  const [globalMaintenanceMode, setGlobalMaintenanceMode] = useState(false);
  
  const [demoInvoices, setDemoInvoices] = useState([]);
  const [demoCustomers, setDemoCustomers] = useState([]);
  const [demoProducts, setDemoProducts] = useState([]);
  const [demoExpenses] = useState([]);
  const [demoSettings, setDemoSettings] = useState(null);

  useEffect(() => {
    const checkDemo = () => {
      const active = isDemoModeActive();
      setIsDemoSessionActive(active);
      const isVideo = localStorage.getItem('billqyro_demo_video_creator') === 'true';
      setIsVideoCreatorMode(isVideo);
      
      if (active) {
        autoGenerateDemoDataIfNeeded();
        setDemoInvoices(getDemoInvoices());
        setDemoCustomers(getDemoCustomers());
        setDemoProducts(getDemoProducts());
        
        // Reports / settings
        const s = JSON.parse(localStorage.getItem('billqyro_demo_settings') || 'null');
        setDemoSettings(s || {
           businessName: isVideo ? 'Demo Corp' : 'My Business (Demo)',
           ownerName: isVideo ? 'Demo Owner' : 'Me',
           email: isVideo ? 'hello@democorp.com' : 'demo@example.com',
           phone: isVideo ? '+1 555-0199' : '9999999999',
           themeColor: 'obsidian-gold'
        });
      }
    };
    checkDemo();
    window.addEventListener('storage', checkDemo);
    return () => window.removeEventListener('storage', checkDemo);
  }, []);

  const [currentTab, setCurrentTab] = useState(() => {
    if (window.location.pathname === '/km-admin') {
      return 'admin-panel';
    }
    const saved = localStorage.getItem('billqyro_last_route');
    const isAuth = !!authEngine.getAuthSession() || (localStorage.getItem('billqyro_demo_session_active') === 'true' && localStorage.getItem('billqyro_demo_journey_mode') === 'true' && localStorage.getItem('billqyro_demo_logged_in') === 'true');
    if (isAuth && saved && saved !== 'admin-panel') {
      return saved;
    }
    if (!isAuth) return 'landing';
    return null; // Neutral boot state - resolved centrally by the app gate
  });

  useEffect(() => {
    if (currentTab && currentTab !== 'landing') {
      localStorage.setItem('billqyro_last_route', currentTab);
    }
    
    // Sync URL for km-admin to act like a real route
    if (currentTab === 'admin-panel') {
      window.history.replaceState({}, '', '/km-admin');
    } else if (window.location.pathname === '/km-admin') {
      window.history.replaceState({}, '', '/');
    }

    sendEmpireEvent({
      eventType: "page_view",
      message: `Navigated to ${currentTab}`,
      page: currentTab
    });
  }, [currentTab]);

  const [userRole, setUserRole] = useState(() => localStorage.getItem('billqyro_user_role') || 'user');
  const [userPermissions, setUserPermissions] = useState(null);
  const [workspaceVerified, setWorkspaceVerified] = useState(false);

  // Capacitor Android Back Button Handler
  useEffect(() => {
    import('@capacitor/app').then(({ App: CapApp }) => {
      CapApp.removeAllListeners('backButton');
      CapApp.addListener('backButton', () => {
        setCurrentTab((prevTab) => {
          if (prevTab !== 'dashboard') {
            return 'dashboard';
          } else {
            CapApp.exitApp();
            return prevTab;
          }
        });
      });
    }).catch(() => { /* not in capacitor env */ });
  }, []);


  // Boot Interceptor for Public Invoice
  const [publicInvoice, setPublicInvoice] = useState(null);
  const [loadingPublicInvoice, setLoadingPublicInvoice] = useState(false);
  const [publicToken, setPublicToken] = useState(null);

  useEffect(() => {
    const path = window.location.pathname;
    const publicTokenMatch = path.match(/^\/invoice\/([a-zA-Z0-9_-]+)/);
    const urlParams = new URLSearchParams(window.location.search);
    const tokenFromQuery = urlParams.get('uuid') || urlParams.get('i');
    const token = (publicTokenMatch ? publicTokenMatch[1] : null) || tokenFromQuery;

    if (token) {
      setPublicToken(token);
      setLoadingPublicInvoice(true);
      import('./services/invoiceEngine').then(({ invoiceEngine }) => { invoiceEngine.getInvoiceByPublicToken(token).then((inv) => {
          setPublicInvoice(inv);
          setLoadingPublicInvoice(false);
        });
      });
    }
  }, []);

  // Boot Interceptor for Portals
  const [portalId, setPortalId] = useState(null);
  const [eduPortalId, setEduPortalId] = useState(null);

  useEffect(() => {
    const path = window.location.pathname;
    
    // Strict redirect for Business workspaces trying to access student paths
    if (path === '/student' || path === '/students' || path.startsWith('/student/')) {
       const id = path.split('/')[2];
       if (id) {
         window.history.replaceState({}, '', `/billing/${id}`);
       } else {
         window.history.replaceState({}, '', '/billing');
       }
    }
    
    const newPath = window.location.pathname;

    const studentMatchLegacy = newPath.match(/^\/student\/(.+)/);
    const customerMatch = newPath.match(/^\/customer\/(.+)/);
    const portalMatch = newPath.match(/^\/portal\/(.+)/);
    const billingMatch = newPath.match(/^\/billing\/(.+)/);
    const eduPortalMatch = newPath.match(/^\/student-portal\/(.+)/);
    
    if (eduPortalMatch) {
      setEduPortalId(decodeURIComponent(eduPortalMatch[1]));
    } else if (customerMatch) {
      setPortalId(decodeURIComponent(customerMatch[1]));
    } else if (portalMatch) {
      setPortalId(decodeURIComponent(portalMatch[1]));
    } else if (billingMatch) {
      setPortalId(decodeURIComponent(billingMatch[1]));
    } else if (studentMatchLegacy) {
      setPortalId(decodeURIComponent(studentMatchLegacy[1]));
    } else if (newPath === '/customer' || newPath === '/portal') {
      // Allow access without ID, CustomerWorkspace handles prompt
      setPortalId('verification-pending'); 
    }
  }, []);

  // Storage states
  const [invoices, setInvoices] = useState([]);
  const [customers, setCustomers] = useState([]);
  const [products, setProducts] = useState([]);
  // Settings with workspace support
  const [settings, setSettings] = useState(() => {
    const s = dbGetSettings() || {};
    if (!s.businessWorkspaces) {
      // Initialize default workspace
      const defaultWs = {
        id: 'ws_default_001',
        name: 'Default Workspace',
        type: 'default',
        enabledModules: ['billing', 'customers', 'products', 'dueLedger', 'reports'],
      };
      s.businessWorkspaces = [defaultWs];
      s.activeWorkspaceId = defaultWs.id;
    } else if (!s.activeWorkspaceId && s.businessWorkspaces.length) {
      s.activeWorkspaceId = s.businessWorkspaces[0].id;
    }
    // Do not call settingsEngine.saveSettings(s) here, as it may queue an offline sync
    // that overwrites the user's cloud settings before syncFromFirestore downloads them.
    // The defaults will live in memory until the user completes onboarding.
    return s;
  });

  // PHASE 2 AUTH STABILIZATION: Removed reactive boot-time redirect to prevent Dashboard flash


  const [expenses, setExpenses] = useState([]);
  const [students, setStudents] = useState([]);
  const [subscription, setSubscription] = useState(() => subscriptionEngine.getSubscriptionDetailsSync({}));
  const [revenueStatus, setRevenueStatus] = useState({
    totalBillsCreated: 0,
    freeBillsUsed: 0,
    billableBillsCount: 0,
    platformDueAmount: 0,
    platformPaidAmount: 0,
    platformPendingAmount: 0,
    lastPlatformPaymentDate: null,
    lockStatus: 'none',
    graceStatus: 'none',
    premiumStatus: 'free'
  });

  useEffect(() => {
    const fetchRevenue = async () => {
      const session = authEngine.getAuthSession();
      const userId = session?.uid || authEngine.getRealUserId() || 'local-user';
      try {
        const subDetails = await subscriptionEngine.getSubscriptionDetails();
        setSubscription(subDetails);
        const status = await paymentEngine.getUserRevenueState(userId, invoices, subDetails);
        setRevenueStatus(status);
      } catch (e) {
        console.error('Failed to load user revenue status:', e);
      }
    };
    fetchRevenue();
  }, [invoices, subscription, isAuthenticated]);
  // Workspace state
  const safeSettings = settings || {};
  const safeWorkspaces = safeSettings.businessWorkspaces || [];
  
  const [businessWorkspaces, setBusinessWorkspaces] = useState(safeWorkspaces);
  const [activeWorkspaceId, setActiveWorkspaceId] = useState(safeSettings.activeWorkspaceId || (safeWorkspaces.length > 0 ? safeWorkspaces[0].id : null));
  
  // Feature Control Engine Integration
  const { isFeatureEnabled, loading: featuresLoading } = useFeatureControl(activeWorkspaceId || settings?.activeWorkspaceId);

  // Keep workspaces in sync with cloud settings updates
  useEffect(() => {
    const currentSafeSettings = settings || {};
    const currentSafeWorkspaces = currentSafeSettings.businessWorkspaces || [];
    
    if (currentSafeSettings.businessWorkspaces && JSON.stringify(currentSafeWorkspaces) !== JSON.stringify(businessWorkspaces)) {
      setBusinessWorkspaces(currentSafeWorkspaces);
    }
    if (currentSafeSettings.activeWorkspaceId && currentSafeSettings.activeWorkspaceId !== activeWorkspaceId) {
      setActiveWorkspaceId(currentSafeSettings.activeWorkspaceId);
    }
  }, [settings, businessWorkspaces, activeWorkspaceId]);

  // Handle local workspace changes
  const updateWorkspaceState = (newWorkspaces, newActiveId) => {
    setBusinessWorkspaces(newWorkspaces);
    setActiveWorkspaceId(newActiveId);
    const updated = { ...(settings || {}), businessWorkspaces: newWorkspaces, activeWorkspaceId: newActiveId };
    setSettings(updated);
    settingsEngine.saveSettings(updated);
    window.dispatchEvent(new CustomEvent('billqyro_sync'));
  };

  const setActiveWorkspace = (id) => {
    updateWorkspaceState(businessWorkspaces, id);
  };

  // Real-time Pending Payments state
  const [pendingPayments, setPendingPayments] = useState([]);
  
  useEffect(() => {
    if (!isAuthenticated || !db || !auth) return;
    
    let unsubscribe = () => {};
    
    // Listen for auth state changes to get current user UID
    const authUnsubscribe = onAuthStateChanged(auth, (user) => {
      if (user) {
        const q = query(
          collection(db, 'payment_proofs'),
          where('ownerId', '==', user.uid),
          where('status', '==', 'pending')
        );
        
        unsubscribe = onSnapshot(q, (snapshot) => {
          const proofs = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
          setPendingPayments(proofs);
        });
      } else {
        setPendingPayments([]);
      }
    });
    
    return () => {
      authUnsubscribe();
      unsubscribe();
    };
  }, [isAuthenticated]);
  
  // --- 🚀 GLOBAL BOOT & LOADING STATE ---
  const [isAppBooting, setIsAppBooting] = useState(true);
  const [isDataHydrating, setIsDataHydrating] = useState(true);
  const [cloudSyncDone, setCloudSyncDone] = useState(false);

  // Safety timeout to ensure app never gets stuck on boot screen
  useEffect(() => {
    if (isAppBooting) {
      const timeout = setTimeout(() => {
        console.warn('[BOOT TIMEOUT] 3000ms reached, forcing app load.');
        setIsAppBooting(false);
      }, 3000);
      return () => clearTimeout(timeout);
    }
  }, [isAppBooting]);

  // Async Data Loader & Boot Sequence
  useEffect(() => {
    let isBooted = false;

    const loadLocalData = async () => {
      sendEmpireEvent({ eventType: "app_opened", message: "BillQyro Web App Opened", page: "init" });
      sendEmpireHealth({ status: "Healthy", healthScore: 100, note: "App initialized successfully" });
      
      try {
        setInvoices(await invoiceEngine.getInvoices() || []);
        setCustomers(await customerEngine.getCustomers() || []);
        setProducts(await productEngine.getProducts() || []);
        setStudents(await customerEngine.getCustomers() || []);
        setExpenses(await expenseEngine.getExpenses() || []);
      } catch (err) {
        console.error("Error loading local data:", err);
      } finally {
        setIsDataHydrating(false);
        isBooted = true;
        setIsAppBooting(false);
      }
    };
    loadLocalData();

    const handleSync = async () => {
      if (!isBooted) return;
      try {
        setInvoices(await invoiceEngine.getInvoices() || []);
        setCustomers(await customerEngine.getCustomers() || []);
        setProducts(await productEngine.getProducts() || []);
        setStudents(await customerEngine.getCustomers() || []);
        setExpenses(await expenseEngine.getExpenses() || []);
        const latestSettings = await settingsEngine.getSettings();
        if (latestSettings) {
          if (adminEngine.isAdminUser(authEngine.getAuthSession()) && latestSettings.maintenanceMode) {
            const cleaned = { ...latestSettings };
            delete cleaned.maintenanceMode;
            setSettings(cleaned);
            settingsEngine.saveSettings(cleaned);
          } else {
            setSettings(latestSettings);
          }
        }
        const updatedSub = await subscriptionEngine.getSubscriptionDetails();
        setSubscription(updatedSub);
      } catch (err) {
        console.error("Error reloading data on sync:", err);
      }
    };
    window.addEventListener('billqyro_sync', handleSync);
    
    // --- Pro Sync Engine Event Bus ---
    const handleSettingsUpdated = (e) => {
      if (e.detail) setSettings(e.detail);
    };
    const handleDataUpdated = async (e) => {
      const col = e.detail?.collectionName;
      if (col === 'invoices') setInvoices(await invoiceEngine.getInvoices() || []);
      if (col === 'customers') setCustomers(await customerEngine.getCustomers() || []);
      if (col === 'products') setProducts(await productEngine.getProducts() || []);
      if (col === 'students') setStudents(await customerEngine.getCustomers() || []);
      if (col === 'bankLedger' || col === 'bankCredit') {
        window.dispatchEvent(new CustomEvent('billqyro_bank_updated'));
      }
    };
    const handleSyncStatus = (e) => {
      if (e.detail) setSyncStatus(e.detail);
    };
    window.addEventListener('billqyro:settings-updated', handleSettingsUpdated);
    window.addEventListener('billqyro:data-updated', handleDataUpdated);
    window.addEventListener('billqyro:sync-status', handleSyncStatus);
    
    const handleNavigate = (e) => {
      if (e.detail) {
        setCurrentTab(e.detail);
      }
    };
    window.addEventListener('navigate_tab', handleNavigate);

    return () => {
      window.removeEventListener('billqyro_sync', handleSync);
      window.removeEventListener('billqyro:settings-updated', handleSettingsUpdated);
      window.removeEventListener('billqyro:data-updated', handleDataUpdated);
      window.removeEventListener('billqyro:sync-status', handleSyncStatus);
      window.removeEventListener('navigate_tab', handleNavigate);
    };
  }, []);

  // Workspace Contexts
  const [editingInvoice, setEditingInvoice] = useState(null);
  const [showPaywallModal, setShowPaywallModal] = useState(false);

  // PWA Installer States
  const [installPromptEvent, setInstallPromptEvent] = useState(null);
  const [isAppInstalled, setIsAppInstalled] = useState(false);
  const [isQuickBillOpen, setIsQuickBillOpen] = useState(false);

  // Initialize Smart SVG Dynamic Theme Engine
  useThemeEngine(settings);

  useEffect(() => {
    const handleBeforeInstallPrompt = (e) => {
      e.preventDefault();
      setInstallPromptEvent(e);
      // PWA install prompt stashed
    };

    const handleAppInstalled = () => {
      setInstallPromptEvent(null);
      setIsAppInstalled(true);
      toast.success('🎉 BillQyro App installed successfully!');
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    window.addEventListener('appinstalled', handleAppInstalled);

    if (window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true) {
      setIsAppInstalled(true);
    }

    return () => {
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
      window.removeEventListener('appinstalled', handleAppInstalled);
    };
  }, []);

  const handleInstallApp = async () => {
    if (!installPromptEvent) return;
    installPromptEvent.prompt();
    const { outcome } = await installPromptEvent.userChoice;
    // User install choice handled
    setInstallPromptEvent(null);
  };

  // --- EFFECTS ---

  // Initialize Database on App mount
  useEffect(() => {
    initializeStorage();
  }, []);

  // Listen to Firebase Auth state
  useEffect(() => {
    if (firebaseReady && auth) {
      const unsubscribe = onAuthStateChanged(auth, async (user) => {
        // Firebase auth state updated
        if (user) {
          const session = authEngine.getAuthSession();
          const newSession = {
            timestamp: Date.now(),
            token: 'billqyro-secure-session',
            userEmail: user.email || '',
            uid: user.uid
          };
          localStorage.setItem('billqyro_auth', JSON.stringify(newSession));
          setIsAuthenticated(true);
          const role = localStorage.getItem('billqyro_user_role') || 'user';
          setUserRole(role);

          // AUTH → WORKSPACE VERIFICATION → PERMISSION CHECK → DASHBOARD
          try {
            const currentWs = await workspaceEngine.getCurrent();
            const verified = await workspaceEngine.verifyAccess(user.uid, currentWs.id);
            setWorkspaceVerified(verified.authorized);
            if (!verified.authorized) {
              console.warn('[AuthFlow] Workspace verification failed:', verified.reason);
            }
            const permissions = await securityEngine.getPermissions(user.uid);
            setUserPermissions(permissions);
            localStorage.setItem('billqyro_user_permissions', JSON.stringify(permissions));
          } catch (e) {
            console.warn('[AuthFlow] Workspace/perm check failed:', e);
            setWorkspaceVerified(true);
            setUserPermissions(null);
          }
        } else {
          setIsAuthenticated(false);
          setWorkspaceVerified(false);
          setUserPermissions(null);
          setIsAppBooting(false);
          setIsDataHydrating(false);
        }
      });
      return () => unsubscribe();
    } else {
      setIsAppBooting(false);
      setIsDataHydrating(false);
    }
  }, []);

  // Sync from Firebase Firestore when authenticated
  useEffect(() => {
    if (isAuthenticated) {
      const currentUserId = authEngine.getAuthSession()?.uid;
      const runSync = async () => {
        try {
          const synced = await invoiceEngine.syncFromCloud();
          
          // Additive: pull + merge Internal Bank data (fire-and-forget, failure-isolated).
          import('./services/bankEngine').then(({ bankEngine }) => bankEngine.syncFromCloud(true)).catch((e) => {
            console.warn('[BANK SYNC] Startup pull skipped:', e);
          });
          
          if (currentUserId !== authEngine.getAuthSession()?.uid) {
            console.warn('[Session Guard] Stale sync aborted due to session change');
            return;
          }
          
          if (synced) {
            if (synced.invoices) setInvoices(synced.invoices);
            if (synced.customers) setCustomers(synced.customers);
            if (synced.products) setProducts(synced.products);
            if (synced.settings) setSettings(synced.settings);
            if (synced.expenses) setExpenses(synced.expenses);
            if (synced.subscription) setSubscription(synced.subscription);
          }
          
          // Fetch global admin settings for defaults
          try {
            const adminGlobal = await adminEngine.getGlobalAdminSettings();
            if (adminGlobal) {
              if (adminGlobal.defaultTheme) {
                localStorage.setItem('billqyro_admin_default_theme', adminGlobal.defaultTheme);
                if (!synced?.settings?.themeColor && !synced?.settings?.brandColor) {
                  // Handled by ThemeContext
                  import('./utils/themeIcon').then(m => m.updateFaviconForTheme(adminGlobal.defaultTheme));
                }
              }
              if (adminGlobal.defaultMode) {
                localStorage.setItem('billqyro_admin_default_mode', adminGlobal.defaultMode);
                if (!synced?.settings?.displayMode) {
                  // Handled by ThemeContext
                }
              }
            }
          } catch { console.warn('Could not fetch admin settings on boot.'); }

          try {
            const ann = await adminEngine.getActiveAnnouncement();
            if (ann && ann.type === 'maintenance') {
              setGlobalMaintenanceMode(true);
            } else {
              setGlobalMaintenanceMode(false);
            }
          } catch { console.warn('Could not fetch active announcement on boot.'); }

          // Enable real-time multi-device sync via new Sync Engine
          import('./services/syncEngine').then(({ startRealTimeSync }) => {
            const userId = auth.currentUser?.uid;
            if (userId) {
              startRealTimeSync(userId, (newSettings) => {
                setSettings(newSettings);
              });
            }
          });
        } catch {
          sendEmpireError({ errorType: "sync_failed", message: "Could not sync Firestore on startup", severity: "Medium" });
          console.warn('Could not sync Firestore on startup. Falling back to LocalStorage.', e);
        } finally {
          setIsAppBooting(false); // ALWAYS EXIT BOOT
          setCloudSyncDone(true);
        }
      };
      runSync();
    }
  }, [isAuthenticated]);



  // --- AUTH BRIDGE ---
  const handleLoginSuccess = () => {
    if (!sessionStorage.getItem('billqyro_welcome_shown')) {
      setShowWelcomeAnimation(true);
      sessionStorage.setItem('billqyro_welcome_shown', 'true');
    }
    // Yield route control to the Central App Gate
    setCurrentTab(null);
  };

  // Handle Legacy User Silent Upgrade (No redirects)
  useEffect(() => {
    if (isAuthenticated && !isAppBooting && settings && cloudSyncDone) {
      const isLegacyConfigured = !!(settings.businessName && settings.businessName.trim());
      if (!settings.setupCompleted && isLegacyConfigured) {
        const updated = { ...settings, setupCompleted: true };
        settingsEngine.saveSettings(updated);
        setSettings(updated);
      }
    }
  }, [isAuthenticated, isAppBooting, settings, cloudSyncDone]);

  const handleLogout = async () => {
    try {
      if (firebaseReady && auth) {
        await auth.signOut();
      }
    } catch (err) {
      console.error('Firebase sign out error', err);
    }
    await authEngine.logout();
    localStorage.removeItem('billqyro_user_role');
    localStorage.removeItem('billqyro_admin_unlocked');
    
    // STRICT MEMORY WIPE
    setSettings({});
    setBusinessWorkspaces([]);
    setActiveWorkspaceId(null);
    setInvoices([]);
    setCustomers([]);
    setProducts([]);
    setExpenses([]);
    setPendingPayments([]);
    setStudents([]);
    subscriptionEngine.getSubscriptionDetails().then(setSubscription);
    
    // RESET GLOBAL DOM THEME
    window.dispatchEvent(new CustomEvent('billqyro:settings-updated', { detail: {} }));
    
    setUserRole('user');
    setIsAuthenticated(false);
    setCurrentTab('landing');
