  // --- DATA SYNCHRONIZERS ---

  // Invoices
  const handleSaveInvoice = async (payload, saveCustomerAsNew = false, isSilent = false) => {
    if (isDemoSessionActive) {
      if (!payload.id) {
        payload.id = 'demo-inv-' + Date.now();
        if (!payload.invoiceNumber) payload.invoiceNumber = 'DEMO-INV-' + (1000 + demoInvoices.length);
      }
      saveDemoInvoice(payload);
      if (!isSilent) {
        toast.success('Saved to Demo Session');
        setEditingInvoice(null);
        setCurrentTab('dashboard'); // Redirect to dashboard to see real-time updates!
      }
      return;
    }

    // Flatten nested InvoiceContext state if present
    if (payload.customer && typeof payload.customer === 'object') {
      payload.customerId = payload.customer.id || payload.customerId;
      payload.customerName = payload.customer.name || payload.customerName;
      payload.customerPhone = payload.customer.phone || payload.customerPhone;
      payload.customerEmail = payload.customer.email || payload.customerEmail;
      payload.customerAddress = payload.customer.address || payload.customerAddress;
      delete payload.customer;
    }

    // CRITICAL FIX: Merge payload with existing invoice to preserve fields like createdAt, publicToken, paymentHistory that sparse payloads drop
    if (payload.id) {
      const existing = invoices.find(inv => inv.id === payload.id);
      if (existing) {
        payload = { ...existing, ...payload };
      }
    }
    if (payload.totals && typeof payload.totals === 'object') {
      payload.subtotal = payload.totals.subtotal || payload.subtotal || 0;
      payload.taxPercentage = payload.totals.taxPercentage ?? payload.taxPercentage ?? 18;
      payload.taxAmount = payload.totals.taxAmount || payload.taxAmount || 0;
      payload.discountAmount = payload.totals.discountAmount || payload.discountAmount || 0;
      payload.grandTotal = payload.totals.grandTotal || payload.grandTotal || 0;
      payload.amountPaid = payload.totals.amountPaid || payload.amountPaid || 0;
      payload.balanceDue = payload.totals.balanceDue || payload.balanceDue || 0;
      delete payload.totals;
    }
    if (payload.settings && typeof payload.settings === 'object') {
      payload.notes = payload.settings.notes || payload.notes || '';
      payload.terms = payload.settings.terms || payload.terms || '';
      payload.paymentStatus = payload.settings.paymentStatus || payload.paymentStatus || 'Unpaid';
      payload.orderStatus = payload.settings.orderStatus || payload.orderStatus || 'Pending';
      payload.paymentMethod = payload.settings.paymentMethod || payload.paymentMethod || 'Cash';
      payload.paymentNote = payload.settings.paymentNote || payload.paymentNote || '';
      if (payload.settings.auditHistory) {
        payload.auditHistory = payload.settings.auditHistory;
      }
      delete payload.settings;
    }

    // Advanced Payload Validation
    const validationResult = validatePayload(invoiceSchema, payload);
    if (!validationResult.success && !isDemoSessionActive) {
      toast.error('Validation Error: Invalid invoice data.');
      console.error('Invoice Validation Failed:', validationResult.errors);
      return;
    }
    if (validationResult.success) {
      payload = validationResult.data;
    }

    // Final Integrity Check
    if (payload.items && payload.items.length > 0) {
      const hasValidItems = payload.items.some(i => (parseFloat(i.qty) || 0) > 0 && (parseFloat(i.rate) || 0) > 0);
      if (hasValidItems && (!payload.grandTotal || payload.grandTotal === 0)) {
        console.warn('⚠️ CRITICAL: Attempted to save invoice with ₹0 grand total but valid items exist. Forcing recalculation to prevent data corruption.');
        const recalculated = calculateTotals(payload.items, payload.taxPercentage || 0, payload.discountAmount || 0);
        payload.subtotal = recalculated.subtotal;
        payload.taxAmount = recalculated.taxAmount;
        payload.grandTotal = recalculated.grandTotal;
        payload.balanceDue = Math.max(0, recalculated.grandTotal - (payload.amountPaid || 0));
      }
    }

    const isNew = !payload.id || !invoices.some(inv => inv.id === payload.id);
    if (isNew && revenueStatus.lockStatus === 'locked') {
      toast.error('New invoice creation is locked. Please clear your platform dues.');
      return;
    }
    const freeLimit = settings?.freeInvoiceLimit !== undefined ? settings.freeInvoiceLimit : 15;
    const isPPBActive = revenueStatus.lockStatus !== 'none' || revenueStatus.platformDueAmount > 0;
    if (isNew && subscription.status !== 'premium' && invoices.length >= freeLimit && !isSilent && !isPPBActive) {
      setShowPaywallModal(true);
      return;
    }
    let unlinkedItems = false;
    let lowStockWarning = false;

    let productsUpdated = false;
    const currentProducts = [...products];
    const updatedProductIds = new Set();

    // 1. If editing an existing invoice, reverse previous stock deduction
    const oldInvoice = payload.id ? invoices.find(inv => inv.id === payload.id) : null;
    if (oldInvoice && oldInvoice.items) {
      for (const oldItem of oldInvoice.items) {
        const itemName = (oldItem.description || oldItem.productName || oldItem.serviceName || oldItem.itemService || '').trim().toLowerCase();
        if (!itemName) continue;

        const matchedProduct = currentProducts.find(p => p.name.trim().toLowerCase() === itemName);
        if (matchedProduct && matchedProduct.stockQty !== undefined) {
          const oldQty = parseFloat(oldItem.qty) || 1;
          matchedProduct.stockQty += oldQty;
          updatedProductIds.add(matchedProduct.id);
          productsUpdated = true;
        }
      }
    }

    // 2. Apply new stock deduction
    for (const item of payload.items) {
      const itemName = (item.description || item.productName || item.serviceName || item.itemService || '').trim().toLowerCase();
      if (!itemName) continue;

      const matchedProduct = currentProducts.find(p => p.name.trim().toLowerCase() === itemName);
      
      if (matchedProduct) {
        const requestedQty = parseFloat(item.qty) || 1;
        const currentStock = matchedProduct.stockQty !== undefined ? matchedProduct.stockQty : 0;
        if (currentStock < requestedQty) {
          lowStockWarning = true;
          matchedProduct.stockQty = 0; // Prevent going below 0 without confirmation
        } else {
          matchedProduct.stockQty = currentStock - requestedQty;
        }
        updatedProductIds.add(matchedProduct.id);
        productsUpdated = true;
      } else {
        unlinkedItems = true;
      }
    }

    if (productsUpdated) {
      const savePromises = [];
      for (const p of currentProducts) {
        if (updatedProductIds.has(p.id)) {
          savePromises.push(productEngine.saveProduct(p));
        }
      }
      Promise.all(savePromises).catch(e => console.error("Error saving products:", e));
      setProducts(currentProducts);
    }

    // --- Customer Linking Logic ---
    if (saveCustomerAsNew && payload.customerName && !isSilent) {
      // Check if customer already exists
      const existingCustomer = customers.find(c => 
        c.name.toLowerCase() === payload.customerName.toLowerCase() || 
        (payload.customerPhone && c.phone === payload.customerPhone)
      );
      
      if (existingCustomer) {
        payload.customerId = existingCustomer.id;
      } else {
        const newCustomer = {
          id: 'cust-' + Date.now(),
          name: payload.customerName,
          phone: payload.customerPhone || '',
          email: payload.customerEmail || '',
          address: payload.customerAddress || '',
        };
        handleSaveCustomer(newCustomer, true);
        payload.customerId = newCustomer.id;
      }
    } else if (!payload.customerId && payload.customerPhone) {
      // Fallback for missing customer ID if phone is provided
      const existingCustomer = customers.find(c => c.phone === payload.customerPhone || c.name === payload.customerName);
      if (existingCustomer) {
        payload.customerId = existingCustomer.id;
      }
    }

    // Fire and forget saveInvoice for Layer 2 persistence
    invoiceEngine.saveInvoice(payload).then(({ updatedInvoices, firebaseStatus }) => {
      setInvoices(updatedInvoices);

      if (!isSilent) {
        if (firebaseStatus === 'failed') {
          toast.success('Invoice created successfully. (Saved locally. Firebase sync pending.)');
        } else {
          toast.success('Invoice created successfully');
        }
        
        sendEmpireEvent({
          eventType: "invoice_created",
          message: "Invoice created in BillQyro",
          page: "create-invoice",
          metadata: { feature: "invoice", action: "created", privateDataIncluded: false }
        });

        // Trigger haptic & audio feedback
        if (payload.paymentStatus === 'Paid' && (!oldInvoice || oldInvoice.paymentStatus !== 'Paid')) {
          triggerPaymentSuccessFeedback();
          triggerVoiceFeedback("Payment received successfully!");
          window.dispatchEvent(new Event('trigger-confetti'));
        } else {
          triggerPopFeedback();
        }

        if (unlinkedItems) {
          toast.custom(
            (t) => (
              <div className={`${t.visible ? 'animate-enter' : 'animate-leave'} max-w-md w-full bg-theme-warning/5 dark:bg-amber-950/40 shadow-lg rounded-xl pointer-events-auto flex ring-1 ring-amber-500/30`}>
                <div className="flex-1 w-0 p-4">
                  <div className="flex items-start">
                    <div className="flex-shrink-0 pt-0.5">
                      <span className="text-xl">⚠️</span>
                    </div>
                    <div className="ml-3 flex-1">
                      <p className="text-sm font-semibold text-amber-800 dark:text-amber-300">
                        Some bill items are not linked to products, so inventory stock was not updated.
                      </p>
                    </div>
                  </div>
                </div>
                <div className="flex border-l border-amber-500/20">
                  <button
                    onClick={() => {
                      toast.dismiss(t.id);
                      setCurrentTab('products');
                    }}
                    className="w-full border border-transparent rounded-none rounded-r-xl p-4 flex items-center justify-center text-xs font-bold text-amber-700 dark:text-amber-400 hover:bg-theme-warning/10 focus:outline-none transition-colors"
                  >
                    Link Products
                  </button>
                </div>
              </div>
            ),
            { duration: 6000 }
          );
        } else if (productsUpdated) {
          toast.success('Inventory stock updated successfully.', { duration: 4000 });
        }

        if (lowStockWarning) {
          toast.error('Low stock or insufficient stock for some products.', { duration: 4000 });
        }

        setEditingInvoice(null);
        setCurrentTab('invoices');
      }
    }).catch(e => console.error("Error saving invoice locally:", e));

    return payload;
  };

  const handleDeleteInvoice = async (id, permanent = false, skipConfirmation = false) => {
    if (isDemoSessionActive) {
      deleteDemoInvoice(id);
      toast.success('Deleted from Demo Session');
      return;
    }

    const executeDelete = async () => {
      triggerDeleteFeedback();
      const { updatedInvoices, firebaseStatus } = await invoiceEngine.deleteInvoice(id, permanent);
      setInvoices(updatedInvoices);
      if (firebaseStatus === 'failed') {
        toast.success(permanent ? 'Invoice permanently deleted locally. Will sync when online.' : 'Invoice moved to trash locally.');
      } else {
        toast.success(permanent ? 'Invoice permanently deleted!' : 'Invoice moved to trash.');
      }
    };

    if (permanent || skipConfirmation) {
      await executeDelete();
    } else {
      toast.custom(
        (t) => (
          <div className={`${t.visible ? 'animate-enter' : 'animate-leave'} max-w-sm w-full bg-theme-surface/90 backdrop-blur-xl shadow-[0_0_50px_rgba(244,63,94,0.15)] rounded-2xl pointer-events-auto border border-rose-500/20 overflow-hidden`}>
            <div className="p-6 flex flex-col items-center text-center">
              <div className="w-14 h-14 rounded-full bg-gradient-to-br from-rose-500/20 to-rose-500/5 text-rose-500 flex items-center justify-center mb-4 shadow-[0_0_15px_rgba(244,63,94,0.2)]">
                <Trash2 className="w-7 h-7" />
              </div>
              <h3 className="text-xl font-black text-theme-primary mb-2">Move to Trash?</h3>
              <p className="text-sm text-theme-muted font-bold mb-6">
                Are you sure you want to move this invoice to the trash? You can restore it later if needed.
              </p>
              <div className="flex w-full gap-3">
                <button
                  onClick={() => toast.dismiss(t.id)}
                  className="flex-1 bg-theme-app border border-theme-border-soft text-theme-primary font-bold py-3 rounded-xl transition-all hover:bg-theme-border-soft hover:shadow-md"
                >
                  Cancel
                </button>
                <button
                  onClick={async () => {
                    toast.dismiss(t.id);
                    await executeDelete();
                  }}
                  className="flex-1 bg-gradient-to-r from-rose-500 to-rose-600 text-white font-black py-3 rounded-xl transition-all hover:from-rose-600 hover:to-rose-700 shadow-lg shadow-rose-500/25"
                >
                  Yes, Delete
                </button>
              </div>
            </div>
          </div>
        ),
        { duration: 4000 }
      );
    }
  };

  // Customers
  const handleSaveCustomer = async (payload) => {
