          page: "invoice"
        });
        toast.error(`Image Error: ${err?.toString() || "Unknown error generating image"}`);
      });
  };

  // HARD DEMO MODE ISOLATION SWITCH
  const activeInvoices = isDemoSessionActive ? demoInvoices : invoices;
  const activeCustomers = isDemoSessionActive ? demoCustomers : customers;
  const activeProducts = isDemoSessionActive ? demoProducts : products;
  const activeExpenses = isDemoSessionActive ? demoExpenses : expenses;
  
  let activeSettings = (isDemoSessionActive && demoSettings) ? demoSettings : settings;
  if (isDemoSessionActive && isVideoCreatorMode && activeSettings) {
    activeSettings = {
      ...activeSettings,
      businessName: activeSettings.businessName || 'Demo Corp',
      ownerName: 'Demo Owner',
      email: 'hello@democorp.local',
      phone: '+1 555-0199',
      logoUrl: '',
      whatsapp: '+1 555-0199'
    };
  }

  // --- TAB ROUTER SWITCHBOARD ---
  const TAB_TO_FEATURE_MAP = {
    'invoices': 'invoice', 'create-invoice': 'invoice', 'estimates': 'invoice',
    'customers': 'customer', 'patients': 'customer', 'students': 'customer', 'clients': 'customer',
    'due-ledger': 'treasury', 'pending-payments': 'payment', 'reports': 'reports',
    'expenses': 'treasury.moneyOut', 'products': 'product', 'orders': 'product', 'bank': 'bank',
    'appointments': 'customer', 'delivery': 'product', 'measurements': 'product',
    'designBook': 'product', 'devices': 'product', 'serviceJobs': 'product', 'projects': 'product'
  };

  const renderTabContent = (targetTab = currentTab) => {
    const isMaintenanceMode = (globalMaintenanceMode || activeSettings?.maintenanceMode) && !adminEngine.isAdminUser(authEngine.getAuthSession());

    // Feature gating fallback
    if (!featuresLoading) {
      const requiredFeature = TAB_TO_FEATURE_MAP[targetTab];
      if (requiredFeature && !isFeatureEnabled(requiredFeature)) {
        return (
          <div className="flex flex-col items-center justify-center h-full text-center p-10 bg-theme-main">
            <Lock className="w-16 h-16 text-theme-muted mb-4" />
            <h2 className="text-2xl font-black text-white mb-2">Feature Disabled</h2>
            <p className="text-theme-muted max-w-md mb-6">
              The '{targetTab}' module is currently disabled for this workspace. You can enable it from the Settings Studio.
            </p>
            <button onClick={() => setCurrentTab('dashboard')} className="px-6 py-2.5 bg-theme-accent text-white font-bold rounded-xl hover:bg-theme-accent/80 transition-colors">
              Return to Dashboard
            </button>
          </div>
        );
      }
    }

    switch (targetTab) {
      case 'landing':
        if (isAuthenticated) {
          setTimeout(() => setCurrentTab('dashboard'), 0);
          return <div className="flex flex-col items-center justify-center h-full text-center p-10"><ClassicLoader /></div>;
        }
        return <Landing onLoginSuccess={handleLoginSuccess} />;
      case 'cyber-dashboard':
        return <CyberDashboard setCurrentTab={setCurrentTab} />;
      case 'portal-hub':
        return <PortalHub />;
      case 'quick-tools':
        return <QuickToolsCenter />;
      case 'customer-register':
        return <CustomerRegister />;
      case 'cash-management':
        return <CashManagement />;
      case 'dashboard':
        return (
          <Dashboard
            invoices={activeInvoices}
            customers={activeCustomers}
            products={activeProducts}
            expenses={activeExpenses}
            onViewInvoice={(inv) => {
              setEditingInvoice(inv);
              setCurrentTab('invoices');
            }}
            onEditInvoice={(inv) => {
              setEditingInvoice(inv);
              setCurrentTab('create-invoice');
            }}
            onDeleteInvoice={handleDeleteInvoice}
            onDownloadPDF={handleDownloadPDF}
            setCurrentTab={setCurrentTab}
            businessSettings={activeSettings}
            installPromptEvent={installPromptEvent}
            isAppInstalled={isAppInstalled}
            onInstallApp={handleInstallApp}
            subscription={subscription}
            onQuickBillOpen={() => setIsQuickBillOpen(true)}
            pendingPaymentsCount={pendingPayments.length}
            isLoading={isDataHydrating}
            revenueStatus={revenueStatus}
            onSaveCustomer={handleSaveCustomer}
            permissions={userPermissions}
            workspaceVerified={workspaceVerified}
          />
        );
      case 'pending-payments':
        return (
          <PendingPayments 
            setCurrentTab={setCurrentTab}
            pendingPayments={pendingPayments}
          />
        );
      case 'help-center':
        return (
          <HelpCenter />
        );
      case 'customer-portal-config':
        return <CustomerPortalConfig />;
      case 'system-health':
        return <SystemHealth setCurrentTab={setCurrentTab} />;
      case 'sandbox-admin':
        return <SandboxAdmin setCurrentTab={setCurrentTab} />;
      case 'audit-logs':
        return (
          <AuditLogs setCurrentTab={setCurrentTab} />
        );
      case 'due':
      case 'due-ledger':
        return (
          <DueLedger 
            customers={activeCustomers} 
            invoices={activeInvoices} 
            businessSettings={activeSettings}
          />
        );
      case 'bank':
        return (
          <InternalBank
            customers={activeCustomers}
            invoices={activeInvoices}
            businessSettings={activeSettings}
          />
        );
      case 'reports':
        return (
          <Reports 
            invoices={activeInvoices} 
            customers={activeCustomers} 
            businessSettings={activeSettings}
          />
        );
      case 'invoices':
        return (
          <Invoices
            invoices={activeInvoices}
            editingInvoice={editingInvoice}
            onEditInvoice={setEditingInvoice}
            onDeleteInvoice={handleDeleteInvoice}
            onDownloadPDF={handleDownloadPDF}
            onDownloadImage={handleDownloadImage}
            setCurrentTab={setCurrentTab}
            businessSettings={activeSettings}
          />
        );
      case 'estimates':
        return (
          <Estimates
            invoices={activeInvoices}
            editingInvoice={editingInvoice}
            onEditInvoice={setEditingInvoice}
            onDeleteInvoice={handleDeleteInvoice}
            onDownloadPDF={handleDownloadPDF}
            onDownloadImage={handleDownloadImage}
            setCurrentTab={setCurrentTab}
            businessSettings={activeSettings}
            onSaveInvoice={handleSaveInvoice}
          />
        );
      case 'create-invoice':
        if ((isMaintenanceMode || (activeSettings?.disableNewBillCreation && !adminEngine.isAdminUser(authEngine.getAuthSession()))) && !editingInvoice) {
          return (
            <div className="flex-1 flex flex-col items-center justify-center p-6 text-center">
              <div className="w-16 h-16 bg-theme-warning/20 text-theme-warning rounded-2xl flex items-center justify-center mx-auto mb-6">
                <AlertTriangle className="w-8 h-8 text-theme-warning" />
              </div>
              <h2 className="text-xl font-bold text-white mb-2">New Bill Creation Disabled</h2>
              <p className="text-sm text-theme-muted max-w-sm mb-6">
                The platform is currently undergoing scheduled maintenance or the owner has disabled new bill creation. You can still view existing bills and run backups.
              </p>
              <button onClick={() => setCurrentTab('dashboard')} className="px-5 py-2.5 bg-theme-accent text-white font-bold rounded-xl">
                Go to Dashboard
              </button>
            </div>
          );
        }
        if (revenueStatus.lockStatus === 'locked' && !editingInvoice) {
          return (
            <React.Suspense fallback={<div className="flex h-screen items-center justify-center"><ClassicLoader /></div>}>
              <PaymentDueScreen 
                pendingAmount={revenueStatus.platformPendingAmount}
                chargeableBills={revenueStatus.billableBillsCount}
                onCancel={() => setCurrentTab('dashboard')}
                onLogout={() => {
                  authEngine.logout();
                  setIsAuthenticated(false);
                  setCurrentTab('login');
                }}
              />
            </React.Suspense>
          );
        }
        return (
          <CreateInvoice
            invoices={activeInvoices}
            customers={activeCustomers}
            products={activeProducts}
            businessSettings={activeSettings}
            onSaveInvoice={handleSaveInvoice}
            setCurrentTab={setCurrentTab}
            editingInvoice={editingInvoice}
            onDownloadPDF={handleDownloadPDF}
            onBack={() => {
              setEditingInvoice(null);
              setCurrentTab('dashboard');
            }}
            onQuickBillOpen={() => setIsQuickBillOpen(true)}
            subscription={subscription}
          />
        );
      case 'guide':
        // Legacy fallback
        return (
          <HelpCenter />
        );
      case 'customers':
        return (
          <Customers
            customers={activeCustomers}
            invoices={activeInvoices}
            onSaveCustomer={handleSaveCustomer}
            onDeleteCustomer={handleDeleteCustomer}
            businessSettings={activeSettings}
            setCurrentTab={setCurrentTab}
            onCreateBill={(cust) => {
              setEditingInvoice({ customerName: cust.name });
              setCurrentTab('create-invoice');
            }}
          />
        );
      case 'products':
        return (
          <Products
            products={activeProducts}
            onSaveProduct={handleSaveProduct}
            onDeleteProduct={handleDeleteProduct}
            businessSettings={activeSettings}
            setCurrentTab={setCurrentTab}
          />
        );
      case 'expenses':
        return (
          <Expenses
            expenses={activeExpenses}
            onSaveExpense={handleSaveExpense}
            onDeleteExpense={handleDeleteExpense}
            businessSettings={activeSettings}
            setCurrentTab={setCurrentTab}
          />
        );
      case 'appointments':
        return <Appointments />;
      case 'orders':
        return <Orders invoices={activeInvoices} customers={activeCustomers} businessSettings={activeSettings} setCurrentTab={setCurrentTab} />;
      case 'patients':
        return <Patients />;
      case 'students':
        if (activeSettings && !isEducationBusiness(activeSettings.defaultBillingTemplate)) {
          // If a Business workspace attempts to open /students, automatically redirect
          // We don't render Students, we redirect to customers
          setTimeout(() => setCurrentTab('customers'), 0);
          return <div className="min-h-screen flex items-center justify-center"><ClassicLoader /></div>;
        }
        return <Students students={students} onSaveStudent={handleSaveStudent} onDeleteStudent={handleDeleteStudent} />;
      case 'clients':
        return <Clients />;
      case 'measurements':
        return <Measurements />;
      case 'designBook':
        return <DesignBook />;
      case 'devices':
        return <Devices />;
      case 'serviceJobs':
        return <ServiceJobs />;
      case 'projects':
        return <Projects />;
      case 'delivery':
        return <Delivery />;
      case 'premium-upgrade':
        if (isMaintenanceMode || activeSettings?.disablePremiumUpgrade) {
          return (
            <div className="flex-1 flex flex-col items-center justify-center p-6 text-center">
              <div className="w-16 h-16 bg-theme-warning/20 text-theme-warning rounded-2xl flex items-center justify-center mx-auto mb-6">
                <AlertTriangle className="w-8 h-8 text-theme-warning" />
              </div>
              <h2 className="text-xl font-bold text-white mb-2">Premium Upgrades Suspended</h2>
              <p className="text-sm text-theme-muted max-w-sm mb-6">
                Upgrading to premium features is temporarily suspended by the administrator.
              </p>
              <button onClick={() => setCurrentTab('dashboard')} className="px-5 py-2.5 bg-theme-accent text-white font-bold rounded-xl">
                Back to Dashboard
              </button>
            </div>
          );
        }
        return (
          <StudioLayout 
            settings={activeSettings} 
            onSaveSettings={handleSaveSettings} 
            setCurrentTab={setCurrentTab}
            subscription={subscription}
          />
        );
      case 'subscription':
        return (
          <StudioLayout 
            settings={activeSettings} 
            onSaveSettings={handleSaveSettings} 
            setCurrentTab={setCurrentTab}
            subscription={subscription}
          />
        );

      case 'pdf-templates':
        if (isMaintenanceMode || activeSettings?.disableLiveLinkCreation) {
          return (
            <div className="flex-1 flex flex-col items-center justify-center p-6 text-center">
              <div className="w-16 h-16 bg-theme-warning/20 text-theme-warning rounded-2xl flex items-center justify-center mx-auto mb-6">
                <AlertTriangle className="w-8 h-8 text-theme-warning" />
              </div>
              <h2 className="text-xl font-bold text-white mb-2">Customization Suspended</h2>
              <p className="text-sm text-theme-muted max-w-sm mb-6">
                Template customization is temporarily suspended by the administrator.
              </p>
              <button onClick={() => setCurrentTab('dashboard')} className="px-5 py-2.5 bg-theme-accent text-white font-bold rounded-xl">
                Back to Dashboard
              </button>
            </div>
          );
        }
        return (
          <PdfTemplateStudio 
            businessSettings={settings} 
            setSettings={setSettings} 
            setCurrentTab={setCurrentTab}
            subscription={subscription}
          />
        );
      case 'live-link-templates':
      case 'billing-portal-settings':
      case 'student-portal-settings':
        if (isMaintenanceMode || activeSettings?.disableLiveLinkCreation) {
          return (
            <div className="flex-1 flex flex-col items-center justify-center p-6 text-center">
              <div className="w-16 h-16 bg-theme-warning/20 text-theme-warning rounded-2xl flex items-center justify-center mx-auto mb-6">
                <AlertTriangle className="w-8 h-8 text-theme-warning" />
              </div>
              <h2 className="text-xl font-bold text-white mb-2">Live Invoice Links Suspended</h2>
              <p className="text-sm text-theme-muted max-w-sm mb-6">
                Live link customization and settings are temporarily suspended by the administrator.
              </p>
              <button onClick={() => setCurrentTab('dashboard')} className="px-5 py-2.5 bg-theme-accent text-white font-bold rounded-xl">
                Back to Dashboard
              </button>
            </div>
          );
        }
        return (
          <LiveLinkTemplateStudio 
            settings={settings}
            onSaveSettings={handleSaveSettings}
            subscription={subscription}
            setCurrentTab={setCurrentTab}
          />
        );
      case 'marketplace':
        return (
          <TemplateMarketplace
            settings={settings}
            onSaveSettings={handleSaveSettings}
            subscription={subscription}
            setCurrentTab={setCurrentTab}
          />
        );
      case 'design-studio':
        return (
          <DesignStudio setCurrentTab={setCurrentTab} />
        );
      case 'backup-restore':
        return (
          <BackupRestore
            settings={settings}
            invoices={invoices}
            customers={customers}
            products={products}
            expenses={expenses}
            onImportBackup={handleImportBackup}
          />
        );
      case 'more':
        return (
          <MoreMenu
            setCurrentTab={setCurrentTab}
            isAuthenticated={isAuthenticated}
            onLoginSuccess={handleLoginSuccess}
            businessSettings={settings}
            userRole={userRole}
            pendingPaymentsCount={pendingPayments.length}
          />
        );
      case 'privacy':
        return <PrivacyPolicy setCurrentTab={setCurrentTab} />;
      case 'terms':
        return <TermsOfService setCurrentTab={setCurrentTab} />;
      case 'refund':
        return <RefundPolicy setCurrentTab={setCurrentTab} />;
      case 'data-deletion':
        return <DataDeletion onBack={() => setCurrentTab('more')} />;
      case 'support':
        return <Support onBack={() => setCurrentTab('more')} />;
      case 'workspace-manager':
        return (
          <WorkspaceManager
            businessWorkspaces={businessWorkspaces}
            activeWorkspaceId={activeWorkspaceId}
            setActiveWorkspace={setActiveWorkspace}
            settings={activeSettings}
            onSaveSettings={handleSaveSettings}
            setCurrentTab={setCurrentTab}
          />
        );
      case 'settings': {
        const session = authEngine.getAuthSession();
        return (
          <StudioLayout
            settings={activeSettings}
            onSaveSettings={handleSaveSettings}
            isAdmin={adminEngine.isAdminUser(session)}
            onResetDemo={handleResetDemo}
            onImportBackup={handleImportBackup}
            invoices={activeInvoices}
            customers={activeCustomers}
            installPromptEvent={installPromptEvent}
            isAppInstalled={isAppInstalled}
            onInstallApp={handleInstallApp}
            subscription={subscription}
            setCurrentTab={setCurrentTab}
          />
        );
      }
      default:
        // Automatically recover from invalid tabs stored in localStorage
        setTimeout(() => setCurrentTab('dashboard'), 0);
        return (
          <div className="flex flex-col items-center justify-center h-full text-center p-10">
            <ClassicLoader />
            <p className="text-theme-muted font-bold mt-4 animate-pulse">Recovering workspace...</p>
          </div>
        );
    }
  };

  // Intercept for Public Invoice Loading/Display (No Auth Route Interceptor)
  if (loadingPublicInvoice) {
    return (
      <div className="min-h-screen bg-theme-main flex flex-col items-center justify-center p-6 text-center text-white font-sans">
        <ClassicLoader />
        <p className="text-theme-muted text-xs font-bold uppercase mt-4 tracking-widest animate-pulse">Loading secure digital invoice...</p>
      </div>
    );
  }

  if (publicToken) {
    return (
      <React.Suspense fallback={
        <div className="flex h-screen items-center justify-center">
          <ClassicLoader />
        </div>
      }>
        <PublicInvoice initialInvoice={publicInvoice} />
      </React.Suspense>
    );
  }

  if (portalId) {
    return (
      <React.Suspense fallback={
        <div className="flex h-screen items-center justify-center">
          <ClassicLoader />
        </div>
      }>
        <CustomerWorkspace customerId={portalId === 'verification-pending' ? null : portalId} />
      </React.Suspense>
    );
  }

  if (eduPortalId) {
    return (
      <React.Suspense fallback={
        <div className="flex h-screen items-center justify-center">
          <ClassicLoader />
        </div>
      }>
        <StudentPortal studentId={eduPortalId} />
      </React.Suspense>
    );
  }

  // Show onboarding/login if not authenticated
  const isDemoJourneyActive = localStorage.getItem('billqyro_demo_journey_mode') === 'true';
  const isDemoLoggedIn = localStorage.getItem('billqyro_demo_logged_in') === 'true';

  if (isDemoSessionActive && isDemoJourneyActive && !isDemoLoggedIn) {
    return (
      <React.Suspense fallback={
        <div className="flex h-screen items-center justify-center">
          <ClassicLoader />
        </div>
      }>
        <DemoLogin onDemoLoginSuccess={() => {
          setIsAuthenticated(true);
          setShowWelcomeAnimation(true);
          window.dispatchEvent(new Event('storage'));
        }} />
      </React.Suspense>
    );
  }

  if (!isAuthenticated && (!isDemoSessionActive || !isDemoJourneyActive)) {
    return (
      <React.Suspense fallback={
        <div className="flex h-screen items-center justify-center">
          <ClassicLoader />
        </div>
      }>
        <Landing onLoginSuccess={handleLoginSuccess} />
      </React.Suspense>
    );
  }

  // --- Account Blocked Interceptor ---
  if (settings?.blocked === true) {
    const session = authEngine.getAuthSession();
    if (!adminEngine.isAdminUser(session)) {
      return (
        <div className="min-h-screen bg-theme-main flex flex-col items-center justify-center p-6 text-center font-sans text-white">
          <motion.div
            initial={{ scale: 0.9, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            className="max-w-md bg-theme-card p-8 rounded-3xl border border-theme-border-soft shadow-2xl space-y-6"
          >
            <div className="w-16 h-16 bg-theme-danger/20 text-theme-danger rounded-2xl flex items-center justify-center mx-auto shadow-lg shadow-rose-500/10">
              <Lock className="w-8 h-8" />
            </div>
            <h1 className="text-2xl font-black tracking-tight text-white">Account Deactivated</h1>
            <p className="text-theme-muted text-xs font-semibold leading-relaxed">
              Your BillQyro workspace has been temporarily blocked by the platform administrator due to policy guidelines or outstanding billing concerns.
            </p>
            <div className="p-4 bg-theme-surface/50 rounded-2xl border border-theme-border-soft/80 text-left space-y-2">
              <span className="text-[10px] text-theme-muted uppercase font-black block tracking-widest">Administrator Notice</span>
              <p className="text-[11px] text-theme-muted font-semibold leading-relaxed">
                If you believe this is an error or wish to request immediate reactivation, please contact support at <strong className="text-theme-accent select-all">{settings.email || 'support@billqyro.com'}</strong> or email your account manager directly.
              </p>
            </div>
            <button
              onClick={() => {
                authEngine.logout();
                setIsAuthenticated(false);
              }}
              className="w-full py-3 bg-theme-card hover:bg-theme-surface text-white font-bold text-xs rounded-xl shadow-lg active:scale-[0.98] transition-all cursor-pointer uppercase tracking-wider"
            >
              Sign Out of Account
            </button>
          </motion.div>
        </div>
      );
    }
  }

  // --- Account Soft Lock Interceptor (Due Limit) ---
  const freeLimit = settings?.freeInvoiceLimit || 15;
  const pendingAmountLimit = settings?.maximumPendingDue || 100;
  const chargePerBill = settings?.chargePerBill || 5;
  
  if (subscription?.status !== 'premium' && invoices.length > freeLimit) {
    const chargeableBills = invoices.length - freeLimit;
    const pendingAmount = chargeableBills * chargePerBill;
    
    if (pendingAmount >= pendingAmountLimit) {
      const session = authEngine.getAuthSession();
      if (!adminEngine.isAdminUser(session)) {
        return (
          <React.Suspense fallback={<div className="flex h-screen items-center justify-center"><ClassicLoader /></div>}>
            <PaymentDueScreen 
              pendingAmount={pendingAmount} 
              chargeableBills={chargeableBills}
              onLogout={() => {
                authEngine.logout();
                setIsAuthenticated(false);
              }} 
            />
          </React.Suspense>
        );
      }
    }
  }

  // Root level maintenance mode interceptor removed to allow access to dashboard, invoices view, and backups.

  const path = window.location.pathname;
  const showAdminRoute = path === '/km-admin' || currentTab === 'admin-panel';

  // Enterprise Route Gate - Wait for Auth, Workspace, and Sync to resolve
  const isAppReady = !isAppBooting && (!isAuthenticated || (cloudSyncDone && settings));
  const isSetupIncomplete = isAuthenticated && activeSettings && !activeSettings.setupCompleted && !activeSettings.businessName;

  // Resolve currentTab when we reach layout (defaulting to dashboard if null)
  const resolvedTab = currentTab || 'dashboard';

  return (
    <ErrorBoundary>
      <AnimatePresence mode="wait">
        {!isAppReady ? (
          <motion.div 
            key="global-loader"
            exit={{ opacity: 0, transition: { duration: 0.25, ease: 'easeOut' } }}
            className="fixed inset-0 z-[9999] bg-theme-main flex flex-col items-center justify-center font-sans"
          >
            <ClassicLoader />
            <p className="text-theme-muted font-bold mt-4 animate-pulse">Loading workspace...</p>
          </motion.div>
        ) : showAdminRoute ? (
          <motion.div key="admin-route" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="w-full h-full">
            <React.Suspense fallback={<div className="flex h-screen items-center justify-center"><ClassicLoader /></div>}>
              <AdminRouteGuard setCurrentTab={(tab) => {
                setCurrentTab(tab);
                if (window.location.pathname === '/km-admin') {
                  window.history.replaceState({}, '', '/');
                }
              }}>
                <AdminPanel 
                  currentTab={resolvedTab} 
                  setCurrentTab={(tab) => {
                    setCurrentTab(tab);
                    if (window.location.pathname === '/km-admin') {
                      window.history.replaceState({}, '', '/');
                    }
                  }} 
                />
              </AdminRouteGuard>
            </React.Suspense>
          </motion.div>
        ) : (
          <motion.div key="main-app" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.2 }} className="w-full h-full flex flex-col">
            {isDemoSessionActive && (
              <div className="bg-amber-500 text-amber-950 px-4 py-2 flex items-center justify-between font-bold text-sm z-[999999] relative shadow-md">
                <span className="flex items-center">
                  <AlertTriangle className="w-4 h-4 mr-2"/> DEMO MODE ACTIVE — Real data is safe. {isVideoCreatorMode && " | Video Creator Masking ON"}
                </span>
                <button onClick={() => {
                  if (window.confirm("Exit Demo Mode and return to Owner Test Lab?")) {
                    if (window.confirm("Do you want to clear the Demo Sandbox data as well?")) {
                      localStorage.removeItem('billqyro_demo_customers');
                      localStorage.removeItem('billqyro_demo_invoices');
                      localStorage.removeItem('billqyro_demo_products');
                      localStorage.removeItem('billqyro_demo_reports');
                      localStorage.removeItem('billqyro_demo_payments');
                      localStorage.removeItem('billqyro_demo_settings');
                      localStorage.removeItem('billqyro_demo_logged_in');
                    }
                    localStorage.removeItem('billqyro_demo_session_active');
                    localStorage.removeItem('billqyro_demo_journey_mode');
                    localStorage.removeItem('billqyro_demo_video_creator');
                    window.location.href = '/km-admin';
                  }
                }} className="bg-amber-950 hover:bg-amber-900 text-amber-500 px-3 py-1 rounded-md text-xs transition-colors">Exit Demo</button>
              </div>
            )}
            <PostLoginWelcome 
              show={showWelcomeAnimation} 
              userName={settings?.businessName || ''} 
              onComplete={() => setShowWelcomeAnimation(false)} 
            />
            {isSetupIncomplete ? (
              <OnboardingWizard 
                onComplete={() => setCurrentTab('dashboard')} 
