      taxPercentage: 0,
      discountAmount: 0,
      amountPaid: paid,
      balanceDue,
      notes,
      paymentStatus,
      orderStatus: 'Pending',
      subtotal: amount,
      taxAmount: 0,
      grandTotal: amount,
    };
    
    // Call the global save function
    onSave(payload, true); // true = save as new customer
