                transition={{ delay: 0.25, duration: 0.2, ease: [0.25, 0.1, 0.25, 1] }}
                className="text-xs text-theme-muted font-medium"
              >
                {submessage}
              </motion.p>
            )}
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

// Toast-style success banner
const SuccessBanner = ({ message, show, onDismiss }) => {
