import React, { useState, useEffect } from 'react';
import { Button } from '../ui/Button';
import toast from 'react-hot-toast';
import { Modal } from '../ui/Modal';
import {
  FileText,
  Image as ImageIcon,
  Copy,
  Check,
  Download,
  Send,
  Smartphone,
  MessageCircle,
  ExternalLink,
  Link as LinkIcon,
  Info
} from 'lucide-react';
import { communicationEngine } from '../../services/communication/communicationEngine';
import { whatsappShareAdapter } from '../../services/communication/whatsappShareAdapter';

/**
 * Premium WhatsApp Communication Preview & Share flow.
 * Consumes the exact payload generated by communicationEngine.prepareCommunication.
 *
 * Props:
 *   workspaceId, userId, invoiceId – identifiers required to build the payload.
 *   onClose – callback when the preview modal is dismissed.
 */
export default function WhatsAppCommunicationPreview({ workspaceId, userId, invoiceId, onClose }) {
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const [error, setError] = useState(null);
  const [payload, setPayload] = useState(null);
  const [editableMessage, setEditableMessage] = useState('');
  const [copied, setCopied] = useState(false);

  // Prepare the communication payload once on mount
  useEffect(() => {
    const prepare = async () => {
      try {
        if (!navigator.onLine) {
          throw new Error('Network offline – cannot prepare WhatsApp communication');
        }
        const comm = await communicationEngine.prepareCommunication({
          workspaceId,
          userId,
          invoiceId,
          overrides: {}
        });
        if (comm && comm.status === 'offline_prepared') {
          throw new Error(comm.reason || 'Network offline – cannot prepare WhatsApp communication');
        }
        setPayload(comm);
        setEditableMessage(comm.message || '');
      } catch (e) {
        console.error(e);
        setError(e.message || 'Failed to prepare WhatsApp reminder.');
      } finally {
        setLoading(false);
      }
    };
    prepare();
  }, [workspaceId, userId, invoiceId]);

  const pdf = (payload?.attachments || []).find(a => a.type === 'pdf');
  const image = (payload?.attachments || []).find(a => a.type === 'image');
  const readyCount = (payload?.attachments || []).filter(a => a.ready).length;
  const selectedCount = (payload?.attachments || []).length;
  const currency = payload?.currency || '₹';

  const formatAmount = (value) => {
    if (value == null) return '—';
    return `${currency}${Number(value).toFixed(2)}`;
  };

  const formatSize = (bytes) => {
    if (!bytes) return '';
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  };

  const openWhatsApp = async () => {
    if (!payload || sending) return;
    if (localStorage.getItem('billqyro_demo_session_active') === 'true') {
      toast.error('WhatsApp sharing is disabled in Demo mode.');
      return;
    }
    // Never silently drop a failed PDF – warn before sharing.
    if (payload.includePdf !== false && pdf && !pdf.ready) {
      toast.error('Invoice PDF could not be generated – your message will be sent without the PDF.');
    }
    setSending(true);
    setError(null);
    try {
      const result = await whatsappShareAdapter.shareViaWhatsApp({
        recipient: payload.recipientPhone,
        message: editableMessage,
        attachments: payload.attachments
      });
      console.log('[WhatsAppCommunicationPreview] share result', result);

      if (result.status === 'cancelled') {
        toast.info('Share cancelled – nothing was sent.');
      } else if (result.method === 'webshare' && result.filesShared) {
        toast.success(`WhatsApp opened with ${result.filesCount} attachment${result.filesCount > 1 ? 's' : ''} (PDF + message).`);
      } else if (result.method === 'webshare') {
        toast.success('WhatsApp opened with your message.');
      } else {
        toast(
          <span>
            <strong>WhatsApp opened with your message.</strong>
            <br />
            Your PDF/image could not be attached automatically on this device. Please attach the files manually before sending.
          </span>,
          { duration: 6000, icon: <Info className="w-4 h-4" /> }
        );
      }
    } catch (e) {
      console.error(e);
      setError(e.message || 'Failed to open WhatsApp.');
      toast.error(e.message || 'Failed to open WhatsApp.');
    } finally {
      setSending(false);
    }
  };

  const downloadPdf = () => {
    if (pdf && pdf.ready && pdf.blob) {
      const link = document.createElement('a');
      link.href = pdf.blobUrl || URL.createObjectURL(pdf.blob);
      link.download = pdf.name || 'invoice.pdf';
      link.click();
    } else {
      toast.error('PDF is not ready yet.');
    }
  };

  const copyMessage = async () => {
    try {
      await navigator.clipboard.writeText(editableMessage || '');
      setCopied(true);
      toast.success('Message copied to clipboard.');
      setTimeout(() => setCopied(false), 2000);
    } catch {
      toast.error('Could not copy message.');
    }
  };

  // Attachment chip: Ready / Failed / Disabled per attachment type.
  const AttachmentChip = ({ kind, state, name, size }) => {
    const styles = {
      ready: 'bg-emerald-500/5 border-emerald-500/20 text-emerald-600 dark:text-emerald-400',
      failed: 'bg-rose-500/5 border-rose-500/20 text-rose-600 dark:text-rose-400',
      disabled: 'bg-theme-app dark:bg-theme-surface border-theme-border-soft text-theme-muted'
    };
    const label = state === 'ready' ? '✓ Ready' : state === 'failed' ? 'Failed' : 'Disabled';
    const chipName = name || (kind === 'pdf' ? 'Invoice PDF' : 'Business Image');
    return (
      <div className={`flex items-center gap-2 px-3 py-2 rounded-xl border text-xs font-bold ${styles[state]}`}>
        {kind === 'pdf' ? <FileText className="w-4 h-4 shrink-0" /> : <ImageIcon className="w-4 h-4 shrink-0" />}
        <div className="min-w-0">
          <div className="truncate">{chipName}</div>
          {size ? <div className="text-[10px] opacity-70">{formatSize(size)}</div> : null}
        </div>
        <span className="ml-auto shrink-0">{label}</span>
      </div>
    );
  };

  const pdfState = payload?.includePdf === false ? 'disabled' : (pdf?.ready ? 'ready' : 'failed');
  const imageState = payload?.includeImage === false || !image ? 'disabled' : (image.ready ? 'ready' : 'failed');

  return (
    <Modal isOpen={true} onClose={onClose} title="Send WhatsApp Reminder">
      {error && (
        <div className="m-4 p-3 rounded-xl bg-rose-500/10 border border-rose-500/20 text-rose-600 dark:text-rose-400 text-xs font-semibold flex items-center gap-2">
          <Info className="w-4 h-4 shrink-0" /> {error}
        </div>
      )}

      {loading && (
        <div className="flex flex-col items-center justify-center py-16 text-theme-muted">
          <Send className="w-8 h-8 animate-bounce mb-3 text-theme-accent" />
          <p className="text-xs font-bold uppercase tracking-wider">Preparing professional reminder…</p>
          <p className="text-[11px] mt-1 opacity-70">Generating your invoice PDF for WhatsApp</p>
        </div>
      )}

      {payload && !loading && (
        <div className="space-y-4 p-5">
          {/* Summary: customer (name + id), invoice # (+ due date), total / paid / due */}
          <div className="grid grid-cols-2 gap-2 text-xs text-theme-secondary">
            <div className="p-3 rounded-xl bg-theme-app dark:bg-theme-surface border border-theme-border-soft">
              <div className="text-[9px] uppercase tracking-wider text-theme-muted font-bold">Customer</div>
              <div className="font-extrabold text-theme-primary">{payload.customer?.name || '—'}</div>
              {payload.customer?.id && (
                <div className="text-[10px] text-theme-muted mt-0.5 truncate">ID: {payload.customer.id}</div>
              )}
            </div>
            <div className="p-3 rounded-xl bg-theme-app dark:bg-theme-surface border border-theme-border-soft">
              <div className="text-[9px] uppercase tracking-wider text-theme-muted font-bold">Invoice #</div>
              <div className="font-extrabold text-theme-primary">{payload.invoice?.invoiceNumber || '—'}</div>
              {payload.invoice?.dueDate && (
                <div className="text-[10px] text-theme-muted mt-0.5">Due: {payload.invoice.dueDate}</div>
              )}
            </div>
            <div className="p-3 rounded-xl bg-theme-app dark:bg-theme-surface border border-theme-border-soft">
              <div className="text-[9px] uppercase tracking-wider text-theme-muted font-bold">Total</div>
              <div className="font-extrabold text-theme-primary">{formatAmount(payload.invoice?.grandTotal)}</div>
            </div>
            <div className="p-3 rounded-xl bg-theme-app dark:bg-theme-surface border border-theme-border-soft">
              <div className="text-[9px] uppercase tracking-wider text-theme-muted font-bold">Paid</div>
              <div className="font-extrabold text-emerald-500">{formatAmount(payload.invoice?.amountPaid)}</div>
            </div>
            <div className="p-3 rounded-xl bg-theme-app dark:bg-theme-surface border border-theme-border-soft">
              <div className="text-[9px] uppercase tracking-wider text-theme-muted font-bold">Due</div>
              <div className="font-extrabold text-rose-500">{formatAmount(payload.invoice?.balanceDue)}</div>
            </div>
            <div className="p-3 rounded-xl bg-theme-app dark:bg-theme-surface border border-theme-border-soft">
              <div className="text-[9px] uppercase tracking-wider text-theme-muted font-bold">Due Date</div>
              <div className="font-extrabold text-theme-primary">{payload.invoice?.dueDate || '—'}</div>
            </div>
          </div>

          {/* WhatsApp-style message bubble */}
          <div className="rounded-2xl bg-[#DCF8C6] dark:bg-[#1f2c33] p-4 shadow-inner border border-black/5">
            <div className="flex items-center gap-2 mb-3 text-[10px] font-bold text-emerald-700 dark:text-emerald-400">
              <MessageCircle className="w-3.5 h-3.5" /> WhatsApp Message Preview
            </div>
            <pre className="whitespace-pre-wrap text-[13px] leading-relaxed text-gray-800 dark:text-gray-100 font-sans">{editableMessage}</pre>
            <div className="text-right text-[10px] text-gray-500 dark:text-gray-400 mt-2">
              {new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} ✓✓
            </div>
          </div>

          {/* Attachment status chips + portal link status */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
            <AttachmentChip kind="pdf" state={pdfState} name={pdf?.name} size={pdf?.size} />
            <AttachmentChip kind="image" state={imageState} name={image?.name} size={image?.size} />
            <div className={`flex items-center gap-2 px-3 py-2 rounded-xl border text-xs font-bold ${
              payload.portalLink
                ? 'bg-emerald-500/5 border-emerald-500/20 text-emerald-600 dark:text-emerald-400'
                : 'bg-theme-app dark:bg-theme-surface border-theme-border-soft text-theme-muted'
            }`}>
              <LinkIcon className="w-4 h-4 shrink-0" />
              <span className="truncate">{payload.portalLink ? 'Portal Link Ready' : 'Portal Link Disabled'}</span>
              <span className="ml-auto shrink-0">{payload.portalLink ? '✓ Ready' : 'Disabled'}</span>
            </div>
          </div>

          {/* Attachment count */}
          <div className="text-[11px] font-semibold text-theme-muted">
            {readyCount > 0
              ? `${readyCount} attachment${readyCount > 1 ? 's' : ''} ready to share${selectedCount > readyCount ? ` · ${selectedCount - readyCount} unavailable` : ''}`
              : selectedCount > 0
                ? 'Attachments could not be generated.'
                : 'No attachments selected for this message.'}
          </div>

          {/* Device note */}
          <div className="flex items-start gap-2 p-3 rounded-xl bg-sky-500/5 border border-sky-500/20 text-[11px] text-sky-700 dark:text-sky-300">
            <Smartphone className="w-4 h-4 shrink-0 mt-0.5" />
            <span>
              On <strong>mobile</strong>, WhatsApp opens with the PDF &amp; message attached automatically. On <strong>desktop</strong>, WhatsApp Web opens with the message – download the PDF and attach it manually if needed.
            </span>
          </div>

          {/* Editable message */}
          <div>
            <div className="text-[10px] uppercase tracking-wider text-theme-muted font-bold mb-1.5">Edit Message</div>
            <textarea
              className="w-full h-28 p-3 rounded-xl border border-theme-border-soft bg-theme-app dark:bg-theme-surface text-sm text-theme-primary resize-y no-scrollbar"
              value={editableMessage}
              onChange={(e) => setEditableMessage(e.target.value)}
              disabled={sending}
            />
          </div>

          {/* Actions */}
          <div className="flex flex-wrap items-center justify-end gap-2">
            <Button variant="secondary" size="sm" onClick={copyMessage} disabled={sending} leftIcon={copied ? Check : Copy}>
              {copied ? 'Copied' : 'Copy'}
            </Button>
            {pdf && pdf.ready && (
              <Button variant="outline" size="sm" onClick={downloadPdf} disabled={sending} leftIcon={Download}>
                Download PDF
              </Button>
            )}
            <Button variant="ghost" size="sm" onClick={onClose} disabled={sending}>
              Cancel
            </Button>
            <Button variant="primary" size="sm" onClick={openWhatsApp} isLoading={sending} leftIcon={ExternalLink}>
              Open WhatsApp
            </Button>
          </div>
        </div>
      )}
    </Modal>
  );
}

// src/components/communication/WhatsAppSharePreview.jsx

import React, { useState } from 'react';
import { Button } from '../ui/Button'; // Assuming a generic Button component exists
import { shareViaWhatsApp } from '../../services/communication/whatsappShareAdapter';
import { communicationEngine } from '../../services/communication/communicationEngine';
import { toast } from 'react-hot-toast';

/**
 * Props:
 *   workspaceId, userId, customerId, invoiceId, paymentId (optional)
 *   onClose – callback when preview is dismissed
 */
export default function WhatsAppSharePreview({
  workspaceId,
  userId,
  customerId,
  invoiceId,
  paymentId,
  onClose
}) {
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [prepared, setPrepared] = useState(null);
  const [error, setError] = useState(null);

  const prepare = async () => {
    setLoading(true);
    setError(null);
    try {
      const comm = await communicationEngine.prepareCommunication({
        workspaceId,
        userId,
        invoiceId
      });

      const adaptedComm = {
        ...comm,
        recipient: comm.recipientPhone || comm.customer?.phone,
        metadata: {
          customerId: comm.customer?.name || comm.customer?.id || customerId,
          invoiceId: comm.invoice?.invoiceNumber || invoiceId
        }
      };

      setMessage(adaptedComm.message);
      setPrepared(adaptedComm);
    } catch (e) {
      console.error(e);
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  const openWhatsApp = async () => {
    if (!prepared || loading) return;
    setLoading(true);
    try {
      const finalPrepared = { ...prepared, message };
      const result = await shareViaWhatsApp(finalPrepared);
      console.log('[WhatsAppSharePreview] share result', result);

      if (!result.filesShared && prepared.attachments && prepared.attachments.length > 0) {
        if (result.pdfDownloaded) {
          toast.success('PDF downloaded! Attach it manually in WhatsApp.', {
            icon: '📎',
            duration: 6000
          });
        } else {
          toast('WhatsApp opened. Use the "Download PDF" button to get the invoice, then attach it manually.', {
            icon: 'ℹ️',
            duration: 6000
          });
        }
        // Do NOT auto close so they can use the Download PDF button
      } else {
        onClose(); // Auto close the preview when sharing completes fully
      }
    } catch (e) {
      console.error(e);
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  const handleDownloadPdf = () => {
    const pdfAttachment = prepared?.attachments?.find(a => a.type === 'pdf');
    if (pdfAttachment && pdfAttachment.blobUrl) {
      const a = document.createElement('a');
      a.href = pdfAttachment.blobUrl;
      a.download = pdfAttachment.name || 'Invoice.pdf';
      a.click();
    }
  };

  // Initial preparation when component mounts.
  React.useEffect(() => {
    prepare();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div className="fixed inset-0 bg-black bg-opacity-60 flex items-center justify-center z-50">
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow-lg max-w-lg w-full p-6 overflow-auto max-h-screen">
        <h2 className="text-xl font-bold mb-4 text-gray-900 dark:text-gray-100">WhatsApp Reminder Preview</h2>
        {error && <p className="text-red-600 mb-2">Error: {error}</p>}
        {loading && <p className="mb-2">Loading…</p>}
        {prepared && (
          <>
            <div className="grid grid-cols-2 gap-2 mb-4 text-sm text-gray-700 dark:text-gray-300">
              <div><strong>Customer:</strong> {prepared.metadata.customerId}</div>
              <div><strong>WhatsApp:</strong> {prepared.recipient}</div>
              <div><strong>Invoice:</strong> {prepared.metadata.invoiceId}</div>
              <div><strong>Total:</strong> {prepared.message.match(/Total:.*$/m)?.[0] || ''}</div>
              <div><strong>Paid:</strong> {prepared.message.match(/Paid:.*$/m)?.[0] || ''}</div>
              <div><strong>Due:</strong> {prepared.message.match(/Due:.*$/m)?.[0] || ''}</div>
              {prepared.attachments?.some(a => a.type === 'pdf') && (
                <div className="col-span-2 text-green-600">PDF: Enabled</div>
              )}
              {prepared.attachments?.some(a => a.type === 'image') && (
                <div className="col-span-2 text-green-600">Business Image: Enabled</div>
              )}
            </div>
            <div className="border rounded p-3 mb-4 bg-gray-50 dark:bg-gray-700">
              <textarea
                className="w-full min-h-40 p-2 bg-transparent text-gray-800 dark:text-gray-100 font-mono text-sm resize-y focus:outline-none"
                style={{ wordBreak: 'break-word' }}
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                aria-label="WhatsApp message"
              />
            </div>
            <div className="flex justify-end space-x-2">
              <Button onClick={onClose} disabled={loading}>Cancel</Button>
              {prepared.attachments?.some(a => a.type === 'pdf') && (
                <Button onClick={handleDownloadPdf} disabled={loading} className="bg-blue-600 text-white hover:bg-blue-700">Download PDF</Button>
              )}
              <Button onClick={openWhatsApp} disabled={loading} className="bg-green-600 text-white hover:bg-green-700">Open WhatsApp</Button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

import React from 'react';
import { 
  X, 
  Phone, 
  Mail, 
  MapPin, 
  FileText, 
  TrendingUp, 
  AlertCircle,
  MessageCircle,
  CheckCircle2,
  Calendar,
  Clock,
  Banknote,
  Save,
  Loader2,
  Plus
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { invoiceEngine } from '../../services/invoiceEngine';
import { toast } from 'react-hot-toast';

/**
 * Customer Ledger Modal
 * Displays a comprehensive view of a customer's history and metrics.
 */
const CustomerLedger = ({ isOpen, onClose, customer, invoices = [], currencySymbol = '₹', onCreateBill }) => {
  const [updatingInvoiceId, setUpdatingInvoiceId] = React.useState(null);
  const [paymentAmount, setPaymentAmount] = React.useState('');
  const [paymentMethod, setPaymentMethod] = React.useState('Cash');
  const [paymentNote, setPaymentNote] = React.useState('');
  const [isSaving, setIsSaving] = React.useState(false);

  if (!isOpen || !customer) return null;

  // 1. Filter invoices for this customer
  const customerInvoices = invoices.filter(
    (inv) => inv.customerName?.toLowerCase() === customer.name?.toLowerCase()
  );

  // 2. Calculate Metrics
  const totalBilled = customerInvoices.reduce((acc, inv) => acc + (parseFloat(inv.grandTotal || inv.total) || 0), 0);
  const totalPaid = customerInvoices.reduce((acc, inv) => {
    const paid = inv.paymentStatus === 'Paid' ? (parseFloat(inv.grandTotal || inv.total) || 0) : (parseFloat(inv.amountPaid) || 0);
    return acc + paid;
  }, 0);
  const totalDue = Math.max(0, totalBilled - totalPaid);

  // 3. Sort invoices chronologically (newest first)
  const timeline = [...customerInvoices].sort((a, b) => new Date(b.date) - new Date(a.date));

  const formatCurrency = (amount) => {
    const formattedNum = new Intl.NumberFormat('en-IN', {
      minimumFractionDigits: 0,
      maximumFractionDigits: 2
    }).format(amount || 0);
    return `${currencySymbol} ${formattedNum}`;
  };

  const handleUpdatePayment = async (inv) => {
    setIsSaving(true);
    try {
      const newPaid = (parseFloat(inv.amountPaid) || 0) + parseFloat(paymentAmount);
      const grandTotal = parseFloat(inv.grandTotal || inv.total);
      
      let newStatus = 'Partial';
      if (newPaid >= grandTotal) {
        newStatus = 'Paid';
      } else if (newPaid === 0) {
        newStatus = 'Unpaid';
      }

      const updatedInvoice = {
        ...inv,
        amountPaid: newPaid,
        balanceDue: Math.max(0, grandTotal - newPaid),
        paymentStatus: newStatus,
        paymentMethod: paymentMethod,
        paymentNote: paymentNote,
        paymentDate: new Date().toISOString()
      };

      await invoiceEngine.saveInvoice(updatedInvoice);
      setUpdatingInvoiceId(null);
      setPaymentAmount('');
      setPaymentNote('');
      // We don't have a direct way to trigger a re-render of App.jsx invoices here unless we pass a callback, 
      // but dbEngine's onSnapshot handles live updates if online, or the user can refresh/re-open.
      toast.success('Payment updated successfully! The ledger will reflect changes shortly.');
    } catch (err) {
      console.error(err);
      toast.error('Failed to update payment');
    } finally {
      setIsSaving(false);
    }
  };

  const generateWhatsAppReminder = () => {
    const amount = formatCurrency(totalDue);
    const message = `Hello ${customer.name},%0A%0AThis is a gentle reminder that you have a pending due of *${amount}* with us. Please clear it at your earliest convenience.%0A%0AThank you!`;
    const phone = customer.phone ? customer.phone.replace(/[^0-9]/g, '') : '';
    if (phone) {
      window.open(`https://wa.me/${phone}?text=${message}`, '_blank');
    } else {
      toast.error("No phone number found for this customer.");
    }
  };

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-black/60 backdrop-blur-sm"
        onClick={onClose}
      >
        <motion.div
          initial={{ y: '100%', opacity: 0.5 }}
          animate={{ y: 0, opacity: 1 }}
          exit={{ y: '100%', opacity: 0 }}
          transition={{ type: 'spring', damping: 25, stiffness: 200 }}
          className="w-full h-[90vh] sm:h-auto sm:max-h-[90vh] sm:max-w-2xl bg-theme-app dark:bg-theme-app rounded-t-[2rem] sm:rounded-3xl shadow-2xl flex flex-col overflow-hidden"
          onClick={(e) => e.stopPropagation()}
        >
          {/* Header */}
          <div className="relative pt-6 px-6 pb-4 bg-[image:var(--accent-gradient)] text-white shrink-0">
            <button
              onClick={onClose}
              className="absolute top-4 right-4 w-8 h-8 flex items-center justify-center rounded-full bg-black/20 hover:bg-black/40 transition-colors"
            >
              <X className="w-4 h-4" />
            </button>
            <div className="flex items-center gap-4">
              <div className="w-16 h-16 rounded-2xl bg-white/20 backdrop-blur-md flex items-center justify-center font-black text-2xl border border-white/30 shadow-inner">
                {customer.name ? customer.name.substring(0, 2).toUpperCase() : '??'}
              </div>
              <div className="flex-1">
                <h2 className="text-2xl font-black tracking-tight">{customer.name}</h2>
                <p className="text-white/80 text-xs font-semibold uppercase tracking-wider mt-0.5">Customer Ledger</p>
              </div>
            </div>
          </div>

          {/* Body */}
          <div className="flex-1 overflow-y-auto p-6 space-y-6">
            
            {/* Contact Info Card */}
            <div className="glass-panel dark:glass-panel-heavy rounded-2xl p-4 flex flex-col gap-3">
              {customer.phone && (
                <div className="flex items-center gap-3 text-sm font-semibold text-theme-primary">
                  <div className="w-8 h-8 rounded-full bg-theme-accent/10 text-theme-accent flex items-center justify-center shrink-0">
                    <Phone className="w-4 h-4" />
                  </div>
                  <span>{customer.phone}</span>
                </div>
              )}
              {customer.email && (
                <div className="flex items-center gap-3 text-sm font-semibold text-theme-primary">
                  <div className="w-8 h-8 rounded-full bg-theme-accent/10 text-theme-accent flex items-center justify-center shrink-0">
                    <Mail className="w-4 h-4" />
                  </div>
                  <span>{customer.email}</span>
                </div>
              )}
              {customer.address && (
                <div className="flex items-center gap-3 text-sm font-semibold text-theme-primary">
                  <div className="w-8 h-8 rounded-full bg-theme-accent/10 text-theme-accent flex items-center justify-center shrink-0">
                    <MapPin className="w-4 h-4" />
                  </div>
                  <span>{customer.address}</span>
                </div>
              )}
            </div>

            {/* Metrics Grid */}
            <div className="grid grid-cols-3 gap-3">
              <div className="bg-theme-card border border-theme-border-soft rounded-2xl p-4 text-center">
                <span className="block text-[10px] uppercase font-bold text-theme-muted mb-1">Total Billed</span>
                <span className="block text-lg font-black text-theme-primary">{formatCurrency(totalBilled)}</span>
              </div>
              <div className="bg-emerald-50 dark:bg-emerald-950/30 border border-emerald-200 dark:border-emerald-900/50 rounded-2xl p-4 text-center">
                <span className="block text-[10px] uppercase font-bold text-emerald-600 dark:text-emerald-400 mb-1">Total Paid</span>
                <span className="block text-lg font-black text-emerald-700 dark:text-emerald-300">{formatCurrency(totalPaid)}</span>
              </div>
              <div className="bg-rose-50 dark:bg-rose-950/30 border border-rose-200 dark:border-rose-900/50 rounded-2xl p-4 text-center">
                <span className="block text-[10px] uppercase font-bold text-rose-600 dark:text-rose-400 mb-1">Total Due</span>
                <span className="block text-lg font-black text-rose-700 dark:text-rose-300">{formatCurrency(totalDue)}</span>
              </div>
            </div>

            {/* Quick Actions */}
            <div className="grid grid-cols-2 gap-2">
              {onCreateBill && (
                <button
                  onClick={() => {
                    onCreateBill(customer);
                    onClose();
                  }}
                  className="py-3.5 bg-theme-accent hover:bg-theme-accent-dark text-white font-bold rounded-2xl flex items-center justify-center gap-2 transition-transform active:scale-95"
                >
                  <Plus className="w-5 h-5" />
                  <span>New Bill</span>
                </button>
              )}
              {totalDue > 0 && (
                <button
                  onClick={generateWhatsAppReminder}
                  className="py-3.5 bg-emerald-500 hover:bg-emerald-600 text-white font-bold rounded-2xl shadow-lg shadow-emerald-500/30 flex items-center justify-center gap-2 transition-transform active:scale-95"
                >
                  <MessageCircle className="w-5 h-5" />
                  <span>Remind</span>
                </button>
              )}
            </div>

            {/* Timeline */}
            <div className="space-y-4">
              <h3 className="font-extrabold text-theme-primary flex items-center gap-2">
                <FileText className="w-4 h-4 text-theme-accent" />
                Billing History
              </h3>
              
              {timeline.length === 0 ? (
                <div className="text-center py-8 text-theme-muted font-semibold text-sm bg-theme-surface rounded-2xl border border-dashed border-theme-border-strong">
                  No invoices found for this customer.
                </div>
              ) : (
                <div className="space-y-3">
                  {timeline.map((inv, index) => {
                    const isPaid = inv.status === 'Paid';
                    return (
                      <div key={inv.id} className="relative flex gap-4 pl-2 group">
                        {/* Timeline Line */}
                        <div className="absolute left-4 top-8 bottom-[-16px] w-0.5 bg-theme-border-soft group-last:hidden"></div>
                        
                        {/* Timeline Dot */}
                        <div className="relative z-10 w-4 h-4 mt-2 rounded-full border-4 border-theme-card shadow-sm shrink-0" 
                             style={{ backgroundColor: isPaid ? 'var(--status-success)' : 'var(--status-warning)' }}>
                        </div>
                        
                        {/* Content Card */}
                        <div className="flex-1 bg-theme-card border border-theme-border-soft rounded-2xl p-4 shadow-sm hover:shadow-md transition-shadow">
                          <div className="flex justify-between items-start mb-2">
                            <div>
                              <span className="text-xs font-black text-theme-primary block">{inv.invoiceNumber}</span>
                              <span className="text-[10px] font-bold text-theme-muted flex items-center gap-1 mt-0.5">
                                <Calendar className="w-3 h-3" /> {new Date(inv.date).toLocaleDateString()}
                              </span>
                            </div>
                            <span className="text-sm font-black text-theme-primary">
                              {formatCurrency(inv.grandTotal || inv.total)}
                            </span>
                          </div>
                          
                          <div className="flex items-center justify-between mt-3">
                            <span className={`text-[10px] font-extrabold uppercase px-2 py-0.5 rounded-full ${
                              isPaid 
                                ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-500/20 dark:text-emerald-400' 
                                : 'bg-amber-100 text-amber-700 dark:bg-amber-500/20 dark:text-amber-400'
                            }`}>
                              {inv.status || 'Unpaid'}
                            </span>
                            
                            {!isPaid && (
                              <span className="text-[10px] font-bold text-rose-500 flex items-center gap-1">
                                <Clock className="w-3 h-3" /> Due {formatCurrency(inv.balanceDue || (inv.total - (inv.amountPaid || 0)))}
                              </span>
                            )}
                          </div>

                          {!isPaid && (
                            <div className="mt-3 pt-3 border-t border-theme-border-soft">
                              {updatingInvoiceId === inv.id ? (
                                <div className="space-y-3">
                                  <div className="grid grid-cols-2 gap-2">
                                    <div className="space-y-1">
                                      <label className="text-[9px] font-bold text-theme-muted uppercase tracking-wider">Amount ({formatCurrency(inv.balanceDue || (inv.total - (inv.amountPaid || 0)))})</label>
                                      <div className="relative">
                                        <Banknote className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-theme-success" />
                                        <input
                                          type="number"
                                          value={paymentAmount}
                                          onChange={e => setPaymentAmount(e.target.value)}
                                          className="w-full pl-8 pr-2 py-2 bg-theme-surface border border-theme-border-soft rounded-lg text-xs font-bold text-theme-primary focus:border-theme-accent focus:ring-1 focus:ring-theme-accent transition-all"
                                          placeholder="Enter amount"
                                          max={inv.balanceDue || (inv.total - (inv.amountPaid || 0))}
                                        />
                                      </div>
                                    </div>
                                    <div className="space-y-1">
                                      <label className="text-[9px] font-bold text-theme-muted uppercase tracking-wider">Method</label>
                                      <select
                                        value={paymentMethod}
                                        onChange={e => setPaymentMethod(e.target.value)}
                                        className="w-full px-2 py-2 bg-theme-surface border border-theme-border-soft rounded-lg text-xs font-bold text-theme-primary focus:border-theme-accent focus:ring-1 focus:ring-theme-accent transition-all"
                                      >
                                        <option value="Cash">Cash</option>
                                        <option value="Bank Transfer">Bank Transfer</option>
                                        <option value="UPI / QR">UPI / QR</option>
                                        <option value="Credit Card">Credit Card</option>
                                      </select>
                                    </div>
                                  </div>
                                  <div className="flex gap-2">
                                    <input
                                      type="text"
                                      value={paymentNote}
                                      onChange={e => setPaymentNote(e.target.value)}
                                      placeholder="Payment Note (e.g. Txn ID)"
                                      className="flex-1 px-3 py-2 bg-theme-surface border border-theme-border-soft rounded-lg text-xs font-medium text-theme-primary focus:border-theme-accent focus:ring-1 focus:ring-theme-accent transition-all"
                                    />
                                  </div>
                                  <div className="flex gap-2 justify-end">
                                    <button
                                      onClick={() => setUpdatingInvoiceId(null)}
                                      className="px-3 py-1.5 rounded-lg text-xs font-bold text-theme-muted hover:bg-theme-surface transition-colors"
                                      disabled={isSaving}
                                    >
                                      Cancel
                                    </button>
                                    <button
                                      onClick={() => handleUpdatePayment(inv)}
                                      disabled={!paymentAmount || isSaving}
                                      className="px-4 py-1.5 bg-theme-success hover:bg-emerald-600 text-white rounded-lg text-xs font-bold shadow-md shadow-emerald-500/20 disabled:opacity-50 flex items-center gap-1.5 transition-all"
                                    >
                                      {isSaving ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Save className="w-3.5 h-3.5" />}
                                      Update
                                    </button>
                                  </div>
                                </div>
                              ) : (
                                <button
                                  onClick={() => {
                                    setUpdatingInvoiceId(inv.id);
                                    setPaymentAmount(inv.balanceDue || (inv.total - (inv.amountPaid || 0)));
                                  }}
                                  className="w-full py-2 bg-theme-surface hover:bg-emerald-50 dark:hover:bg-emerald-500/10 border border-theme-border-soft hover:border-emerald-200 dark:hover:border-emerald-500/30 text-emerald-600 dark:text-emerald-400 rounded-xl text-xs font-bold flex items-center justify-center gap-1.5 transition-all"
                                >
                                  <Banknote className="w-3.5 h-3.5" /> Record Payment
                                </button>
                              )}
                            </div>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
            
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
};

export default CustomerLedger;

import React, { useState } from 'react';
import { 
  FileText, Columns, Droplet, ArrowUp, ArrowDown, Eye, EyeOff, 
  Building, DollarSign, Palette, ShieldCheck, Trash2 
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import PdfTemplateStudio from '../../pages/PdfTemplateStudio';

const InvoiceCustomizationPanel = ({ 
  businessSettings,
  setBusinessSettings,
  viewMode,
  setViewMode,
  subscription,
  selectedTemplate,
  onSelectTemplate,
  discountType,
  setDiscountType,
  discountAmount,
  setDiscountAmount,
  taxPercent,
  setTaxPercent,
  shipping,
  setShipping,
  invoiceColumns = [],
  setInvoiceColumns,
  notes,
  setNotes,
  activeTab
}) => {

  const tabs = [
    { id: 'templates', label: 'Templates', icon: Palette },
    { id: 'columns', label: 'Columns & Tables', icon: Columns },
    { id: 'branding', label: 'Branding & Text', icon: FileText },
    { id: 'financial', label: 'Bank & Payments', icon: DollarSign },
  ];

  const handleUpdateSettings = (updates) => {
    setBusinessSettings(prev => ({
      ...prev,
      ...updates
    }));
  };

  const handleUpdateBuilderSettings = (updates) => {
    handleUpdateSettings({
      invoiceBuilderSettings: {
        ...(businessSettings?.invoiceBuilderSettings || {}),
        ...updates
      }
    });
  };

  const handleColumnToggle = (id) => {
    const newCols = invoiceColumns.map(c => c.id === id ? { ...c, visible: !c.visible } : c);
    setInvoiceColumns(newCols);
  };

  const moveColumn = (index, direction) => {
    if (direction === -1 && index === 0) return;
    if (direction === 1 && index === invoiceColumns.length - 1) return;

    const newCols = [...invoiceColumns];
    const temp = newCols[index];
    newCols[index] = newCols[index + direction];
    newCols[index + direction] = temp;

    const reordered = newCols.map((c, i) => ({ ...c, order: i + 1 }));
    setInvoiceColumns(reordered);
  };

  const builderSettings = businessSettings?.invoiceBuilderSettings || {};
  const customColumns = builderSettings.customColumns || [];
  const taxLabel = builderSettings.taxLabel || 'Tax';
  const showDiscount = builderSettings.showDiscount !== false;
  const invoiceItemLabel = builderSettings.itemLabel || 'Item';

  return (
    <div className="bg-theme-surface border border-theme-border-soft p-4 md:p-6 rounded-2xl mb-8 shadow-sm">
      <AnimatePresence mode="wait">
        <motion.div
          key={activeTab}
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -10 }}
          transition={{ duration: 0.2 }}
          className="space-y-6"
        >
          {/* TEMPLATES TAB */}
          {activeTab === 'templates' && (
            <div className="card-premium p-6 overflow-hidden">
              <PdfTemplateStudio 
                businessSettings={businessSettings} 
                setSettings={handleUpdateSettings} 
                viewMode={viewMode} 
                setViewMode={setViewMode} 
                subscription={subscription}
                templateOverride={selectedTemplate}
                onSelectTemplate={onSelectTemplate}
              />
            </div>
          )}

          {/* COLUMNS & TABLES TAB */}
          {activeTab === 'columns' && (
            <div className="space-y-6">
              <div className="card-premium p-6">
                <div className="flex items-center gap-3 mb-6 border-b border-theme-border-soft pb-4">
                  <div className="w-10 h-10 rounded-xl bg-theme-success/10 text-theme-success flex items-center justify-center">
                    <Columns className="w-5 h-5" />
                  </div>
                  <div>
                    <h2 className="text-lg font-black text-theme-primary">Column Manager</h2>
                    <p className="text-xs text-theme-muted">Show, hide, and reorder invoice item columns</p>
                  </div>
                </div>

                <div className="bg-theme-surface/50 border border-theme-border-soft rounded-2xl overflow-hidden mb-6">
                  {invoiceColumns.map((col, idx) => (
                    <div key={col.id} className="flex items-center justify-between p-3 border-b border-theme-border-soft last:border-b-0 hover:bg-theme-surface transition-colors">
                      <div className="flex items-center gap-3">
                        <button 
                          onClick={() => handleColumnToggle(col.id)}
                          className={`w-8 h-8 rounded-lg flex items-center justify-center transition-colors ${
                            col.visible ? 'bg-theme-success/20 text-theme-success' : 'bg-theme-surface-hover text-theme-muted'
                          }`}
                        >
                          {col.visible ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
                        </button>
                        <span className={`text-sm font-bold ${
                          col.visible ? 'text-theme-primary' : 'text-theme-muted line-through'
                        }`}>{col.label}</span>
                      </div>
                      <div className="flex items-center gap-1">
                        <button 
                          onClick={() => moveColumn(idx, -1)}
                          disabled={idx === 0}
                          className="p-1.5 rounded bg-theme-surface border border-theme-border-soft text-theme-muted hover:text-theme-primary hover:bg-theme-card disabled:opacity-30 disabled:cursor-not-allowed"
                        >
                          <ArrowUp className="w-3 h-3" />
                        </button>
                        <button 
                          onClick={() => moveColumn(idx, 1)}
                          disabled={idx === invoiceColumns.length - 1}
                          className="p-1.5 rounded bg-theme-surface border border-theme-border-soft text-theme-muted hover:text-theme-primary hover:bg-theme-card disabled:opacity-30 disabled:cursor-not-allowed"
                        >
                          <ArrowDown className="w-3 h-3" />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              <div className="card-premium p-6 mt-6">
                  <div className="flex items-center gap-3 mb-6 border-b border-theme-border-soft pb-4">
                    <div className="w-10 h-10 rounded-xl bg-theme-accent/10 text-theme-accent flex items-center justify-center">
                      <FileText className="w-5 h-5" />
                    </div>
                    <div>
                      <h2 className="text-lg font-black text-theme-primary">Custom Columns</h2>
                      <p className="text-xs text-theme-muted">Add extra fields like Size, Color, or Warranty</p>
                    </div>
                  </div>

                  <div className="mb-6">
                    <label className="block text-[10px] font-bold text-theme-muted uppercase tracking-wider mb-2">Item/Product Column Label</label>
                    <input
                      type="text"
                      value={invoiceItemLabel}
                      onChange={(e) => handleUpdateBuilderSettings({ itemLabel: e.target.value })}
                      className="w-full max-w-xs px-4 py-3 bg-theme-surface border border-theme-border-soft rounded-xl focus:outline-none focus:border-theme-accent text-theme-primary font-bold text-sm"
                      placeholder="e.g. Item, Product, Service"
                    />
                  </div>

                  <div>
