          <div className="relative group">
            <IndianRupee className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-rose-500 transition-colors group-focus-within:text-rose-400" />
            <input
              type="number"
              value={state.customer.previousDue || ''}
              onChange={(e) => handleQuickChange('previousDue', e.target.value)}
              placeholder="0.00"
              className="w-full pl-9 pr-2 py-2 rounded-xl bg-theme-app border border-theme-border-soft focus:border-rose-500 focus:ring-2 focus:ring-rose-500/20 outline-none text-theme-primary text-sm font-bold transition-all"
            />
          </div>
        </div>
        <div>
          <label className="block text-[10px] font-bold text-theme-muted mb-1 uppercase tracking-wider ml-1">Last Order</label>
          <div className="relative group">
            <Clock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-theme-muted transition-colors group-focus-within:text-theme-accent" />
            <input
              type="date"
              value={state.customer.lastOrderDate || ''}
              onChange={(e) => handleQuickChange('lastOrderDate', e.target.value)}
              className="w-full pl-9 pr-2 py-2 rounded-xl bg-theme-app border border-theme-border-soft focus:border-theme-accent focus:ring-2 focus:ring-theme-accent/20 outline-none text-theme-primary text-sm font-bold transition-all"
            />
          </div>
        </div>
      </motion.div>
      )}

      {/* AI Customer Insights */}
      <CustomerInsightsPane customerId={state.customer.id} />
    </div>
  );
};

export default SmartCustomerSelect;

import React from 'react';
import { useInvoice } from '../../../contexts/InvoiceContext';
import { Wallet, Banknote, CreditCard, Clock } from 'lucide-react';

const SmartPaymentSection = () => {
  const { state, dispatch } = useInvoice();

  const handlePaymentTypeClick = (type) => {
    let amountPaid = 0;
    
    if (type === 'Paid') {
      amountPaid = state.totals.grandTotal;
    } else if (type === 'Unpaid') {
      amountPaid = 0;
    } else if (type === 'Partial') {
      // Don't auto-fill, keep current or let user type
      amountPaid = state.totals.amountPaid || (state.totals.grandTotal / 2);
    } else if (type === 'Advance') {
      amountPaid = state.totals.amountPaid || 500;
    }

    dispatch({
      type: 'UPDATE_TOTALS',
      payload: { amountPaid }
    });
    dispatch({
      type: 'UPDATE_SETTINGS',
      payload: { paymentStatus: type }
    });
  };

  const paymentOptions = [
    { id: 'Paid', icon: CheckCircleIcon, label: 'Full Paid', color: 'text-theme-success', bg: 'bg-theme-success/10 hover:bg-theme-success/20 border-theme-success/20 hover:border-theme-success' },
    { id: 'Partial', icon: Banknote, label: 'Partial', color: 'text-theme-warning', bg: 'bg-theme-warning/10 hover:bg-theme-warning/20 border-theme-warning/20 hover:border-theme-warning' },
    { id: 'Due', icon: Clock, label: 'Due', color: 'text-theme-danger', bg: 'bg-theme-danger/10 hover:bg-theme-danger/20 border-theme-danger/20 hover:border-theme-danger' }
  ];

  const paymentMethods = ['Cash', 'UPI', 'Bank', 'Card'];

  return (
    <div className="mb-4">
      <p className="text-[10px] font-bold uppercase tracking-wider text-theme-muted mb-2">Payment Status</p>
      <div className="grid grid-cols-3 gap-2 mb-4">
        {paymentOptions.map(opt => {
          const Icon = opt.icon;
          const isActive = state.settings.paymentStatus === opt.id || (opt.id === 'Due' && state.settings.paymentStatus === 'Unpaid');
          return (
            <button
              key={opt.id}
              onClick={() => handlePaymentTypeClick(opt.id === 'Due' ? 'Unpaid' : opt.id)}
              className={`flex items-center justify-center gap-1.5 p-2 rounded-xl border text-[11px] font-bold transition-all ${
                isActive 
                  ? `${opt.bg.split(' ')[0]} ${opt.color} ring-2 ring-current border-transparent shadow-sm` 
                  : `bg-theme-surface border-theme-border-soft text-theme-muted hover:text-theme-primary`
              }`}
            >
              <Icon className="w-3.5 h-3.5" /> {opt.label}
            </button>
          );
        })}
      </div>

      <p className="text-[10px] font-bold uppercase tracking-wider text-theme-muted mb-2">Payment Method</p>
      <div className="flex gap-2 mb-4 overflow-x-auto pb-1 scrollbar-hide">
        {paymentMethods.map(method => (
          <button
            key={method}
            onClick={() => dispatch({ type: 'UPDATE_SETTINGS', payload: { paymentMethod: method } })}
            className={`px-3 py-1.5 rounded-lg text-xs font-bold border transition-colors whitespace-nowrap ${
              state.settings.paymentMethod === method
                ? 'bg-theme-accent/10 border-theme-accent text-theme-accent'
                : 'bg-theme-surface border-theme-border-soft text-theme-muted hover:text-theme-primary'
            }`}
          >
            {method}
          </button>
        ))}
      </div>

      <div className="bg-theme-surface border border-theme-border-soft rounded-xl p-3 flex items-center justify-between">
        <label className="text-xs font-bold text-theme-muted">Amount Received</label>
        <div className="flex items-center">
          <span className="text-theme-muted font-bold mr-2">₹</span>
          <input
            type="number"
            value={state.totals.amountPaid || ''}
            onChange={(e) => {
              const val = parseFloat(e.target.value) || 0;
              dispatch({ type: 'UPDATE_TOTALS', payload: { amountPaid: val } });
            }}
            className="w-24 bg-transparent border-b border-theme-border-soft focus:border-theme-accent outline-none text-right font-black text-theme-primary text-lg transition-colors"
          />
        </div>
      </div>
    </div>
  );
};

// Extracted simple check icon to avoid heavy imports
function CheckCircleIcon(props) {
  return (
    <svg {...props} xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path>
      <polyline points="22 4 12 14.01 9 11.01"></polyline>
    </svg>
  );
}

export default SmartPaymentSection;

import React, { useState } from 'react';
import { useInvoice } from '../../../contexts/InvoiceContext';
import { motion, AnimatePresence } from 'framer-motion';
import { Settings2, Calculator, ChevronUp, ChevronDown, FileText, Link, Loader2 } from 'lucide-react';
import SmartPaymentSection from './SmartPaymentSection';

const StickyTotalPanel = ({ onFinalize, isSaving }) => {
  const { state, dispatch } = useInvoice();
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [showAdjustments, setShowAdjustments] = useState(false);

  const SummaryContent = () => (
    <div className="flex flex-col gap-6">
      <div className="flex items-center justify-between">
        <h2 className="text-sm font-black uppercase tracking-wider text-theme-primary flex items-center gap-2">
          <Calculator className="w-4 h-4 text-theme-accent" /> Summary
        </h2>
        <button 
          onClick={() => setShowAdjustments(!showAdjustments)}
          className="p-1.5 text-theme-muted hover:text-theme-accent transition-colors rounded-lg hover:bg-theme-accent/10 cursor-pointer" 
          title="Toggle Adjustments"
        >
          <Settings2 className="w-4 h-4" />
        </button>
      </div>

      <div className="flex flex-col gap-3">
        <div className="flex items-center justify-between text-sm">
          <span className="font-bold text-theme-muted">Subtotal</span>
          <span className="font-black text-theme-primary tabular-nums">₹{state.totals.subtotal.toLocaleString()}</span>
        </div>

        {/* Collapsible Adjustments */}
        <AnimatePresence>
          {showAdjustments && (
            <motion.div 
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
              exit={{ opacity: 0, height: 0 }}
              className="overflow-hidden flex flex-col gap-3 border-t border-theme-border-soft pt-3"
            >
              <div className="flex items-center justify-between text-sm group">
                <span className="font-bold text-theme-muted flex items-center gap-1.5">
                  Tax
                  <div className="relative">
                    <input 
                      type="number" 
                      value={state.totals.taxPercentage ?? ''} 
                      onChange={(e) => dispatch({ type: 'UPDATE_TOTALS', payload: { taxPercentage: parseFloat(e.target.value) || 0 } })}
                      className="w-12 bg-theme-app border border-theme-border-soft rounded px-1.5 py-0.5 text-xs text-center font-bold focus:border-theme-accent outline-none transition-colors"
                    />
                    <span className="absolute right-1 top-1/2 -translate-y-1/2 text-[10px] text-theme-muted pointer-events-none">%</span>
                  </div>
                </span>
                <span className="font-black text-theme-primary tabular-nums">₹{state.totals.taxAmount.toLocaleString()}</span>
              </div>

              <div className="flex items-center justify-between text-sm group">
                <span className="font-bold text-theme-muted">Discount (₹)</span>
                <div className="relative flex items-center">
                  <span className="text-theme-muted text-xs mr-1 font-bold">-₹</span>
                  <input 
                    type="number" 
                    value={state.totals.discountAmount || ''} 
                    onChange={(e) => dispatch({ type: 'UPDATE_TOTALS', payload: { discountAmount: parseFloat(e.target.value) || 0 } })}
                    className="w-20 bg-theme-app border border-theme-border-soft rounded px-1.5 py-0.5 text-xs text-right font-bold focus:border-theme-accent outline-none transition-colors text-theme-success"
                    placeholder="0"
                  />
                </div>
              </div>

              <div className="border-t border-theme-border-soft pt-3">
                <SmartPaymentSection />
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Toggle adjustments hint link */}
        {!showAdjustments && (
          <button 
            onClick={() => setShowAdjustments(true)}
            className="text-left text-[11px] font-bold text-theme-accent hover:underline flex items-center gap-1 cursor-pointer min-h-[30px]"
          >
            + Add Discount, Tax or Payment details
          </button>
        )}

        <div className="bg-theme-accent/5 border border-theme-accent/30 rounded-2xl p-4 my-2 relative overflow-hidden">
          <p className="text-xs font-black uppercase tracking-widest text-theme-accent mb-1 relative z-10">Grand Total</p>
          <p className="text-3xl font-black text-theme-accent tracking-tight relative z-10 tabular-nums">₹{state.totals.grandTotal.toLocaleString()}</p>
        </div>
      </div>

      <div className="flex flex-col gap-3 mt-2">
        <button
          onClick={onFinalize}
          disabled={isSaving}
          className="w-full h-[52px] bg-theme-accent text-white rounded-2xl flex items-center justify-center font-black text-sm cursor-pointer transition-colors hover:opacity-90 disabled:opacity-50"
        >
          {isSaving ? (
            <Loader2 className="w-4 h-4 animate-spin mr-2" />
          ) : (
            <Link className="w-4 h-4 mr-2" />
          )}
          Generate Live Link
        </button>
      </div>
    </div>
  );

  return (
    <>
      {/* Desktop Vertical Sidebar */}
      <div className="hidden lg:flex w-full bg-theme-surface flex-col p-6">
        <SummaryContent />
      </div>

      {/* Mobile Bottom Drawer Toggle */}
      <div className="lg:hidden">
        <div className="fixed bottom-0 left-0 right-0 z-50">
          <AnimatePresence>
            {isDrawerOpen && (
              <>
                <motion.div 
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                  onClick={() => setIsDrawerOpen(false)}
                  className="fixed inset-0 bg-black/40 backdrop-blur-sm z-40"
                />
                <motion.div 
                  initial={{ y: '100%' }}
                  animate={{ y: 0 }}
                  exit={{ y: '100%' }}
                  transition={{ type: 'spring', damping: 25, stiffness: 200 }}
                  className="absolute bottom-0 left-0 right-0 bg-theme-surface rounded-t-3xl border-t border-theme-border-soft p-6 z-50 max-h-[85vh] overflow-y-auto"
                >
                  <div className="w-12 h-1.5 bg-theme-border-soft rounded-full mx-auto mb-6" />
                  <SummaryContent />
                </motion.div>
              </>
            )}
          </AnimatePresence>

          {!isDrawerOpen && (
            <motion.div 
              initial={{ y: '100%' }}
              animate={{ y: 0 }}
              className="bg-theme-surface/95 backdrop-blur-xl border-t border-theme-border-soft p-4 flex items-center justify-between safe-bottom"
              onClick={() => setIsDrawerOpen(true)}
            >
              <div className="flex flex-col">
                <span className="text-[10px] font-bold text-theme-muted uppercase tracking-wider">Grand Total</span>
                <span className="text-xl font-black text-theme-primary tabular-nums">₹{state.totals.grandTotal.toLocaleString()}</span>
              </div>
              <button className="flex items-center gap-2 bg-theme-accent text-white px-5 py-2.5 rounded-2xl font-black transition-colors min-h-[48px]">
                Summary <ChevronUp className="w-4 h-4" />
              </button>
            </motion.div>
          )}
        </div>
      </div>
    </>
  );
};

export default StickyTotalPanel;

import React from 'react';
import { useInvoice } from '../../../contexts/InvoiceContext';
import { Loader2, Cloud, CloudOff, FileText, Eye, ArrowLeft, Save } from 'lucide-react';

const StudioHeader = ({ showPreviewModal, setShowPreviewModal, lastSaved, saveStatus, isSaving, onSaveDraft, onDownloadPDF, onBack }) => {
