          onClick={onSaveDraft}
          disabled={isSaving || saveStatus === 'saved'}
          className="flex items-center justify-center gap-1.5 px-4 py-2 bg-theme-accent hover:bg-theme-accent/90 text-white text-[10px] font-black uppercase tracking-wider rounded-xl transition-all shadow-sm disabled:opacity-50"
        >
          {isSaving ? (
            <><Loader2 className="w-4 h-4 animate-spin" /> Saving Draft</>
          ) : (
            <><Save className="w-4 h-4" /> Save Draft</>
          )}
        </button>

        {/* Preview Button */}
        <button
          onClick={() => setShowPreviewModal(true)}
          className="flex items-center justify-center gap-1.5 px-4 py-2 bg-theme-surface hover:bg-theme-border-soft text-theme-primary text-[10px] font-black uppercase tracking-wider rounded-xl transition-all shadow-sm border border-theme-border-soft"
        >
          <Eye className="w-4 h-4 text-theme-accent" /> Preview
        </button>

        {/* Download PDF Button */}
        <button
          onClick={onDownloadPDF}
          disabled={isSaving}
          className="flex items-center justify-center gap-1.5 px-4 py-2 bg-theme-surface hover:bg-theme-border-soft text-theme-primary text-[10px] font-black uppercase tracking-wider rounded-xl transition-all shadow-sm border border-theme-border-soft disabled:opacity-50"
        >
          <FileText className="w-4 h-4 text-rose-500" /> Download PDF
        </button>

      </div>
    </div>
  );
};

export default StudioHeader;

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ArrowLeft, ArrowRight, Save, Eye, Loader2, Check } from 'lucide-react';
import { useInvoice } from '../../../contexts/InvoiceContext';
import { toast } from 'react-hot-toast';
import { auth } from '../../../services/firebaseConfig';
import { generateInvoiceNumber } from '../../../services/invoiceNumberService';
import { ShimmerButton } from '../../magicui/shimmer-button';

import CustomerSelectionStep from './steps/CustomerSelectionStep';
import ItemsSelectionStep from './steps/ItemsSelectionStep';
import PaymentDiscountStep from './steps/PaymentDiscountStep';
import PreviewDownloadStep from './steps/PreviewDownloadStep';

const STEPS = [
  { id: 1, title: '১. কাস্টমার নির্বাচন' },
  { id: 2, title: '২. ইনভয়েস আইটেম' },
  { id: 3, title: '৩. পেমেন্ট ও ডিসকাউন্ট' },
  { id: 4, title: '৪. প্রিভিউ ও সেভ' }
];

const CreateInvoiceWizard = ({ onSaveInvoice, onDownloadPDF, setCurrentTab, customers, products }) => {
  const [currentStep, setCurrentStep] = useState(1);
  const { state, dispatch, businessSettings } = useInvoice();

  // Generate Invoice Number if missing
  useEffect(() => {
    const initNumber = async () => {
      if (!state.invoiceNumber && !state.generatingNumber) {
        dispatch({ type: 'GENERATE_INVOICE_NUMBER_START' });
        try {
          const userId = auth?.currentUser?.uid;
          if (userId) {
            const newNum = await generateInvoiceNumber(userId);
            dispatch({ type: 'SET_INVOICE_NUMBER', payload: newNum });
          } else {
            // Fallback for demo mode
            dispatch({ type: 'SET_INVOICE_NUMBER', payload: `INV-${new Date().getFullYear()}-${Math.floor(Math.random()*1000)}` });
          }
        } catch (err) {
          console.error("Number generation failed:", err);
          dispatch({ type: 'SET_INVOICE_NUMBER', payload: `INV-MANUAL-${Math.floor(Math.random()*1000)}` });
        }
      }
    };
    initNumber();
  }, [state.invoiceNumber, state.generatingNumber, dispatch]);

  const handleSave = (statusOverride, isSilent = false) => {
    // Basic validation before saving
    if (!state.customer.name && statusOverride !== 'Draft') {
      if (!isSilent) toast.error('Please add a customer name before saving the final invoice.');
      return;
    }

    // Clean items
    const cleanedItems = state.items.filter(item => 
      (item.description && item.description.trim() !== '') || 
      (item.designNo && item.designNo.trim() !== '') || 
      (parseFloat(item.rate) > 0)
    ).map(item => {
      const qty = parseFloat(item.qty);
      const rate = parseFloat(item.rate !== undefined ? item.rate : (item.unitPrice !== undefined ? item.unitPrice : item.price));
      return {
        ...item,
        qty: isNaN(qty) ? 1 : qty,
        rate: isNaN(rate) ? 0 : rate,
        amount: (isNaN(qty) ? 1 : qty) * (isNaN(rate) ? 0 : rate)
      };
    });

    if (cleanedItems.length === 0 && statusOverride !== 'Draft') {
      if (!isSilent) toast.error('Please add at least one item before saving.');
      return;
    }

    const payload = {
      id: state.id,
      invoiceNumber: state.invoiceNumber,
      date: state.date,
      dueDate: state.dueDate,
      billType: state.billType,
      customerId: state.customer.id || null,
      customerName: state.customer.name,
      customerPhone: state.customer.phone,
      customerEmail: state.customer.email,
      customerAddress: state.customer.address,
      items: cleanedItems,
      taxPercentage: state.totals.taxPercentage,
      taxAmount: state.totals.taxAmount,
      discountAmount: state.totals.discountAmount,
      amountPaid: state.totals.amountPaid,
      balanceDue: state.totals.balanceDue,
      notes: state.settings.notes,
      terms: state.settings.terms,
      paymentStatus: typeof statusOverride === 'string' ? statusOverride : state.settings.paymentStatus,
      paymentMethod: state.settings.paymentMethod,
      paymentNote: state.settings.paymentNote,
      orderStatus: state.settings.orderStatus,
      subtotal: state.totals.subtotal,
      grandTotal: state.totals.grandTotal,
      paymentProofs: state.paymentProofs,
      // Pass the business snapshot
      businessSnapshot: businessSettings,
      paymentSettingsSnapshot: businessSettings,
      regionalSettingsSnapshot: businessSettings
    };

    onSaveInvoice(payload, state.saveCustomer && !state.customer.id, isSilent);
    if (!isSilent && statusOverride !== 'Draft') {
      toast.success('Invoice saved successfully!');
    }
  };

  const handleNext = () => {
    // Validate Step 1
    if (currentStep === 1) {
      if (!state.customer.name) {
        toast.error('Customer Name is required');
        return;
      }
    }
    // Validate Step 2
    if (currentStep === 2) {
      const hasValidItem = state.items.some(i => i.description || i.designNo || i.rate > 0);
      if (!hasValidItem) {
        toast.error('Please add at least one item');
        return;
      }
    }
    if (currentStep < 4) setCurrentStep(s => s + 1);
  };

  const handlePrev = () => {
    if (currentStep > 1) setCurrentStep(s => s - 1);
  };

  const containerVariants = {
    hidden: { opacity: 0, x: 20 },
    show: { opacity: 1, x: 0, transition: { duration: 0.3 } },
    exit: { opacity: 0, x: -20, transition: { duration: 0.2 } }
  };

  return (
    <div className="flex flex-col min-h-screen pb-24 md:pb-8">
      {/* Header */}
      <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4 mb-6">
        <div>
          <h1 className="text-2xl font-black text-theme-primary">
            {state.id.startsWith('inv-') && !state.isInitialized ? 'Create Invoice' : 'Invoice Details'}
          </h1>
          <p className="text-sm font-bold text-theme-muted mt-1">Step {currentStep} of 4: {STEPS[currentStep-1].title}</p>
        </div>
        
        <div className="flex flex-col sm:flex-row gap-3 w-full md:w-auto">
          {/* Invoice Number Display/Override */}
          <div className="flex items-center bg-theme-surface dark:bg-theme-card border border-theme-border-soft rounded-xl overflow-hidden px-3 py-1.5 min-w-[200px]">
            <span className="text-[10px] font-black uppercase text-theme-muted tracking-wider mr-2">Invoice #</span>
            {state.generatingNumber ? (
              <div className="flex items-center gap-1.5 text-theme-accent">
                <Loader2 className="w-3.5 h-3.5 animate-spin" />
                <span className="text-xs font-bold">Generating...</span>
              </div>
            ) : (
              <input 
                type="text" 
                value={state.invoiceNumber}
                onChange={(e) => dispatch({ type: 'SET_INVOICE_NUMBER', payload: e.target.value.toUpperCase() })}
                className="bg-transparent border-none outline-none text-theme-primary font-bold text-sm w-32 focus:ring-0 p-0"
                placeholder="INV-XXXX-XXX"
              />
            )}
          </div>
          
          <button 
            onClick={() => handleSave('Draft')}
            className="flex items-center justify-center gap-2 px-4 py-2 bg-theme-surface hover:bg-theme-border-soft text-theme-primary font-bold rounded-xl transition-all shadow-sm border border-theme-border-soft"
          >
            <Save className="w-4 h-4 text-theme-muted" />
            <span className="hidden sm:inline">Save Draft</span>
          </button>
        </div>
      </div>

      {/* Progress Bar */}
      <div className="flex items-center justify-between mb-16 relative px-2 md:px-8">
        <div className="absolute left-6 right-6 md:left-12 md:right-12 top-1/2 -translate-y-1/2 h-1 bg-theme-border-soft rounded-full z-0" />
        <div 
          className="absolute left-6 md:left-12 top-1/2 -translate-y-1/2 h-1 bg-theme-accent rounded-full z-0 transition-all duration-500 ease-in-out" 
          style={{ width: `calc(${((currentStep - 1) / (STEPS.length - 1)) * 100}% - ${currentStep === 1 ? '0px' : '48px'})` }}
        />
        
        {STEPS.map((step) => {
          const isCompleted = currentStep > step.id;
          const isCurrent = currentStep === step.id;
          
          return (
            <div key={step.id} className="relative z-10 flex flex-col items-center">
              <div 
                className={`w-8 h-8 md:w-10 md:h-10 rounded-full flex items-center justify-center font-bold text-sm transition-all duration-300 ${
                  isCompleted 
                    ? 'bg-theme-accent text-white scale-100 shadow-lg shadow-theme-glow' 
                    : isCurrent 
                      ? 'bg-theme-card border-2 border-theme-accent text-theme-accent scale-110 shadow-xl' 
                      : 'bg-theme-surface border-2 border-theme-border-soft text-theme-muted scale-95'
                }`}
              >
                {isCompleted ? <Check className="w-5 h-5" /> : step.id}
              </div>
              <span 
                className={`absolute top-12 text-center w-20 md:w-32 text-[10px] md:text-xs font-bold transition-colors duration-300 ${
                  isCurrent ? 'text-theme-accent' : isCompleted ? 'text-theme-primary' : 'text-theme-muted hidden sm:block'
                }`}
              >
                {step.title}
              </span>
            </div>
          );
        })}
      </div>

      {/* Step Content */}
      <div className="flex-1">
        <AnimatePresence mode="wait">
          <motion.div
            key={currentStep}
            variants={containerVariants}
            initial="hidden"
            animate="show"
            exit="exit"
            className="h-full"
          >
            {currentStep === 1 && <CustomerSelectionStep customers={customers} />}
            {currentStep === 2 && <ItemsSelectionStep products={products} />}
            {currentStep === 3 && <PaymentDiscountStep />}
            {currentStep === 4 && <PreviewDownloadStep onDownloadPDF={onDownloadPDF} handleSave={handleSave} />}
          </motion.div>
        </AnimatePresence>
      </div>

      {/* Bottom Fixed Navigation (Mobile friendly) */}
      <div className="fixed bottom-0 left-0 right-0 md:relative md:mt-8 bg-theme-card border-t border-theme-border-soft md:border-none p-4 md:p-0 z-40 md:bg-transparent shadow-[0_-10px_30px_rgba(0,0,0,0.05)] md:shadow-none">
        <div className="max-w-7xl mx-auto flex flex-col-reverse md:flex-row justify-between gap-3 md:gap-4">
          <button
            onClick={handlePrev}
            disabled={currentStep === 1}
            className={`w-full md:w-auto flex items-center justify-center gap-2 px-6 py-3.5 rounded-xl font-bold transition-all min-h-[48px] ${
              currentStep === 1 
                ? 'opacity-50 cursor-not-allowed bg-theme-surface text-theme-muted' 
                : 'bg-theme-surface hover:bg-theme-border-soft text-theme-primary'
            }`}
          >
            <ArrowLeft className="w-5 h-5" /> Previous
          </button>
          
          {currentStep < 4 ? (
            <ShimmerButton
              onClick={handleNext}
              className="w-full md:w-auto min-h-[48px] shadow-lg shadow-theme-glow"
              shimmerColor="#ffffff"
              background="var(--accent-gradient)"
            >
              <div className="flex items-center gap-2 text-theme-button-text font-black">
                Next <ArrowRight className="w-5 h-5" />
              </div>
            </ShimmerButton>
          ) : (
            <ShimmerButton
              onClick={() => handleSave('Pending')}
              className="w-full md:w-auto min-h-[48px] shadow-lg"
              shimmerColor="#ffffff"
              background="var(--status-success)"
            >
              <div className="flex items-center gap-2 text-white font-black">
                <Save className="w-5 h-5" /> Finalize Invoice
              </div>
            </ShimmerButton>
          )}
        </div>
      </div>
    </div>
  );
};

export default CreateInvoiceWizard;

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { User, Phone, Mail, MapPin, Search, FileText, Check } from 'lucide-react';
import * as Icons from 'lucide-react';
import { useInvoice } from '../../../../contexts/InvoiceContext';
import { invoiceTemplates } from '../../../../config/invoiceTemplates';
import { getCustomerLabelByType } from '../../../../config/businessPresets';

const CustomerSelectionStep = ({ customers = [] }) => {
  const { state, dispatch, businessSettings } = useInvoice();
  const wsType = businessSettings?.businessWorkspaces?.find(ws => ws.id === businessSettings.activeWorkspaceId)?.type || businessSettings?.businessType || 'retail';
  const customerLabel = getCustomerLabelByType(wsType);
  const { customer, saveCustomer } = state;
  const [searchTerm, setSearchTerm] = useState('');

  const handleCustomerSelect = (e) => {
    const custId = e.target.value;
    if (custId === '') {
      dispatch({ type: 'UPDATE_CUSTOMER', payload: { id: '', name: '', phone: '', email: '', address: '' } });
      return;
    }
    const client = customers.find(c => c.id === custId);
    if (client) {
      dispatch({ 
        type: 'UPDATE_CUSTOMER', 
        payload: { id: client.id, name: client.name, phone: client.phone || '', email: client.email || '', address: client.address || '' } 
      });
      setSearchTerm('');
    }
  };

  const handleFieldChange = (field, value) => {
    dispatch({ 
      type: 'UPDATE_CUSTOMER', 
      payload: { [field]: value } 
    });
  };

  return (
    <div className="bg-theme-card border border-theme-border-soft rounded-3xl p-6 shadow-premium h-full flex flex-col overflow-y-auto">
      {/* TEMPLATE SELECTOR */}
      <div className="mb-8">
        <h3 className="text-lg font-semibold mb-4 flex items-center gap-2 text-theme-primary">
          <FileText className="w-5 h-5 text-theme-accent" />
          বিল টেমপ্লেট নির্বাচন করুন
        </h3>
        
        <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
          {invoiceTemplates.map((template) => {
            const IconComponent = Icons[template.icon];
            return (
              <motion.button
                key={template.id}
                whileHover={{ scale: 1.05, y: -2 }}
                whileTap={{ scale: 0.95 }}
                onClick={() => dispatch({ type: 'SET_TEMPLATE', payload: template.id })}
                className={`
                  p-4 rounded-xl border-2 transition-all text-left relative overflow-hidden flex flex-col items-start
                  ${state.selectedTemplate === template.id
                    ? `border-theme-accent bg-theme-accent/5 shadow-lg`
                    : 'border-theme-border-soft hover:border-theme-accent/50 bg-theme-surface'
                  }
                `}
              >
                {IconComponent && <IconComponent className={`w-8 h-8 mb-2 ${state.selectedTemplate === template.id ? 'text-theme-accent' : 'text-theme-muted'}`} />}
                <p className="font-bold text-sm text-theme-primary">{template.name}</p>
                <p className="text-[10px] text-theme-muted font-bold uppercase tracking-wider">{template.nameEn}</p>
                
                {/* Selected indicator */}
                {state.selectedTemplate === template.id && (
                  <motion.div
                    initial={{ scale: 0 }}
                    animate={{ scale: 1 }}
                    className="absolute top-3 right-3"
                  >
                    <Check className="w-5 h-5 text-theme-accent" />
                  </motion.div>
                )}
              </motion.button>
            );
          })}
        </div>
      </div>

      <div className="mb-6 border-t border-theme-border-soft pt-6">
        <h2 className="text-xl font-extrabold text-theme-primary">{customerLabel} Details</h2>
        <p className="text-sm text-theme-muted font-medium mt-1">Select an existing {customerLabel.toLowerCase()} or enter new details.</p>
      </div>

      {customers.length > 0 && (
        <div className="mb-8 p-4 bg-theme-surface rounded-2xl border border-theme-border-soft">
          <label className="block text-xs font-bold text-theme-muted uppercase tracking-wider mb-3">Quick Select</label>
          <div className="relative">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-theme-muted" />
            <select
              value={customer.id || ''}
              onChange={handleCustomerSelect}
              className="w-full pl-10 pr-4 py-3 bg-theme-card border border-theme-border-soft rounded-xl text-sm font-semibold focus:outline-none focus:ring-2 focus:ring-theme-accent/30 focus:border-theme-accent transition-all text-theme-primary appearance-none"
            >
              <option value="">-- Add New {customerLabel} --</option>
              {customers.map(c => (
                <option key={c.id} value={c.id}>{c.name} {c.phone ? `(${c.phone})` : ''}</option>
              ))}
            </select>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-5 flex-1">
        {/* Name */}
        <div className="space-y-1.5 md:col-span-2">
          <label className="block text-xs font-bold text-theme-muted uppercase tracking-wider">{customerLabel} Name <span className="text-theme-danger">*</span></label>
          <div className="relative">
            <User className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-theme-muted" />
            <input
              type="text"
              value={customer.name}
              onChange={(e) => handleFieldChange('name', e.target.value)}
              placeholder="e.g. Acme Corp"
              className={`w-full pl-10 pr-4 py-3.5 bg-theme-surface border rounded-xl text-sm font-bold focus:outline-none focus:ring-2 focus:ring-theme-accent/30 transition-all ${!customer.name && customer.id === '' ? 'border-theme-warning/50 focus:border-theme-warning text-theme-primary' : 'border-theme-border-soft focus:border-theme-accent text-theme-primary'}`}
            />
          </div>
        </div>

        {/* Phone */}
        <div className="space-y-1.5">
          <label className="block text-xs font-bold text-theme-muted uppercase tracking-wider">Phone</label>
          <div className="relative">
            <Phone className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-theme-muted" />
            <input
              type="tel"
              value={customer.phone}
              onChange={(e) => handleFieldChange('phone', e.target.value)}
              placeholder="e.g. +91 98765 43210"
              className="w-full pl-10 pr-4 py-3.5 bg-theme-surface border border-theme-border-soft rounded-xl text-sm font-semibold focus:outline-none focus:ring-2 focus:ring-theme-accent/30 focus:border-theme-accent transition-all text-theme-primary"
            />
          </div>
        </div>

        {/* Email */}
        <div className="space-y-1.5">
          <label className="block text-xs font-bold text-theme-muted uppercase tracking-wider">Email</label>
          <div className="relative">
            <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-theme-muted" />
            <input
              type="email"
              value={customer.email}
              onChange={(e) => handleFieldChange('email', e.target.value)}
              placeholder="e.g. client@example.com"
              className="w-full pl-10 pr-4 py-3.5 bg-theme-surface border border-theme-border-soft rounded-xl text-sm font-semibold focus:outline-none focus:ring-2 focus:ring-theme-accent/30 focus:border-theme-accent transition-all text-theme-primary"
            />
          </div>
        </div>

        {/* Address */}
        <div className="space-y-1.5 md:col-span-2">
          <label className="block text-xs font-bold text-theme-muted uppercase tracking-wider">Address</label>
          <div className="relative h-full">
            <MapPin className="absolute left-4 top-4 w-4 h-4 text-theme-muted" />
            <textarea
              value={customer.address}
              onChange={(e) => handleFieldChange('address', e.target.value)}
              placeholder="Billing Address..."
              rows={3}
              className="w-full pl-10 pr-4 py-3.5 bg-theme-surface border border-theme-border-soft rounded-xl text-sm font-semibold focus:outline-none focus:ring-2 focus:ring-theme-accent/30 focus:border-theme-accent transition-all text-theme-primary resize-none"
            />
          </div>
        </div>
      </div>

      {!customer.id && customer.name && (
        <motion.div 
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          className="mt-6 p-4 bg-theme-accent-light border border-theme-accent/20 rounded-2xl flex items-center justify-between"
        >
          <div>
          <p className="text-sm font-bold text-theme-primary">Save {customerLabel} to CRM?</p>
          <p className="text-xs font-medium text-theme-muted">Save this {customerLabel.toLowerCase()} for faster billing next time.</p>
          </div>
          <label className="relative inline-flex items-center cursor-pointer">
            <input type="checkbox" checked={saveCustomer} onChange={(e) => dispatch({ type: 'UPDATE_SAVE_CUSTOMER', payload: e.target.checked })} className="sr-only peer" />
            <div className="w-11 h-6 bg-theme-border-strong rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-0.5 after:left-[2px] after:bg-white after:border-theme-border-soft after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-theme-accent"></div>
          </label>
        </motion.div>
      )}
    </div>
  );
};

export default CustomerSelectionStep;

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { useInvoice } from '../../../../contexts/InvoiceContext';
import { invoiceTemplates } from '../../../../config/invoiceTemplates';
import { Plus, Trash2, GripVertical, Package, X } from 'lucide-react';
import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
} from '@dnd-kit/core';
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
  useSortable
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import * as Icons from 'lucide-react';
import ProductSearch from '../../ProductSearch';

const CustomTemplateBuilder = ({ templateFields, setTemplateFields }) => {
  const addField = (type) => {
    const newField = {
      id: `field_${Date.now()}`,
      label: '',
      labelEn: '',
      type: type,
      required: false
    };
    setTemplateFields([...templateFields, newField]);
  };
  
  return (
    <div className="p-6 bg-theme-surface rounded-2xl border border-theme-border-soft mb-6">
      <h4 className="font-extrabold text-theme-primary mb-4 text-sm">Build Custom Template Fields</h4>
      
      <div className="flex gap-2 mb-6">
        <button type="button" onClick={() => addField('text')} className="px-4 py-2 bg-blue-500/10 text-blue-500 hover:bg-blue-500/20 rounded-xl text-xs font-bold transition-all">
          + Text Field
        </button>
        <button type="button" onClick={() => addField('number')} className="px-4 py-2 bg-green-500/10 text-green-500 hover:bg-green-500/20 rounded-xl text-xs font-bold transition-all">
          + Number Field
        </button>
        <button type="button" onClick={() => addField('select')} className="px-4 py-2 bg-purple-500/10 text-purple-500 hover:bg-purple-500/20 rounded-xl text-xs font-bold transition-all">
          + Dropdown
        </button>
      </div>
      
      <div className="space-y-3">
        {templateFields.map((field, idx) => (
          <div key={field.id} className="flex items-center gap-3 p-3 bg-theme-card rounded-xl border border-theme-border-soft">
            <input
              placeholder="Field Label (e.g. Serial No)"
              value={field.label}
              onChange={(e) => {
                const updated = [...templateFields];
                updated[idx].label = e.target.value;
                setTemplateFields(updated);
              }}
              className="flex-1 px-3 py-2 bg-theme-surface border border-theme-border-soft rounded-lg text-sm font-bold text-theme-primary focus:outline-none focus:border-theme-accent"
            />
            <span className="text-[10px] font-black uppercase text-theme-muted bg-theme-surface px-2 py-1 rounded">{field.type}</span>
            <button type="button" onClick={() => setTemplateFields(templateFields.filter(f => f.id !== field.id))} className="text-theme-danger hover:bg-theme-danger/10 p-2 rounded-lg">
              <X className="w-4 h-4" />
            </button>
          </div>
        ))}
      </div>
    </div>
  );
};

const SortableItem = ({ id, item, index, handleItemChange, removeItemRow, templateFields, currencySymbol, products }) => {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging
  } = useSortable({ id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    zIndex: isDragging ? 100 : 1,
  };

  return (
    <div 
      ref={setNodeRef} 
      style={style} 
      className={`relative flex items-start gap-3 p-4 bg-theme-surface border ${isDragging ? 'border-theme-accent shadow-2xl opacity-50 scale-95 rotate-2 z-50' : 'border-theme-border-soft hover:border-theme-border-strong'} rounded-2xl transition-all duration-300 group origin-center`}
    >
      <div 
        {...attributes} 
        {...listeners} 
        className="mt-3 cursor-grab active:cursor-grabbing text-theme-muted hover:text-theme-primary transition-colors"
      >
        <GripVertical className="w-5 h-5" />
      </div>

      <div className="flex-1 flex flex-wrap gap-3">
        {templateFields.map((field) => {
          let flexBasis = 'flex-1 min-w-[120px]';
          if (field.id === 'item' || field.id === 'product' || field.id === 'service' || field.id === 'design' || field.id === 'issue' || field.id === 'patientName') {
            flexBasis = 'flex-[2] min-w-[200px]';
          }
          if (field.type === 'calculated') {
            flexBasis = 'min-w-[100px]';
          }

          return (
            <div key={field.id} className={`${flexBasis} space-y-1`}>
              <label className="block text-[10px] font-bold text-theme-muted uppercase tracking-wider">{field.label}</label>
              
              {field.type === 'text' && (
                <>
                  {['item', 'product', 'service', 'description'].includes(field.id) ? (
                    <ProductSearch 
                      value={item[field.id] || ''}
                      onChange={(val) => handleItemChange(index, field.id, val)}
                      onSelectProduct={(p) => {
                        const updates = { [field.id]: p.name || p.productName };
                        if (p.price || p.rate) {
                          const rateField = templateFields.find(f => ['rate', 'mrp', 'price'].includes(f.id));
                          if (rateField) updates[rateField.id] = p.price || p.rate;
                        }
                        handleItemChange(index, updates);
                      }}
                      products={products}
                      placeholder={field.labelEn || "Search product..."}
                    />
                  ) : (
                    <input
                      type="text"
                      value={item[field.id] || ''}
                      onChange={(e) => handleItemChange(index, field.id, e.target.value)}
                      className="w-full px-4 py-2.5 bg-theme-card border border-theme-border-soft rounded-xl text-sm font-bold focus:outline-none focus:ring-2 focus:ring-theme-accent/30 focus:border-theme-accent text-theme-primary transition-all"
                      placeholder={field.labelEn}
                    />
                  )}
                </>
              )}
              
              {field.type === 'number' && (
                <div className="relative">
                  {['rate', 'mrp', 'fee', 'labor', 'parts', 'amount'].includes(field.id) && <span className="absolute left-3 top-1/2 -translate-y-1/2 text-theme-muted font-bold text-sm">{currencySymbol}</span>}
                  <input
                    type="number"
                    value={item[field.id] === 0 ? '' : item[field.id] || ''}
                    onChange={(e) => handleItemChange(index, field.id, e.target.value)}
                    className={`w-full px-4 py-2.5 bg-theme-card border border-theme-border-soft rounded-xl text-sm font-bold focus:outline-none focus:ring-2 focus:ring-theme-accent/30 focus:border-theme-accent text-theme-primary transition-all ${['rate', 'mrp', 'fee', 'labor', 'parts', 'amount'].includes(field.id) ? 'pl-8 text-right' : 'text-center'}`}
                    placeholder="0"
                  />
                </div>
              )}
              
              {field.type === 'select' && (
                <select
                  value={item[field.id] || (field.options && field.options[0]) || ''}
                  onChange={(e) => handleItemChange(index, field.id, e.target.value)}
                  className="w-full px-4 py-2.5 bg-theme-card border border-theme-border-soft rounded-xl text-sm font-bold focus:outline-none focus:ring-2 focus:ring-theme-accent/30 focus:border-theme-accent text-theme-primary transition-all"
                >
                  {field.options && field.options.map(opt => (
                    <option key={opt} value={opt}>{opt}</option>
                  ))}
                </select>
              )}
              
              {field.type === 'calculated' && (
                <div className="w-full px-4 py-2.5 bg-theme-app border border-theme-border-soft rounded-xl text-sm font-black text-theme-accent flex items-center justify-end">
                  {currencySymbol}{(item.amount || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                </div>
              )}
            </div>
          );
        })}
      </div>

      <button
        type="button"
        onClick={() => removeItemRow(index)}
        className="mt-2.5 p-2 text-theme-danger/70 hover:text-theme-danger hover:bg-theme-danger/10 rounded-xl transition-all"
        title="Remove Item"
      >
        <Trash2 className="w-4 h-4" />
      </button>
    </div>
  );
};

const ItemsSelectionStep = ({ products = [] }) => {
  const { state, dispatch, businessSettings } = useInvoice();
  const { items, selectedTemplate, templateFields } = state;
  const currencySymbol = businessSettings?.currency || '₹';
  
  const currentTemplate = invoiceTemplates.find(t => t.id === selectedTemplate) || invoiceTemplates[0];
  const TemplateIcon = currentTemplate.icon ? Icons[currentTemplate.icon] : null;

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  const handleDragEnd = (event) => {
    const { active, over } = event;
    if (active.id !== over.id) {
      const oldIndex = items.findIndex((item) => item.id === active.id);
      const newIndex = items.findIndex((item) => item.id === over.id);
      const newItems = arrayMove(items, oldIndex, newIndex);
      dispatch({ type: 'SET_ITEMS', payload: newItems });
    }
  };

  const setCustomTemplateFields = (newFields) => {
    dispatch({
        type: 'INIT_INVOICE',
        payload: { templateFields: newFields }
    });
  };

  const safeEval = (expr) => {
    const cleaned = expr.replace(/[^0-9+\-*/.() ]/g, '');
    if (cleaned !== expr.trim()) return NaN;
    try {
      return Function('"use strict"; return (' + cleaned + ')')();
    } catch { return NaN; }
  };

  const calculateFieldValue = (item, formula) => {
    if (!formula) return 0;
    try {
      let evaluated = formula;
      Object.keys(item).forEach(key => {
        const val = parseFloat(item[key]) || 0;
        evaluated = evaluated.replace(new RegExp(`\\b${key}\\b`, 'g'), val);
      });
      const result = safeEval(evaluated);
      return isNaN(result) ? 0 : result;
    } catch {
      return 0;
    }
  };

  const handleItemChange = (index, fieldOrUpdates, optionalValue) => {
    const newItems = [...items];
    
    if (typeof fieldOrUpdates === 'string') {
        const field = fieldOrUpdates;
        const isNumField = templateFields.find(f => f.id === field)?.type === 'number';
        newItems[index][field] = isNumField ? (optionalValue === '' ? '' : (parseFloat(optionalValue) || 0)) : optionalValue;
    } else {
        Object.entries(fieldOrUpdates).forEach(([field, val]) => {
            const isNumField = templateFields.find(f => f.id === field)?.type === 'number';
            newItems[index][field] = isNumField ? (val === '' ? '' : (parseFloat(val) || 0)) : val;
        });
    }

    // Auto-calculate formula fields
    const calcField = templateFields.find(f => f.type === 'calculated');
    if (calcField && calcField.formula) {
        newItems[index].amount = calculateFieldValue(newItems[index], calcField.formula);
    }

    dispatch({ type: 'SET_ITEMS', payload: newItems });
  };

  const handleAddItem = () => {
    const generateId = () => {
      try {
        return crypto.randomUUID();
      } catch {
        return `item-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
      }
    };

    const newItem = { 
        ...currentTemplate.defaultItem, 
        id: generateId(),
        sn: items.length + 1
    };
    dispatch({ type: 'SET_ITEMS', payload: [...items, newItem] });
  };

  const removeItemRow = (index) => {
    const newItems = items.filter((_, i) => i !== index);
    dispatch({ type: 'SET_ITEMS', payload: newItems });
  };

  return (
    <div className="bg-theme-card border border-theme-border-soft rounded-3xl p-6 shadow-premium h-full flex flex-col">
      <div className="flex items-center justify-between gap-4 mb-6">
        <div>
          <h2 className="text-xl font-extrabold text-theme-primary flex items-center gap-2">
            {TemplateIcon && <TemplateIcon className="w-6 h-6 text-theme-accent" />}
            {currentTemplate.name} Items
          </h2>
          <p className="text-sm text-theme-muted font-medium mt-1">Add products or services and drag to reorder.</p>
        </div>
        
        <button
          onClick={handleAddItem}
          className="px-4 py-2 bg-theme-accent text-white rounded-xl hover:shadow-lg transition-all font-bold text-sm hidden sm:block"
        >
          + Add Item
        </button>
      </div>

      {selectedTemplate === 'custom' && (
        <CustomTemplateBuilder 
          templateFields={templateFields} 
          setTemplateFields={setCustomTemplateFields} 
        />
      )}

      {/* ITEMS LIST */}
      <div className="flex-1 overflow-y-auto pr-2 space-y-3 pb-6">
        {items.length === 0 ? (
           <div className="text-center py-16 border-2 border-dashed border-theme-border-soft rounded-2xl">
            <Package className="w-16 h-16 mx-auto text-theme-border-strong mb-4" />
            <p className="text-theme-muted font-bold mb-4">No items added yet</p>
            <button
              onClick={handleAddItem}
              className="px-6 py-3 bg-theme-accent text-white rounded-xl font-bold hover:shadow-lg transition-all"
            >
              Add First Item
            </button>
          </div>
        ) : (
            <DndContext
            sensors={sensors}
            collisionDetection={closestCenter}
            onDragEnd={handleDragEnd}
            >
            <SortableContext
                items={items.map(i => i.id)}
                strategy={verticalListSortingStrategy}
            >
                {items.map((item, index) => (
                <SortableItem 
                    key={item.id}
                    id={item.id}
                    item={item}
                    index={index}
                    handleItemChange={handleItemChange}
                    removeItemRow={removeItemRow}
                    templateFields={templateFields}
                    currencySymbol={currencySymbol}
                    products={products}
                />
                ))}
            </SortableContext>
            </DndContext>
        )}

        {items.length > 0 && (
            <motion.button
            whileHover={{ scale: 1.01 }}
            whileTap={{ scale: 0.99 }}
            onClick={handleAddItem}
            className="w-full mt-4 py-4 border-2 border-dashed border-theme-border-strong hover:border-theme-accent text-theme-muted hover:text-theme-accent bg-theme-surface hover:bg-theme-accent-light rounded-2xl flex items-center justify-center gap-2 text-sm font-black transition-colors"
            >
            <Plus className="w-5 h-5" /> Add Another Item
            </motion.button>
        )}
      </div>

      <div className="mt-4 pt-4 border-t border-theme-border-soft flex justify-end">
        <div className="text-right">
          <p className="text-xs font-bold text-theme-muted uppercase tracking-wider mb-1">Subtotal</p>
          <p className="text-2xl font-black text-theme-primary">{currencySymbol}{state.totals.subtotal.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</p>
        </div>
      </div>
    </div>
  );
};

