export const Modal = ({ isOpen, onClose, title, children, className = '' }) => {
  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div 
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4"
        >
          <motion.div 
            role="dialog"
            aria-modal="true"
            aria-labelledby={title ? "modal-title" : undefined}
            initial={{ scale: 0.95, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            exit={{ scale: 0.95, opacity: 0 }}
            className={`bg-theme-surface border border-theme-border-soft rounded-3xl w-full overflow-hidden shadow-glass flex flex-col max-h-[90vh] ${className}`}
          >
            {title && (
              <div className="flex justify-between items-center p-6 border-b border-theme-border-soft bg-theme-surface-elevated shrink-0">
                <h3 id="modal-title" className="text-xl font-black text-theme-primary leading-tight">{title}</h3>
                <button onClick={onClose} aria-label="Close modal" className="p-2 text-theme-muted hover:text-theme-primary bg-theme-surface-hover rounded-xl transition-colors">
                  <X className="w-5 h-5" />
                </button>
              </div>
            )}
            <div className="overflow-y-auto no-scrollbar flex-1">
              {children}
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

import React from 'react';
import { motion } from 'framer-motion';

export const Progress = ({ value = 0, max = 100, className = '', colorClass = 'bg-theme-accent', shadowClass = 'shadow-[0_0_10px_var(--accent)]' }) => {
  const percentage = Math.min(100, Math.max(0, (value / max) * 100));
  
  return (
    <div className={`w-full bg-theme-border-soft h-1.5 rounded-full overflow-hidden ${className}`}>
      <motion.div 
        initial={{ width: 0 }}
        animate={{ width: `${percentage}%` }}
        transition={{ duration: 1, ease: "easeOut" }}
        className={`h-full rounded-full ${colorClass} ${shadowClass}`} 
      />
    </div>
  );
};

export const ProgressRing = ({ value = 0, max = 100, size = 120, strokeWidth = 8, color = 'var(--accent)', label, sublabel }) => {
  const radius = (size - strokeWidth) / 2;
  const circumference = radius * 2 * Math.PI;
  const percentage = Math.min(100, Math.max(0, (value / max) * 100));
  const strokeDashoffset = circumference - (percentage / 100) * circumference;

  return (
    <div className="relative flex items-center justify-center" style={{ width: size, height: size }}>
      <svg width={size} height={size} className="transform -rotate-90">
        {/* Background circle */}
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          stroke="var(--border-soft)"
          strokeWidth={strokeWidth}
          fill="transparent"
        />
        {/* Progress circle */}
        <motion.circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          stroke={color}
          strokeWidth={strokeWidth}
          fill="transparent"
          strokeDasharray={circumference}
          initial={{ strokeDashoffset: circumference }}
          animate={{ strokeDashoffset }}
          transition={{ duration: 1.5, ease: "easeOut" }}
          strokeLinecap="round"
          style={{ filter: `drop-shadow(0 0 4px ${color})` }}
        />
      </svg>
      <div className="absolute flex flex-col items-center justify-center text-center">
        {label && <span className="text-xl font-black text-theme-primary">{label}</span>}
        {sublabel && <span className="text-[10px] text-theme-secondary font-bold uppercase tracking-wider mt-0.5">{sublabel}</span>}
      </div>
    </div>
  );
};

