          <motion.div variants={modalContentVariants} initial="hidden" animate="visible" exit="exit" className="card-premium w-full max-w-lg max-h-[90vh] overflow-y-auto p-5 sm:p-6" onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-5">
              <div>
                <h3 className="text-base font-black text-theme-primary">New Appointment</h3>
                <p className="text-[10px] font-bold text-theme-muted uppercase tracking-wider mt-0.5">SCHEDULE A VISIT</p>
              </div>
              <button onClick={() => setShowModal(false)} className="w-8 h-8 rounded-xl bg-theme-surface dark:bg-theme-card flex items-center justify-center text-theme-muted hover:text-theme-primary transition-colors">
                <X className="w-4 h-4" />
              </button>
            </div>
            <form onSubmit={handleCreate} className="space-y-4">
              <div>
                <label className="block text-[11px] font-extrabold text-theme-primary mb-1.5 uppercase tracking-wider">Customer</label>
                {customers.length > 0 ? (
                  <select value={formData.customerId} onChange={handleCustomerSelect} className="input-premium w-full">
                    <option value="">Select a customer or type below</option>
                    {customers.map(c => (
                      <option key={c.id} value={c.id}>{c.name}{c.phone ? ` — ${c.phone}` : ''}</option>
                    ))}
                  </select>
                ) : null}
                <input type="text" placeholder="Customer name" value={formData.customerName} onChange={e => setFormData(f => ({ ...f, customerName: e.target.value }))} className="input-premium w-full mt-2" required />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-[11px] font-extrabold text-theme-primary mb-1.5 uppercase tracking-wider">Date</label>
                  <input type="date" value={formData.date} onChange={e => setFormData(f => ({ ...f, date: e.target.value }))} className="input-premium w-full" required />
                </div>
                <div>
                  <label className="block text-[11px] font-extrabold text-theme-primary mb-1.5 uppercase tracking-wider">Time</label>
                  <input type="time" value={formData.time} onChange={e => setFormData(f => ({ ...f, time: e.target.value }))} className="input-premium w-full" />
                </div>
              </div>
              <div>
                <label className="block text-[11px] font-extrabold text-theme-primary mb-1.5 uppercase tracking-wider">Service Type</label>
                <input type="text" placeholder="e.g. Consultation, Follow-up, Repair" value={formData.serviceType} onChange={e => setFormData(f => ({ ...f, serviceType: e.target.value }))} className="input-premium w-full" required />
              </div>
              <div>
                <label className="block text-[11px] font-extrabold text-theme-primary mb-1.5 uppercase tracking-wider">Phone (optional)</label>
                <input type="tel" placeholder="Customer phone number" value={formData.customerPhone} onChange={e => setFormData(f => ({ ...f, customerPhone: e.target.value }))} className="input-premium w-full" />
              </div>
              <div>
                <label className="block text-[11px] font-extrabold text-theme-primary mb-1.5 uppercase tracking-wider">Notes (optional)</label>
                <textarea rows={3} placeholder="Any notes or details about this appointment..." value={formData.notes} onChange={e => setFormData(f => ({ ...f, notes: e.target.value }))} className="input-premium w-full resize-none" />
              </div>
              <div className="flex items-center gap-3 pt-2">
                <button type="button" onClick={() => setShowModal(false)} className="btn-premium-ghost flex-1 py-3 text-xs font-extrabold uppercase tracking-wider">
                  Cancel
                </button>
                <button type="submit" className="btn-premium flex-1 py-3 bg-theme-accent text-white rounded-2xl text-xs font-extrabold uppercase tracking-wider flex items-center justify-center gap-2 hover:opacity-90 transition-all">
                  <Plus className="w-4 h-4" />
                  Create
                </button>
              </div>
            </form>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );

  const visibleGroups = ['Today', 'Tomorrow', 'This Week'];
  const hasAppointments = visibleGroups.some(g => grouped[g]?.length > 0) || grouped.Past.length > 0 || grouped.Later.length > 0;

  return (
    <motion.div variants={pageVariants} initial="initial" animate="animate" className="space-y-6 pb-24">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-extrabold text-theme-primary tracking-tight">Appointments</h2>
          <p className="text-[10px] text-theme-muted font-bold uppercase tracking-wider mt-0.5">SCHEDULE & MANAGE VISITS</p>
        </div>
        <button onClick={openCreateModal} className="flex items-center justify-center gap-2 bg-gradient-to-tr from-theme-accent to-theme-accent-dark text-white font-extrabold text-xs px-5 py-3.5 rounded-2xl shadow-md hover:scale-[1.02] active:scale-[0.98] transition-all">
          <Plus className="w-4 h-4" />
          <span>New Appointment</span>
        </button>
      </div>

      {loading ? renderSkeletons() : (
        <>
          <motion.div variants={staggerContainer} initial="hidden" animate="visible" className="stats-grid">
            {renderStats()}
          </motion.div>

          {hasAppointments ? (
            <div>
              {visibleGroups.map(g => renderGroup(g, grouped[g]))}
              {renderGroup('Past Appointments', grouped.Past)}
              {renderGroup('Upcoming', grouped.Later)}
            </div>
          ) : renderEmpty()}
        </>
      )}

      {renderModal()}
    </motion.div>
  );
};

export default Appointments;

import React, { useState, useEffect, useMemo } from 'react';
import { motion } from 'framer-motion';
import { ArrowLeft, Shield, Clock, Activity, Search, Download, Trash2, Filter, X, AlertTriangle } from 'lucide-react';
import { BillQyroDB } from '../services/localDb';
import { pageVariants, staggerContainer, staggerItem } from '../utils/animations';

const AuditLogs = ({ setCurrentTab }) => {
  const [logs, setLogs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [actionFilter, setActionFilter] = useState('');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [page, setPage] = useState(1);
  const [showConfirm, setShowConfirm] = useState(false);
  const perPage = 15;

  useEffect(() => { loadLogs(); }, []);

  const loadLogs = async () => {
    setLoading(true);
    try {
      const allLogs = await BillQyroDB.getAll('auditLogs');
      const sorted = (allLogs || []).sort((a, b) => b.createdAt - a.createdAt);
      setLogs(sorted);
    } catch (e) { console.error(e); }
    setLoading(false);
  };

  const uniqueActions = useMemo(() => {
    const set = new Set(logs.map(l => l.action));
    return ['', ...Array.from(set)];
  }, [logs]);

  const stats = useMemo(() => {
    const now = new Date();
    const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
    const weekStart = new Date(now.getFullYear(), now.getMonth(), now.getDate() - now.getDay()).getTime();
    return {
      total: logs.length,
      today: logs.filter(l => l.createdAt >= todayStart).length,
      week: logs.filter(l => l.createdAt >= weekStart).length
    };
  }, [logs]);

  const filtered = useMemo(() => {
    return logs.filter(log => {
      if (search) {
        const q = search.toLowerCase();
        const userMatch = (log.userEmail || log.userId || '').toLowerCase().includes(q);
        const actionMatch = (log.action || '').toLowerCase().includes(q);
        if (!userMatch && !actionMatch) return false;
      }
      if (actionFilter && log.action !== actionFilter) return false;
      if (dateFrom && log.createdAt < new Date(dateFrom).getTime()) return false;
      if (dateTo) {
        const end = new Date(dateTo);
        end.setHours(23, 59, 59, 999);
        if (log.createdAt > end.getTime()) return false;
      }
      return true;
    });
  }, [logs, search, actionFilter, dateFrom, dateTo]);

  const totalPages = Math.max(1, Math.ceil(filtered.length / perPage));
  const paginated = filtered.slice((page - 1) * perPage, page * perPage);

  useEffect(() => { setPage(1); }, [search, actionFilter, dateFrom, dateTo]);
  useEffect(() => { if (page > totalPages) setPage(totalPages); }, [totalPages, page]);

  const exportCSV = () => {
    const headers = ['Timestamp', 'Action', 'Entity Type', 'Entity ID', 'Actor Role', 'User Email', 'Device Info', 'Details'];
    const rows = filtered.map(log => [
      new Date(log.createdAt).toISOString(),
      log.action,
      log.entityType || '',
      log.entityId || '',
      log.actorRole || '',
      log.userEmail || '',
      `"${(log.deviceInfo || '').replace(/"/g, '""')}"`,
      `"${(log.details || '').replace(/"/g, '""')}"`
    ]);
    const csv = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = `audit_logs_${new Date().toISOString().slice(0, 10)}.csv`;
    a.click(); URL.revokeObjectURL(url);
  };

  const clearAll = async () => {
    try {
      const allLogs = await BillQyroDB.getAll('auditLogs');
      for (const log of allLogs) await BillQyroDB.delete('auditLogs', log.id);
      setLogs([]);
    } catch (e) { console.error(e); }
    setShowConfirm(false);
  };

  const clearFilters = () => { setSearch(''); setActionFilter(''); setDateFrom(''); setDateTo(''); };

  return (
    <motion.div variants={pageVariants} initial="initial" animate="animate" className="max-w-6xl mx-auto pb-12 relative font-sans space-y-6">
      <button onClick={() => setCurrentTab('more')} className="flex items-center gap-2 text-theme-muted hover:text-theme-primary transition-colors cursor-pointer">
        <ArrowLeft className="w-4 h-4" />
        <span className="text-xs font-bold uppercase tracking-wider">Back</span>
      </button>

      <div className="card-premium p-6 md:p-8">
        <div className="flex items-center gap-4 mb-8 pb-6 border-b border-theme-border-soft">
          <div className="w-12 h-12 bg-theme-accent/10 rounded-xl flex items-center justify-center text-theme-accent">
            <Shield className="w-6 h-6" />
          </div>
          <div>
            <h1 className="text-2xl font-black text-theme-primary tracking-tight">Audit Logs</h1>
            <p className="text-sm text-theme-muted font-medium mt-1">Append-only security and action tracing.</p>
          </div>
        </div>

        {loading ? (
          <div className="text-center text-theme-muted py-8 text-sm">Loading logs...</div>
        ) : (
          <motion.div variants={staggerContainer} initial="hidden" animate="visible" className="space-y-6">
            <motion.div variants={staggerItem} className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              <div className="stat-premium">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-xl bg-theme-accent/10 flex items-center justify-center text-theme-accent"><Activity className="w-5 h-5" /></div>
                  <div><p className="text-xs text-theme-muted font-medium">Total Events</p><p className="text-xl font-black text-theme-primary">{stats.total.toLocaleString()}</p></div>
                </div>
              </div>
              <div className="stat-premium">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-xl bg-emerald-500/10 flex items-center justify-center text-emerald-500"><Clock className="w-5 h-5" /></div>
                  <div><p className="text-xs text-theme-muted font-medium">Today</p><p className="text-xl font-black text-theme-primary">{stats.today.toLocaleString()}</p></div>
                </div>
              </div>
              <div className="stat-premium">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-xl bg-violet-500/10 flex items-center justify-center text-violet-500"><Shield className="w-5 h-5" /></div>
                  <div><p className="text-xs text-theme-muted font-medium">This Week</p><p className="text-xl font-black text-theme-primary">{stats.week.toLocaleString()}</p></div>
                </div>
              </div>
            </motion.div>

            <motion.div variants={staggerItem}>
              <div className="section-header flex-wrap gap-3">
                <div className="flex items-center gap-2 flex-wrap">
                  <div className="relative">
                    <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-theme-muted" />
                    <input type="text" placeholder="Search user or action..." value={search} onChange={e => setSearch(e.target.value)} className="input-premium pl-9 w-52" />
                  </div>
                  <select value={actionFilter} onChange={e => setActionFilter(e.target.value)} className="input-premium w-40">
                    <option value="">All Actions</option>
                    {uniqueActions.filter(Boolean).map(a => <option key={a} value={a}>{a}</option>)}
                  </select>
                  <input type="date" value={dateFrom} onChange={e => setDateFrom(e.target.value)} className="input-premium w-36" />
                  <span className="text-xs text-theme-muted">to</span>
                  <input type="date" value={dateTo} onChange={e => setDateTo(e.target.value)} className="input-premium w-36" />
                  {(search || actionFilter || dateFrom || dateTo) && (
                    <button onClick={clearFilters} className="btn-premium-ghost text-xs flex items-center gap-1"><X className="w-3 h-3" /> Clear</button>
                  )}
                </div>
                <div className="flex items-center gap-2">
                  <span className="badge-premium badge-info text-xs">{filtered.length} records</span>
                  <button onClick={exportCSV} className="btn-premium text-xs flex items-center gap-1.5"><Download className="w-3 h-3" /> Export CSV</button>
                  <button onClick={() => setShowConfirm(true)} className="btn-premium-outline text-xs text-red-500 border-red-500/30 hover:bg-red-500/10 flex items-center gap-1.5"><Trash2 className="w-3 h-3" /> Clear All</button>
                </div>
              </div>

              {filtered.length === 0 ? (
                <div className="empty-state">
                  <div className="empty-state-icon"><Filter className="w-5 h-5" /></div>
                  <p className="empty-state-title">No matching logs</p>
                  <p className="empty-state-text">Try adjusting your filters or search query.</p>
                </div>
              ) : (
                <div className="overflow-x-auto">
                  <table className="table-premium min-w-[700px]">
                    <thead>
                      <tr>
                        <th>Timestamp</th>
                        <th>Action</th>
                        <th>Entity</th>
                        <th>Actor Role</th>
                        <th>User</th>
                        <th>Device Info</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-theme-border-soft/50">
                      {paginated.map(log => (
                        <motion.tr key={log.id} variants={staggerItem} className="hover:bg-theme-bg-soft/50 transition-colors cursor-default">
                          <td className="text-xs text-theme-secondary whitespace-nowrap">
                            <div className="flex items-center gap-1.5">
                              <Clock className="w-3 h-3 opacity-50 shrink-0" />
                              {new Date(log.createdAt).toLocaleString()}
                            </div>
                          </td>
                          <td><span className="badge-premium bg-theme-accent/10 text-theme-accent text-xs border border-theme-accent/20">{log.action}</span></td>
                          <td className="text-sm text-theme-secondary truncate max-w-[130px]">{log.entityType} ({log.entityId})</td>
                          <td className="text-sm text-theme-secondary">{log.actorRole || '-'}</td>
                          <td className="text-xs text-theme-muted truncate max-w-[120px]" title={log.userEmail || log.userId}>{log.userEmail || log.userId || '-'}</td>
                          <td className="text-xs text-theme-muted truncate max-w-[160px]" title={log.deviceInfo}>{log.deviceInfo || '-'}</td>
                        </motion.tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}

              <div className="flex items-center justify-between pt-4 border-t border-theme-border-soft">
                <span className="text-xs text-theme-muted">Page {page} of {totalPages}</span>
                <div className="flex items-center gap-2">
                  <button disabled={page <= 1} onClick={() => setPage(p => p - 1)} className="btn-premium-outline text-xs px-3 py-1.5 disabled:opacity-30">Previous</button>
                  <button disabled={page >= totalPages} onClick={() => setPage(p => p + 1)} className="btn-premium text-xs px-3 py-1.5 disabled:opacity-30">Next</button>
                </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </div>

      {showConfirm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm" onClick={() => setShowConfirm(false)}>
          <div className="card-premium p-6 max-w-sm w-full mx-4 space-y-4" onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-red-500/10 flex items-center justify-center text-red-500"><AlertTriangle className="w-5 h-5" /></div>
              <div><p className="text-sm font-bold text-theme-primary">Clear All Logs?</p><p className="text-xs text-theme-muted mt-0.5">This action cannot be undone.</p></div>
            </div>
            <div className="flex gap-3">
              <button onClick={() => setShowConfirm(false)} className="btn-premium-outline flex-1 text-xs">Cancel</button>
              <button onClick={clearAll} className="btn-premium flex-1 text-xs bg-red-500 hover:bg-red-600 border-none">Delete All</button>
            </div>
          </div>
        </div>
      )}
    </motion.div>
  );
};

export default AuditLogs;

import React, { useState, useRef, useEffect } from 'react';
import { motion } from 'framer-motion';
import { 
  Database, 
  DownloadCloud, 
  UploadCloud, 
  AlertTriangle, 
  CheckCircle2, 
  ShieldCheck,
  Shield,
  History,
  FileJson,
  Settings,
  RefreshCw,
  Clock,
  Cloud,
  Server,
  ArrowRight,
  Archive
} from 'lucide-react';
import { toast } from 'react-hot-toast';
import { backupEngine } from '../services/backupEngine';

import { pageVariants, staggerContainer, staggerItem, modalOverlayVariants, modalContentVariants } from '../utils/animations';
import { CardSkeleton } from '../components/PremiumSkeleton';
import PremiumEmptyState from '../components/PremiumEmptyState';

const BackupRestore = ({ settings, invoices, customers, products, expenses, onImportBackup }) => {
  const [isExporting, setIsExporting] = useState(false);
  const [isImporting, setIsImporting] = useState(false);
  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [pendingImportData, setPendingImportData] = useState(null);
  const fileInputRef = useRef(null);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedDataTypes, setSelectedDataTypes] = useState({
    invoices: true, customers: true, products: true, expenses: true, settings: true
  });
  const [autoBackupFrequency, setAutoBackupFrequency] = useState('weekly');
  const [isAutoBackupEnabled, setIsAutoBackupEnabled] = useState(false);
  const [progressPercent, setProgressPercent] = useState(0);

  const lastBackupDate = localStorage.getItem('last_backup_date') || 'Never';
  const totalRecords = (invoices?.length || 0) + (customers?.length || 0) + (products?.length || 0) + (expenses?.length || 0);
  const lastExportDate = localStorage.getItem('last_export_date') || 'Never';
  const storageEstimate = Math.max(1, (totalRecords * 0.5)).toFixed(1);

  useEffect(() => {
    const timer = setTimeout(() => setIsLoading(false), 600);
    return () => clearTimeout(timer);
  }, []);

  const handleExport = async () => {
    try {
      setIsExporting(true);
      setProgressPercent(0);
      const progressTimer = setInterval(() => {
        setProgressPercent(p => Math.min(p + 15, 85));
      }, 400);
      const backupData = await backupEngine.exportLocal();
      clearInterval(progressTimer);
      setProgressPercent(100);
      const dataStr = JSON.stringify(backupData, null, 2);
      const dataBlob = new Blob([dataStr], { type: 'application/json' });
      const url = URL.createObjectURL(dataBlob);
      
      const link = document.createElement('a');
      link.href = url;
      const dateStr = new Date().toISOString().split('T')[0];
      link.download = `BillQyro_Backup_${dateStr}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
      
      const now = new Date().toLocaleString();
      localStorage.setItem('last_backup_date', now);
      localStorage.setItem('last_export_date', now);
      
      toast.success('Backup exported successfully!');
    } catch {
      toast.error('Failed to export backup.');
    } finally {
      setIsExporting(false);
      setProgressPercent(0);
    }
  };

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const parsed = JSON.parse(event.target.result);
        
        // Validation check (hardened)
        if (!parsed || typeof parsed !== 'object') {
          throw new Error('Invalid JSON structure. Root must be an object.');
        }
        if (parsed.appName !== 'BillQyro' && !parsed.invoices) {
          throw new Error('Invalid file type. Not a BillQyro backup.');
        }
        if (!Array.isArray(parsed.invoices)) {
          throw new Error('Corrupted data. Invoices data is missing or invalid.');
        }

        // Add default arrays if they are missing (for backward compatibility)
        if (!Array.isArray(parsed.customers)) parsed.customers = [];
        if (!Array.isArray(parsed.products)) parsed.products = [];
        if (!Array.isArray(parsed.expenses)) parsed.expenses = [];
        if (!parsed.settings || typeof parsed.settings !== 'object') parsed.settings = {};

        setPendingImportData(parsed);
        setShowConfirmModal(true);
      } catch (err) {
        console.error("Backup import error:", err);
        toast.error(`Invalid backup file: ${err.message}`);
      }
      // Reset input
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  const confirmImport = () => {
    if (!pendingImportData || !onImportBackup) return;
    
    setIsImporting(true);
    setProgressPercent(0);
    const progressTimer = setInterval(() => {
      setProgressPercent(p => Math.min(p + 25, 90));
    }, 200);
    try {
      onImportBackup(pendingImportData);
      clearInterval(progressTimer);
      setProgressPercent(100);
      toast.success('Data restored successfully!');
      setShowConfirmModal(false);
      setPendingImportData(null);
    } catch {
      toast.error('Failed to restore data.');
    } finally {
      setIsImporting(false);
      setProgressPercent(0);
    }
  };

  return (
    <motion.div
      variants={pageVariants}
      initial="initial"
      animate="animate"
      className="p-4 md:p-8 max-w-5xl mx-auto space-y-6 animate-fade-in relative"
    >
      {isLoading ? (
        <div className="space-y-6">
          {[1,2,3,4].map(i => (
            <CardSkeleton key={i} lines={3} />
          ))}
        </div>
      ) : (
        <motion.div variants={staggerContainer} initial="hidden" animate="visible" className="space-y-6">
      
      {totalRecords === 0 ? (
        <motion.div variants={staggerItem}>
          <PremiumEmptyState
            icon={Database}
            title="No Backup Data Yet"
            description="You haven't created any records yet. Add invoices, customers, products, or expenses first, then come back to create your first backup."
          />
        </motion.div>
      ) : (
        <>

      {/* Header */}
      <motion.div variants={staggerItem} className="section-header flex items-center gap-4 border-b border-theme-border-soft pb-6 mb-6">
        <div className="w-12 h-12 rounded-2xl bg-indigo-50 text-indigo-600 dark:bg-indigo-950/30 dark:text-indigo-400 flex items-center justify-center shadow-sm glass">
          <Database className="w-6 h-6" />
        </div>
        <div>
          <h1 className="text-2xl font-black text-theme-primary tracking-tight">Backup & Restore</h1>
          <p className="text-xs text-theme-muted font-bold mt-1">Keep your business data safe or migrate it to another device.</p>
        </div>
