export default DesignStudio;

import React, { useState, useMemo } from 'react';
import { motion } from 'framer-motion';
import { Clock, Search, CheckCircle2, AlertCircle, CreditCard, ChevronRight, Calendar, X, Bell, User, DollarSign, TrendingUp, TrendingDown, Send, Eye, Ban, Download } from 'lucide-react';
import { pageVariants, staggerContainer, staggerItem } from '../utils/animations';
import { formatCurrency } from '../utils/invoiceUtils';
import { CardSkeleton } from '../components/PremiumSkeleton';
import CustomerLedger from '../components/customers/CustomerLedger';

const DueCenter = ({ customers = [], invoices = [], businessSettings }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCustomer, setSelectedCustomer] = useState(null);
  const [loading, setLoading] = useState(false);
  const currencySymbol = businessSettings?.currency || '₹';

  const dueBills = useMemo(() => {
    return invoices
      .filter(inv => {
        const s = (inv.paymentStatus || '').toLowerCase();
        return s === 'unpaid' || s === 'partial' || s === 'partially paid';
      })
      .map(inv => ({
        ...inv,
        dueAmount: inv.dueAmount || (inv.grandTotal || inv.total || 0) - (inv.amountPaid || 0),
        dueDate: new Date(inv.dueDate || inv.createdAt)
      }))
      .sort((a, b) => a.dueDate - b.dueDate);
  }, [invoices]);

  const grouped = useMemo(() => {
    const now = new Date();
    now.setHours(0, 0, 0, 0);
    const dayOfWeek = now.getDay();
    const endOfWeek = new Date(now);
    endOfWeek.setDate(endOfWeek.getDate() + (6 - dayOfWeek));
    endOfWeek.setHours(23, 59, 59, 999);

    const today = [];
    const thisWeek = [];
    const older = [];

    dueBills.forEach(bill => {
      const due = bill.dueDate;
      if (due <= now) {
        today.push(bill);
      } else if (due <= endOfWeek) {
        thisWeek.push(bill);
      } else {
        older.push(bill);
      }
    });

    return { today, thisWeek, older };
  }, [dueBills]);

  const totalDueToday = useMemo(() => 
    grouped.today.reduce((sum, b) => sum + b.dueAmount, 0)
  , [grouped.today]);

  const totalDueThisWeek = useMemo(() => 
    grouped.thisWeek.reduce((sum, b) => sum + b.dueAmount, 0)
  , [grouped.thisWeek]);

  const totalOverdue = useMemo(() => 
    grouped.today.length
  , [grouped.today]);

  const totalUpcoming = useMemo(() => 
    grouped.older.reduce((sum, b) => sum + b.dueAmount, 0)
  , [grouped.older]);

  const totalOutstanding = useMemo(() => 
    dueBills.reduce((sum, b) => sum + b.dueAmount, 0)
  , [dueBills]);

  const filteredToday = grouped.today.filter(b => 
    b.customerName?.toLowerCase().includes(searchQuery.toLowerCase()) ||
    b.invoiceNumber?.toLowerCase().includes(searchQuery.toLowerCase())
  );
  const filteredThisWeek = grouped.thisWeek.filter(b =>
    b.customerName?.toLowerCase().includes(searchQuery.toLowerCase()) ||
    b.invoiceNumber?.toLowerCase().includes(searchQuery.toLowerCase())
  );
  const filteredOlder = grouped.older.filter(b =>
    b.customerName?.toLowerCase().includes(searchQuery.toLowerCase()) ||
    b.invoiceNumber?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const allFilteredEmpty = filteredToday.length === 0 && filteredThisWeek.length === 0 && filteredOlder.length === 0;

  const getUrgencyBadge = (bill) => {
    const now = new Date();
    now.setHours(0, 0, 0, 0);
    const diffDays = Math.floor((now - bill.dueDate) / (1000 * 60 * 60 * 24));

    if (diffDays > 7) return { label: 'Critical', class: 'badge-danger' };
    if (diffDays > 0) return { label: 'Overdue', class: 'badge-warning' };
    if (diffDays === 0) return { label: 'Due Today', class: 'badge-danger' };
    return { label: 'Upcoming', class: 'badge-info' };
  };

  const getStatusBadge = (bill) => {
    if (bill.status === 'partial') return { label: 'Partial', class: 'badge-warning' };
    return { label: 'Unpaid', class: 'badge-danger' };
  };

  const handleMarkPaid = (bill) => {
    if (bill.customerId) {
      const customer = customers.find(c => c.id === bill.customerId);
      setSelectedCustomer(customer || { id: bill.customerId, name: bill.customerName });
    } else {
      setSelectedCustomer({ id: null, name: bill.customerName });
    }
  };

  const handleOpenCustomer = (bill) => {
    if (bill.customerId) {
      const customer = customers.find(c => c.id === bill.customerId);
      setSelectedCustomer(customer || { id: bill.customerId, name: bill.customerName });
    } else {
      setSelectedCustomer({ id: null, name: bill.customerName });
    }
  };

  const handleSendReminder = (bill) => {
    if (bill.customerId) {
      const customer = customers.find(c => c.id === bill.customerId);
      setSelectedCustomer(customer || { id: bill.customerId, name: bill.customerName });
    } else {
      setSelectedCustomer({ id: null, name: bill.customerName });
    }
  };

  const Section = ({ title, icon: Icon, bills, accent, accentBg, badgeColor }) => {
    if (bills.length === 0 && !searchQuery) return null;
    return (
      <motion.div variants={staggerItem} className="mb-6">
        <div className="section-header">
          <div className="flex items-center gap-2">
            <div className={`w-8 h-8 rounded-xl ${accentBg} flex items-center justify-center`}>
              <Icon className="w-4 h-4 text-white" />
            </div>
            <div>
              <h3 className="section-header-title">{title}</h3>
              <p className="section-header-subtitle">{bills.length} bill{bills.length !== 1 ? 's' : ''}</p>
            </div>
          </div>
          <span className={`badge-premium ${badgeColor}`}>{bills.length} pending</span>
        </div>
        <motion.div variants={staggerContainer} initial="hidden" animate="visible" className="space-y-2">
          {bills.map((bill, idx) => {
            const urgency = getUrgencyBadge(bill);
            const status = getStatusBadge(bill);
            return (
              <motion.div
                key={bill.id}
                variants={staggerItem}
                className="card-premium p-4 group"
              >
                <div className="flex items-center justify-between gap-3">
                  <div className="flex items-center gap-3 flex-1 min-w-0">
                    <div className="w-10 h-10 rounded-xl bg-theme-surface flex items-center justify-center text-theme-muted group-hover:text-theme-accent group-hover:bg-theme-accent/10 transition-colors shrink-0">
                      <User className="w-5 h-5" />
                    </div>
                    <div className="min-w-0 flex-1">
                      <div className="flex items-center gap-2 flex-wrap">
                        <p className="text-sm font-bold text-theme-primary truncate">{bill.customerName || 'Walk-in Customer'}</p>
                        <span className={`badge-premium ${urgency.class}`}>{urgency.label}</span>
                      </div>
                      <div className="flex items-center gap-2 mt-0.5">
                        <p className="text-xs text-theme-muted font-semibold">
                          {bill.invoiceNumber || `#${bill.id?.slice(0, 6)}`}
                        </p>
                        <span className="text-theme-border-strong">•</span>
                        <p className="text-xs text-theme-muted font-semibold">
                          Due {bill.dueDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}
                        </p>
                        <span className={`badge-premium ${status.class}`}>{status.label}</span>
                      </div>
                    </div>
                  </div>
                  <div className="text-right shrink-0">
                    <p className="text-sm font-black text-theme-primary tabular-nums">{formatCurrency(bill.dueAmount, currencySymbol)}</p>
                  </div>
                </div>
                <div className="flex items-center gap-2 mt-3 pt-3 border-t border-theme-border-soft">
                  <button
                    onClick={() => handleMarkPaid(bill)}
                    className="btn-premium-ghost text-[10px] !min-h-[32px] !py-1.5 !px-3"
                  >
                    <CheckCircle2 className="w-3 h-3" /> Mark Paid
                  </button>
                  <button
                    onClick={() => handleSendReminder(bill)}
                    className="btn-premium-ghost text-[10px] !min-h-[32px] !py-1.5 !px-3"
                  >
                    <Send className="w-3 h-3" /> Remind
                  </button>
                  <button
                    onClick={() => handleOpenCustomer(bill)}
                    className="btn-premium-ghost text-[10px] !min-h-[32px] !py-1.5 !px-3"
                  >
                    <Eye className="w-3 h-3" /> Customer
                  </button>
                </div>
              </motion.div>
            );
          })}
          {bills.length === 0 && searchQuery && (
            <div className="empty-state py-6">
              <div className="empty-state-icon">
                <Search className="w-5 h-5" />
              </div>
              <p className="empty-state-title">No results found</p>
              <p className="empty-state-text">No bills match your search for "{searchQuery}"</p>
            </div>
          )}
        </motion.div>
      </motion.div>
    );
  };

  if (loading) {
    return (
      <div className="page-premium">
        <div className="stats-grid mb-6">
          {[1, 2, 3, 4].map(i => (
            <CardSkeleton key={i} lines={2} />
          ))}
        </div>
        <CardSkeleton lines={6} />
      </div>
    );
  }

  return (
    <motion.div
      variants={pageVariants}
      initial="initial"
      animate="animate"
      className="page-premium w-full max-w-full pb-24"
    >
      <div className="hero-premium">
        <h1 className="hero-premium-title">Due Ledger</h1>
        <p className="hero-premium-subtitle">Track and collect pending payments</p>
      </div>

      <div className="stats-grid mb-6">
        <div className="stat-premium">
          <div className="flex items-center justify-between mb-2">
            <div className="icon-premium icon-premium-sm">
              <AlertCircle className="w-4 h-4" />
            </div>
            <span className="badge-premium badge-danger">{totalOverdue} bills</span>
          </div>
          <p className="text-2xs font-bold text-theme-muted uppercase tracking-premium-wide mb-1">Overdue</p>
          <p className="text-xl font-black text-theme-primary tabular-nums">{formatCurrency(totalDueToday, currencySymbol)}</p>
        </div>
        <div className="stat-premium">
          <div className="flex items-center justify-between mb-2">
            <div className="icon-premium icon-premium-sm bg-amber-500/10 text-amber-500">
              <Calendar className="w-4 h-4" />
            </div>
            <span className="badge-premium badge-warning">{grouped.thisWeek.length} bills</span>
          </div>
          <p className="text-2xs font-bold text-theme-muted uppercase tracking-premium-wide mb-1">Due This Week</p>
          <p className="text-xl font-black text-theme-primary tabular-nums">{formatCurrency(totalDueThisWeek, currencySymbol)}</p>
        </div>
        <div className="stat-premium">
          <div className="flex items-center justify-between mb-2">
            <div className="icon-premium icon-premium-sm">
              <Clock className="w-4 h-4" />
            </div>
            <span className="badge-premium badge-info">{grouped.older.length} bills</span>
          </div>
          <p className="text-2xs font-bold text-theme-muted uppercase tracking-premium-wide mb-1">Upcoming</p>
          <p className="text-xl font-black text-theme-primary tabular-nums">{formatCurrency(totalUpcoming, currencySymbol)}</p>
        </div>
        <div className="stat-premium">
          <div className="flex items-center justify-between mb-2">
            <div className="icon-premium icon-premium-sm bg-emerald-500/10 text-emerald-500">
              <DollarSign className="w-4 h-4" />
            </div>
            <span className="badge-premium badge-success">{dueBills.length} total</span>
          </div>
          <p className="text-2xs font-bold text-theme-muted uppercase tracking-premium-wide mb-1">Total Outstanding</p>
          <p className="text-xl font-black text-theme-primary tabular-nums">{formatCurrency(totalOutstanding, currencySymbol)}</p>
        </div>
      </div>

      {/* DUE SUMMARY */}
      <motion.div variants={staggerItem} className="grid grid-cols-2 sm:grid-cols-3 gap-3 mb-4">
        <div className="stat-premium !p-3">
          <p className="text-2xs font-bold text-theme-muted uppercase tracking-premium-wide mb-1">Total Due Amount</p>
          <p className="text-lg font-black text-theme-primary tabular-nums">{formatCurrency(totalOutstanding, currencySymbol)}</p>
        </div>
        <div className="stat-premium !p-3">
          <p className="text-2xs font-bold text-theme-muted uppercase tracking-premium-wide mb-1">Overdue %</p>
          <p className="text-lg font-black text-rose-500 tabular-nums">
            {dueBills.length > 0 ? Math.round((grouped.today.length / dueBills.length) * 100) : 0}%
          </p>
        </div>
        <div className="stat-premium !p-3">
          <p className="text-2xs font-bold text-theme-muted uppercase tracking-premium-wide mb-1">Avg Days Overdue</p>
          <p className="text-lg font-black text-theme-primary tabular-nums">
            {grouped.today.length > 0
              ? Math.round(grouped.today.reduce((s, b) => s + Math.max(0, Math.floor((new Date() - b.dueDate) / (1000 * 60 * 60 * 24))), 0) / grouped.today.length)
              : 0}d
          </p>
        </div>
      </motion.div>

      {/* QUICK ACTIONS */}
      <motion.div variants={staggerItem} className="flex items-center gap-2 mb-4 flex-wrap">
        <button className="btn-premium text-[10px] !min-h-[36px] !px-4 flex items-center gap-1.5 bg-theme-accent text-white">
          <Bell className="w-3.5 h-3.5" /> Send Reminder to All
        </button>
        <button className="btn-premium text-[10px] !min-h-[36px] !px-4 flex items-center gap-1.5 bg-emerald-500 text-white">
          <CheckCircle2 className="w-3.5 h-3.5" /> Mark Paid
        </button>
        <button onClick={() => {
          const csvRows = ['Customer,Invoice No,Due Date,Amount,Status'];
          dueBills.forEach(b => {
            csvRows.push(`"${b.customerName || 'Walk-in'}","${b.invoiceNumber || ''}","${new Date(b.dueDate).toLocaleDateString()}","${formatCurrency(b.dueAmount)}","${b.paymentStatus || 'Unpaid'}"`);
          });
          const blob = new Blob([csvRows.join('\n')], { type: 'text/csv' });
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a'); a.href = url; a.download = 'DueList.csv'; a.click();
          URL.revokeObjectURL(url);
        }} className="btn-premium text-[10px] !min-h-[36px] !px-4 flex items-center gap-1.5 bg-theme-card border border-theme-border-soft text-theme-primary">
          <Download className="w-3.5 h-3.5" /> Export Due List
        </button>
      </motion.div>

      <div className="toolbar-premium mb-6">
        <span className="absolute inset-y-0 left-0 pl-3.5 flex items-center text-theme-muted pointer-events-none">
          <Search className="w-4 h-4" />
        </span>
        <input
          type="text"
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          placeholder="Search by customer or bill number..."
          className="input-premium"
        />
        {searchQuery && (
          <button
            onClick={() => setSearchQuery('')}
            className="btn-premium-ghost !min-h-[44px] !px-3"
          >
            <X className="w-4 h-4" />
          </button>
        )}
      </div>

      <motion.div variants={staggerContainer} initial="hidden" animate="visible">
        <Section
          title="Due Now / Overdue"
          icon={AlertCircle}
          bills={filteredToday}
          accent="bg-rose-500"
          accentBg="bg-rose-500"
          badgeColor="badge-danger"
        />
        <Section
          title="Due This Week"
          icon={Calendar}
          bills={filteredThisWeek}
          accent="bg-amber-500"
          accentBg="bg-amber-500"
          badgeColor="badge-warning"
        />
        <Section
          title="Upcoming"
          icon={Clock}
          bills={filteredOlder}
          accent="bg-theme-accent"
          accentBg="bg-theme-accent"
          badgeColor="badge-info"
        />
      </motion.div>

      {!searchQuery && grouped.today.length === 0 && grouped.thisWeek.length === 0 && grouped.older.length === 0 && (
        <div className="card-premium p-5">
          <div className="empty-state py-6">
            <div className="empty-state-icon">
              <CheckCircle2 className="w-6 h-6" />
            </div>
            <p className="empty-state-title">All clear!</p>
            <p className="empty-state-text">No pending bills due. You're all caught up.</p>
          </div>
          <div className="border-t border-theme-border-soft pt-4 mt-2">
            <p className="text-2xs font-bold text-theme-muted uppercase tracking-premium-wide mb-2">Collection Tips</p>
            <div className="space-y-2">
              <div className="flex items-start gap-2 text-xs text-theme-muted font-semibold">
                <span className="w-5 h-5 rounded-full bg-theme-accent/10 text-theme-accent flex items-center justify-center shrink-0 text-[10px] font-bold">1</span>
                <span>Send invoice reminders 24 hours before the due date for best results.</span>
              </div>
              <div className="flex items-start gap-2 text-xs text-theme-muted font-semibold">
                <span className="w-5 h-5 rounded-full bg-theme-accent/10 text-theme-accent flex items-center justify-center shrink-0 text-[10px] font-bold">2</span>
                <span>Offer a 2% early payment discount to encourage faster settlements.</span>
              </div>
              <div className="flex items-start gap-2 text-xs text-theme-muted font-semibold">
                <span className="w-5 h-5 rounded-full bg-theme-accent/10 text-theme-accent flex items-center justify-center shrink-0 text-[10px] font-bold">3</span>
                <span>Follow up overdue accounts with a phone call — it works better than email.</span>
              </div>
            </div>
          </div>
        </div>
      )}

      {searchQuery && allFilteredEmpty && (
        <div className="card-premium p-5">
          <div className="empty-state py-8">
            <div className="empty-state-icon">
              <Search className="w-5 h-5" />
            </div>
            <p className="empty-state-title">No matching bills</p>
            <p className="empty-state-text">Try adjusting your search to find what you're looking for.</p>
          </div>
        </div>
      )}

      <CustomerLedger
        isOpen={!!selectedCustomer}
        onClose={() => setSelectedCustomer(null)}
        customer={selectedCustomer}
        invoices={invoices}
        currencySymbol={currencySymbol}
      />

      <style dangerouslySetInnerHTML={{__html: `
        @media print {
          body { background: white !important; color: black !important; }
          .no-print { display: none !important; }
          .bg-theme-card { background: white !important; border: 1px solid #ddd !important; box-shadow: none !important; }
          table { width: 100% !important; border-collapse: collapse; }
          th, td { border: 1px solid #ddd; padding: 6px !important; color: black !important; font-size: 10px !important; }
        }
      `}} />
    </motion.div>
  );
};

export default DueCenter;

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import AnimatedPage from '../components/AnimatedPage';
import InvoiceCard from '../components/InvoiceCard';
import InvoicePreview from '../components/InvoicePreview';
import { 
  Search, 
  Plus, 
  FileSpreadsheet, 
  X, 
  Printer, 
  Download, 
  ImageDown,
  Edit,
  Mail,
  Copy,
  Check,
  Share2,
  Link,
  ArrowRightLeft
} from 'lucide-react';
import { createPortal } from 'react-dom';
import { toast } from 'react-hot-toast';
import { 
  generateWhatsAppShareLink, 
  generateEmailShareLink, 
  generateInvoiceShareText 
} from '../utils/shareUtils';
import { invoiceEngine } from '../services/invoiceEngine';
import PullToRefresh from '../components/PullToRefresh';

// Premium WhatsApp Icon SVG Component
const WhatsAppIcon = ({ className = "w-4 h-4" }) => (
  <svg
    viewBox="0 0 24 24"
    fill="currentColor"
    className={className}
  >
    <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L0 24l6.335-1.662c1.746.953 3.71 1.458 5.704 1.459h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413z" />
  </svg>
);

const Estimates = ({ 
  invoices = [], 
  editingInvoice = null,
  onEditInvoice, 
  onDeleteInvoice,
  onDownloadPDF, 
  onDownloadImage, 
  setCurrentTab,
  businessSettings,
  onSaveInvoice
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [viewingEstimate, setViewingEstimate] = useState(null);
  
  const currencySymbol = businessSettings?.currency || '₹';

  useEffect(() => {
    if (editingInvoice && (editingInvoice.billType === 'Estimate' || editingInvoice.billType === 'Quotation' || editingInvoice.documentType === 'estimate' || editingInvoice.documentType === 'quotation')) {
      setViewingEstimate(editingInvoice);
    }
  }, [editingInvoice]);

  // Extract only estimates from the invoices array
  const estimates = invoices.filter(inv => {
    if (inv.isDeleted) return false;
    const type = (inv.billType || inv.documentType || '').toLowerCase();
    return type === 'estimate' || type === 'quotation';
  });

  // Calculate KPIs
  const totalEstimates = estimates.length;
  const pendingCount = estimates.filter(e => !e.status || e.status === 'Draft' || e.status === 'Pending').length;
  const acceptedCount = estimates.filter(e => e.status === 'Accepted').length;
  const convertedCount = estimates.filter(e => e.status === 'Converted').length;

  // Filter Logic
  const filteredEstimates = estimates.filter((inv) => {
    // 1. Filter by Search Query
    const q = searchQuery.toLowerCase();
    const matchSearch = (
      (inv.invoiceNumber || '').toLowerCase().includes(q) ||
      (inv.customerName || '').toLowerCase().includes(q) ||
      (inv.status || inv.paymentStatus || '').toLowerCase().includes(q) ||
      (inv.date || '').includes(q)
    );

    // 2. Filter by Status
    let matchStatus = true;
    if (statusFilter !== 'All') {
      const invStatus = inv.status || 'Pending'; // Default to Pending if no status
      matchStatus = (invStatus === statusFilter) || (invStatus === 'Draft' && statusFilter === 'Pending');
    }

    return matchSearch && matchStatus;
  });

  const handlePrint = () => {
    window.print();
  };

  const handleStatusChange = async (estimate, newStatus) => {
    if (!window.confirm(`Are you sure you want to mark this estimate as ${newStatus}?`)) return;
    
    const updatedEstimate = {
      ...estimate,
      status: newStatus,
      updatedAt: new Date().toISOString()
    };

    await onSaveInvoice(updatedEstimate);
    if (viewingEstimate?.id === estimate.id) {
      setViewingEstimate(updatedEstimate);
    }
    toast.success(`Estimate marked as ${newStatus}`);
  };

  const handleConvertToInvoice = async (estimate) => {
    if (!window.confirm('Convert this estimate into a new invoice? The original estimate will be marked as Converted.')) return;

    try {
      // 1. generate new ID
      const newInvoiceId = crypto.randomUUID();
      const newInvoiceNumber = `INV-${Date.now().toString().slice(-6)}`;
      
      // 2. clone estimate into a new invoice
      const newInvoice = {
        ...estimate,
        id: newInvoiceId,
        invoiceNumber: newInvoiceNumber,
        billType: 'Invoice',
        documentType: 'Invoice',
        amountPaid: 0,
        balanceDue: estimate.grandTotal,
        paymentStatus: 'Unpaid',
        paymentHistory: [],
        paymentProofs: [],
        status: 'Draft',
        publicToken: '', // Clear token so it gets a fresh one
        convertedFromEstimateId: estimate.id,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        isDeleted: false
      };

      // 3. update old estimate status
      const updatedEstimate = {
        ...estimate,
        status: 'Converted',
        convertedToInvoiceId: newInvoiceId,
        updatedAt: new Date().toISOString()
      };

      await onSaveInvoice(newInvoice);
      await onSaveInvoice(updatedEstimate);
      
      if (viewingEstimate?.id === estimate.id) {
        setViewingEstimate(updatedEstimate);
      }
      
      toast.success('Successfully converted to Invoice!');
      
      // Optionally redirect to new invoice
      onEditInvoice(newInvoice);
      setCurrentTab('create-invoice');
      
    } catch (err) {
      console.error(err);
      toast.error('Failed to convert estimate');
    }
  };

  const handleRefresh = async () => {
    await invoiceEngine.syncFromCloud();
    window.dispatchEvent(new Event('billqyro_sync'));
  };

  const containerVariants = {
    hidden: { opacity: 0 },
    show: { opacity: 1, transition: { staggerChildren: 0.1 } }
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 15 },
    show: { opacity: 1, y: 0, transition: { duration: 0.4, ease: 'easeOut' } }
  };

  return (
    <AnimatedPage>
      <PullToRefresh onRefresh={handleRefresh}>
        <motion.div 
        className="space-y-6 pb-24"
        variants={containerVariants}
        initial="hidden"
        animate="show"
      >
      
      {/* Page Header Area */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-base font-extrabold text-theme-primary dark:text-theme-primary tracking-tight">
            Estimates & Quotations
          </h2>
          <p className="text-[10px] text-theme-muted font-bold uppercase tracking-wider mt-0.5">MANAGE QUOTES AND PROPOSALS</p>
        </div>

        <div className="flex items-center gap-3">
          <motion.button
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
            onClick={() => {
              onEditInvoice(null); 
              setCurrentTab('create-invoice');
              // The user needs to manually select "Estimate" in the wizard for now, as CreateInvoiceWizard manages the dropdown
              toast('Remember to select "Estimate" as the Bill Type!', { icon: '💡' });
            }}
            className="flex items-center justify-center gap-2 bg-gradient-to-tr from-theme-accent to-theme-accent-dark text-white font-extrabold text-xs px-5 py-3.5 rounded-2xl shadow-premium transition-shadow cursor-pointer"
          >
            <Plus className="w-4 h-4" />
            <span>Create Estimate</span>
          </motion.button>
        </div>
      </div>

      {/* KPI CARDS */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="bg-theme-card p-4 rounded-2xl border border-theme-border-soft shadow-premium">
          <h3 className="text-[10px] text-theme-muted font-bold uppercase tracking-wider mb-1">Total Estimates</h3>
          <p className="text-2xl font-black text-theme-primary">{totalEstimates}</p>
        </div>
        <div className="bg-theme-card p-4 rounded-2xl border border-theme-border-soft shadow-premium">
          <h3 className="text-[10px] text-theme-muted font-bold uppercase tracking-wider mb-1">Pending</h3>
          <p className="text-2xl font-black text-theme-warning">{pendingCount}</p>
        </div>
        <div className="bg-theme-card p-4 rounded-2xl border border-theme-border-soft shadow-premium">
          <h3 className="text-[10px] text-theme-muted font-bold uppercase tracking-wider mb-1">Accepted</h3>
          <p className="text-2xl font-black text-theme-success">{acceptedCount}</p>
        </div>
        <div className="bg-theme-card p-4 rounded-2xl border border-theme-border-soft shadow-premium">
          <h3 className="text-[10px] text-theme-muted font-bold uppercase tracking-wider mb-1">Converted</h3>
          <p className="text-2xl font-black text-theme-primary">{convertedCount}</p>
        </div>
      </div>

      {/* SEARCH AND FILTERS */}
      <div className="bg-theme-card dark:bg-theme-card rounded-3xl p-4 md:p-5 border border-theme-border-soft dark:border-theme-border-soft shadow-premium flex flex-col md:flex-row gap-4 items-center justify-between">
        
        {/* Left Side: Filter Tabs */}
        <div className="flex gap-1 bg-theme-app dark:bg-theme-surface p-1.5 rounded-2xl w-full md:w-auto overflow-x-auto no-scrollbar">
          {['All', 'Pending', 'Accepted', 'Rejected', 'Converted'].map((status) => (
            <button
              key={status}
              onClick={() => setStatusFilter(status)}
              className={`text-xs font-bold px-4 py-2 rounded-xl transition-all whitespace-nowrap ${
                statusFilter === status
                  ? 'bg-theme-card dark:bg-theme-card text-theme-primary dark:text-theme-primary shadow-sm border border-theme-border-soft dark:border-theme-border-soft/50'
                  : 'text-theme-muted hover:text-theme-muted'
              }`}
            >
              {status}
            </button>
          ))}
        </div>

        {/* Right Side: Search */}
        <div className="relative w-full md:w-80">
          <span className="absolute inset-y-0 left-0 pl-3.5 flex items-center text-theme-muted pointer-events-none">
            <Search className="w-4 h-4" />
          </span>
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search estimate number, client..."
            className="w-full pl-10 pr-4 py-2.5 bg-theme-app dark:bg-theme-surface border border-theme-border-soft dark:border-theme-border-soft/50 rounded-xl text-xs font-semibold focus:outline-none focus:ring-2 focus:ring-theme-accent/30 focus:border-theme-accent focus:bg-theme-card dark:bg-theme-card transition-all text-theme-primary dark:text-theme-primary"
          />
        </div>
      </div>

      {/* ESTIMATES GRID LIST */}
      <div className="space-y-3">
        {filteredEstimates.map((estimate) => (
          <motion.div key={estimate.id} variants={itemVariants}>
              <InvoiceCard
                invoice={estimate}
                currencySymbol={currencySymbol}
                businessSettings={businessSettings}
                onView={(inv) => setViewingEstimate(inv)}
                onEdit={(inv) => {
                  onEditInvoice(inv);
                  setCurrentTab('create-invoice');
                }}
                onDelete={(id) => {
                  onDeleteInvoice(id, false);
                }}
                onDownload={onDownloadPDF}
                isDeleted={false}
              />
          </motion.div>
        ))}

        {filteredEstimates.length === 0 && (
            <div className="bg-theme-card dark:bg-theme-card rounded-3xl p-12 border border-theme-border-soft dark:border-theme-border-soft text-center shadow-premium relative overflow-hidden">
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-[0.03] dark:opacity-5 grayscale">
                <img src="/brand/billqyro-icon.png" alt="Watermark" className="w-64 h-64 object-contain scale-125" />
              </div>
              <div className="relative z-10">
                <img src="/brand/billqyro-icon.png" alt="Empty" className="w-12 h-12 object-contain mx-auto mb-3 opacity-40 grayscale drop-shadow-sm" />
                <h4 className="font-extrabold text-theme-primary dark:text-theme-muted">No estimates yet</h4>
                <p className="text-xs text-theme-muted font-semibold mt-1 max-w-xs mx-auto">
                  Create your first estimate to see it here!
                </p>
              </div>
            </div>
          )}
      </div>

      {/* DYNAMIC ELEVEN-STAR PREVIEW MODAL OVERLAY */}
      {viewingEstimate && createPortal(
        <div 
          onClick={() => {
            setViewingEstimate(null);
            onEditInvoice(null);
          }}
          className="fixed inset-0 z-[9999] overflow-y-auto bg-black/60 dark:bg-black/80 backdrop-blur-sm p-4 sm:p-6 md:p-10 no-print"
        >
          <div 
            onClick={(e) => e.stopPropagation()}
            className="bg-theme-app dark:bg-theme-surface w-full max-w-4xl mx-auto rounded-3xl overflow-hidden shadow-2xl relative animate-scaleUp border border-white/10 flex flex-col my-10"
          >
            
            {/* Modal Top Actions Header Bar */}
            <div className="bg-theme-card dark:bg-theme-card border-b border-theme-border-soft dark:border-theme-border-soft px-6 py-4 flex items-center justify-between shrink-0 flex-wrap gap-4">
              <div className="flex items-center gap-2">
                <FileSpreadsheet className="w-5 h-5 text-theme-accent" />
                <span className="font-extrabold text-theme-primary dark:text-theme-primary text-sm">{viewingEstimate.invoiceNumber} - Preview</span>
                <span className={`px-2 py-0.5 text-[10px] font-black rounded-md ml-2 uppercase ${
                  viewingEstimate.status === 'Accepted' ? 'bg-theme-success/10 text-theme-success' :
                  viewingEstimate.status === 'Rejected' ? 'bg-theme-danger/10 text-theme-danger' :
                  viewingEstimate.status === 'Converted' ? 'bg-theme-primary/10 text-theme-primary' :
                  'bg-theme-warning/10 text-theme-warning'
                }`}>
                  {viewingEstimate.status || 'Pending'}
                </span>
              </div>

              <div className="flex items-center gap-2">
                {/* Convert to Invoice Action */}
                {viewingEstimate.status !== 'Converted' && (
                  <button
                    onClick={() => handleConvertToInvoice(viewingEstimate)}
                    className="flex items-center gap-1.5 px-3 py-1.5 bg-gradient-to-tr from-theme-accent to-indigo-600 text-white font-bold text-xs rounded-lg shadow-sm hover:opacity-90 transition-all mr-2"
                  >
                    <ArrowRightLeft className="w-3.5 h-3.5" />
                    Convert to Invoice
                  </button>
                )}

                {/* Status Toggles */}
                {viewingEstimate.status !== 'Converted' && (
                  <div className="flex bg-theme-app rounded-lg p-1 mr-2 border border-theme-border-soft">
                    <button
                      onClick={() => handleStatusChange(viewingEstimate, 'Accepted')}
                      className={`p-1.5 rounded transition-all ${viewingEstimate.status === 'Accepted' ? 'bg-theme-success/20 text-theme-success' : 'text-theme-muted hover:text-theme-success'}`}
                      title="Mark Accepted"
                    >
                      <Check className="w-3.5 h-3.5" />
                    </button>
                    <button
                      onClick={() => handleStatusChange(viewingEstimate, 'Rejected')}
                      className={`p-1.5 rounded transition-all ${viewingEstimate.status === 'Rejected' ? 'bg-theme-danger/20 text-theme-danger' : 'text-theme-muted hover:text-theme-danger'}`}
                      title="Mark Rejected"
                    >
                      <X className="w-3.5 h-3.5" />
                    </button>
                  </div>
                )}

                <button
                  onClick={handlePrint}
                  className="p-2 text-theme-muted hover:text-theme-accent hover:bg-theme-app dark:bg-theme-surface rounded-xl transition-all"
                  title="Print Estimate"
                >
                  <Printer className="w-4 h-4" />
                </button>
                <button
                  onClick={() => onDownloadPDF(viewingEstimate)}
                  className="p-2 text-theme-muted hover:text-theme-accent hover:bg-theme-app dark:bg-theme-surface rounded-xl transition-all"
                  title="Download PDF"
                >
                  <Download className="w-4 h-4" />
                </button>
                <button
                  onClick={() => onDownloadImage && onDownloadImage(viewingEstimate)}
                  className="p-2 text-theme-muted hover:text-theme-accent hover:bg-theme-app dark:bg-theme-surface rounded-xl transition-all"
                  title="Download Image (PNG)"
                >
                  <ImageDown className="w-4 h-4" />
                </button>
                
                <button
                  onClick={() => {
                    onEditInvoice(viewingEstimate);
                    setViewingEstimate(null);
                    setCurrentTab('create-invoice');
                  }}
                  className="p-2 text-theme-muted hover:text-theme-accent hover:bg-theme-app dark:bg-theme-surface rounded-xl transition-all"
                  title="Edit Estimate"
                >
                  <Edit className="w-4 h-4" />
                </button>
                <div className="w-px h-6 bg-theme-surface dark:bg-theme-card mx-1"></div>

                <button
                  onClick={() => {
                    setViewingEstimate(null);
                    onEditInvoice(null);
                  }}
                  className="p-2 text-theme-muted hover:text-theme-primary dark:text-theme-primary hover:bg-theme-surface dark:bg-theme-card rounded-xl transition-all"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>
            </div>

            {/* Preview Wrapper */}
            <div className="p-4 md:p-6 bg-theme-app dark:bg-theme-surface">
              <InvoicePreview 
                invoice={viewingEstimate}
                businessSettings={businessSettings}
              />
            </div>
            
            {/* Print Only Embedded Capture Zone */}
            <div className="hidden print:block print:absolute print:inset-0 bg-theme-card dark:bg-theme-card">
              <InvoicePreview 
                invoice={viewingEstimate}
                businessSettings={businessSettings}
              />
            </div>
          </div>
        </div>,
        document.body
      )}
      </motion.div>
      </PullToRefresh>
    </AnimatedPage>
  );
};

export default Estimates;

import React, { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import AnimatedPage from '../components/AnimatedPage';
import { 
  Plus, 
  Trash2, 
  IndianRupee, 
  Calendar, 
  Tag, 
  PieChart, 
  Wrench, 
  Receipt,
  Lightbulb
} from 'lucide-react';
import { formatCurrency } from '../utils/invoiceUtils';
import CenteredModal from '../components/CenteredModal';
import { toast } from 'react-hot-toast';
import PullToRefresh from '../components/PullToRefresh';
import { invoiceEngine } from '../services/invoiceEngine';

const CATEGORIES = [
  { name: 'Supplies', color: 'bg-theme-accent-light text-theme-accent', border: 'border-theme-border-soft' },
  { name: 'Utilities', color: 'bg-theme-warning/10 text-theme-warning', border: 'border-theme-warning/30' },
  { name: 'Salaries & Wages', color: 'bg-theme-accent-light text-theme-accent', border: 'border-theme-border-soft' },
  { name: 'Rent & Maintenance', color: 'bg-theme-danger/10 text-theme-danger', border: 'border-theme-danger/30' },
  { name: 'Marketing', color: 'bg-theme-accent-light text-theme-accent', border: 'border-theme-border-soft' },
  { name: 'Other', color: 'bg-theme-surface dark:bg-theme-card text-theme-primary dark:text-theme-muted', border: 'border-theme-border-soft' }
];

const Expenses = ({ expenses = [], onSaveExpense, onDeleteExpense, businessSettings, setCurrentTab }) => {
  const [showAddForm, setShowAddForm] = useState(false);
  const [title, setTitle] = useState('');
  const [category, setCategory] = useState('Supplies');
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  const currencySymbol = businessSettings?.currency || '₹';

  // --- STATS ---
  const { totalExpenses, categoryTotals } = useMemo(() => {
    let total = 0;
    const catTotals = {};
    expenses.forEach(exp => {
      const amt = parseFloat(exp.amount || 0);
      total += amt;
      const cat = exp.category || 'Other';
      catTotals[cat] = (catTotals[cat] || 0) + amt;
    });
    return { totalExpenses: total, categoryTotals: catTotals };
  }, [expenses]);

  const getCategoryTotal = (catName) => categoryTotals[catName] || 0;

  const handleAddExpense = (e) => {
    e.preventDefault();
    if (!title || !amount) {
      toast.error('Please fill out all required fields.');
      return;
    }

    const payload = {
      title,
      category,
      amount: parseFloat(amount),
      date
    };

    onSaveExpense(payload);
    
    // Clear form
    setTitle('');
    setCategory('Supplies');
    setAmount('');
    setDate(new Date().toISOString().split('T')[0]);
    setShowAddForm(false);
  };

  const handleRefresh = async () => {
    await invoiceEngine.syncFromCloud();
    window.dispatchEvent(new Event('billqyro_sync'));
  };

  return (
    <AnimatedPage>
      <PullToRefresh onRefresh={handleRefresh}>
        <motion.div 
        initial={{ opacity: 0, y: 15 }}
        animate={{ opacity: 1, y: 0 }}
        exit={{ opacity: 0, y: -15 }}
        transition={{ duration: 0.3 }}
        className="space-y-6 pb-24"
      >
      {/* 1. HEADER ROW */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          {setCurrentTab && (
            <button
              onClick={() => setCurrentTab('dashboard')}
              className="p-2 rounded-xl bg-theme-surface hover:bg-theme-border-soft transition-colors text-theme-primary"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m15 18-6-6 6-6"/></svg>
            </button>
          )}
          <div>
            <h2 className="text-xl font-extrabold text-theme-primary dark:text-theme-primary tracking-tight">Expense Tracker</h2>
            <p className="text-[10px] text-theme-muted font-bold uppercase tracking-wider mt-0.5">MANAGE OPERATING COSTS</p>
          </div>
        </div>

        <button
          onClick={() => setShowAddForm(true)}
          className="flex items-center justify-center gap-2 bg-gradient-to-tr from-theme-accent to-theme-accent-dark text-white font-extrabold text-xs px-5 py-3.5 rounded-2xl shadow-premium hover:scale-[1.02] active:scale-[0.98] transition-all"
        >
          <Plus className="w-4 h-4" />
          <span>Log Expense</span>
        </button>
      </div>

      {/* 2. OVERALL AGGREGATES */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
        
        {/* TOTAL BOX */}
        <div className="bg-theme-card text-white rounded-3xl p-6 shadow-premium relative overflow-hidden border border-theme-border-soft">
          <div className="absolute top-[-20%] right-[-10%] w-32 h-32 bg-theme-accent-light rounded-full blur-2xl"></div>
          <p className="text-[10px] font-bold text-theme-accent uppercase tracking-widest">Total Monthly Cost</p>
          <h3 className="text-3xl font-black mt-2 tracking-tight">
            {formatCurrency(totalExpenses, currencySymbol)}
          </h3>
          <div className="flex items-center gap-1.5 mt-3 text-xs font-semibold text-theme-muted">
            <PieChart className="w-4 h-4 text-theme-accent" />
            <span>Aggregate business overhead logged</span>
          </div>
        </div>

        {/* TOP CATEGORIES PANEL */}
        <div className="bg-theme-card dark:bg-theme-card rounded-3xl p-5 border border-theme-border-soft dark:border-theme-border-soft shadow-premium md:col-span-2 space-y-4">
          <h3 className="text-xs font-bold text-theme-muted uppercase tracking-wider border-b border-theme-border-soft pb-2">
            Cost By Category
          </h3>
          <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
            {CATEGORIES.slice(0, 6).map((cat) => {
              const catTotal = getCategoryTotal(cat.name);
              return (
                <div key={cat.name} className="p-3 bg-theme-app dark:bg-theme-surface/50 border border-theme-border-soft dark:border-theme-border-soft rounded-2xl">
                  <span className={`inline-block text-[9px] font-extrabold px-2 py-0.5 rounded-full ${cat.color}`}>
                    {cat.name.split(' ')[0]}
                  </span>
                  <p className="text-sm font-black text-theme-primary dark:text-theme-muted mt-2">
                    {formatCurrency(catTotal, currencySymbol)}
                  </p>
                </div>
              );
            })}
          </div>
        </div>

      </div>

      <div className="grid grid-cols-1 gap-6 items-start">
        
        {/* 3. LOG NEW EXPENSE DRAWER */}
        <CenteredModal 
          isOpen={showAddForm} 
          onClose={() => setShowAddForm(false)} 
          title="Log New Bill"
        >
          <form onSubmit={handleAddExpense} className="space-y-4 text-xs font-semibold text-theme-muted pb-4">
            <div>
              <label className="block mb-1 text-theme-muted">Expense Title / Description</label>
              <input
                type="text"
                required
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                placeholder="e.g. Embroidery Thread Reels"
                className="w-full px-4 py-3 bg-theme-app dark:bg-theme-surface border border-theme-border-soft dark:border-theme-border-soft rounded-xl focus:outline-none focus:ring-2 focus:ring-theme-accent/30 focus:border-theme-accent text-theme-primary dark:text-theme-primary font-bold"
              />
            </div>

            <div>
              <label className="block mb-1 text-theme-muted">Category</label>
              <select
                value={category}
                onChange={(e) => setCategory(e.target.value)}
                className="w-full px-4 py-3 bg-theme-app dark:bg-theme-surface border border-theme-border-soft dark:border-theme-border-soft rounded-xl focus:outline-none focus:ring-2 focus:ring-theme-accent/30 focus:border-theme-accent text-theme-primary dark:text-theme-primary font-extrabold"
              >
                {CATEGORIES.map(c => (
                  <option key={c.name} value={c.name}>{c.name}</option>
                ))}
              </select>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block mb-1 text-theme-muted">Amount ({currencySymbol})</label>
                <input
                  type="number"
                  required
                  min="0"
                  step="0.01"
                  value={amount}
                  onChange={(e) => setAmount(e.target.value)}
                  placeholder="1500"
                  className="w-full px-4 py-3 bg-theme-app dark:bg-theme-surface border border-theme-border-soft dark:border-theme-border-soft rounded-xl focus:outline-none focus:ring-2 focus:ring-theme-accent/30 focus:border-theme-accent text-theme-primary dark:text-theme-primary font-bold"
                />
              </div>

              <div>
                <label className="block mb-1 text-theme-muted">Date</label>
                <input
                  type="date"
                  required
                  value={date}
                  onChange={(e) => setDate(e.target.value)}
                  className="w-full px-4 py-3 bg-theme-app dark:bg-theme-surface border border-theme-border-soft dark:border-theme-border-soft rounded-xl focus:outline-none focus:ring-2 focus:ring-theme-accent/30 focus:border-theme-accent text-theme-primary dark:text-theme-primary font-bold"
                />
              </div>
            </div>

            <button
              type="submit"
              className="w-full py-4 mt-2 bg-[image:var(--accent-gradient)] text-theme-button-text border-0 rounded-2xl font-bold shadow-premium transition-all flex items-center justify-center gap-2"
            >
              <Receipt className="w-4 h-4" />
              <span>Confirm Log Cost</span>
            </button>
          </form>
        </CenteredModal>

        {/* 4. EXPENSE ENTRIES REGISTRY */}
        <div className="w-full space-y-3">
          <div className="flex items-center justify-between">
            <h3 className="text-sm font-extrabold text-theme-primary dark:text-theme-primary tracking-tight">Registry Log</h3>
            <span className="text-[10px] text-theme-muted font-bold uppercase tracking-wider bg-theme-surface dark:bg-theme-card px-2 py-0.5 rounded-full">
              {expenses.length} Records
            </span>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 md:gap-5">
            <AnimatePresence>
              {expenses.map((exp) => {
                const catInfo = CATEGORIES.find(c => c.name === exp.category) || CATEGORIES[5];
                return (
                  <motion.div
                    key={exp.id}
                    layout
                    initial={{ opacity: 0, scale: 0.98 }}
                    animate={{ opacity: 1, scale: 1 }}
                    exit={{ opacity: 0, scale: 0.9 }}
                    transition={{ duration: 0.2 }}
                    className="bg-theme-card dark:bg-theme-card rounded-3xl p-5 border border-theme-border-soft dark:border-theme-border-soft shadow-premium hover:shadow-premium-hover transition-all duration-300 relative flex flex-col justify-between"
                  >
                    <div>
                      <div className="flex justify-between items-start">
                        <div className="flex items-center gap-3">
                          <div className="w-10 h-10 rounded-xl bg-theme-accent-light border border-theme-border-soft flex items-center justify-center font-extrabold text-theme-accent text-sm">
                            <Receipt className="w-4 h-4" />
                          </div>
                          <div>
                            <h3 className="font-extrabold text-sm text-theme-primary dark:text-theme-primary tracking-tight leading-tight">{exp.title}</h3>
                            <span className="text-[10px] text-theme-muted font-bold uppercase tracking-widest mt-0.5 inline-block">Expense Entry</span>
                          </div>
                        </div>

                        <div className="flex gap-1">
                          <button
                            onClick={() => onDeleteExpense(exp.id)}
                            className="p-2 text-theme-muted hover:text-theme-danger hover:bg-theme-danger/5 rounded-xl transition-all"
                            title="Delete Expense"
                          >
                            <Trash2 className="w-3.5 h-3.5" />
                          </button>
                        </div>
                      </div>

                      <div className="mt-3 flex items-center gap-2 flex-wrap">
                        <span className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold ${catInfo.color} ${catInfo.border}`}>
                          {exp.category}
                        </span>
                        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-[10px] font-bold bg-theme-app dark:bg-theme-surface text-theme-muted border border-theme-border-soft">
                          <Calendar className="w-3 h-3" />
                          {exp.date}
                        </span>
                      </div>
                    </div>

                    <div className="border-t border-theme-border-soft dark:border-theme-border-soft/60 pt-4 mt-5 flex justify-between items-center">
                      <span className="text-[10px] text-theme-muted font-extrabold uppercase tracking-wider">Logged Amount</span>
                      <span className="text-base font-black text-theme-accent">
                        {formatCurrency(exp.amount, currencySymbol)}
                      </span>
                    </div>
                  </motion.div>
                );
              })}
            </AnimatePresence>

            {expenses.length === 0 && (
              <div className="md:col-span-2 lg:col-span-3 bg-theme-card dark:bg-theme-card rounded-3xl p-12 border border-theme-border-soft dark:border-theme-border-soft text-center shadow-premium">
                <Receipt className="w-12 h-12 text-theme-primary mx-auto mb-3 animate-pulse" />
                <h4 className="font-extrabold text-theme-primary dark:text-theme-muted">No Operating Costs Logged</h4>
                <p className="text-xs text-theme-muted font-semibold mt-1 max-w-xs mx-auto">
                  Keep overhead clean. Click Log Expense to add business expenses!
                </p>
              </div>
            )}
          </div>
        </div>

      </div>
      </motion.div>
      </PullToRefresh>
    </AnimatedPage>
  );
};

export default Expenses;

import React, { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import AnimatedPage from '../components/AnimatedPage';
import { Search, ChevronRight, Languages, Clock, X, Play, CheckCircle2 } from 'lucide-react';
import * as Icons from 'lucide-react';
import { guides, categories, faqs as faqsData } from '../data/guides';

// FAQ Accordion Component
const FAQAccordion = ({ language }) => {
  const [openIndex, setOpenIndex] = useState(null);
  
  return (
    <div className="space-y-3">
      {faqsData.map((faq, index) => (
        <div key={index} className="bg-theme-card dark:bg-theme-card border border-theme-border-soft rounded-xl overflow-hidden shadow-sm hover:border-theme-border-strong transition-colors">
          <button
            onClick={() => setOpenIndex(openIndex === index ? null : index)}
            className="w-full px-5 md:px-6 py-4 text-left flex items-center justify-between hover:bg-theme-app dark:hover:bg-theme-surface transition-colors"
          >
            <span className="font-semibold text-theme-primary dark:text-theme-primary text-sm md:text-base">
              {language === 'bn' ? faq.question : faq.questionEn}
            </span>
            <ChevronRight className={`w-5 h-5 text-theme-muted transition-transform ${
              openIndex === index ? 'rotate-90' : ''
            }`} />
          </button>
          
          <AnimatePresence>
            {openIndex === index && (
              <motion.div
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: 'auto', opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                className="overflow-hidden bg-theme-app dark:bg-theme-surface"
              >
                <div className="px-5 md:px-6 py-4 border-t border-theme-border-soft text-theme-muted text-sm leading-relaxed">
                  {language === 'bn' ? faq.answer : faq.answerEn}
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      ))}
    </div>
  );
};

// Guide Detail Modal (Step-by-step view)
const GuideDetailModal = ({ guide, language, onClose }) => {
  const IconComponent = Icons[guide.icon] || Icons.FileText;

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 md:p-6"
        onClick={onClose}
      >
        <motion.div
          initial={{ scale: 0.95, y: 20 }}
          animate={{ scale: 1, y: 0 }}
          exit={{ scale: 0.95, y: 20 }}
          onClick={(e) => e.stopPropagation()}
          className="bg-theme-app dark:bg-theme-app max-w-3xl w-full max-h-[90vh] overflow-y-auto rounded-3xl shadow-2xl flex flex-col border border-theme-border-soft"
        >
          {/* Header */}
          <div className="sticky top-0 z-10 bg-theme-app/90 dark:bg-theme-app/90 backdrop-blur-md border-b border-theme-border-soft px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2.5 bg-theme-accent-light text-theme-accent rounded-xl">
                <IconComponent className="w-6 h-6" />
              </div>
              <div>
                <h2 className="text-xl font-bold text-theme-primary dark:text-theme-primary">
                  {language === 'bn' ? guide.title : guide.titleEn}
                </h2>
                <div className="flex items-center gap-3 text-xs text-theme-muted mt-1 font-medium">
                  <div className="flex items-center gap-1">
                    <Clock className="w-3.5 h-3.5" />
                    {guide.duration}
                  </div>
                  <div className={`px-2 py-0.5 rounded-md ${
                      guide.difficulty === 'beginner' ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400' :
                      guide.difficulty === 'intermediate' ? 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400' :
                      'bg-rose-100 text-rose-700 dark:bg-rose-900/30 dark:text-rose-400'
                    }`}>
                      {guide.difficulty === 'beginner' ? (language === 'bn' ? 'নতুন' : 'Beginner') :
                       guide.difficulty === 'intermediate' ? (language === 'bn' ? 'মধ্যম' : 'Intermediate') :
                       (language === 'bn' ? 'উন্নত' : 'Advanced')}
                  </div>
                </div>
              </div>
            </div>
            <button
              onClick={onClose}
              className="p-2 hover:bg-theme-surface dark:hover:bg-theme-surface rounded-full transition-colors text-theme-muted hover:text-theme-primary"
            >
              <X className="w-6 h-6" />
            </button>
          </div>

          {/* Content */}
          <div className="p-6 md:p-8 space-y-8">
            {/* Steps */}
            <div className="space-y-6">
              {guide.steps.map((step, idx) => (
                <div key={idx} className="flex gap-4 md:gap-6 group">
                  <div className="flex flex-col items-center">
                    <div className="w-8 h-8 rounded-full bg-theme-accent text-white flex items-center justify-center font-bold shadow-sm shrink-0">
                      {idx + 1}
                    </div>
                    {idx !== guide.steps.length - 1 && (
                      <div className="w-0.5 h-full bg-theme-border-soft dark:bg-theme-border-strong my-2 group-hover:bg-theme-accent/50 transition-colors"></div>
                    )}
                  </div>
                  <div className="flex-1 pb-6">
                    <h3 className="text-base md:text-lg font-bold text-theme-primary dark:text-theme-primary mb-2">
                      {language === 'bn' ? step.title : step.titleEn}
                    </h3>
                    <p className="text-theme-muted text-sm md:text-base leading-relaxed bg-theme-card dark:bg-theme-card p-4 rounded-xl border border-theme-border-soft">
                      {language === 'bn' ? step.description : step.descriptionEn}
                    </p>
                    
                    {step.image && (
                      <div className="mt-4 w-full h-48 md:h-64 bg-theme-surface dark:bg-theme-surface border border-theme-border-soft rounded-xl flex items-center justify-center overflow-hidden relative group-hover:border-theme-accent/30 transition-colors">
                        {/* Placeholder for actual image */}
                        <div className="text-center text-theme-muted">
                          <CheckCircle2 className="w-8 h-8 mx-auto mb-2 opacity-50" />
                          <p className="text-xs font-semibold uppercase tracking-wider">Example Image</p>
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>

            {/* Video Placeholder */}
            {guide.videoUrl !== undefined && (
              <div className="mt-8 pt-8 border-t border-theme-border-soft">
                <h3 className="text-sm font-bold text-theme-primary dark:text-theme-primary mb-4 flex items-center gap-2">
                  <Play className="w-4 h-4 text-theme-accent" />
                  {language === 'bn' ? 'ভিডিও টিউটোরিয়াল' : 'Video Tutorial'}
