                <div className="flex gap-2">
                  {business.whatsapp && (
                    <a href={`https://wa.me/${business.whatsapp.replace(/\D/g, '')}?text=${encodeURIComponent('Hi, I have a question about Invoice ' + invoice.invoiceNumber)}`} target="_blank" rel="noopener noreferrer" className="flex-1 flex items-center justify-center gap-1.5 py-2.5 md:py-3 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-600 font-bold rounded-xl transition-all cursor-pointer text-[10px] md:text-xs animate-wa-pulse premium-focus">
                      <MessageCircle className="w-3.5 md:w-4 h-3.5 md:h-4" />
                      WhatsApp
                    </a>
                  )}
                  {business.phone && !business.whatsapp && (
                    <a href={`tel:${business.phone}`} className="flex-1 flex items-center justify-center gap-1.5 py-2 md:py-2.5 bg-theme-accent/10 hover:bg-theme-accent/20 text-theme-accent font-bold rounded-xl transition-all cursor-pointer text-[10px] md:text-xs premium-focus">
                      <Phone className="w-3 md:w-3.5 h-3 md:h-3.5" />
                      Call
                    </a>
                  )}
                  {business.email && (
                    <a href={`mailto:${business.email}?subject=Invoice%20${invoice.invoiceNumber}`} className="flex-1 flex items-center justify-center gap-1.5 py-2 md:py-2.5 bg-theme-accent/10 hover:bg-theme-accent/20 text-theme-accent font-bold rounded-xl transition-all cursor-pointer text-[10px] md:text-xs premium-focus">
                      <Mail className="w-3 md:w-3.5 h-3 md:h-3.5" />
                      Email
                    </a>
                  )}
                </div>
              </div>
            )}

          </div>
        )}

        </div>

        {/* ===== STICKY PAY BUTTON (Mobile Only) ===== */}
        {invoice.paymentStatus !== 'Paid' && invoice.paymentStatus !== 'Pending Verification' && (
          <div className="lg:hidden no-print fixed bottom-0 left-0 right-0 z-50 bg-theme-card/95 backdrop-blur-xl border-t border-theme-border-soft px-4 py-3 pb-[max(0.75rem,env(safe-area-inset-bottom))] shadow-[0_-10px_30px_rgba(0,0,0,0.08)] safe-area-bottom">
            <div className="flex items-center gap-3">
              <div className="flex-1">
                <p className="text-[8px] text-theme-muted font-bold uppercase tracking-wider">Amount Due</p>
                <p className="text-lg font-black text-rose-500">{formatVal(dueAmount)}</p>
              </div>
              {liveLinkPrefs.allowPaymentProofSubmit ? (
                <button onClick={() => setShowPaymentModal(true)} className="btn-premium px-6 py-3 text-sm">
                  <Wallet className="w-4 h-4" />
                  Pay Now
                </button>
              ) : (
                <a href={`https://wa.me/${business.whatsapp?.replace(/\D/g, '') || business.phone?.replace(/\D/g, '')}?text=${encodeURIComponent('Hi, I want to pay for Invoice ' + invoice.invoiceNumber)}`} target="_blank" rel="noopener noreferrer" className="btn-premium px-6 py-3 text-sm bg-emerald-500 shadow-lg shadow-emerald-500/25" style={{ backgroundImage: 'none', background: '#10B981' }}>
                  <MessageCircle className="w-4 h-4" />
                  Pay via WhatsApp
                </a>
              )}
            </div>
          </div>
        )}

        {/* ===== TRUST FOOTER ===== */}
        <footer className={`mt-6 md:mt-8 w-full max-w-5xl ${invoice.paymentStatus !== 'Paid' && invoice.paymentStatus !== 'Pending Verification' ? 'pb-[calc(80px+env(safe-area-inset-bottom))] lg:pb-0' : ''}`}>
        <div className="card-premium overflow-hidden bg-gradient-to-r from-theme-card/80 via-theme-card to-theme-card/80 backdrop-blur-sm rounded-2xl border border-theme-border-soft/60 p-4 md:p-5 shadow-lg">
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 md:gap-3 mb-3 md:mb-4">
            <div className="flex items-center gap-2 px-2.5 md:px-3 py-2 md:py-2.5 bg-theme-surface/50 rounded-xl border border-theme-border-soft/40">
              <ShieldCheck className="w-4 h-4 md:w-5 md:h-5 text-emerald-500 shrink-0" />
              <div>
                <p className="text-[8px] md:text-[9px] font-black text-theme-primary leading-tight">BillQyro</p>
                <p className="text-[7px] md:text-[8px] text-theme-muted font-semibold">Billing Platform</p>
              </div>
            </div>
            <div className="flex items-center gap-2 px-2.5 md:px-3 py-2 md:py-2.5 bg-theme-surface/50 rounded-xl border border-theme-border-soft/40">
              <Lock className="w-4 h-4 md:w-5 md:h-5 text-indigo-500 shrink-0" />
              <div>
                <p className="text-[8px] md:text-[9px] font-black text-theme-primary leading-tight">256-bit</p>
                <p className="text-[7px] md:text-[8px] text-theme-muted font-semibold">Encrypted</p>
              </div>
            </div>
            <div className="flex items-center gap-2 px-2.5 md:px-3 py-2 md:py-2.5 bg-theme-surface/50 rounded-xl border border-theme-border-soft/40">
              <CheckCircle2 className="w-4 h-4 md:w-5 md:h-5 text-blue-500 shrink-0" />
              <div>
                <p className="text-[8px] md:text-[9px] font-black text-theme-primary leading-tight">Invoice</p>
                <p className="text-[7px] md:text-[8px] text-theme-muted font-semibold">#{invoice.invoiceNumber}</p>
              </div>
            </div>
            <div className="flex items-center gap-2 px-2.5 md:px-3 py-2 md:py-2.5 bg-theme-surface/50 rounded-xl border border-theme-border-soft/40">
              <Info className="w-4 h-4 md:w-5 md:h-5 text-theme-accent shrink-0" />
              <div>
                <p className="text-[8px] md:text-[9px] font-black text-theme-primary leading-tight">Date</p>
                <p className="text-[7px] md:text-[8px] text-theme-muted font-semibold">{invoice.date}</p>
              </div>
            </div>
          </div>
          <p className="text-[7px] md:text-[8px] text-theme-muted/60 font-semibold text-center">Digitally compiled by BillQyro &middot; Your data is protected &middot; Secure checkout</p>
        </div>
      </footer>

    </div>

      <style dangerouslySetInnerHTML={{__html: `
        @media print {
          body { background: white !important; color: black !important; }
          .no-print { display: none !important; }
          .bg-theme-card, .card-premium { background: white !important; border: 1px solid #ddd !important; box-shadow: none !important; }
          table { width: 100% !important; border-collapse: collapse; }
          th, td { border: 1px solid #ddd; padding: 6px !important; color: black !important; }
        }
      `}} />
    </motion.div>
  );
};

export default PublicInvoice;

import { toast } from 'react-hot-toast';
import React, { useState, useMemo } from 'react';
import { motion } from 'framer-motion';
import { 
  BarChart, Bar, AreaChart, Area, PieChart, Pie, Cell, 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend 
} from 'recharts';
import { 
  Filter, Download, Printer, PieChart as PieChartIcon, 
  TrendingUp, DollarSign, FileText, CheckCircle2, AlertCircle, Clock
} from 'lucide-react';
import { formatCurrency } from '../utils/invoiceUtils';
import { pageVariants, staggerContainer, staggerItem } from '../utils/animations';

const COLORS = {
  emerald: '#10b981',
  rose: '#f43f5e',
  amber: '#f59e0b',
  slate: '#64748b',
  accent: '#14b8a6',
  purple: '#8b5cf6'
};

const Reports = ({ invoices = [], customers = [], businessSettings }) => {
  const currencySymbol = businessSettings?.currency || '₹';

  // --- FILTERS STATE ---
  const [dateRange, setDateRange] = useState('This Month');
  const [customStart, setCustomStart] = useState('');
  const [customEnd, setCustomEnd] = useState('');
  const [docType, setDocType] = useState('All');
  const [paymentStatus, setPaymentStatus] = useState('All');

  const isDateInRange = (dateString, rangeType, start, end) => {
    if (!dateString) return false;
    const d = new Date(dateString);
    d.setHours(0,0,0,0);
    const today = new Date();
    today.setHours(0,0,0,0);

    if (rangeType === 'All Time') return true;
    if (rangeType === 'Today') {
      return d.getTime() === today.getTime();
    }
    if (rangeType === 'This Week') {
      const firstDay = new Date(today.setDate(today.getDate() - today.getDay()));
      const lastDay = new Date(today.setDate(today.getDate() - today.getDay() + 6));
      return d >= firstDay && d <= lastDay;
    }
    if (rangeType === 'This Month') {
      return d.getMonth() === today.getMonth() && d.getFullYear() === today.getFullYear();
    }
    if (rangeType === 'Custom') {
      const s = start ? new Date(start) : null;
      const e = end ? new Date(end) : null;
      if (s && e) return d >= s && d <= e;
      if (s) return d >= s;
      if (e) return d <= e;
      return true;
    }
    return true;
  };

  const { 
    filteredData, 
    metrics, 
    charts 
  } = useMemo(() => {
    const processed = invoices.filter(inv => {
      const type = inv.documentType || (inv.billType === 'Estimate' ? 'Estimate' : 'Invoice');
      if (docType !== 'All' && type !== docType) return false;

      const targetDate = inv.date || inv.createdAt;
      if (!isDateInRange(targetDate, dateRange, customStart, customEnd)) return false;

      const pStatus = inv.paymentStatus || 'Unpaid';
      if (paymentStatus !== 'All' && pStatus !== paymentStatus) return false;

      return true;
    }).map(inv => {
      const grandTotal = parseFloat(inv.grandTotal || inv.total) || 0;
      let paid = 0;
      if (inv.paymentStatus === 'Paid') paid = grandTotal;
      else paid = parseFloat(inv.amountPaid) || 0;

      return {
        ...inv,
        parsedType: inv.documentType || (inv.billType === 'Estimate' ? 'Estimate' : 'Invoice'),
        parsedDate: new Date(inv.date || inv.createdAt),
        parsedTotal: grandTotal,
        parsedPaid: paid,
        parsedDue: Math.max(0, grandTotal - paid),
        parsedStatus: inv.paymentStatus || 'Unpaid'
      };
    }).sort((a, b) => b.parsedDate - a.parsedDate);

    const counts = { Invoice: 0, Estimate: 0, Quotation: 0 };
    let totalSales = 0;
    let totalCollected = 0;
    let totalDue = 0;
    let totalOverdue = 0;
    
    const salesByDate = {};
    const salesByCustomer = {};
    const salesByItem = {};
    const statusBreakdown = { Paid: 0, Partial: 0, Unpaid: 0, Overdue: 0 };

    processed.forEach(inv => {
      counts[inv.parsedType] = (counts[inv.parsedType] || 0) + 1;
      
      if (inv.parsedType === 'Invoice') {
        totalSales += inv.parsedTotal;
        totalCollected += inv.parsedPaid;
        totalDue += inv.parsedDue;

        if (inv.parsedStatus === 'Overdue') {
          totalOverdue += inv.parsedDue;
        }

        statusBreakdown[inv.parsedStatus] = (statusBreakdown[inv.parsedStatus] || 0) + 1;

        const dateStr = inv.parsedDate.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
        if (!salesByDate[dateStr]) salesByDate[dateStr] = 0;
        salesByDate[dateStr] += inv.parsedTotal;

        const custName = inv.customerName || 'Unknown';
        if (!salesByCustomer[custName]) salesByCustomer[custName] = 0;
        salesByCustomer[custName] += inv.parsedTotal;

        if (inv.items && Array.isArray(inv.items)) {
          inv.items.forEach(item => {
            const name = item.item || item.description || 'Unknown Item';
            const amount = parseFloat(item.amount || (item.qty * item.rate)) || 0;
            if (!salesByItem[name]) salesByItem[name] = 0;
            salesByItem[name] += amount;
          });
        }
      }
    });

    const areaChartData = Object.keys(salesByDate).map(date => ({ date, revenue: salesByDate[date] })).reverse();
    
    const topCustomers = Object.keys(salesByCustomer)
      .map(name => ({ name, value: salesByCustomer[name] }))
      .sort((a, b) => b.value - a.value)
      .slice(0, 5);

    const topItems = Object.keys(salesByItem)
      .map(name => ({ name, value: salesByItem[name] }))
      .sort((a, b) => b.value - a.value)
      .slice(0, 5);

    const pieData = Object.keys(statusBreakdown)
      .filter(k => statusBreakdown[k] > 0)
      .map(k => ({ name: k, value: statusBreakdown[k] }));

    return {
      filteredData: processed,
      metrics: {
        totalSales, totalCollected, totalDue, totalOverdue,
        invoiceCount: counts.Invoice,
        estimateCount: counts.Estimate,
        quotationCount: counts.Quotation,
        avgValue: counts.Invoice > 0 ? (totalSales / counts.Invoice) : 0,
        topCustomer: topCustomers.length > 0 ? topCustomers[0].name : 'N/A',
        topItem: topItems.length > 0 ? topItems[0].name : 'N/A'
      },
      charts: {
        areaChartData,
        topCustomers,
        topItems,
        pieData
      }
    };
  }, [invoices, dateRange, customStart, customEnd, docType, paymentStatus]);

  const exportCSV = () => {
    if (filteredData.length === 0) return toast.error("No data to export.");
    
    const escapeCSV = (val) => {
      const str = String(val ?? '').replace(/\n/g, ' ').replace(/\r/g, ' ');
      return `"${str.replace(/"/g, '""')}"`;
    };
    
    const headers = ['Date', 'Document No', 'Type', 'Customer', 'Total Amount', 'Paid Amount', 'Due Amount', 'Status'];
    const rows = filteredData.map(inv => [
      inv.parsedDate?.toLocaleDateString() || '',
      inv.invoiceNumber || inv.id || '',
      inv.parsedType || '',
      inv.customerName || 'Unknown',
      inv.parsedTotal.toFixed(2),
      inv.parsedPaid.toFixed(2),
      inv.parsedDue.toFixed(2),
      inv.parsedStatus || ''
    ]);

    const BOM = '\uFEFF';
    const csvString = BOM + headers.join(',') + '\n' + 
      rows.map(row => row.map(escapeCSV).join(',')).join('\n');

    const blob = new Blob([csvString], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `BillQyro_Report_${Date.now()}.csv`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(link.href);
  };

  const handlePrint = () => {
    window.print();
  };

  const dateOptions = ['All Time', 'Today', 'This Week', 'This Month', 'Custom'];
  const docOptions = ['All', 'Invoice', 'Estimate', 'Quotation'];
  const paymentOptions = ['All', 'Paid', 'Partial', 'Unpaid', 'Overdue'];

  return (
    <motion.div
      variants={pageVariants}
      initial="initial"
      animate="animate"
      className="page-premium pb-28 h-full flex flex-col print-container"
    >
      {/* HEADER SECTION */}
      <div className="hero-premium section-spacing-sm">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <div className="flex items-center gap-3 mb-1">
              <div className="icon-premium icon-premium-lg">
                <PieChartIcon className="w-5 h-5" />
              </div>
              <div>
                <h1 className="hero-premium-title">Business Reports</h1>
                <p className="hero-premium-subtitle">Analytics, metrics & exports for your business</p>
              </div>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <motion.button
              variants={staggerItem}
              onClick={exportCSV}
              className="btn-premium-outline text-xs"
            >
              <Download className="w-4 h-4" /> Export CSV
            </motion.button>
