              <div className="md:col-span-1">
                <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1.5 uppercase tracking-wide">Business Name</label>
                <input type="text" value={businessName} onChange={(e) => setBusinessName(e.target.value)} placeholder="ABC Coaching Center" className="input-premium w-full px-4 py-3 bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-[var(--accent)]/20 focus:border-[var(--accent)] text-gray-900 dark:text-white font-bold" />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1.5 uppercase tracking-wide">Owner Name</label>
                <div className="relative">
                  <span className="absolute inset-y-0 left-0 pl-3.5 flex items-center text-gray-400"><User className="w-4 h-4" /></span>
                  <input type="text" value={ownerName} onChange={(e) => setOwnerName(e.target.value)} placeholder="Khairul Basar" className="input-premium w-full pl-10 pr-4 py-3 bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-[var(--accent)]/20 focus:border-[var(--accent)] text-gray-900 dark:text-white font-medium" />
                </div>
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1.5 uppercase tracking-wide">Business Logo</label>
                <div className={'relative border-2 border-dashed rounded-xl p-4 text-center transition-all ' + (isDragging ? 'border-[var(--accent)] bg-[var(--accent)]/5' : 'border-gray-200 dark:border-white/10 bg-white/50 dark:bg-white/5')}
                  onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
                  onDragLeave={() => setIsDragging(false)}
                  onDrop={async (e) => { e.preventDefault(); setIsDragging(false); const f = e.dataTransfer.files[0]; if (f && f.type.startsWith('image/')) setLogoUrl(await compressImage(f)); }}
                >
                  <input type="file" accept="image/*" onChange={async (e) => { const f = e.target.files[0]; if (f && f.type.startsWith('image/')) setLogoUrl(await compressImage(f)); }} className="absolute inset-0 opacity-0 cursor-pointer" />
                  <Upload className="w-5 h-5 mx-auto text-gray-400" />
                  <span className="text-xs font-bold text-gray-400 mt-1 block">Upload Logo</span>
                </div>
                {logoUrl && (
                  <div className="mt-2 relative inline-block group">
                    <img src={logoUrl} alt="Logo" className="h-12 w-auto object-contain rounded-lg border border-gray-200 dark:border-white/10 p-1 bg-white dark:bg-white/5" />
                    <button onClick={() => setLogoUrl('')} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1 opacity-0 group-hover:opacity-100"><Trash2 className="w-3 h-3" /></button>
                  </div>
                )}
                <input type="url" value={logoUrl} onChange={(e) => setLogoUrl(e.target.value)} placeholder="Or paste image URL..." className="input-premium w-full mt-2 px-3 py-2 bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-lg text-xs" />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1.5 uppercase tracking-wide">Phone</label>
                <input type="text" value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="+91 98765 43210" className="input-premium w-full px-4 py-3 bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-xl" />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1.5 uppercase tracking-wide">WhatsApp</label>
                <input type="text" value={whatsapp} onChange={(e) => setWhatsapp(e.target.value)} placeholder="+91 98765 43210" className="input-premium w-full px-4 py-3 bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-xl" />
              </div>
              <div className="md:col-span-2">
                <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1.5 uppercase tracking-wide">Email</label>
                <input type="email" value={loggedInEmail} readOnly className="w-full px-4 py-3 bg-gray-100 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-xl text-gray-500 cursor-not-allowed" />
              </div>
              <div className="md:col-span-2">
                <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1.5 uppercase tracking-wide">Address</label>
                <textarea value={address} onChange={(e) => setAddress(e.target.value)} rows={2} className="input-premium w-full px-4 py-3 bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-xl resize-none text-xs" />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 mb-1.5 uppercase tracking-wide">GST Number</label>
                <input type="text" value={gstNumber} onChange={(e) => setGstNumber(e.target.value)} placeholder="29ABCDE1234F1Z5" className="input-premium w-full px-4 py-3 bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-xl" />
              </div>
            </div>
          </div>
        );

      case 'workspace':
        return (
          <div className="card-premium p-6 md:p-8 space-y-6 animate-fadeIn">
            <div className="section-header border-b border-gray-200 dark:border-white/10 pb-4">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-[image:var(--accent-gradient)] text-white flex items-center justify-center shadow-sm shrink-0"><Globe className="w-5 h-5" /></div>
                <div><h2 className="section-header-title">Workspace Settings</h2><p className="section-header-subtitle">Regional preferences and localization</p></div>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div><label className="block text-xs font-bold text-gray-500 mb-1.5 uppercase tracking-wide">Country</label>
                <select value={country} onChange={(e) => handleCountryAutoConfigure(e.target.value)} className="input-premium w-full px-4 py-3 bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-xl">
                  <option value="India">India</option><option value="Bangladesh">Bangladesh</option><option value="Other">Other</option>
                </select></div>
              <div><label className="block text-xs font-bold text-gray-500 mb-1.5 uppercase tracking-wide">Language</label>
                <select value={language} onChange={(e) => setLanguage(e.target.value)} className="input-premium w-full px-4 py-3 bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-xl">
                  <option value="English">English</option><option value="Bengali">Bengali</option><option value="Hindi">Hindi</option>
                </select></div>
              <div><label className="block text-xs font-bold text-gray-500 mb-1.5 uppercase tracking-wide">Currency Symbol</label>
                <input type="text" value={currency} onChange={(e) => setCurrency(e.target.value)} className="input-premium w-full px-4 py-3 bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-xl" /></div>
              <div><label className="block text-xs font-bold text-gray-500 mb-1.5 uppercase tracking-wide">Currency Code</label>
                <input type="text" value={currencyCode} onChange={(e) => setCurrencyCode(e.target.value)} className="input-premium w-full px-4 py-3 bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-xl" /></div>
              <div><label className="block text-xs font-bold text-gray-500 mb-1.5 uppercase tracking-wide">Tax Label</label>
                <select value={taxLabel} onChange={(e) => setTaxLabel(e.target.value)} className="input-premium w-full px-4 py-3 bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-xl">
                  <option value="GST">GST</option><option value="VAT">VAT</option><option value="Tax">Tax</option><option value="None">None</option>
                </select></div>
              <div><label className="block text-xs font-bold text-gray-500 mb-1.5 uppercase tracking-wide">Date Format</label>
                <select value={dateFormat} onChange={(e) => setDateFormat(e.target.value)} className="input-premium w-full px-4 py-3 bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-xl">
                  <option value="DD/MM/YYYY">DD/MM/YYYY</option><option value="MM/DD/YYYY">MM/DD/YYYY</option><option value="YYYY-MM-DD">YYYY-MM-DD</option>
                </select></div>
              <div><label className="block text-xs font-bold text-gray-500 mb-1.5 uppercase tracking-wide">Number Format</label>
                <select value={numberFormat} onChange={(e) => setNumberFormat(e.target.value)} className="input-premium w-full px-4 py-3 bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-xl">
                  <option value="Indian">Indian (lakh/crore)</option><option value="Standard">Standard (1,234,567)</option><option value="European">European (1.234.567,89)</option>
                </select></div>
              <div><label className="block text-xs font-bold text-gray-500 mb-1.5 uppercase tracking-wide">Default Tax Rate (%)</label>
                <input type="number" value={defaultTax} onChange={(e) => setDefaultTax(e.target.value)} className="input-premium w-full px-4 py-3 bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-xl" /></div>
            </div>
          </div>
        );

      case 'theme-engine':
        return (
          <div className="space-y-6 animate-fadeIn">
            <div className="card-premium p-6 space-y-6">
              <div className="section-header border-b border-gray-200 dark:border-white/10 pb-4">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-xl bg-[image:var(--accent-gradient)] text-white flex items-center justify-center shadow-sm shrink-0"><Palette className="w-5 h-5" /></div>
                  <div><h2 className="section-header-title">Theme Engine</h2><p className="section-header-subtitle">Customize every visual aspect instantly</p></div>
                </div>
              </div>

              {/* Mode Selector */}
              <div className="flex items-center justify-between p-4 bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-2xl">
                <div>
                  <h3 className="text-xs font-bold text-gray-900 dark:text-white">Dark Mode</h3>
                  <p className="text-[9px] text-gray-500">Toggle dark/light appearance</p>
                </div>
                <button onClick={handleToggleDark} className={'relative w-12 h-6 rounded-full transition-all flex items-center p-1 ' + (darkMode ? 'bg-[image:var(--accent-gradient)]' : 'bg-slate-300 dark:bg-slate-700/60')}>
                  <span className={'w-4 h-4 bg-white rounded-full shadow-md transition-transform ' + (darkMode ? 'translate-x-6' : 'translate-x-0')} />
                </button>
              </div>

              {/* Theme Presets Grid */}
              <div>
                <h3 className="text-xs font-bold text-gray-500 mb-3 uppercase tracking-wider">Theme Presets</h3>
                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3">
                  {ALL_THEMES.map(({ id, name, category }) => {
                    const info = THEME_INFO[id];
                    const isActive = themeId === id;
                    return (
                      <button key={id} onClick={() => handleApplyTheme(id)}
                        className={'relative rounded-xl border-2 p-3 text-left transition-all hover:scale-[1.02] ' + (isActive ? 'border-[var(--accent)] shadow-lg shadow-[var(--accent)]/20' : 'border-gray-200 dark:border-white/10 hover:border-gray-300 dark:hover:border-white/20')}
                      >
                        <div className="flex gap-1 mb-2">
                          {info?.colors?.slice(0, 3).map((c, i) => <div key={i} className="flex-1 h-3 rounded-sm" style={{ backgroundColor: c }} />)}
                        </div>
                        <p className="text-[10px] font-bold text-gray-900 dark:text-white truncate">{name}</p>
                        <p className="text-[8px] text-gray-400 uppercase tracking-wider">{category}</p>
                        {isActive && <div className="absolute top-1 right-1 w-4 h-4 rounded-full bg-[var(--accent)] text-white flex items-center justify-center text-[8px]">+</div>}
                      </button>
                    );
                  })}
                </div>
              </div>

              {/* Custom Color */}
              <div className="flex items-center gap-4 p-4 bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-2xl">
                <div>
                  <h3 className="text-xs font-bold text-gray-900 dark:text-white">Custom Brand Color</h3>
                  <p className="text-[9px] text-gray-500">Set a specific accent color</p>
                </div>
                <input type="color" value={brandColor} onChange={(e) => { setBrandColor(e.target.value); setThemeId('custom'); applyTheme('custom', e.target.value, darkMode, false); }} className="w-10 h-10 rounded-xl cursor-pointer border border-gray-200" />
                <input type="text" value={brandColor} onChange={(e) => { setBrandColor(e.target.value); setThemeId('custom'); applyTheme('custom', e.target.value, darkMode, false); }} className="flex-1 px-3 py-2 bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-lg text-xs font-mono" />
              </div>

              {/* Advanced Settings */}
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {[
                  { label: 'Corner Radius', value: cornerRadius, set: (v) => { setCornerRadius(v); applyTheme(themeId, brandColor, darkMode, false); document.documentElement.style.setProperty('--radius-base', `${v}px`); }, min: 4, max: 24, unit: 'px' },
                  { label: 'Shadow Intensity', value: shadowIntensity, set: (v) => { setShadowIntensity(v); document.documentElement.style.setProperty('--shadow-opacity', `${v / 100}`); }, min: 0, max: 100, unit: '%' },
                  { label: 'Animation Speed', value: animationSpeed, set: (v) => { setAnimationSpeed(v); document.documentElement.style.setProperty('--animation-multiplier', `${v}s`); }, min: 0.25, max: 2, step: 0.25, unit: 'x' },
                  { label: 'Font Density', value: fontDensity === 'compact' ? 0 : fontDensity === 'normal' ? 1 : 2, set: (v) => { const newDensity = ['compact', 'normal', 'relaxed'][v]; setFontDensity(newDensity); }, min: 0, max: 2, step: 1, unit: '', display: fontDensity }
                ].map((opt, i) => (
                  <div key={i} className="p-4 bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-2xl">
                    <label className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">{opt.label}</label>
                    <div className="flex items-center gap-2 mt-2">
                      <input type="range" min={opt.min} max={opt.max} step={opt.step || 1} value={typeof opt.value === 'number' ? opt.value : 0} onChange={(e) => opt.set(parseFloat(e.target.value))} className="flex-1 accent-[var(--accent)] h-1.5" />
                      <span className="text-xs font-bold text-gray-900 dark:text-white w-12 text-right">{opt.display || opt.value}{opt.unit}</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        );

      case 'payment':
        return (
          <div className="card-premium p-6 md:p-8 space-y-6 animate-fadeIn">
            <div className="section-header border-b border-gray-200 dark:border-white/10 pb-4">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-[image:var(--accent-gradient)] text-white flex items-center justify-center shadow-sm shrink-0"><QrCode className="w-5 h-5" /></div>
                <div><h2 className="section-header-title">Payment Methods</h2><p className="section-header-subtitle">Configure how customers pay you</p></div>
              </div>
            </div>
            <ToggleSwitch enabled={paymentQrEnabled} onChange={setPaymentQrEnabled} label="Enable Digital Payments" description="Show payment details on invoices" />
            {paymentQrEnabled && (
              <div className="bg-white/50 dark:bg-white/5 p-6 rounded-2xl border border-gray-200 dark:border-white/10 space-y-4">
                <div><label className="block text-xs font-bold text-gray-500 mb-1.5">Payment Method</label>
                  <select value={paymentMethod} onChange={(e) => setPaymentMethod(e.target.value)} className="input-premium w-full px-4 py-3 bg-white/50 border border-gray-200 rounded-xl">
                    <option value="UPI">UPI (India)</option><option value="bKash">bKash (Bangladesh)</option><option value="Nagad">Nagad (Bangladesh)</option><option value="Bank">Bank Transfer</option><option value="Manual">Custom Link</option>
                  </select></div>
                {paymentMethod === 'UPI' && <div><label className="block text-xs font-bold text-gray-500 mb-1.5">UPI ID</label><input type="text" value={upiId} onChange={(e) => setUpiId(e.target.value)} placeholder="example@ybl" className="input-premium w-full px-4 py-3 bg-white/50 border border-gray-200 rounded-xl" /></div>}
                {paymentMethod === 'bKash' && <div><label className="block text-xs font-bold text-gray-500 mb-1.5">bKash Number</label><input type="text" value={bkashNumber} onChange={(e) => setBkashNumber(e.target.value)} className="input-premium w-full px-4 py-3 bg-white/50 border border-gray-200 rounded-xl" /></div>}
                {paymentMethod === 'Nagad' && <div><label className="block text-xs font-bold text-gray-500 mb-1.5">Nagad Number</label><input type="text" value={nagadNumber} onChange={(e) => setNagadNumber(e.target.value)} className="input-premium w-full px-4 py-3 bg-white/50 border border-gray-200 rounded-xl" /></div>}
                {paymentMethod === 'Rocket' && <div><label className="block text-xs font-bold text-gray-500 mb-1.5">Rocket Number</label><input type="text" value={rocketNumber} onChange={(e) => setRocketNumber(e.target.value)} className="input-premium w-full px-4 py-3 bg-white/50 border border-gray-200 rounded-xl" /></div>}
                {paymentMethod === 'Manual' && <div><label className="block text-xs font-bold text-gray-500 mb-1.5">Custom Payment Link / Details</label><input type="text" value={customPaymentLink} onChange={(e) => setCustomPaymentLink(e.target.value)} placeholder="https:// or bank details" className="input-premium w-full px-4 py-3 bg-white/50 border border-gray-200 rounded-xl" /></div>}
                <div><label className="block text-xs font-bold text-gray-500 mb-1.5">Payee Name</label><input type="text" value={payeeName} onChange={(e) => setPayeeName(e.target.value)} className="input-premium w-full px-4 py-3 bg-white/50 border border-gray-200 rounded-xl" /></div>
                <div><label className="block text-xs font-bold text-gray-500 mb-1.5">Payment Note</label><input type="text" value={paymentNote} onChange={(e) => setPaymentNote(e.target.value)} className="input-premium w-full px-4 py-3 bg-white/50 border border-gray-200 rounded-xl" /></div>
                <div className="flex items-center justify-between p-3 bg-white/50 border border-gray-200 rounded-xl">
                  <span className="text-xs font-bold text-gray-700">Show QR on Invoice Preview</span>
                  <button onClick={() => setShowQrInPreview(!showQrInPreview)} className={'relative w-10 h-5 rounded-full transition-all flex items-center p-0.5 ' + (showQrInPreview ? 'bg-[image:var(--accent-gradient)]' : 'bg-slate-300')}>
                    <span className={'w-4 h-4 bg-white rounded-full shadow transition-transform ' + (showQrInPreview ? 'translate-x-5' : 'translate-x-0')} />
                  </button>
                </div>
                <div className="flex items-center justify-between p-3 bg-white/50 border border-gray-200 rounded-xl">
                  <span className="text-xs font-bold text-gray-700">Show QR on PDF</span>
                  <button onClick={() => setShowQrInPdf(!showQrInPdf)} className={'relative w-10 h-5 rounded-full transition-all flex items-center p-0.5 ' + (showQrInPdf ? 'bg-[image:var(--accent-gradient)]' : 'bg-slate-300')}>
                    <span className={'w-4 h-4 bg-white rounded-full shadow transition-transform ' + (showQrInPdf ? 'translate-x-5' : 'translate-x-0')} />
                  </button>
                </div>
              </div>
            )}
          </div>
        );

      case 'notifications':
        return (
          <div className="card-premium p-6 md:p-8 space-y-6 animate-fadeIn">
            <div className="section-header border-b border-gray-200 dark:border-white/10 pb-4">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-[image:var(--accent-gradient)] text-white flex items-center justify-center shadow-sm shrink-0"><Bell className="w-5 h-5" /></div>
                <div><h2 className="section-header-title">Notifications</h2><p className="section-header-subtitle">Manage alerts and reminders</p></div>
              </div>
            </div>
            <div className="space-y-3">
              <ToggleSwitch enabled={emailNotifications} onChange={setEmailNotifications} label="Email Notifications" description="Invoice and payment updates via email" />
              <ToggleSwitch enabled={whatsappNotifications} onChange={setWhatsappNotifications} label="WhatsApp Notifications" description="Real-time WhatsApp updates" />
              <ToggleSwitch enabled={dueDateReminders} onChange={setDueDateReminders} label="Due Date Reminders" description="Automatic reminders before due dates" />
              <ToggleSwitch enabled={paymentConfirmation} onChange={setPaymentConfirmation} label="Payment Confirmations" description="When customer submits payment proof" />
              <ToggleSwitch enabled={securityAlerts} onChange={setSecurityAlerts} label="Security Alerts" description="Login activity and security changes" />
              <ToggleSwitch enabled={marketingEmails} onChange={setMarketingEmails} label="Marketing & Updates" description="Product updates and tips" />
            </div>
          </div>
        );

      case 'security':
        return (
          <div className="card-premium p-6 md:p-8 space-y-6 animate-fadeIn">
            <div className="section-header border-b border-gray-200 dark:border-white/10 pb-4">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-[image:var(--accent-gradient)] text-white flex items-center justify-center shadow-sm shrink-0"><Shield className="w-5 h-5" /></div>
                <div><h2 className="section-header-title">Security & API Keys</h2><p className="section-header-subtitle">API credentials and account protection</p></div>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-2xl p-4">
                <div className="flex items-center gap-2 mb-2"><ShieldCheck className="w-4 h-4 text-green-500" /><span className="text-[10px] font-bold text-green-500 uppercase">Account</span></div>
                <p className="text-xs font-bold text-gray-900 dark:text-white">Authenticated</p>
                <p className="text-[9px] text-gray-500 truncate">{loggedInEmail}</p>
              </div>
              <div className="bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-2xl p-4">
                <div className="flex items-center gap-2 mb-2"><Key className="w-4 h-4 text-[var(--accent)]" /><span className="text-[10px] font-bold text-[var(--accent)] uppercase">Database</span></div>
                <select value={dbProvider} onChange={(e) => { setDbProvider(e.target.value); localStorage.setItem('billmint_db_provider', e.target.value); }} className="text-xs w-full bg-transparent border border-gray-200 dark:border-white/10 rounded-lg px-2 py-1 font-bold">
                  <option value="firebase">Firebase</option><option value="indexeddb">IndexedDB (Local)</option>
                </select>
              </div>
              <div className="bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-2xl p-4">
                <div className="flex items-center gap-2 mb-2">
                  {firebaseStatus === 'connected' ? <Wifi className="w-4 h-4 text-green-500" /> : <WifiOff className="w-4 h-4 text-yellow-500" />}
                  <span className="text-[10px] font-bold uppercase">{firebaseStatus === 'connected' ? 'Connected' : 'Offline'}</span>
                </div>
                <p className="text-xs text-gray-500">Sync status: {firebaseStatus === 'connected' ? 'All good' : 'Working offline'}</p>
              </div>
            </div>
            <div className="space-y-4 pt-2">
              <div><label className="block text-[10px] font-bold text-gray-500 uppercase mb-1.5">Gemini API Key (AI Scanner)</label>
                <input type="password" value={geminiApiKey} onChange={(e) => setGeminiApiKey(e.target.value)} placeholder="AIzaSy..." className="input-premium w-full px-4 py-3 bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-xl text-xs" /></div>
              <div><label className="block text-[10px] font-bold text-gray-500 uppercase mb-1.5">Twilio Account SID</label>
                <input type="text" value={twilioAccountSid} onChange={(e) => setTwilioAccountSid(e.target.value)} placeholder="AC..." className="input-premium w-full px-4 py-3 bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-xl text-xs mb-3" />
                <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1.5">Twilio Auth Token</label>
                <input type="password" value={twilioAuthToken} onChange={(e) => setTwilioAuthToken(e.target.value)} className="input-premium w-full px-4 py-3 bg-white/50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-xl text-xs" /></div>
            </div>
          </div>
        );

      case 'backup':
        return (
          <div className="card-premium p-6 md:p-8 space-y-6 animate-fadeIn">
            <div className="section-header border-b border-gray-200 dark:border-white/10 pb-4">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-[image:var(--accent-gradient)] text-white flex items-center justify-center shadow-sm shrink-0"><Database className="w-5 h-5" /></div>
                <div><h2 className="section-header-title">Backup & Restore</h2><p className="section-header-subtitle">Export, import, and manage your data</p></div>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <button onClick={handleExport} className="flex items-center gap-3 p-4 rounded-xl border border-emerald-500/30 bg-emerald-500/5 hover:bg-emerald-500/10 text-left transition-colors">
                <Download className="text-emerald-500 w-5 h-5 shrink-0" />
                <div>
                  <div className="font-extrabold text-sm text-theme-primary">Export Backup</div>
                  <div className="text-[10px] font-semibold text-theme-muted mt-0.5">Download all data as JSON</div>
                </div>
              </button>
              <label className="flex items-center gap-3 p-4 rounded-xl border border-blue-500/30 bg-blue-500/5 hover:bg-blue-500/10 cursor-pointer text-left transition-colors">
                <Upload className="text-blue-500 w-5 h-5 shrink-0" />
                <div>
                  <div className="font-extrabold text-sm text-theme-primary">Import Backup</div>
                  <div className="text-[10px] font-semibold text-theme-muted mt-0.5">Restore from a backup file</div>
                </div>
                <input type="file" accept=".json" onChange={handleImport} className="hidden" />
              </label>
              <button onClick={() => { if (confirm('Clear cache?')) { adminEngine.clearCacheOnly(); toast.success('Cache cleared'); } }} className="flex items-center gap-3 p-4 rounded-xl border border-amber-500/30 bg-amber-500/5 hover:bg-amber-500/10 text-left transition-colors">
                <RotateCcw className="text-amber-500 w-5 h-5 shrink-0" />
                <div>
                  <div className="font-extrabold text-sm text-theme-primary">Clear Cache</div>
                  <div className="text-[10px] font-semibold text-theme-muted mt-0.5">Reset temporary data</div>
                </div>
              </button>
              <button onClick={() => { if (confirm('Reset all data? This cannot be undone.')) { adminEngine.factoryResetAllData(); toast.success('Data reset in progress...'); } }} className="flex items-center gap-3 p-4 rounded-xl border border-rose-500/30 bg-rose-500/5 hover:bg-rose-500/10 text-left transition-colors">
                <Trash2 className="text-rose-500 w-5 h-5 shrink-0" />
                <div>
                  <div className="font-extrabold text-sm text-rose-600 dark:text-rose-400">Factory Reset</div>
                  <div className="text-[10px] font-bold text-rose-500/80 mt-0.5">Wipe all local data permanently</div>
                </div>
              </button>
            </div>
          </div>
        );

      case 'invoice-builder':
        return (
          <div className="card-premium p-6 md:p-8 space-y-6 animate-fadeIn">
            <div className="section-header border-b border-gray-200 dark:border-white/10 pb-4">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-[image:var(--accent-gradient)] text-white flex items-center justify-center shadow-sm shrink-0">
                  <LayoutTemplate className="w-5 h-5" />
                </div>
                <div>
                  <h2 className="section-header-title">Invoice Builder Controls</h2>
                  <p className="section-header-subtitle">Enable or disable premium features in the invoice builder</p>
                </div>
              </div>
            </div>
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <ToggleSwitch
                enabled={enableProductAutocomplete}
                onChange={setEnableProductAutocomplete}
                label="Product Autocomplete"
                description="Auto-suggest items from your catalog"
              />
              <ToggleSwitch
                enabled={enableTemplateSwitcher}
                onChange={setEnableTemplateSwitcher}
                label="Template Switcher"
                description="Allow switching invoice designs"
              />
              <ToggleSwitch
                enabled={enableItemLevelDiscount}
                onChange={setEnableItemLevelDiscount}
                label="Item-Level Discount"
                description="Allow adding discounts per line item"
              />
              <ToggleSwitch
                enabled={enableItemLevelTax}
                onChange={setEnableItemLevelTax}
                label="Item-Level Tax"
                description="Allow adding tax per line item"
              />
              <ToggleSwitch
                enabled={enableDragAndDrop}
                onChange={setEnableDragAndDrop}
                label="Drag & Drop Rows"
                description="Reorder items by dragging"
              />
              <ToggleSwitch
                enabled={enableDigitalSignature}
                onChange={setEnableDigitalSignature}
                label="Digital Signature"
                description="Enable signature pad on invoice"
              />
              <ToggleSwitch
                enabled={enableLivePreview}
                onChange={setEnableLivePreview}
                label="Live PDF Preview"
                description="Real-time PDF rendering preview"
              />
            </div>
            
            {/* Custom Columns & Labels */}
            <div className="mt-8 pt-6 border-t border-gray-200 dark:border-white/10">
              <h3 className="text-lg font-bold text-theme-primary mb-4">Table Customization</h3>
              
              <div className="mb-6">
                <label className="block text-sm font-semibold text-theme-main mb-2">Item/Product Column Label</label>
                <input
                  type="text"
                  value={invoiceItemLabel}
                  onChange={(e) => setInvoiceItemLabel(e.target.value)}
                  className="w-full max-w-xs px-4 py-2 bg-theme-surface border border-theme-border rounded-xl focus:outline-none focus:border-theme-accent focus:ring-1 focus:ring-theme-accent text-theme-main"
                  placeholder="e.g. Item, Product, Service"
                />
              </div>

              <div>
                <div className="flex items-center justify-between mb-3">
                  <div>
                    <label className="block text-sm font-semibold text-theme-main">Custom Columns</label>
                    <p className="text-xs text-theme-muted mt-1">Add additional columns to your invoice table (e.g. Size, Color, Warranty)</p>
                  </div>
                  <button onClick={() => setInvoiceCustomColumns([...invoiceCustomColumns, { id: 'col_' + Date.now(), name: '', type: 'text', options: '' }])} className="px-3 py-1.5 text-xs font-bold bg-theme-accent text-white rounded-lg shadow-sm hover:brightness-110 transition-all">+ Add Column</button>
                </div>
                {invoiceCustomColumns.length === 0 ? (
                  <p className="text-sm text-theme-muted p-4 bg-gray-50 dark:bg-black/20 rounded-xl border border-dashed border-gray-300 dark:border-white/20 text-center">No custom columns added.</p>
                ) : (
                  <div className="space-y-3">
                    {invoiceCustomColumns.map((col, index) => (
                      <div key={col.id} className="flex flex-wrap items-center gap-3 p-3 bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-white/10 rounded-xl">
                        <input
                          type="text"
                          value={col.name}
                          onChange={(e) => {
                            const newCols = [...invoiceCustomColumns];
                            newCols[index].name = e.target.value;
                            setInvoiceCustomColumns(newCols);
                          }}
                          className="flex-1 min-w-[120px] px-3 py-1.5 text-sm bg-theme-surface border border-theme-border rounded-lg text-theme-main focus:outline-none focus:border-theme-accent"
                          placeholder="Column Name"
                        />
                        <select
                          value={col.type}
                          onChange={(e) => {
                            const newCols = [...invoiceCustomColumns];
                            newCols[index].type = e.target.value;
                            setInvoiceCustomColumns(newCols);
                          }}
                          className="px-3 py-1.5 text-sm bg-theme-surface border border-theme-border rounded-lg text-theme-main focus:outline-none focus:border-theme-accent"
                        >
                          <option value="text">Text Input</option>
                          <option value="number">Number Input</option>
                          <option value="dropdown">Dropdown</option>
                        </select>
                        {col.type === 'dropdown' && (
                          <input
                            type="text"
                            value={col.options || ''}
                            onChange={(e) => {
                              const newCols = [...invoiceCustomColumns];
                              newCols[index].options = e.target.value;
                              setInvoiceCustomColumns(newCols);
                            }}
                            className="flex-1 min-w-[150px] px-3 py-1.5 text-sm bg-theme-surface border border-theme-border rounded-lg text-theme-main focus:outline-none focus:border-theme-accent"
                            placeholder="Options (comma separated)"
                          />
                        )}
                        <button
                          onClick={() => {
                            const newCols = invoiceCustomColumns.filter((_, i) => i !== index);
                            setInvoiceCustomColumns(newCols);
                          }}
                          className="p-1.5 text-red-500 hover:bg-red-500/10 rounded-lg transition-colors shrink-0"
                          title="Remove Column"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          </div>
        );

      case 'subscription':
        return <div className="animate-fadeIn"><Subscription currentSubscription={subscription} onUpgrade={onUpgrade} businessSettings={settings} /></div>;

      case 'template-gallery':
        return (
          <div className="animate-fadeIn">
            <div className="flex items-center justify-between mb-4">
              <div className="section-header">
                <h2 className="section-header-title">Universal Template Gallery</h2>
                <p className="section-header-subtitle">Select a single design to unify your PDF, Live Link, and Printed invoices.</p>
              </div>
            </div>
            <PdfTemplateStudio setCurrentTab={(tab) => {
              if (tab === 'dashboard') setCurrentTab?.('dashboard');
              else if (tab === 'settings') setActiveSection('business');
              else setActiveSection(tab);
            }} businessSettings={settings} setSettings={onSaveSettings} />
          </div>
        );

      case 'users':
        return (
          <div className="card-premium p-6 md:p-8 space-y-6 animate-fadeIn">
            <div className="section-header border-b border-gray-200 dark:border-white/10 pb-4">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-[image:var(--accent-gradient)] text-white flex items-center justify-center shadow-sm shrink-0"><Users className="w-5 h-5" /></div>
                <div><h2 className="section-header-title">Users & Roles</h2><p className="section-header-subtitle">Manage team access</p></div>
              </div>
            </div>
            <p className="text-sm text-gray-500">Team management coming soon. Currently, accounts are managed through Firebase Auth.</p>
          </div>
        );

      case 'advanced':
        return (
          <div className="card-premium p-6 md:p-8 space-y-6 animate-fadeIn">
            <div className="section-header border-b border-gray-200 dark:border-white/10 pb-4">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-red-500 text-white flex items-center justify-center shadow-sm shrink-0"><Settings2 className="w-5 h-5" /></div>
                <div><h2 className="section-header-title text-red-600">Advanced</h2><p className="section-header-subtitle">Danger zone — proceed with caution</p></div>
              </div>
            </div>
            <div className="space-y-3">
              {[
                { label: 'Clear All Local Data', desc: 'Wipe everything including IndexedDB', action: async () => { if (confirm('Permanently wipe all local data?')) { await adminEngine.clearAllLocalData(); toast.success('Data wiped'); window.location.href = '/'; } }, danger: true },
                { label: 'Clean Duplicate Drafts', desc: 'Remove empty zero-amount invoices', action: async () => { const r = await adminEngine.cleanDuplicateDrafts(); toast.success('Removed ' + r + ' drafts'); } },
                { label: 'Empty Trash', desc: 'Permanently delete trashed invoices', action: async () => { const r = await adminEngine.emptyTrash(); toast.success('Deleted ' + r.count + ' items'); } }
              ].map((item, i) => (
                <button key={i} onClick={item.action} className={'w-full flex items-center justify-between p-4 rounded-xl border text-left ' + (item.danger ? 'border-red-500/30 bg-red-500/5 hover:bg-red-500/10' : 'border-gray-200 dark:border-white/10 bg-white/50 dark:bg-white/5 hover:bg-gray-50 dark:hover:bg-white/10')}>
                  <div><p className={'text-xs font-bold ' + (item.danger ? 'text-red-600' : 'text-gray-900 dark:text-white')}>{item.label}</p><p className="text-[9px] text-gray-500">{item.desc}</p></div>
                  <span className={'text-[9px] font-bold ' + (item.danger ? 'text-red-500' : 'text-gray-400')}>Run</span>
                </button>
              ))}
            </div>
          </div>
        );

      case 'cyber-portals':
        return <CyberPortalsConfig cyberPortals={cyberPortals} setCyberPortals={setCyberPortals} />;

      case 'cyber-tools':
        return (
          <CyberToolsConfig 
            enablePhotoMaker={enablePhotoMaker} setEnablePhotoMaker={setEnablePhotoMaker} 
            removeBgApiKey={removeBgApiKey} setRemoveBgApiKey={setRemoveBgApiKey} 
          />
        );

      default:
        return <div className="p-8 text-center text-gray-500">Select a section from the navigation</div>;
    }
  };

  return (
    <motion.div variants={pageVariants} initial="initial" animate="animate" className="min-h-screen pb-32 font-sans">
      {/* Premium Header */}
      <div className="sticky top-0 z-30 backdrop-blur-xl bg-white/80 dark:bg-[var(--app-bg)]/80 border-b border-gray-200 dark:border-white/10">
        <div className="max-w-full mx-auto px-4 md:px-6 py-3">
          <div className="flex items-center justify-between gap-4">
            {/* Left: Back + Title */}
            <div className="flex items-center gap-3 min-w-0">
              {setCurrentTab && (
                <button onClick={() => setCurrentTab('dashboard')} className="w-9 h-9 rounded-xl bg-white dark:bg-white/5 border border-gray-200 dark:border-white/10 hover:border-[var(--accent)]/30 transition-all flex items-center justify-center text-gray-600 dark:text-gray-300 shrink-0">
                  <ArrowLeft className="w-4 h-4" />
                </button>
              )}
              <div className="min-w-0">
                <div className="flex items-center gap-2">
                  <h1 className="text-lg md:text-xl font-black text-gray-900 dark:text-white tracking-tight truncate">
                    Settings Studio
                  </h1>
                  <span className="hidden md:inline-block text-[8px] font-bold text-[var(--accent)] bg-[var(--accent)]/10 px-2 py-0.5 rounded-full border border-[var(--accent)]/20 uppercase tracking-wider">V2</span>
                </div>
                <p className="text-[10px] text-gray-500 dark:text-gray-400 font-medium truncate">{settings?.businessName || 'Workspace'}</p>
              </div>
            </div>

            {/* Center: Search */}
            <div className="hidden md:flex flex-1 max-w-md relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-gray-400" />
              <input
                type="text" value={searchQuery} onChange={(e) => handleSearchChange(e.target.value)}
                placeholder="Search all settings..." 
                className="w-full pl-9 pr-8 py-2 bg-white dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-xl text-xs font-medium text-gray-900 dark:text-white placeholder:text-gray-400 focus:outline-none focus:ring-2 focus:ring-[var(--accent)]/20 focus:border-[var(--accent)] transition-all"
              />
              {searchQuery && (
                <button onClick={() => setSearchQuery('')} className="absolute right-2 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600 bg-white dark:bg-white/10 rounded-full p-0.5">
                  <X className="w-3 h-3" />
                </button>
              )}
            </div>

            {/* Right: Status + Actions */}
            <div className="flex items-center gap-2">
              {lastSaved && (
                <span className="hidden lg:inline-flex items-center gap-1 text-[9px] text-gray-400 bg-white dark:bg-white/5 px-2 py-1 rounded-lg border border-gray-200 dark:border-white/10">
                  <Clock className="w-3 h-3" /> Saved {saveTimeAgo}
                </span>
              )}
              {isDirty && (
                <span className="hidden lg:inline-flex items-center gap-1 text-[9px] text-yellow-600 bg-yellow-50 dark:bg-yellow-500/10 px-2 py-1 rounded-lg border border-yellow-200 dark:border-yellow-500/30">
                  <AlertTriangle className="w-3 h-3" /> Unsaved
                </span>
              )}
              {saveState === 'saved' && (
                <span className="inline-flex items-center gap-1 text-[9px] text-green-600 bg-green-50 dark:bg-green-500/10 px-2 py-1 rounded-lg border border-green-200 dark:border-green-500/30 animate-fadeIn">
                  <Check className="w-3 h-3" /> Saved
                </span>
              )}
              <span className="hidden lg:inline-flex text-[9px] text-gray-400 bg-white dark:bg-white/5 px-2 py-1 rounded-lg border border-gray-200 dark:border-white/10">
                Ctrl+S
              </span>
              <button onClick={handleSave} disabled={isSaving || !isDirty}
                className="flex items-center gap-1.5 px-4 py-2 rounded-xl text-[10px] font-bold text-white bg-[image:var(--accent-gradient)] hover:opacity-90 transition-all disabled:opacity-40 disabled:cursor-not-allowed shadow-md active:scale-95"
              >
                {isSaving ? <span className="w-3.5 h-3.5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Save className="w-3.5 h-3.5" />}
                {isSaving ? 'Saving...' : 'Save'}
              </button>
              {isAdmin && (
                <>
                  <button onClick={handleExport} className="hidden sm:flex items-center gap-1.5 px-3 py-2 rounded-xl text-[10px] font-bold text-gray-600 dark:text-gray-300 bg-white dark:bg-white/5 border border-gray-200 dark:border-white/10 hover:bg-gray-50 dark:hover:bg-white/10 transition-all">
                    <Download className="w-3.5 h-3.5" /> Export
                  </button>
                  <label className="hidden sm:flex items-center gap-1.5 px-3 py-2 rounded-xl text-[10px] font-bold text-gray-600 dark:text-gray-300 bg-white dark:bg-white/5 border border-gray-200 dark:border-white/10 hover:bg-gray-50 dark:hover:bg-white/10 cursor-pointer transition-all">
                    <Upload className="w-3.5 h-3.5" /> Import
                    <input type="file" accept=".json" onChange={handleImport} className="hidden" />
                  </label>
                </>
              )}
              <button onClick={() => setShowPreview(!showPreview)}
                className={'hidden lg:flex items-center gap-1.5 px-3 py-2 rounded-xl text-[10px] font-bold border transition-all ' + (showPreview ? 'text-[var(--accent)] bg-[var(--accent)]/10 border-[var(--accent)]/30' : 'text-gray-600 dark:text-gray-300 bg-white dark:bg-white/5 border-gray-200 dark:border-white/10')}
              >
                <Eye className="w-3.5 h-3.5" /> Preview
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Horizontal Navigation Bar (Replaces Left Sidebar) */}
      <div className="max-w-full mx-auto px-4 md:px-6 py-3">
        <div className="flex items-center gap-2 overflow-x-auto hide-scrollbar pb-1">
          {filteredNav.flatMap(group => group.items).map((item) => {
            const isEdu = isEducationBusiness(settings.defaultBillingTemplate);
            const label = item.dynamicLabel ? item.dynamicLabel(isEdu) : item.label;
            const Icon = item.icon;
            const isSelected = activeSection === item.id;
            return (
              <button key={item.id} onClick={() => setActiveSection(item.id)}
                className={'flex items-center gap-1.5 px-4 py-2 rounded-full text-[11px] font-bold whitespace-nowrap border transition-all ' + (isSelected ? 'bg-[var(--accent)] text-white border-[var(--accent)] shadow-sm' : 'bg-white dark:bg-white/5 text-gray-600 dark:text-gray-300 border-gray-200 dark:border-white/10 hover:bg-gray-50 dark:hover:bg-white/10')}
              >
                <Icon className="w-3.5 h-3.5" /> {label}
              </button>
            );
          })}
        </div>
      </div>

      {/* Main Content Area */}
      <div className="max-w-full mx-auto px-4 md:px-6 mt-4">
        <div className="flex gap-6">

          {/* Content Area */}
          <div className={'flex-1 min-w-0 ' + (showPreview ? 'lg:mr-80' : '')}>
            <div className="space-y-6 w-full">
              <AnimatePresence mode="wait">
                <motion.div key={activeSection} initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -8 }} transition={{ duration: 0.15 }}>
                  {renderContent()}
                </motion.div>
              </AnimatePresence>
            </div>
          </div>
        </div>
      </div>

      {/* Live Preview Panel */}
      {showPreview && (
        <LivePreviewPanel themeId={themeId} darkMode={darkMode} brandColor={brandColor} settings={settings} />
      )}

      {/* Sticky Save Bar */}
      <AnimatePresence>
        {isDirty && (
          <motion.div
            initial={{ y: 80, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: 80, opacity: 0 }}
            className="fixed bottom-0 left-0 right-0 z-50 backdrop-blur-xl bg-white/90 dark:bg-gray-900/90 border-t border-gray-200 dark:border-white/10 shadow-2xl"
          >
            <div className="max-w-full mx-auto px-4 md:px-6 py-3 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="w-8 h-8 rounded-lg bg-yellow-100 dark:bg-yellow-500/10 flex items-center justify-center">
                  <AlertTriangle className="w-4 h-4 text-yellow-600" />
                </div>
                <div>
                  <p className="text-xs font-bold text-gray-900 dark:text-white">Unsaved changes</p>
                  <p className="text-[9px] text-gray-500">You have pending modifications</p>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <button onClick={handleDiscard} className="px-4 py-2 rounded-xl text-[10px] font-bold text-gray-600 dark:text-gray-300 bg-white dark:bg-white/5 border border-gray-200 dark:border-white/10 hover:bg-gray-50 dark:hover:bg-white/10 transition-all">
                  Discard
                </button>
                <button onClick={() => handleSave(null)} disabled={isSaving}
                  className="px-6 py-2 rounded-xl text-[10px] font-bold text-white bg-[image:var(--accent-gradient)] hover:opacity-90 transition-all disabled:opacity-40 shadow-md flex items-center gap-1.5"
                >
                  {isSaving ? <><span className="w-3 h-3 border-2 border-white/30 border-t-white rounded-full animate-spin" /> Saving...</> : <><Save className="w-3.5 h-3.5" /> Save Changes</>}
                </button>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Mobile Bottom Nav */}
      <div className="lg:hidden fixed bottom-0 left-0 right-0 z-50 bg-white dark:bg-gray-900 border-t border-gray-200 dark:border-white/10 overflow-x-auto hide-scrollbar">
        <div className="flex items-center justify-around px-2 py-1.5 min-w-max">
          {NAV_GROUPS.map((group) => {
            const firstItem = group.items[0];
            const Icon = group.icon;
            const isActive = group.items.some(i => i.id === activeSection);
            return (
              <button key={group.group} onClick={() => setActiveSection(firstItem?.id || group.group)}
                className={'flex flex-col items-center gap-0.5 px-3 py-1 rounded-lg transition-all ' + (isActive ? 'text-[var(--accent)]' : 'text-gray-400')}
              >
                <Icon className="w-5 h-5" />
                <span className="text-[7px] font-bold whitespace-nowrap">{group.group}</span>
              </button>
            );
          })}
        </div>
      </div>
    </motion.div>
  );
};

export default SettingsStudioV2;

import React, { useState } from 'react';
import { 
  Scissors, 
  ShoppingBasket, 
  Wrench, 
  ShoppingBag, 
  PenTool, 
  CheckCircle2, 
  Globe, 
  Building2, 
  User, 
  Phone, 
  Mail, 
  MapPin, 
  QrCode, 
  CreditCard, 
  ChevronRight, 
  ChevronLeft, 
  Languages, 
  Sparkles, 
  Upload, 
  Image as ImageIcon, 
  Trash2, 
  Check 
} from 'lucide-react';
import { toast } from 'react-hot-toast';

const SetupBilling = ({ businessSettings, onSaveSettings, setCurrentTab }) => {
  const [step, setStep] = useState(1);
  const [isSaving, setIsSaving] = useState(false);

  // Form States
  const [country, setCountry] = useState('India');
  const [language, setLanguage] = useState('English');
  
  // Business Profile
  const [businessName, setBusinessName] = useState('');
  const [ownerName, setOwnerName] = useState('');
  const [phone, setPhone] = useState('');
  const [email, setEmail] = useState('');
  const [address, setAddress] = useState('');
  const [logoUrl, setLogoUrl] = useState('');
  const [selectedTemplate, setSelectedTemplate] = useState('custom');

  // Payments
  const [paymentQrEnabled, setPaymentQrEnabled] = useState(true);
  const [paymentMethod, setPaymentMethod] = useState('UPI');
  const [upiId, setUpiId] = useState('');
  const [payeeName, setPayeeName] = useState('');
  const [gstNumber, setGstNumber] = useState(''); // India GSTIN
  const [bkashNumber, setBkashNumber] = useState('');
  const [nagadNumber, setNagadNumber] = useState('');
  const [rocketNumber, setRocketNumber] = useState(''); // Bangladesh MFS Rocket
  const [vatTax, setVatTax] = useState(''); // Bangladesh VAT rate %
  const [customCurrency, setCustomCurrency] = useState('$'); // Other Currency Symbol
  const [customPaymentLink, setCustomPaymentLink] = useState(''); // Other Custom Bank link
  const [paymentNote, setPaymentNote] = useState('');

  const [isDragging, setIsDragging] = useState(false);

  const templates = [
    {
      id: 'embroidery',
      title: 'Embroidery / Fashion',
      icon: <Scissors className="w-5 h-5 text-theme-accent" />,
      color: 'bg-theme-surface border-theme-border-soft hover:border-theme-accent dark:bg-theme-card dark:border-theme-border-soft',
      description: 'Design No, Work Type, Size, Qty, Rate, Amount'
    },
    {
      id: 'grocery',
      title: 'Grocery / Mudi Shop',
      icon: <ShoppingBasket className="w-5 h-5 text-theme-warning" />,
      color: 'bg-theme-warning/10 border-theme-warning/20 hover:border-theme-warning',
      description: 'Product Name, Unit, Quantity, Unit Price, Amount'
    },
    {
      id: 'repair',
      title: 'Repair / Service',
      icon: <Wrench className="w-5 h-5 text-theme-accent" />,
      color: 'bg-theme-accent-light border-theme-border-soft hover:border-theme-accent dark:bg-theme-accent/10 dark:border-theme-accent/30',
      description: 'Service, Problem details, Parts, Labour, Qty'
    },
    {
      id: 'retail',
      title: 'Retail / Shopping',
      icon: <ShoppingBag className="w-5 h-5 text-theme-accent" />,
      color: 'bg-theme-surface border-theme-border-soft hover:border-theme-accent dark:bg-theme-card dark:border-theme-border-soft',
      description: 'Product, Category, Variant, Qty, Price, Discount'
    },
    {
      id: 'custom',
      title: 'Custom Bill',
      icon: <PenTool className="w-5 h-5 text-theme-muted" />,
      color: 'bg-theme-app dark:bg-theme-surface border-theme-border-soft hover:border-theme-border-soft0 dark:bg-theme-surface/40 dark:border-theme-border-soft',
      description: 'Item/Service, Description, Quantity, Rate, Amount'
    }
  ];

  // Helper when changing country, auto pre-configure some options
  const handleCountryChange = (selectedCountry) => {
    setCountry(selectedCountry);
    if (selectedCountry === 'India') {
      setPaymentMethod('UPI');
      setPaymentNote('Scan QR using any UPI app to pay securely.');
      setCustomCurrency('₹');
    } else if (selectedCountry === 'Bangladesh') {
      setPaymentMethod('bKash');
      setPaymentNote('Transfer the due amount using bKash/Nagad.');
      setCustomCurrency('৳');
    } else {
      setPaymentMethod('Manual');
      setPaymentNote('Please complete the bank transfer using details above.');
      setCustomCurrency('$');
    }
  };

  const handleNext = () => {
    if (step === 1 && !country) {
      toast.error('Please select a country to proceed.');
      return;
    }
    if (step === 2) {
      if (!businessName.trim()) {
        toast.error('Business Name is required.');
        return;
      }
      if (!ownerName.trim()) {
        toast.error('Owner Name is required.');
        return;
      }
    }
    if (step === 3) {
      if (paymentQrEnabled) {
        if (country === 'India') {
          if (paymentMethod === 'UPI' && !upiId.trim()) {
            toast.error('Please enter your UPI ID.');
            return;
          }
        } else if (country === 'Bangladesh') {
          if (paymentMethod === 'bKash' && !bkashNumber.trim() && !nagadNumber.trim()) {
            toast.error('Please provide at least a bKash or Nagad wallet number.');
            return;
          }
        } else {
          if (paymentMethod === 'Manual' && !customPaymentLink.trim()) {
            toast.error('Please enter Bank transfer details or custom payment URL.');
            return;
          }
        }
      }
    }
    setStep(prev => Math.min(prev + 1, 4));
  };

  const handleBack = () => {
    setStep(prev => Math.max(prev - 1, 1));
  };

  const handleSave = () => {
    setIsSaving(true);
    
    let currencySymbol;
    let currencyCode;
    let taxLabel;
    let computedTax;
    let dateFormat;
    let numberFormat;

    if (country === 'India') {
      currencySymbol = '₹';
      currencyCode = 'INR';
      taxLabel = 'GST';
      computedTax = 18;
      dateFormat = 'DD/MM/YYYY';
      numberFormat = 'Indian';
    } else if (country === 'Bangladesh') {
      currencySymbol = '৳';
      currencyCode = 'BDT';
      taxLabel = 'VAT';
      computedTax = parseFloat(vatTax) || 0;
      dateFormat = 'DD/MM/YYYY';
      numberFormat = 'Standard';
    } else {
      currencySymbol = customCurrency || '$';
      currencyCode = customCurrency === '$' ? 'USD' : (customCurrency === '€' ? 'EUR' : 'USD');
      taxLabel = 'Tax';
      computedTax = 0;
      dateFormat = 'DD/MM/YYYY';
      numberFormat = 'Standard';
    }

    const payload = {
      ...businessSettings,
      setupCompleted: true,
      country,
      language,
      businessName,
      ownerName,
      phone,
      email,
      address,
      logoUrl,
      defaultBillingTemplate: selectedTemplate,
      currency: currencySymbol,
      currencyCode,
      taxLabel,
      defaultTax: computedTax,
      gstNumber: gstNumber || '',
      vatTax: vatTax || '',
      paymentQrEnabled,
      paymentMethod,
      upiId,
      bkashNumber,
      nagadNumber,
      rocketNumber,
      payeeName: payeeName || businessName,
      paymentNote,
      customPaymentLink,
      brandColor: country === 'India' ? '#14b8a6' : (country === 'Bangladesh' ? '#e11d48' : '#6366f1'),
      invoiceTemplate: 'modern',
      dateFormat,
      numberFormat,
      customerLiveLinkSettings: {
        enableLiveInvoiceLink: true,
        showPaymentQr: true,
        allowCustomerPdfDownload: true,
        allowPaymentProofSubmit: true,
        showPaidDueAmount: true,
        showContactButton: true,
        requireTransactionId: true,
        requirePaymentScreenshot: false
      }
    };

    setTimeout(() => {
      onSaveSettings(payload);
      setIsSaving(false);
      toast.success('BillQyro workspace successfully initialized!');
      setCurrentTab('dashboard');
    }, 800);
  };

  return (
    <div className="min-h-screen bg-theme-app dark:bg-theme-surface dark:bg-theme-app py-10 px-4 md:px-6 flex items-center justify-center font-sans antialiased">
      <div className="max-w-3xl w-full bg-theme-card dark:bg-theme-card rounded-3xl shadow-xl border border-theme-border-soft dark:border-theme-border-soft/80 overflow-hidden flex flex-col min-h-[580px] transition-all">
        
        {/* Top Progress bar Indicator */}
        <div className="relative h-2 bg-theme-surface dark:bg-theme-card">
          <div 
            className="absolute top-0 left-0 h-full bg-[image:var(--accent-gradient)] text-theme-button-text border-0 rounded-r-full transition-all duration-500 ease-out"
            style={{ width: `${(step / 4) * 100}%` }}
          ></div>
        </div>

        {/* Dynamic Step Header */}
        <div className="bg-[#071B3A] p-6 md:p-8 text-white relative overflow-hidden">
          <div className="absolute top-0 right-0 w-32 h-32 bg-theme-accent-light rounded-full blur-2xl pointer-events-none"></div>
          <div className="absolute -bottom-10 left-10 w-32 h-32 bg-theme-accent-light rounded-full blur-2xl pointer-events-none"></div>
          
          <div className="relative z-10 flex items-center justify-between">
            <div>
              <span className="text-[10px] bg-theme-accent-light text-theme-accent border border-theme-border-soft px-2.5 py-1 rounded-full uppercase tracking-wider font-extrabold">
                Step {step} of 4
              </span>
              <h1 className="text-xl md:text-2xl font-black mt-2 tracking-tight">
                {step === 1 && 'Configure Local Region'}
                {step === 2 && 'Business Information'}
                {step === 3 && 'Payment Gateway Setup'}
                {step === 4 && 'Complete Setup & Launch'}
              </h1>
              <p className="text-xs text-theme-muted font-medium mt-1">
                {step === 1 && 'Select your country to set localization defaults.'}
                {step === 2 && 'Personalize invoices with your company details.'}
                {step === 3 && 'Enable Scan-to-Pay code options for your clients.'}
                {step === 4 && 'Double check your workspace profile and language.'}
              </p>
            </div>
            
            <div className="w-12 h-12 bg-theme-card dark:bg-theme-card/10 backdrop-blur-md border border-white/20 rounded-2xl flex items-center justify-center font-bold text-white text-lg">
              {step === 1 && <Globe className="w-6 h-6 text-theme-accent" />}
              {step === 2 && <Building2 className="w-6 h-6 text-theme-accent" />}
              {step === 3 && <QrCode className="w-6 h-6 text-theme-accent" />}
              {step === 4 && <Sparkles className="w-6 h-6 text-theme-warning" />}
            </div>
          </div>
        </div>

        {/* Core Wizard Body */}
        <div className="flex-1 p-6 md:p-8 flex flex-col justify-between">
          
          {/* STEP 1: Select Country */}
          {step === 1 && (
            <div className="space-y-6 animate-fadeIn">
              <div>
                <label className="block text-xs font-black text-theme-muted dark:text-theme-muted mb-3 uppercase tracking-wider">
                  Choose your Country
                </label>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                  {[
                    { id: 'India', flag: '🇮🇳', label: 'India', desc: 'UPI, INR ₹ Currency, GST tax defaults' },
                    { id: 'Bangladesh', flag: '🇧🇩', label: 'Bangladesh', desc: 'bKash, Nagad, Rocket, BDT ৳ Currency, VAT defaults' },
                    { id: 'Other', flag: '🌐', label: 'Other', desc: 'Manual currency selection & bank transfers' }
                  ].map((item) => (
                    <button
                      key={item.id}
                      type="button"
                      onClick={() => handleCountryChange(item.id)}
                      className={`p-5 rounded-2xl border-2 text-left transition-all ${
                        country === item.id 
                          ? 'border-theme-accent bg-theme-accent-light/20 dark:bg-theme-accent-light/20' 
                          : 'border-theme-border-soft dark:border-theme-border-soft hover:border-theme-border-soft dark:border-theme-border-soft bg-theme-app dark:bg-theme-surface/50 hover:bg-theme-surface dark:bg-theme-surface/40 dark:bg-theme-card/30'
                      }`}
                    >
                      <div className="text-3xl mb-2">{item.flag}</div>
                      <h3 className="font-extrabold text-sm text-theme-primary dark:text-theme-primary">{item.label}</h3>
                      <p className="text-[10px] text-theme-muted font-semibold mt-1 leading-snug">{item.desc}</p>
                    </button>
                  ))}
                </div>
              </div>

              <div className="p-4 bg-theme-surface dark:bg-theme-surface dark:bg-theme-accent/5 border border-theme-border-soft dark:border-theme-border-soft rounded-2xl">
                <p className="text-[10px] text-theme-muted leading-relaxed font-bold">
                  “Choose your country to automatically set currency, payment methods, and tax labels.”
                </p>
              </div>
            </div>
          )}

          {/* STEP 2: Business Profile */}
          {step === 2 && (
            <div className="space-y-4 animate-fadeIn">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-theme-muted dark:text-theme-muted mb-1.5 uppercase">Registered Business Name *</label>
                  <input
                    type="text"
                    required
                    value={businessName}
                    onChange={(e) => setBusinessName(e.target.value)}
                    placeholder="e.g. BillQyro Embroidery"
                    className="w-full px-4 py-2.5 bg-theme-app dark:bg-theme-surface dark:bg-theme-card border border-theme-border-soft dark:border-theme-border-soft rounded-xl focus:outline-none focus:ring-2 focus:ring-theme-accent/30 focus:border-theme-accent text-theme-primary dark:text-theme-primary font-bold"
                  />
                </div>
                
                <div>
                  <label className="block text-xs font-bold text-theme-muted dark:text-theme-muted mb-1.5 uppercase">Owner Full Name *</label>
                  <input
                    type="text"
                    required
                    value={ownerName}
                    onChange={(e) => setOwnerName(e.target.value)}
                    placeholder="e.g. John Doe"
                    className="w-full px-4 py-2.5 bg-theme-app dark:bg-theme-surface dark:bg-theme-card border border-theme-border-soft dark:border-theme-border-soft rounded-xl focus:outline-none focus:ring-2 focus:ring-theme-accent/30 focus:border-theme-accent text-theme-primary dark:text-theme-primary font-bold"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-theme-muted dark:text-theme-muted mb-1.5 uppercase">Phone Number</label>
                  <input
                    type="text"
                    value={phone}
                    onChange={(e) => setPhone(e.target.value)}
                    placeholder="e.g. +91 98765 XXXXX"
                    className="w-full px-4 py-2.5 bg-theme-app dark:bg-theme-surface dark:bg-theme-card border border-theme-border-soft dark:border-theme-border-soft rounded-xl focus:outline-none focus:ring-2 focus:ring-theme-accent/30 text-theme-primary dark:text-theme-primary dark:text-theme-secondary font-semibold"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-theme-muted dark:text-theme-muted mb-1.5 uppercase">Business Email</label>
                  <input
                    type="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="contact@company.com"
                    className="w-full px-4 py-2.5 bg-theme-app dark:bg-theme-surface dark:bg-theme-card border border-theme-border-soft dark:border-theme-border-soft rounded-xl focus:outline-none focus:ring-2 focus:ring-theme-accent/30 text-theme-primary dark:text-theme-primary dark:text-theme-secondary font-semibold"
                  />
                </div>

                <div className="md:col-span-2">
                  <label className="block text-xs font-bold text-theme-muted dark:text-theme-muted mb-1.5 uppercase">Corporate Address</label>
                  <textarea
                    value={address}
                    onChange={(e) => setAddress(e.target.value)}
                    placeholder="Full business office address details..."
                    rows="2"
                    className="w-full px-4 py-2.5 bg-theme-app dark:bg-theme-surface dark:bg-theme-card border border-theme-border-soft dark:border-theme-border-soft rounded-xl focus:outline-none focus:ring-2 focus:ring-theme-accent/30 text-theme-primary dark:text-theme-primary dark:text-theme-secondary resize-none text-xs"
                  />
                </div>

                {/* Base64 Logo Upload integration */}
                <div className="md:col-span-2">
                  <label className="block text-xs font-bold text-theme-muted dark:text-theme-muted mb-1.5 uppercase">Corporate Logo (Optional)</label>
                  <div
                    className={`relative border-2 border-dashed rounded-xl p-4.5 text-center transition-all ${
                      isDragging ? 'border-theme-accent bg-theme-accent-light/30 dark:bg-theme-accent-light/20' : 'border-theme-border-soft bg-theme-app dark:bg-theme-surface hover:bg-theme-surface dark:bg-theme-card dark:border-theme-border-soft dark:bg-theme-surface/40 dark:hover:bg-theme-surface'
                    }`}
                    onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
                    onDragLeave={() => setIsDragging(false)}
                    onDrop={(e) => {
                      e.preventDefault();
                      setIsDragging(false);
                      const file = e.dataTransfer.files[0];
                      if (file && file.type.startsWith('image/')) {
                        const reader = new FileReader();
                        reader.onload = (event) => setLogoUrl(event.target.result);
                        reader.readAsDataURL(file);
                      }
                    }}
                  >
                    <input
                      type="file"
                      accept="image/*"
                      onChange={(e) => {
                        const file = e.target.files[0];
                        if (file && file.type.startsWith('image/')) {
                          const reader = new FileReader();
                          reader.onload = (event) => setLogoUrl(event.target.result);
                          reader.readAsDataURL(file);
                        }
                      }}
                      className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                    />
                    <div className="flex flex-col items-center justify-center gap-1.5 pointer-events-none">
                      <Upload className="w-5 h-5 text-theme-muted" />
                      <span className="text-xs font-bold text-theme-muted dark:text-theme-muted">Drag & drop logo file, or click to upload</span>
                    </div>
                  </div>
                  {logoUrl && (
                    <div className="mt-3 flex items-center gap-3.5 bg-theme-app dark:bg-theme-surface dark:bg-theme-surface p-2.5 rounded-xl border border-theme-border-soft/40 dark:border-theme-border-soft">
                      <img src={logoUrl} alt="Logo" className="h-10 w-auto object-contain rounded-lg border bg-theme-card dark:bg-theme-card p-0.5" />
                      <span className="text-[10px] text-theme-muted font-bold uppercase truncate max-w-xs flex-1">Logo image uploaded</span>
                      <button
                        type="button"
                        onClick={() => setLogoUrl('')}
                        className="p-1.5 bg-theme-danger/5 text-theme-danger hover:bg-theme-danger/10 rounded-lg transition-colors cursor-pointer"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  )}
                </div>
              </div>

              {/* Template selection integrated */}
              <div className="pt-2">
                <label className="block text-xs font-black text-theme-muted dark:text-theme-muted mb-2 uppercase tracking-wide">
                  Configure Your Invoicing Layout
                </label>
                <div className="grid grid-cols-2 sm:grid-cols-5 gap-1.5">
                  {templates.map((tpl) => {
                    const isSelected = selectedTemplate === tpl.id;
                    return (
                      <button
                        key={tpl.id}
                        type="button"
                        onClick={() => setSelectedTemplate(tpl.id)}
                        className={`p-2.5 rounded-xl border text-center transition-all flex flex-col items-center justify-between min-h-[90px] ${
                          isSelected 
                            ? 'border-theme-accent bg-theme-accent-light/30 dark:bg-theme-accent-light/20 text-theme-accent dark:text-theme-accent shadow-sm scale-102 font-bold' 
                            : 'border-theme-border-soft dark:border-theme-border-soft bg-theme-app dark:bg-theme-surface/50 hover:bg-theme-surface dark:bg-theme-card text-theme-muted dark:border-theme-border-soft dark:bg-theme-card/30'
                        }`}
                      >
                        <div className="p-1.5 bg-theme-card dark:bg-theme-card dark:bg-theme-surface rounded-lg shadow-xs mb-1.5">
                          {tpl.icon}
                        </div>
                        <h4 className="text-[10px] leading-tight font-extrabold">{tpl.title}</h4>
                      </button>
                    );
                  })}
                </div>
              </div>
            </div>
          )}

          {/* STEP 3: Payment Configuration (DYNAMICS) */}
          {step === 3 && (
            <div className="space-y-4 animate-fadeIn">
              {/* Payment Enable toggle */}
              <div className="flex items-center justify-between p-3.5 bg-theme-app dark:bg-theme-surface dark:bg-theme-surface border border-theme-border-soft dark:border-theme-border-soft rounded-xl">
                <div>
                  <span className="text-xs font-black text-theme-primary dark:text-theme-muted dark:text-theme-primary block">Enable Automated Scan-to-Pay QR Codes</span>
                  <span className="text-[9px] text-theme-muted font-bold">Embed a QR payment code and deep link inside digital invoices for immediate payment.</span>
                </div>
                <button 
                  type="button"
                  onClick={() => setPaymentQrEnabled(!paymentQrEnabled)}
                  className={`w-10 h-5.5 rounded-full relative transition-colors duration-300 focus:outline-none ${paymentQrEnabled ? 'bg-theme-accent' : 'bg-theme-border-strong dark:bg-theme-surface'}`}
                >
                  <div className={`w-4 h-4 bg-white rounded-full shadow-[0_1px_3px_rgba(0,0,0,0.3)] transition-transform duration-500 ease-in-out ${paymentQrEnabled ? 'translate-x-5' : 'translate-x-0'}`}></div>
                </button>
              </div>

              {paymentQrEnabled && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-2">
                  
                  {/* DYNAMIC CONFIGS DEPENDING ON COUNTRY */}
                  {country === 'India' && (
                    <>
                      <div>
                        <label className="block text-xs font-bold text-theme-muted dark:text-theme-muted mb-1.5 uppercase">UPI ID *</label>
                        <input
                          type="text"
                          required
                          value={upiId}
                          onChange={(e) => setUpiId(e.target.value)}
                          placeholder="e.g. yourbusiness@okaxis"
                          className="w-full px-4 py-2.5 bg-theme-app dark:bg-theme-surface dark:bg-theme-card border border-theme-border-soft dark:border-theme-border-soft rounded-xl focus:outline-none focus:ring-2 focus:ring-theme-accent/30 text-theme-primary dark:text-theme-primary font-bold"
                        />
                      </div>

                      <div>
                        <label className="block text-xs font-bold text-theme-muted dark:text-theme-muted mb-1.5 uppercase">Payee / Account Name *</label>
                        <input
                          type="text"
                          required
                          value={payeeName}
                          onChange={(e) => setPayeeName(e.target.value)}
                          placeholder="e.g. BillQyro Store"
                          className="w-full px-4 py-2.5 bg-theme-app dark:bg-theme-surface dark:bg-theme-card border border-theme-border-soft dark:border-theme-border-soft rounded-xl focus:outline-none focus:ring-2 focus:ring-theme-accent/30 text-theme-primary dark:text-theme-primary font-bold"
                        />
                      </div>

                      <div className="md:col-span-2">
                        <label className="block text-xs font-bold text-theme-muted dark:text-theme-muted mb-1.5 uppercase">GSTIN / Tax ID (Optional)</label>
                        <input
                          type="text"
                          value={gstNumber}
                          onChange={(e) => setGstNumber(e.target.value)}
                          placeholder="e.g. 29AAAAA0000A1Z5"
                          className="w-full px-4 py-2.5 bg-theme-app dark:bg-theme-surface dark:bg-theme-card border border-theme-border-soft dark:border-theme-border-soft rounded-xl focus:outline-none focus:ring-2 focus:ring-theme-accent/30 text-theme-primary dark:text-theme-primary font-bold uppercase"
                        />
                      </div>
                    </>
                  )}

                  {country === 'Bangladesh' && (
                    <>
                      <div>
                        <label className="block text-xs font-bold text-theme-muted dark:text-theme-muted mb-1.5 uppercase">bKash Account Number *</label>
                        <input
                          type="text"
                          required
                          value={bkashNumber}
                          onChange={(e) => setBkashNumber(e.target.value)}
                          placeholder="e.g. 017XXXXXXXX"
                          className="w-full px-4 py-2.5 bg-theme-app dark:bg-theme-surface dark:bg-theme-card border border-theme-border-soft dark:border-theme-border-soft rounded-xl focus:outline-none focus:ring-2 focus:ring-theme-accent/30 text-theme-primary dark:text-theme-primary font-bold"
                        />
                      </div>

                      <div>
                        <label className="block text-xs font-bold text-theme-muted dark:text-theme-muted mb-1.5 uppercase">Nagad Account Number</label>
                        <input
                          type="text"
                          value={nagadNumber}
                          onChange={(e) => setNagadNumber(e.target.value)}
                          placeholder="e.g. 019XXXXXXXX"
                          className="w-full px-4 py-2.5 bg-theme-app dark:bg-theme-surface dark:bg-theme-card border border-theme-border-soft dark:border-theme-border-soft rounded-xl focus:outline-none focus:ring-2 focus:ring-theme-accent/30 text-theme-primary dark:text-theme-primary font-bold"
                        />
                      </div>

                      <div>
                        <label className="block text-xs font-bold text-theme-muted dark:text-theme-muted mb-1.5 uppercase">Rocket Account Number (Optional)</label>
                        <input
                          type="text"
                          value={rocketNumber}
                          onChange={(e) => setRocketNumber(e.target.value)}
                          placeholder="e.g. 018XXXXXXXX"
                          className="w-full px-4 py-2.5 bg-theme-app dark:bg-theme-surface dark:bg-theme-card border border-theme-border-soft dark:border-theme-border-soft rounded-xl focus:outline-none focus:ring-2 focus:ring-theme-accent/30 text-theme-primary dark:text-theme-primary font-bold"
                        />
                      </div>

                      <div>
                        <label className="block text-xs font-bold text-theme-muted dark:text-theme-muted mb-1.5 uppercase">Default VAT/Tax % (Optional)</label>
                        <input
                          type="number"
                          value={vatTax}
                          onChange={(e) => setVatTax(e.target.value)}
                          placeholder="e.g. 7.5"
                          className="w-full px-4 py-2.5 bg-theme-app dark:bg-theme-surface dark:bg-theme-card border border-theme-border-soft dark:border-theme-border-soft rounded-xl focus:outline-none focus:ring-2 focus:ring-theme-accent/30 text-theme-primary dark:text-theme-primary font-bold"
                        />
                      </div>
                    </>
                  )}

                  {country === 'Other' && (
                    <>
                      <div>
                        <label className="block text-xs font-bold text-theme-muted dark:text-theme-muted mb-1.5 uppercase font-black">Choose Currency *</label>
                        <select
                          value={customCurrency}
                          onChange={(e) => setCustomCurrency(e.target.value)}
                          className="w-full px-4 py-2.5 bg-theme-app dark:bg-theme-surface dark:bg-theme-card border border-theme-border-soft dark:border-theme-border-soft rounded-xl focus:outline-none focus:ring-2 focus:ring-theme-accent/30 text-theme-primary dark:text-theme-primary font-bold"
                        >
                          <option value="$">USD $ (US Dollar)</option>
                          <option value="€">EUR € (Euro)</option>
                          <option value="£">GBP £ (Pound)</option>
                          <option value="¥">JPY ¥ (Yen)</option>
                          <option value="AED">AED (Dirham)</option>
                          <option value="SAR">SAR (Riyal)</option>
                        </select>
                      </div>

                      <div>
                        <label className="block text-xs font-bold text-theme-muted dark:text-theme-muted mb-1.5 uppercase">Custom Payment Link / QR Text *</label>
                        <input
                          type="text"
                          required
                          value={customPaymentLink}
                          onChange={(e) => setCustomPaymentLink(e.target.value)}
                          placeholder="e.g. https://paypal.me/yourbusiness or bank details"
                          className="w-full px-4 py-2.5 bg-theme-app dark:bg-theme-surface dark:bg-theme-card border border-theme-border-soft dark:border-theme-border-soft rounded-xl focus:outline-none focus:ring-2 focus:ring-theme-accent/30 text-theme-primary dark:text-theme-primary"
                        />
                      </div>
                    </>
                  )}

                  {/* Payment instructions note */}
                  <div className="md:col-span-2">
                    <label className="block text-xs font-bold text-theme-muted dark:text-theme-muted mb-1.5 uppercase">Custom Payment Instructions (Note)</label>
                    <input
                      type="text"
                      value={paymentNote}
                      onChange={(e) => setPaymentNote(e.target.value)}
                      placeholder="Showed beneath the payment QR code module."
                      className="w-full px-4 py-2.5 bg-theme-app dark:bg-theme-surface dark:bg-theme-card border border-theme-border-soft dark:border-theme-border-soft rounded-xl focus:outline-none focus:ring-2 focus:ring-theme-accent/30 text-theme-primary dark:text-theme-secondary text-xs"
                    />
                  </div>

                </div>
              )}
            </div>
          )}

          {/* STEP 4: Review Summary & Language Selection */}
          {step === 4 && (
            <div className="space-y-5 animate-fadeIn text-xs font-semibold text-theme-muted">
              
              {/* Language selection with dynamic suggests */}
              <div className="bg-theme-card dark:bg-theme-card border border-theme-border-soft dark:border-theme-border-soft rounded-2xl p-4.5 space-y-3.5 shadow-sm">
                <label className="block text-xs font-black text-theme-muted dark:text-theme-muted uppercase tracking-wider">
                  Choose UI Language
                </label>
                <div className="relative">
                  <span className="absolute inset-y-0 left-0 pl-3.5 flex items-center text-theme-muted">
                    <Languages className="w-4 h-4" />
                  </span>
                  <select
                    value={language}
                    onChange={(e) => setLanguage(e.target.value)}
                    className="w-full pl-10 pr-4 py-3 bg-theme-app dark:bg-theme-surface dark:bg-theme-card border border-theme-border-soft dark:border-theme-border-soft rounded-xl focus:outline-none focus:ring-2 focus:ring-theme-accent/30 focus:border-theme-accent text-theme-primary dark:text-theme-muted dark:text-theme-secondary font-bold"
                  >
                    <option value="English">English (Global standard)</option>
                    <option value="Bengali">Bengali (বাংলা)</option>
                    <option value="Hindi">Hindi (हिंदी)</option>
                  </select>
                </div>

                {/* Country recommendations */}
                <div className="flex flex-wrap items-center gap-2 pt-1.5">
                  <span className="text-[9px] text-theme-muted font-extrabold uppercase mr-1">Suggested for you:</span>
                  {country === 'India' && (
                    <>
                      <button type="button" onClick={() => setLanguage('English')} className={`px-3 py-1 text-[10px] font-black rounded-lg border transition-all ${language === 'English' ? 'bg-theme-accent text-white border-theme-accent' : 'bg-theme-app dark:bg-theme-surface text-theme-muted border-theme-border-soft dark:bg-theme-card dark:text-theme-muted dark:border-theme-border-soft'}`}>English</button>
                      <button type="button" onClick={() => setLanguage('Hindi')} className={`px-3 py-1 text-[10px] font-black rounded-lg border transition-all ${language === 'Hindi' ? 'bg-theme-accent text-white border-theme-accent' : 'bg-theme-app dark:bg-theme-surface text-theme-muted border-theme-border-soft dark:bg-theme-card dark:text-theme-muted dark:border-theme-border-soft'}`}>Hindi</button>
                      <button type="button" onClick={() => setLanguage('Bengali')} className={`px-3 py-1 text-[10px] font-black rounded-lg border transition-all ${language === 'Bengali' ? 'bg-theme-accent text-white border-theme-accent' : 'bg-theme-app dark:bg-theme-surface text-theme-muted border-theme-border-soft dark:bg-theme-card dark:text-theme-muted dark:border-theme-border-soft'}`}>Bengali</button>
                    </>
                  )}
                  {country === 'Bangladesh' && (
                    <>
                      <button type="button" onClick={() => setLanguage('English')} className={`px-3 py-1 text-[10px] font-black rounded-lg border transition-all ${language === 'English' ? 'bg-theme-accent text-white border-theme-accent' : 'bg-theme-app dark:bg-theme-surface text-theme-muted border-theme-border-soft dark:bg-theme-card dark:text-theme-muted dark:border-theme-border-soft'}`}>English</button>
                      <button type="button" onClick={() => setLanguage('Bengali')} className={`px-3 py-1 text-[10px] font-black rounded-lg border transition-all ${language === 'Bengali' ? 'bg-theme-accent text-white border-theme-accent' : 'bg-theme-app dark:bg-theme-surface text-theme-muted border-theme-border-soft dark:bg-theme-card dark:text-theme-muted dark:border-theme-border-soft'}`}>Bengali</button>
                    </>
                  )}
                  {country === 'Other' && (
                    <button type="button" onClick={() => setLanguage('English')} className={`px-3 py-1 text-[10px] font-black rounded-lg border transition-all ${language === 'English' ? 'bg-theme-accent text-white border-theme-accent' : 'bg-theme-app dark:bg-theme-surface text-theme-muted border-theme-border-soft dark:bg-theme-card dark:text-theme-muted dark:border-theme-border-soft'}`}>English</button>
                  )}
                </div>
              </div>

              <div className="bg-theme-app dark:bg-theme-surface dark:bg-theme-surface rounded-2xl p-5 border border-theme-border-soft dark:border-theme-border-soft space-y-4">
                <h3 className="font-extrabold text-sm text-theme-primary dark:text-theme-primary flex items-center gap-1.5 uppercase">
                  <CheckCircle2 className="w-4 h-4 text-theme-accent" /> Confirm Profile Summary
                </h3>
                
                <div className="grid grid-cols-2 gap-y-3.5 text-theme-primary dark:text-theme-muted">
                  <div>
                    <span className="text-[10px] text-theme-muted block uppercase">Business Name</span>
                    <strong className="text-theme-primary dark:text-theme-primary text-sm">{businessName}</strong>
                  </div>
                  <div>
                    <span className="text-[10px] text-theme-muted block uppercase">Owner Name</span>
                    <strong className="text-theme-primary dark:text-theme-primary text-sm">{ownerName}</strong>
                  </div>
                  <div>
                    <span className="text-[10px] text-theme-muted block uppercase">Region & Currency</span>
                    <span>{country} ({country === 'India' ? 'INR ₹' : (country === 'Bangladesh' ? 'BDT ৳' : customCurrency)})</span>
                  </div>
                  <div>
                    <span className="text-[10px] text-theme-muted block uppercase">Tax Parameter</span>
                    <span>{country === 'India' ? 'GST' : (country === 'Bangladesh' ? 'VAT' : 'Tax')}</span>
                  </div>
                  <div>
                    <span className="text-[10px] text-theme-muted block uppercase">Invoicing Layout</span>
                    <span className="capitalize">{selectedTemplate} format</span>
                  </div>
                  <div>
                    <span className="text-[10px] text-theme-muted block uppercase">UI Language</span>
                    <span>{language}</span>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Wizard Footer Navigation Controls */}
          <div className="flex items-center justify-between pt-6 border-t border-theme-border-soft dark:border-theme-border-soft/80 mt-8">
            <button
              onClick={handleBack}
              disabled={step === 1 || isSaving}
              className={`flex items-center gap-1.5 px-4.5 py-2.5 rounded-xl text-xs font-extrabold border transition-all cursor-pointer ${
                step === 1 
                  ? 'border-transparent text-theme-muted dark:text-theme-primary dark:text-theme-muted cursor-default' 
                  : 'bg-theme-card dark:bg-theme-card hover:bg-theme-app dark:bg-theme-surface border-theme-border-soft dark:border-theme-border-soft dark:bg-theme-card text-theme-muted dark:text-theme-muted active:scale-95'
              }`}
            >
              <ChevronLeft className="w-4 h-4" />
              <span>Back</span>
            </button>

            {step < 4 ? (
              <button
                onClick={handleNext}
                className="flex items-center gap-1.5 px-6 py-2.5 bg-[image:var(--accent-gradient)] text-theme-button-text border-0 hover:opacity-90 rounded-xl text-xs font-black tracking-wider uppercase active:scale-98 transition-all cursor-pointer shadow-md"
              >
                <span>Continue</span>
                <ChevronRight className="w-4 h-4" />
              </button>
            ) : (
              <button
                onClick={handleSave}
                disabled={isSaving}
                className="flex items-center gap-2 px-8 py-3 bg-[image:var(--accent-gradient)] text-theme-button-text border-0 hover:opacity-90 rounded-xl text-xs font-black tracking-widest uppercase active:scale-98 transition-all cursor-pointer shadow-glow"
              >
                {isSaving ? (
                  <>
                    <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
                    <span>Initializing...</span>
                  </>
                ) : (
                  <>
                    <Check className="w-4 h-4" />
                    <span>Launch Workspace</span>
                  </>
                )}
              </button>
            )}
          </div>

        </div>

      </div>
    </div>
  );
};

export default SetupBilling;

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { LogOut, BookOpen, GraduationCap, Calendar, FileText, Bell, CheckCircle, ShieldCheck, Download, User, Wallet } from 'lucide-react';
import { auth } from '../services/firebaseConfig';
import { onAuthStateChanged, signOut } from 'firebase/auth';
import { invoiceEngine } from '../services/invoiceEngine';
import StudentLogin from '../components/portal/StudentLogin';
import ClassicLoader from '../components/ClassicLoader';
import { formatCurrency } from '../utils/invoiceUtils';
import { downloadInvoicePDF } from '../utils/pdfUtils';
import { toast } from 'react-hot-toast';

export default function StudentPortal({ studentId }) {
  const [user, setUser] = useState(null);
  const [loadingAuth, setLoadingAuth] = useState(true);
  
  const [profile, setProfile] = useState(null);
  const [invoices, setInvoices] = useState([]);
  const [loadingData, setLoadingData] = useState(false);
  const [activeTab, setActiveTab] = useState('fees');

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setLoadingAuth(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (user && studentId) {
      loadPortalData();
    }
  }, [user, studentId]);

  const loadPortalData = async () => {
    setLoadingData(true);
    try {
      const fetchedInvoices = await invoiceEngine.getStudentInvoices(studentId, user.email);
      const fetchedProfile = await invoiceEngine.getStudentProfile(studentId, user.email);
      
      setInvoices(fetchedInvoices);
      setProfile(fetchedProfile || { name: 'Student', email: user.email, id: studentId });
    } catch (err) {
      console.error(err);
      toast.error('Failed to load student data.');
    } finally {
      setLoadingData(false);
    }
  };

  const handleLogout = async () => {
    await signOut(auth);
    setUser(null);
    setInvoices([]);
    setProfile(null);
    toast.success('Securely logged out.');
  };

  if (loadingAuth) {
    return <div className="min-h-screen bg-slate-50 flex items-center justify-center"><ClassicLoader /></div>;
  }

  if (!user) {
    return <StudentLogin studentId={studentId} onLoginSuccess={setUser} />;
  }

  if (loadingData) {
    return <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center"><ClassicLoader /><p className="text-slate-600 mt-4 font-bold animate-pulse">Loading Student Records...</p></div>;
  }

  // Calculate Dashboard Metrics
  const totalDue = invoices.reduce((sum, inv) => sum + (inv.balanceDue || (inv.grandTotal - (inv.amountPaid || 0))), 0);
  const totalPaid = invoices.reduce((sum, inv) => sum + (inv.amountPaid || 0), 0);
  const overdueInvoices = invoices.filter(inv => inv.paymentStatus !== 'Paid' && new Date(inv.dueDate) < new Date());

  const activeSymbol = invoices[0]?.regionalSettingsSnapshot?.currency || '₹';

  const tabs = [
    { id: 'fees', label: 'Fee Details', icon: Wallet },
    { id: 'notices', label: 'Notice Board', icon: Bell },
    { id: 'attendance', label: 'Attendance', icon: Calendar },
    { id: 'results', label: 'Academic Results', icon: BookOpen },
  ];

  return (
    <div className="min-h-screen bg-slate-50 text-slate-800 font-sans p-4 md:p-8">
      <div className="max-w-6xl mx-auto space-y-6">
        
        {/* Header */}
        <header className="flex flex-col md:flex-row justify-between items-start md:items-center bg-white p-6 rounded-3xl border border-slate-200 shadow-sm gap-4 relative overflow-hidden">
          <div className="absolute top-0 right-0 w-64 h-64 bg-blue-500/5 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2"></div>
          <div className="flex items-center gap-4 relative z-10">
            <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-blue-600/30">
              <GraduationCap className="w-8 h-8" />
            </div>
            <div>
              <h1 className="text-2xl font-black text-slate-900">{profile?.name || 'Student Portal'}</h1>
              <p className="text-slate-500 text-sm flex items-center gap-2 font-medium mt-1">
                <ShieldCheck className="w-4 h-4 text-emerald-500" /> ID: {studentId} • {profile?.email}
              </p>
            </div>
          </div>
          <button 
            onClick={handleLogout}
            className="flex items-center gap-2 px-5 py-2.5 bg-rose-50 hover:bg-rose-100 text-rose-600 rounded-xl transition-all font-bold text-sm relative z-10"
          >
            <LogOut className="w-4 h-4" /> Sign Out
          </button>
        </header>

        {/* Tab Navigation */}
        <div className="flex overflow-x-auto hide-scrollbar gap-2 p-1 bg-white rounded-2xl border border-slate-200 shadow-sm">
          {tabs.map(tab => {
            const Icon = tab.icon;
            const isActive = activeTab === tab.id;
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex items-center gap-2 px-6 py-3 rounded-xl font-bold text-sm transition-all whitespace-nowrap ${isActive ? 'bg-blue-600 text-white shadow-md shadow-blue-600/20' : 'text-slate-500 hover:bg-slate-100'}`}
              >
                <Icon className="w-4 h-4" /> {tab.label}
              </button>
            );
          })}
        </div>

        {/* Content Area */}
        <AnimatePresence mode="wait">
          <motion.div
            key={activeTab}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            transition={{ duration: 0.2 }}
          >
            {activeTab === 'fees' && (
              <div className="space-y-6">
                {/* Metrics */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm relative overflow-hidden">
                    <h3 className="text-slate-500 text-xs font-bold uppercase mb-2 flex items-center gap-2"><Wallet className="w-4 h-4" /> Total Due Fees</h3>
                    <p className="text-4xl font-black text-rose-500">{formatCurrency(totalDue, activeSymbol)}</p>
                  </div>
                  <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm relative overflow-hidden">
                    <h3 className="text-slate-500 text-xs font-bold uppercase mb-2 flex items-center gap-2"><CheckCircle className="w-4 h-4" /> Fees Paid</h3>
                    <p className="text-4xl font-black text-emerald-500">{formatCurrency(totalPaid, activeSymbol)}</p>
                  </div>
                  <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm relative overflow-hidden">
                    <h3 className="text-slate-500 text-xs font-bold uppercase mb-2 flex items-center gap-2"><Calendar className="w-4 h-4" /> Overdue Invoices</h3>
                    <p className="text-4xl font-black text-amber-500">{overdueInvoices.length}</p>
                  </div>
                </div>

                {/* Fee History */}
                <div className="bg-white border border-slate-200 rounded-3xl shadow-sm overflow-hidden">
                  <div className="p-6 border-b border-slate-100 flex justify-between items-center">
                    <h2 className="text-xl font-black text-slate-900 flex items-center gap-2"><FileText className="w-5 h-5 text-blue-500" /> Fee Receipts & Invoices</h2>
                  </div>
                  <div className="overflow-x-auto">
                    <table className="w-full text-left text-sm">
                      <thead className="bg-slate-50 text-slate-500 text-xs uppercase font-bold">
                        <tr>
                          <th className="px-6 py-4 rounded-tl-lg">Invoice No</th>
                          <th className="px-6 py-4">Date</th>
                          <th className="px-6 py-4">Total Fee</th>
                          <th className="px-6 py-4">Status</th>
                          <th className="px-6 py-4 text-right rounded-tr-lg">Receipt</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {invoices.length === 0 ? (
                          <tr>
                            <td colSpan="5" className="px-6 py-12 text-center text-slate-500">
                              <div className="flex flex-col items-center justify-center">
                                <FileText className="w-12 h-12 text-slate-300 mb-3" />
                                <span className="font-bold">No fee records found.</span>
                              </div>
                            </td>
                          </tr>
                        ) : (
                          invoices.map((inv) => (
                            <tr key={inv.id} className="hover:bg-slate-50/80 transition-colors">
                              <td className="px-6 py-4 font-bold text-slate-900">{inv.invoiceNumber}</td>
                              <td className="px-6 py-4 text-slate-500 font-medium">{new Date(inv.date).toLocaleDateString()}</td>
                              <td className="px-6 py-4 font-bold text-slate-900">{formatCurrency(inv.grandTotal, activeSymbol)}</td>
                              <td className="px-6 py-4">
                                <span className={`px-2.5 py-1 rounded-lg text-[11px] font-black uppercase tracking-wider ${
                                  inv.paymentStatus === 'Paid' ? 'bg-emerald-100 text-emerald-700' :
                                  inv.paymentStatus === 'Partial' ? 'bg-amber-100 text-amber-700' :
                                  'bg-rose-100 text-rose-700'
                                }`}>
                                  {inv.paymentStatus || 'Unpaid'}
                                </span>
                              </td>
                              <td className="px-6 py-4 text-right">
                                <button 
                                  onClick={() => downloadInvoicePDF(inv, inv.businessSnapshot, false)}
                                  className="inline-flex items-center justify-center p-2.5 bg-blue-50 hover:bg-blue-100 text-blue-600 rounded-xl transition-colors font-semibold text-xs gap-2"
                                  title="Download PDF"
                                >
                                  <Download className="w-4 h-4" /> PDF
                                </button>
                              </td>
                            </tr>
                          ))
                        )}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'notices' && (
              <div className="bg-white border border-slate-200 rounded-3xl p-12 text-center shadow-sm">
                <Bell className="w-16 h-16 text-slate-300 mx-auto mb-4" />
                <h3 className="text-xl font-bold text-slate-900 mb-2">No active notices</h3>
                <p className="text-slate-500">You're all caught up! New announcements will appear here.</p>
              </div>
            )}

            {activeTab === 'attendance' && (
              <div className="bg-white border border-slate-200 rounded-3xl p-12 text-center shadow-sm">
                <Calendar className="w-16 h-16 text-slate-300 mx-auto mb-4" />
                <h3 className="text-xl font-bold text-slate-900 mb-2">Attendance Tracking</h3>
                <p className="text-slate-500">Coming soon in the next update.</p>
              </div>
            )}

            {activeTab === 'results' && (
              <div className="bg-white border border-slate-200 rounded-3xl p-12 text-center shadow-sm">
                <BookOpen className="w-16 h-16 text-slate-300 mx-auto mb-4" />
                <h3 className="text-xl font-bold text-slate-900 mb-2">Academic Results</h3>
                <p className="text-slate-500">Your examination results and report cards will be visible here.</p>
              </div>
            )}
          </motion.div>
        </AnimatePresence>

      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import AnimatedPage from '../components/AnimatedPage';
import { LifeBuoy, ArrowLeft, Mail, MessageCircle, FileText, Check, AlertCircle, Plus, Send, Upload, Inbox, CheckCircle } from 'lucide-react';
import { authEngine } from '../services/authEngine';
import { adminEngine } from '../services/adminEngine';
import { supportEngine } from '../services/supportEngine';
import { toast } from 'react-hot-toast';

export default function Support({ onBack }) {
  const [activeTab, setActiveTab] = useState('faq'); // 'faq' | 'tickets' | 'features' | 'changelog'
  
  // Support ticket form state
  const [issueType, setIssueType] = useState('Question');
  const [ticketMsg, setTicketMsg] = useState('');
  const [userPhone, setUserPhone] = useState('');
  const [userEmail, setUserEmail] = useState('');
  const [ticketScreenshot, setTicketScreenshot] = useState(null);
  const [ticketScreenshotBase64, setTicketScreenshotBase64] = useState('');
  const [submittingTicket, setSubmittingTicket] = useState(false);
  const [myTickets, setMyTickets] = useState([]);

  // Feature request form state
  const [featureTitle, setFeatureTitle] = useState('');
  const [featureDesc, setFeatureDesc] = useState('');
  const [featurePriority, setFeaturePriority] = useState('Medium');
  const [submittingFeature, setSubmittingFeature] = useState(false);
  const [myFeatures, setMyFeatures] = useState([]);

  // Changelogs state
  const [changelogs, setChangelogs] = useState([]);
  const [loadingChangelogs, setLoadingChangelogs] = useState(false);

  // Load user email on mount
  useEffect(() => {
    const session = authEngine.getAuthSession();
    if (session?.userEmail) {
      setUserEmail(session.userEmail);
    }
  }, []);

  const fetchUserData = async () => {
    const userId = authEngine.getRealUserId() || 'local-user';
    try {
      const tickets = await supportEngine.getUserSupportTickets(userId);
      setMyTickets(tickets);
      
      const features = await supportEngine.getUserFeatureRequests(userId);
      setMyFeatures(features);
    } catch (e) {
      console.error(e);
    }
  };

  const fetchChangelogs = async () => {
    setLoadingChangelogs(true);
    try {
      const logs = await adminEngine.getAdminAllChangelogs();
      setChangelogs(logs);
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingChangelogs(false);
    }
  };

  useEffect(() => {
    fetchUserData();
    fetchChangelogs();
  }, []);

  const handleScreenshotChange = (file) => {
    if (file && file.type.startsWith('image/')) {
      setTicketScreenshot(file);
      const reader = new FileReader();
      reader.onload = (event) => setTicketScreenshotBase64(event.target.result);
      reader.readAsDataURL(file);
    }
  };

  const handleTicketSubmit = async (e) => {
    e.preventDefault();
    if (!ticketMsg.trim()) {
      toast.error('Please write a message detailing your issue.');
      return;
    }

    setSubmittingTicket(true);
    try {
      const userId = authEngine.getRealUserId() || 'local-user';
      const email = userEmail || authEngine.getAuthSession()?.userEmail || 'local-user';
      
      await supportEngine.submitSupportTicket(userId, email, userPhone, issueType, ticketMsg, ticketScreenshotBase64);
      toast.success('Support ticket submitted successfully!');
      
      // Reset
      setTicketMsg('');
      setUserPhone('');
      setTicketScreenshot(null);
      setTicketScreenshotBase64('');
      fetchUserData();
    } catch (err) {
      console.error(err);
      toast.error('Failed to submit support ticket.');
    } finally {
      setSubmittingTicket(false);
    }
  };

  const handleFeatureSubmit = async (e) => {
    e.preventDefault();
    if (!featureTitle.trim() || !featureDesc.trim()) {
      toast.error('Please fill in both the title and description.');
      return;
    }

    setSubmittingFeature(true);
    try {
      const userId = authEngine.getRealUserId() || 'local-user';
      const email = userEmail || authEngine.getAuthSession()?.userEmail || 'local-user';
      const businessType = localStorage.getItem('billqyro_business_type') || 'General';

      await supportEngine.submitFeatureRequest(userId, email, featureTitle, featureDesc, businessType, featurePriority);
      toast.success('Feature request submitted successfully!');
      
      setFeatureTitle('');
      setFeatureDesc('');
      fetchUserData();
    } catch (err) {
      console.error(err);
      toast.error('Failed to submit feature request.');
    } finally {
      setSubmittingFeature(false);
    }
  };

  return (
    <AnimatedPage>
      <div className="min-h-screen bg-theme-app text-theme-primary font-sans pb-24">
      {/* Header bar */}
      <div className="bg-theme-card border-b border-theme-border-soft sticky top-0 z-20 shadow-sm">
        <div className="max-w-3xl mx-auto px-4 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <button onClick={onBack} className="p-2 -ml-2 rounded-xl hover:bg-theme-app transition-colors text-theme-muted">
              <ArrowLeft className="w-5 h-5" />
            </button>
            <h1 className="text-lg font-black tracking-tight flex items-center gap-2">
              <LifeBuoy className="w-5 h-5 text-theme-accent" /> Help & Support Center
            </h1>
          </div>
        </div>
      </div>

      <div className="max-w-3xl mx-auto px-4 py-6 space-y-6">
        
        {/* Support Tab Switcher */}
        <div className="flex bg-theme-surface border border-theme-border-soft rounded-2xl p-1 overflow-x-auto whitespace-nowrap scrollbar-none gap-1">
          {[
            { id: 'faq', label: 'FAQ & Quick Links' },
            { id: 'tickets', label: 'Support Tickets' },
            { id: 'features', label: 'Request Features' },
            { id: 'changelog', label: 'What\'s New' }
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex-1 py-2.5 px-4 text-xs font-black rounded-xl transition-all ${
                activeTab === tab.id
                  ? 'bg-theme-card text-theme-primary shadow-sm border border-theme-border-soft/60'
                  : 'text-theme-muted hover:text-theme-primary'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>

        {/* TAB 1: FAQ */}
        {activeTab === 'faq' && (
          <div className="space-y-6">
            <div className="bg-theme-warning/10 border border-theme-warning/30 rounded-2xl p-4 text-theme-warning text-sm font-semibold">
              Disclaimer: BillQyro is not legal, tax, or accounting advice. This tool is provided for your convenience only.
            </div>

            <div className="text-center py-4">
              <h2 className="text-xl font-black mb-1">How can we help you?</h2>
              <p className="text-theme-muted text-xs font-semibold">Our support team is here to assist you with any questions or issues.</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <a href="mailto:support@billqyro.com" className="bg-theme-card rounded-3xl p-6 border border-theme-border-soft shadow-premium hover:shadow-premium-hover transition-all duration-300 block group">
                <div className="w-12 h-12 bg-theme-accent/10 text-theme-accent rounded-full flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                  <Mail className="w-6 h-6" />
                </div>
                <h3 className="text-lg font-bold mb-2">Email Support</h3>
                <p className="text-sm text-theme-muted mb-4">Send us an email and we'll get back to you within 24 hours.</p>
                <span className="text-theme-accent font-bold text-sm">support@billqyro.com &rarr;</span>
              </a>

              <a href="https://wa.me/919876543210" target="_blank" rel="noopener noreferrer" className="bg-theme-card rounded-3xl p-6 border border-theme-border-soft shadow-premium hover:shadow-premium-hover transition-all duration-300 block group">
                <div className="w-12 h-12 bg-theme-success/10 text-theme-success rounded-full flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                  <MessageCircle className="w-6 h-6" />
                </div>
                <h3 className="text-lg font-bold mb-2">Live Chat</h3>
                <p className="text-sm text-theme-muted mb-4">Chat with our support agents directly via WhatsApp.</p>
                <span className="text-theme-success font-bold text-sm">Chat Now &rarr;</span>
              </a>
            </div>

            <section className="bg-theme-card rounded-3xl p-6 border border-theme-border-soft shadow-premium">
              <div className="flex items-center gap-3 mb-4">
                <FileText className="w-5 h-5 text-theme-accent" />
                <h2 className="text-lg font-black">Frequently Asked Questions</h2>
              </div>
              
              <div className="space-y-4">
                <div className="p-4 bg-theme-app rounded-2xl border border-theme-border-soft">
                  <h3 className="font-bold text-sm mb-1">How do I change my currency?</h3>
                  <p className="text-xs text-theme-muted">Go to Settings &gt; Business Profile, and update your currency code.</p>
                </div>
                <div className="p-4 bg-theme-app rounded-2xl border border-theme-border-soft">
                  <h3 className="font-bold text-sm mb-1">Are my invoices backed up?</h3>
                  <p className="text-xs text-theme-muted">Yes, if you have Firebase connected or use the offline-first IndexedDB system, your data is securely stored locally.</p>
                </div>
                <div className="p-4 bg-theme-app rounded-2xl border border-theme-border-soft">
                  <h3 className="font-bold text-sm mb-1">How do I export my data?</h3>
                  <p className="text-xs text-theme-muted">You can export data from the Data Management section under More Menu.</p>
                </div>
              </div>
            </section>
          </div>
        )}

        {/* TAB 2: SUPPORT TICKETS */}
        {activeTab === 'tickets' && (
          <div className="space-y-6">
            {/* Create Ticket Form */}
            <div className="bg-theme-card rounded-3xl p-6 border border-theme-border-soft shadow-premium">
              <h3 className="text-lg font-black text-theme-primary mb-4">Submit a Support Ticket</h3>
              <form onSubmit={handleTicketSubmit} className="space-y-4">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs font-bold text-theme-muted uppercase tracking-wider mb-2">Issue Type</label>
                    <select
                      value={issueType}
                      onChange={(e) => setIssueType(e.target.value)}
                      className="w-full bg-theme-surface border border-theme-border-soft text-theme-primary px-4 py-3 rounded-xl focus:outline-none focus:border-theme-accent text-sm font-semibold cursor-pointer"
                    >
                      <option value="Billing">Billing / Platform Dues</option>
                      <option value="Bug">Technical Bug / Issue</option>
                      <option value="Question">General Question</option>
                      <option value="Other">Other / Help Request</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-theme-muted uppercase tracking-wider mb-2">Contact Phone (Optional)</label>
                    <input 
                      type="text"
                      placeholder="e.g. +91 9876543210"
                      value={userPhone}
                      onChange={(e) => setUserPhone(e.target.value)}
                      className="w-full bg-theme-surface border border-theme-border-soft text-theme-primary px-4 py-3 rounded-xl focus:outline-none focus:border-theme-accent text-sm font-semibold"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-bold text-theme-muted uppercase tracking-wider mb-2">Message / Issue Details</label>
                  <textarea 
                    rows="4"
                    placeholder="Describe your issue in detail so our support team can help..."
                    value={ticketMsg}
                    onChange={(e) => setTicketMsg(e.target.value)}
                    className="w-full bg-theme-surface border border-theme-border-soft text-theme-primary px-4 py-3 rounded-xl focus:outline-none focus:border-theme-accent text-sm font-semibold resize-none"
                    required
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-theme-muted uppercase tracking-wider mb-2">Screenshot (Optional)</label>
                  <div className="relative border border-theme-border-soft border-dashed rounded-xl p-6 text-center hover:border-theme-accent transition-colors bg-theme-surface">
                    <input 
                      type="file" 
                      accept="image/*"
                      onChange={(e) => handleScreenshotChange(e.target.files[0])}
                      className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                    />
                    <Upload className="w-5 h-5 mx-auto mb-2 text-theme-muted" />
                    <span className="text-[10px] text-theme-muted font-bold block">
                      {ticketScreenshot ? ticketScreenshot.name : 'Choose screenshot image'}
                    </span>
                  </div>
                  {ticketScreenshotBase64 && (
                    <div className="mt-2.5 flex items-center gap-3 bg-theme-surface border border-theme-border-soft rounded-xl p-2">
                      <img src={ticketScreenshotBase64} alt="Screenshot preview" className="w-12 h-12 object-cover rounded-lg" />
                      <span className="text-[10px] text-theme-muted truncate max-w-[200px]">{ticketScreenshot?.name}</span>
                    </div>
                  )}
                </div>

                <button
                  type="submit"
                  disabled={submittingTicket}
                  className="w-full h-12 bg-theme-accent text-white font-extrabold rounded-2xl flex items-center justify-center transition-all disabled:opacity-50 mt-4 cursor-pointer"
                >
                  {submittingTicket ? 'Submitting...' : 'Submit Support Ticket'}
                </button>
              </form>
            </div>

            {/* My Tickets List */}
            <div className="bg-theme-card rounded-3xl p-6 border border-theme-border-soft shadow-premium">
              <h3 className="text-lg font-black text-theme-primary mb-4">My Support History</h3>
              {myTickets.length === 0 ? (
                <p className="text-xs text-theme-muted font-bold italic py-4">No support tickets submitted yet.</p>
              ) : (
                <div className="space-y-4">
                  {myTickets.map((ticket) => (
                    <div key={ticket.id} className="bg-theme-surface rounded-2xl p-4 border border-theme-border-soft/60 flex flex-col justify-between gap-3">
                      <div>
                        <div className="flex justify-between items-start mb-2">
                          <span className={`text-[10px] font-black uppercase tracking-wider px-2 py-0.5 rounded-md border ${
                            ticket.issueType === 'Bug' ? 'bg-theme-danger/10 text-theme-danger border-theme-danger/20' : 'bg-theme-accent/10 text-theme-accent border-theme-accent/20'
                          }`}>
                            {ticket.issueType}
                          </span>
                          <span className={`text-[9px] font-black uppercase tracking-wider px-2 py-0.5 rounded-md border ${
                            ticket.status === 'Open' ? 'bg-theme-warning/15 text-theme-warning border-theme-warning/20' : 'bg-emerald-500/15 text-emerald-500 border-emerald-500/20'
                          }`}>
                            {ticket.status}
                          </span>
                        </div>
                        <p className="text-sm font-semibold text-theme-primary">{ticket.message}</p>
                        <p className="text-[10px] text-theme-muted mt-2">Submitted: {new Date(ticket.createdAt).toLocaleDateString()}</p>
                        
                        {ticket.adminNote && (
                          <div className="mt-3 text-emerald-600 dark:text-emerald-400 bg-emerald-500/5 p-3 rounded-xl border border-emerald-500/10">
                            <span className="font-extrabold block text-xs mb-1">Support Reply:</span>
                            {ticket.adminNote}
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        )}

        {/* TAB 3: FEATURE REQUESTS */}
        {activeTab === 'features' && (
          <div className="space-y-6">
            <div className="bg-theme-card rounded-3xl p-6 border border-theme-border-soft shadow-premium">
              <h3 className="text-lg font-black text-theme-primary mb-4">Request a Platform Feature</h3>
              <form onSubmit={handleFeatureSubmit} className="space-y-4">
                <div>
                  <label className="block text-xs font-bold text-theme-muted uppercase tracking-wider mb-2">Feature Title</label>
                  <input 
                    type="text"
                    placeholder="e.g. Export reports to Excel / CSV"
                    value={featureTitle}
                    onChange={(e) => setFeatureTitle(e.target.value)}
                    className="w-full bg-theme-surface border border-theme-border-soft text-theme-primary px-4 py-3 rounded-xl focus:outline-none focus:border-theme-accent text-sm font-semibold"
                    required
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-theme-muted uppercase tracking-wider mb-2">Feature Details & Description</label>
                  <textarea 
                    rows="4"
                    placeholder="Describe how this feature should work and why it is useful for your business..."
                    value={featureDesc}
                    onChange={(e) => setFeatureDesc(e.target.value)}
                    className="w-full bg-theme-surface border border-theme-border-soft text-theme-primary px-4 py-3 rounded-xl focus:outline-none focus:border-theme-accent text-sm font-semibold resize-none"
                    required
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-theme-muted uppercase tracking-wider mb-2">Priority</label>
                  <select
                    value={featurePriority}
                    onChange={(e) => setFeaturePriority(e.target.value)}
                    className="w-full bg-theme-surface border border-theme-border-soft text-theme-primary px-4 py-3 rounded-xl focus:outline-none focus:border-theme-accent text-sm font-semibold cursor-pointer"
                  >
                    <option value="Low">Low - Nice to have</option>
                    <option value="Medium">Medium - Regular feature</option>
                    <option value="High">High - Crucial addition</option>
                  </select>
                </div>

                <button
                  type="submit"
                  disabled={submittingFeature}
                  className="w-full h-12 bg-theme-accent text-white font-extrabold rounded-2xl flex items-center justify-center transition-all disabled:opacity-50 mt-4 cursor-pointer"
                >
                  {submittingFeature ? 'Submitting...' : 'Submit Feature Request'}
                </button>
              </form>
            </div>

            <div className="bg-theme-card rounded-3xl p-6 border border-theme-border-soft shadow-premium">
              <h3 className="text-lg font-black text-theme-primary mb-4">My Feature Requests</h3>
              {myFeatures.length === 0 ? (
                <p className="text-xs text-theme-muted font-bold italic py-4">No feature requests submitted yet.</p>
              ) : (
                <div className="space-y-4">
                  {myFeatures.map((req) => (
                    <div key={req.id} className="bg-theme-surface rounded-2xl p-4 border border-theme-border-soft/60 flex flex-col justify-between gap-3">
                      <div>
                        <div className="flex justify-between items-start mb-2">
                          <span className="font-extrabold text-sm text-theme-primary">{req.title}</span>
                          <span className={`text-[9px] font-black uppercase tracking-wider px-2 py-0.5 rounded-md border ${
                            req.status === 'Done' ? 'bg-emerald-500/15 text-emerald-500 border-emerald-500/20' : 
                            req.status === 'Planned' ? 'bg-theme-accent/15 text-theme-accent border-theme-accent/20' : 
                            req.status === 'Rejected' ? 'bg-theme-danger/15 text-theme-danger border-theme-danger/20' : 
                            'bg-theme-muted/15 text-theme-muted border-theme-muted/20'
                          }`}>
                            {req.status}
                          </span>
                        </div>
                        <p className="text-xs text-theme-muted font-semibold">{req.description}</p>
                        <p className="text-[9px] text-theme-muted font-mono mt-2">Priority: {req.priority}</p>
                        
                        {req.adminNote && (
                          <div className="mt-3 text-theme-accent bg-theme-accent/5 p-3 rounded-xl border border-theme-accent/10">
                            <span className="font-extrabold block text-xs mb-1">Developer Comments:</span>
                            {req.adminNote}
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        )}

        {/* TAB 4: CHANGELOG */}
        {activeTab === 'changelog' && (
          <div className="space-y-6">
            <div className="bg-theme-card rounded-3xl p-6 border border-theme-border-soft shadow-premium">
              <h3 className="text-lg font-black text-theme-primary mb-6 flex items-center gap-2">
                <CheckCircle className="w-5 h-5 text-theme-accent" /> Release Changelog History
              </h3>

              {loadingChangelogs ? (
                <div className="flex justify-center py-6">
                  <span className="w-6 h-6 border-2 border-theme-border-strong border-t-theme-accent rounded-full animate-spin"></span>
                </div>
              ) : changelogs.length === 0 ? (
                <p className="text-xs text-theme-muted font-bold italic py-4">No release logs published yet.</p>
              ) : (
                <div className="space-y-6 relative pl-4 border-l border-theme-border-soft">
                  {changelogs.map((log) => (
                    <div key={log.id} className="relative group space-y-2">
                      {/* Timeline dot */}
                      <div className="absolute -left-[21px] top-1.5 w-3.5 h-3.5 bg-theme-card border-2 border-theme-accent rounded-full group-hover:scale-110 transition-transform"></div>
                      
                      <div className="flex items-center gap-2">
                        <span className="text-sm font-black text-theme-accent font-mono">{log.version}</span>
                        <span className="text-[10px] text-theme-muted font-mono font-bold">{new Date(log.date).toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' })}</span>
                        <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded border ${
                          log.type === 'fix' ? 'bg-theme-danger/10 text-theme-danger border-theme-danger/20' : 
                          log.type === 'new' ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' : 
                          'bg-theme-accent/10 text-theme-accent border-theme-accent/20'
                        }`}>
                          {log.type}
                        </span>
                      </div>

                      <h4 className="text-base font-extrabold text-theme-primary">{log.title}</h4>
                      <div className="text-xs text-theme-muted leading-relaxed font-semibold whitespace-pre-line pl-1">
                        {log.notes}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        )}

      </div>
    </div>
    </AnimatedPage>
  );
}

import React, { useState, useEffect } from 'react';
import AnimatedPage from '../components/AnimatedPage';
import { ArrowLeft, HardDrive, Wifi, WifiOff, RefreshCcw, AlertTriangle, CheckCircle2 } from 'lucide-react';
import { toast } from 'react-hot-toast';
import { BillQyroDB } from '../services/localDb';

const SystemHealth = ({ setCurrentTab }) => {
  const [healthData, setHealthData] = useState({
    isOnline: navigator.onLine,
    pendingSync: 0,
    failedSync: 0,
    errorLogsCount: 0,
    auditLogsCount: 0,
    dbStorageUsage: 'Calculating...'
  });

  useEffect(() => {
    const checkHealth = async () => {
      try {
        const syncQueue = await BillQyroDB.getAll('syncQueue');
        const errorLogs = await BillQyroDB.getAll('errorLogs');
        const auditLogs = await BillQyroDB.getAll('auditLogs');

        let dbStorageUsage = 'Unknown';
        if (navigator.storage && navigator.storage.estimate) {
          const estimate = await navigator.storage.estimate();
          dbStorageUsage = `${(estimate.usage / (1024 * 1024)).toFixed(2)} MB`;
        }

        setHealthData({
          isOnline: navigator.onLine,
          pendingSync: syncQueue.length,
          failedSync: 0, // In this model, failed are just kept in syncQueue or logged
          errorLogsCount: errorLogs.length,
          auditLogsCount: auditLogs.length,
          dbStorageUsage
        });
      } catch (e) {
        console.error('Failed to read system health', e);
      }
    };

    checkHealth();

    const handleOnline = () => setHealthData(prev => ({ ...prev, isOnline: true }));
    const handleOffline = () => setHealthData(prev => ({ ...prev, isOnline: false }));

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    // Check legacy global storage
    const checkLegacyStorage = () => {
      const collections = ['invoices', 'customers', 'products', 'expenses', 'settings', 'subscription'];
      let count = 0;
      let summary = [];
      
      collections.forEach(col => {
        const globalKey = `billqyro_${col}`;
        const data = localStorage.getItem(globalKey);
        if (data) {
          try {
            const parsed = JSON.parse(data);
            const itemsCount = Array.isArray(parsed) ? parsed.length : 1;
            if (itemsCount > 0) {
              count += itemsCount;
              summary.push(`${col}: ${itemsCount}`);
            }
          } catch (e) { console.warn('Ignored error in SystemHealth.jsx:', e); }
        }
      });
      return { hasLegacy: count > 0, summary: summary.join(', ') };
    };

    const legacyDataInfo = checkLegacyStorage();
    setHealthData(prev => ({ ...prev, legacyDataInfo }));

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const handleBackup = async () => {
    try {
      const invoices = await BillQyroDB.getAll('invoices');
      const customers = await BillQyroDB.getAll('customers');
      const products = await BillQyroDB.getAll('products');
      const expenses = await BillQyroDB.getAll('expenses');
      const syncQueue = await BillQyroDB.getAll('syncQueue');

      const dataToExport = {
        version: '3.0.0',
        timestamp: new Date().toISOString(),
        localStorage: { ...localStorage },
        indexedDB: {
          invoices, customers, products, expenses, syncQueue
        }
      };
      
      const blob = new Blob([JSON.stringify(dataToExport, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `billqyro_backup_${new Date().getTime()}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      toast.success('Backup downloaded successfully');
      setHasBackedUp(true);
    } catch (e) {
      toast.error('Backup failed: ' + e.message);
    }
  };

  const [hasBackedUp, setHasBackedUp] = useState(false);

  const handleReplaceWithCloud = async () => {
    if (!hasBackedUp) {
      toast.error('Please backup your data before replacing with cloud data.');
      return;
    }

    try {
      const queue = await BillQyroDB.getAll('syncQueue');
      if (queue && queue.length > 0) {
        toast.loading('Flushing offline queue to cloud first...', { id: 'flush-toast' });
        const { offlineEngine } = await import('../services/offlineEngine');
        await offlineEngine.syncNow();
        
        const newQueue = await BillQyroDB.getAll('syncQueue');
        if (newQueue && newQueue.length > 0) {
          toast.dismiss('flush-toast');
          toast.error(`Cannot replace. ${newQueue.length} items failed to sync to cloud. Check your network or retry later.`);
          return;
        }
        toast.success('Queue flushed successfully!', { id: 'flush-toast' });
      }

      if (!window.confirm('This will clear all local cache on this device and replace it with data from the cloud. Proceed?')) {
        return;
      }

      const { adminEngine } = await import('../services/adminEngine');
      const { invoiceEngine } = await import('../services/invoiceEngine');
      adminEngine.clearCacheOnly();
      await invoiceEngine.syncFromCloud();
      toast.success('Device data refreshed from cloud. Reloading...');
      setTimeout(() => window.location.reload(true), 1500);
    } catch (e) {
      console.error('Failed to replace device data with cloud:', e);
      toast.error('Failed to replace data. See console for details.');
    }
  };

  const handleMigrate = async () => {
    if (!hasBackedUp) {
      toast.error('Please backup your data first before migrating.');
      return;
    }
    if (window.confirm('Are you sure you want to merge old local data into the active account? This cannot be undone.')) {
      const { adminEngine } = await import('../services/adminEngine');
      const result = await adminEngine.migrateGlobalToScopedStorage();
      if (result && result.status === 'success') {
        toast.success(`Successfully migrated ${result.migratedCount} items. Please reload the app.`);
        setTimeout(() => window.location.reload(true), 2000);
      } else {
        toast.error('Migration failed: ' + (result?.message || 'Unknown error'));
      }
    }
  };

  const handleHardReload = () => {
    if (window.confirm('Clear PWA caches and reload? Use this if the app is stuck or showing an old version.')) {
      if ('caches' in window) {
        caches.keys().then(names => {
          names.forEach(name => caches.delete(name));
        });
      }
      window.location.reload(true);
    }
  };

  const handleClearDeviceCache = () => {
    if (!hasBackedUp) {
      toast.error('Please backup your device data first before clearing.');
      return;
    }
    if (window.confirm('WARNING: This will delete ALL local data on this device (localStorage & IndexedDB). It will NOT delete cloud data. Proceed?')) {
      if (window.confirm('Are you absolutely sure? You will be logged out.')) {
        localStorage.clear();
        sessionStorage.clear();
        if ('caches' in window) {
          caches.keys().then(names => {
            names.forEach(name => caches.delete(name));
          });
        }
        
        // Clear IndexedDB
        const req = indexedDB.deleteDatabase('BillQyroDB');
        req.onsuccess = () => {
          window.location.href = '/';
        };
        req.onerror = () => {
          window.location.href = '/';
        };
      }
    }
  };

  const APP_VERSION = "2.0.1 - " + new Date().toISOString().split('T')[0];

  return (
    <AnimatedPage>
      <div className="max-w-4xl mx-auto pb-12 relative font-sans animate-fade-in space-y-6">
      <button 
        onClick={() => setCurrentTab('more')}
        className="flex items-center gap-2 text-theme-muted hover:text-theme-primary transition-colors cursor-pointer"
      >
        <ArrowLeft className="w-4 h-4" />
        <span className="text-xs font-bold uppercase tracking-wider">Back</span>
      </button>

      <div className="bg-theme-card rounded-3xl p-6 md:p-8 border border-theme-border-soft shadow-premium space-y-8">
        <div className="flex items-center justify-between border-b border-theme-border-soft pb-6">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-theme-accent/10 rounded-xl flex items-center justify-center text-theme-accent">
              <HardDrive className="w-6 h-6" />
            </div>
            <div>
              <h1 className="text-2xl font-black text-theme-primary tracking-tight">Storage & Sync Control</h1>
              <p className="text-sm text-theme-muted font-medium mt-1">Real-time status of local database and sync engine.</p>
            </div>
          </div>
          <div className="text-right">
            <p className="text-xs font-bold text-theme-muted uppercase tracking-wider mb-1">App Version</p>
            <p className="text-sm font-semibold text-theme-primary">{APP_VERSION}</p>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="p-4 rounded-2xl border border-theme-border-soft bg-theme-bg-soft">
            <div className="flex items-center gap-3 mb-2">
              {healthData.isOnline ? (
                <Wifi className="w-5 h-5 text-green-500" />
              ) : (
                <WifiOff className="w-5 h-5 text-red-500" />
              )}
              <h3 className="font-semibold text-theme-primary">Network Status</h3>
            </div>
            <p className="text-sm text-theme-secondary">
              {healthData.isOnline ? 'Online (Sync Active)' : 'Offline (Local Mode)'}
            </p>
          </div>

          <div className="p-4 rounded-2xl border border-theme-border-soft bg-theme-bg-soft">
            <div className="flex items-center gap-3 mb-2">
              <RefreshCcw className="w-5 h-5 text-theme-accent" />
              <h3 className="font-semibold text-theme-primary">Sync Queue</h3>
            </div>
            <p className="text-sm text-theme-secondary">
              {healthData.pendingSync} transactions pending
            </p>
          </div>

          <div className="p-4 rounded-2xl border border-theme-border-soft bg-theme-bg-soft">
            <div className="flex items-center gap-3 mb-2">
              <HardDrive className="w-5 h-5 text-blue-500" />
              <h3 className="font-semibold text-theme-primary">Local Storage Usage</h3>
            </div>
            <p className="text-sm text-theme-secondary">
              IndexedDB: {healthData.dbStorageUsage}
            </p>
          </div>

          <div className="p-4 rounded-2xl border border-theme-border-soft bg-theme-bg-soft">
            <div className="flex items-center gap-3 mb-2">
              {healthData.errorLogsCount > 0 ? (
                <AlertTriangle className="w-5 h-5 text-theme-warning" />
              ) : (
                <CheckCircle2 className="w-5 h-5 text-green-500" />
              )}
              <h3 className="font-semibold text-theme-primary">System Errors</h3>
            </div>
            <p className="text-sm text-theme-secondary">
              {healthData.errorLogsCount} errors logged locally
            </p>
          </div>
        </div>

        {healthData.legacyDataInfo?.hasLegacy && (
          <div className="mt-8 p-6 rounded-2xl border border-theme-warning/30 bg-theme-warning/5">
            <div className="flex items-start gap-4">
              <div className="w-10 h-10 bg-theme-warning/10 text-theme-warning rounded-xl flex items-center justify-center shrink-0">
                <AlertTriangle className="w-5 h-5" />
              </div>
              <div className="flex-1">
                <h3 className="text-lg font-bold text-theme-primary mb-1">Old Local Data Found</h3>
                <p className="text-sm text-theme-secondary mb-3">
                  We found un-synced data from an older version: <strong>{healthData.legacyDataInfo.summary}</strong>
                </p>
                <div className="flex items-center gap-3">
                  <button 
                    onClick={handleMigrate}
                    className="px-4 py-2 bg-theme-warning text-white text-sm font-bold rounded-xl shadow-premium hover:opacity-90 transition-opacity"
                  >
                    Migrate & Merge
                  </button>
                  <p className="text-xs text-theme-muted font-medium">Requires backup first</p>
                </div>
              </div>
            </div>
          </div>
        )}

        <div className="mt-8 grid grid-cols-1 md:grid-cols-3 gap-4">
          <button 
            onClick={handleBackup}
            className="p-4 rounded-2xl border border-theme-border-soft bg-theme-card hover:bg-theme-surface transition-colors text-left"
          >
            <h4 className="font-bold text-theme-primary mb-1">Backup Data</h4>
            <p className="text-xs text-theme-secondary font-medium">Download local JSON snapshot</p>
          </button>
          
          <button 
            onClick={handleHardReload}
            className="p-4 rounded-2xl border border-theme-border-soft bg-theme-card hover:bg-theme-surface transition-colors text-left"
          >
            <h4 className="font-bold text-theme-primary mb-1">Hard Reload</h4>
            <p className="text-xs text-theme-secondary font-medium">Clear PWA cache & refresh</p>
          </button>
          
          <button 
            onClick={handleClearDeviceCache}
            className="p-4 rounded-2xl border border-red-500/30 bg-red-500/5 hover:bg-red-500/10 transition-colors text-left group"
          >
            <h4 className="font-bold text-red-500 group-hover:text-red-600 mb-1">Clear Device Cache</h4>
            <p className="text-xs text-red-400/80 font-medium">Wipe local device data only</p>
          </button>

          <button 
            onClick={handleReplaceWithCloud}
            className="p-4 rounded-2xl border border-green-500/30 bg-green-500/5 hover:bg-green-500/10 transition-colors text-left group"
          >
            <h4 className="font-bold text-green-500 group-hover:text-green-600 mb-1">Replace This Device With Cloud Data</h4>
            <p className="text-xs text-green-400/80 font-medium">Clear local cache and load fresh cloud data</p>
          </button>
        </div>
      </div>
    </div>
    </AnimatedPage>
  );
};

