                      <Globe className="w-2.5 h-2.5" /> Live: {tc.live}
                    </span>
                    <span className="text-[8px] font-bold bg-theme-app px-2 py-0.5 rounded-full text-theme-muted border border-theme-border-soft flex items-center gap-1">
                      <FileText className="w-2.5 h-2.5" /> {pack.features.length} Features
                    </span>
                    {pack.type === 'pro' ? (
                      <span className="text-[8px] font-bold bg-amber-400/10 text-amber-600 dark:text-amber-400 px-2 py-0.5 rounded-full border border-amber-400/20 flex items-center gap-1">
                        <Star className="w-2.5 h-2.5" /> Premium
                      </span>
                    ) : (
                      <span className="text-[8px] font-bold bg-emerald-400/10 text-emerald-600 dark:text-emerald-400 px-2 py-0.5 rounded-full border border-emerald-400/20 flex items-center gap-1">
                        <Sparkles className="w-2.5 h-2.5" /> Starter
                      </span>
                    )}
                  </div>

                  <h3 className="font-extrabold text-lg text-theme-primary mb-1">{pack.name}</h3>
                  <p className="text-[11px] text-theme-muted font-semibold mb-6">{pack.desc}</p>

                  <div className="space-y-2 mb-6">
                    <p className="text-[9px] uppercase tracking-widest font-black text-theme-muted">Includes</p>
                    {pack.features.map((feat, i) => (
                      <div key={i} className="flex items-center gap-2 text-[11px] font-bold text-theme-secondary">
                        <CheckCircle2 className="w-3.5 h-3.5 text-theme-accent" />
                        <span>{feat}</span>
                      </div>
                    ))}
                  </div>
                </div>

                <div className="flex gap-2">
                  <button
                    onClick={() => setPreviewPack(pack)}
                    className={`flex-1 py-3 rounded-xl text-xs font-black transition-all flex items-center justify-center gap-2 btn-premium border border-theme-border-soft bg-theme-app dark:bg-theme-surface hover:bg-theme-card text-theme-primary`}
                  >
                    <Eye className="w-4 h-4" /> Preview
                  </button>
                  <button
                    onClick={() => handleApplyPack(pack)}
                    className={`flex-[2] py-3 rounded-xl text-xs font-black transition-all flex items-center justify-center gap-2 btn-premium ${
                      isActive 
                        ? 'bg-theme-accent/10 text-theme-accent cursor-default border border-theme-accent/20' 
                        : isLocked
                          ? 'bg-theme-warning/10 text-theme-warning hover:bg-theme-warning/20 border border-theme-warning/30'
                          : 'bg-theme-app dark:bg-theme-surface hover:bg-theme-accent hover:text-white border border-theme-border-soft text-theme-primary'
                    }`}
                  >
                    {isActive ? (
                      <>Active <CheckCircle2 className="w-4 h-4" /></>
                    ) : isLocked ? (
                      <>Unlock</>
                    ) : (
                      'Apply Pack'
                    )}
                  </button>
                </div>
              </motion.div>
            );
          })}
        </motion.div>
      )}

      {/* Preview Modal */}
      {previewPack && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm"
          onClick={() => setPreviewPack(null)}
        >
          <motion.div
            initial={{ scale: 0.9, opacity: 0, y: 20 }}
            animate={{ scale: 1, opacity: 1, y: 0 }}
            exit={{ scale: 0.9, opacity: 0, y: 20 }}
            onClick={e => e.stopPropagation()}
            className="bg-theme-card rounded-3xl border border-theme-border-soft shadow-2xl max-w-lg w-full p-6 max-h-[90vh] overflow-y-auto"
          >
            <div className="flex items-center justify-between mb-6">
              <div className="flex items-center gap-3">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${previewPack.color}`}>
                  <previewPack.icon className="w-6 h-6" />
                </div>
                <div>
                  <h3 className="font-extrabold text-lg text-theme-primary">{previewPack.name}</h3>
                  <p className="text-[10px] text-theme-muted font-semibold">{previewPack.desc}</p>
                </div>
              </div>
              <button
                onClick={() => setPreviewPack(null)}
                className="w-8 h-8 rounded-xl bg-theme-app border border-theme-border-soft flex items-center justify-center hover:bg-theme-danger/10 hover:border-theme-danger/30 transition-all"
              >
                <X className="w-4 h-4 text-theme-muted" />
              </button>
            </div>

            {/* Large Preview Card */}
            <div className="bg-theme-app rounded-2xl border border-theme-border-soft p-6 mb-6">
              <div className="flex items-center gap-3 mb-4">
                <div className={`w-16 h-16 rounded-2xl flex items-center justify-center ${previewPack.color}`}>
                  <previewPack.icon className="w-8 h-8" />
                </div>
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-1">
                    <h4 className="font-extrabold text-base text-theme-primary">{previewPack.name}</h4>
                    <span className={`text-[9px] font-black uppercase tracking-widest px-2 py-0.5 rounded-full badge-premium ${
                      previewPack.type === 'free'
                        ? 'bg-theme-success/10 text-theme-success border border-theme-success/20'
                        : 'bg-theme-warning/10 text-theme-warning border border-theme-warning/20'
                    }`}>
                      {previewPack.type === 'free' ? 'FREE' : 'PRO'}
                    </span>
                  </div>
                  <p className="text-[11px] text-theme-muted font-semibold">{previewPack.desc}</p>
                </div>
              </div>

              {/* Detail Section */}
              <div className="space-y-3">
                <p className="text-[9px] uppercase tracking-widest font-black text-theme-muted">Features Breakdown</p>
                <div className="grid grid-cols-2 gap-2">
                  {previewPack.features.map((feat, i) => (
                    <div key={i} className="flex items-center gap-2 text-[11px] font-bold text-theme-secondary bg-theme-card rounded-xl px-3 py-2 border border-theme-border-soft">
                      <CheckCircle2 className="w-3.5 h-3.5 text-theme-accent shrink-0" />
                      <span>{feat}</span>
                    </div>
                  ))}
                </div>
              </div>

              {/* Template Details */}
              {(previewPack.templateCounts) && (
                <div className="mt-4 pt-4 border-t border-theme-border-soft">
                  <p className="text-[9px] uppercase tracking-widest font-black text-theme-muted mb-2">Available Templates</p>
                  <div className="flex gap-3">
                    <span className="text-[10px] font-bold bg-blue-500/10 text-blue-600 dark:text-blue-400 px-3 py-1.5 rounded-full border border-blue-500/20 flex items-center gap-1.5">
                      <FileText className="w-3 h-3" /> PDF Templates: {previewPack.templateCounts.pdf}
                    </span>
                    <span className="text-[10px] font-bold bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 px-3 py-1.5 rounded-full border border-emerald-500/20 flex items-center gap-1.5">
                      <Globe className="w-3 h-3" /> Live Links: {previewPack.templateCounts.live}
                    </span>
                  </div>
                </div>
              )}
            </div>

            <div className="flex gap-3">
              <button
                onClick={() => setPreviewPack(null)}
                className="flex-1 py-3 rounded-xl text-xs font-black border border-theme-border-soft bg-theme-app hover:bg-theme-card transition-all text-theme-primary"
              >
                Close
              </button>
              <button
                onClick={() => { handleApplyPack(previewPack); setPreviewPack(null); }}
                className={`flex-[2] py-3 rounded-xl text-xs font-black transition-all flex items-center justify-center gap-2 btn-premium ${
                  currentPackId === previewPack.id
                    ? 'bg-theme-accent/10 text-theme-accent cursor-default border border-theme-accent/20'
                    : (previewPack.type === 'pro' && !isProUser)
                      ? 'bg-theme-warning/10 text-theme-warning hover:bg-theme-warning/20 border border-theme-warning/30'
                      : 'bg-theme-app dark:bg-theme-surface hover:bg-theme-accent hover:text-white border border-theme-border-soft text-theme-primary'
                }`}
              >
                {currentPackId === previewPack.id ? (
                  <>Active Pack <CheckCircle2 className="w-4 h-4" /></>
                ) : (previewPack.type === 'pro' && !isProUser) ? (
                  <>Unlock to Apply</>
                ) : (
                  'Apply This Pack'
                )}
              </button>
            </div>
          </motion.div>
        </motion.div>
      )}
    </motion.div>
  );
};

export default TemplateMarketplace;

import { toast } from 'react-hot-toast';
import React, { useState } from 'react';
import AnimatedPage from '../components/AnimatedPage';
import { 
  Store, 
  Plus, 
  Edit3, 
  Archive, 
  CheckCircle2, 
  Circle,
  Settings2,
  ChevronRight,
  ArrowLeft
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { BUSINESS_PRESETS, ALL_MODULES as ALL_MODULES_CONFIG } from '../config/businessPresets';

const ALL_MODULES = ALL_MODULES_CONFIG;

const WorkspaceManager = ({ 
  businessWorkspaces, 
  activeWorkspaceId, 
  setActiveWorkspace,
  settings,
  onSaveSettings,
  setCurrentTab
}) => {
  const [isAdding, setIsAdding] = useState(false);
  const [editingWorkspace, setEditingWorkspace] = useState(null);
  
  // Form State
  const [name, setName] = useState('');
  const [type, setType] = useState('retail');
  const [enabledModules, setEnabledModules] = useState(['billing', 'customers']);

  const workspaces = businessWorkspaces || [];
  const activeCount = workspaces.filter(w => !w.archived).length;

  const handleOpenAdd = () => {
    setIsAdding(true);
    setEditingWorkspace(null);
    setName('');
    setType('retail');
    setEnabledModules(['billing', 'customers', 'products', 'dueLedger', 'reports']);
  };

  const handleOpenEdit = (ws) => {
    setIsAdding(true);
    setEditingWorkspace(ws);
    setName(ws.name || '');
    setType(ws.type || 'retail');
    setEnabledModules(ws.enabledModules || []);
  };

  const toggleModule = (modId) => {
    if (enabledModules.includes(modId)) {
      setEnabledModules(enabledModules.filter(id => id !== modId));
    } else {
      setEnabledModules([...enabledModules, modId]);
    }
  };

  const handleSave = () => {
    if (!name.trim()) return;
    
    let updatedWorkspaces = [...workspaces];
    
    if (editingWorkspace) {
      updatedWorkspaces = updatedWorkspaces.map(ws => {
        if (ws.id === editingWorkspace.id) {
          return { ...ws, name, type, enabledModules };
        }
        return ws;
      });
    } else {
      const newWs = {
        id: 'ws_' + Date.now(),
        name,
        type,
        enabledModules,
        archived: false
      };
      updatedWorkspaces.push(newWs);
      if (updatedWorkspaces.length === 1) {
        setActiveWorkspace(newWs.id);
      }
    }
    
    onSaveSettings({ ...settings, businessWorkspaces: updatedWorkspaces });
    setIsAdding(false);
  };

  const handleToggleArchive = (ws) => {
    if (ws.id === activeWorkspaceId) {
      toast.error("Cannot archive the currently active workspace.");
      return;
    }
    
    const updatedWorkspaces = workspaces.map(w => {
      if (w.id === ws.id) {
        return { ...w, archived: !w.archived };
      }
      return w;
    });
    onSaveSettings({ ...settings, businessWorkspaces: updatedWorkspaces });
  };

  return (
    <AnimatedPage>
      <div className="max-w-2xl mx-auto pb-24">
      {/* Header */}
      <div className="flex items-center gap-4 mb-6">
        <button 
          onClick={() => setCurrentTab('more')}
          className="w-10 h-10 bg-theme-card border border-theme-border-soft rounded-xl flex items-center justify-center text-theme-muted hover:text-theme-primary transition-colors"
        >
          <ArrowLeft className="w-5 h-5" />
        </button>
        <div>
          <h1 className="text-xl md:text-2xl font-black text-theme-primary tracking-tight">Workspace Manager</h1>
          <p className="text-xs font-bold text-theme-muted">{activeCount} Active Workspaces</p>
        </div>
      </div>

      <AnimatePresence mode="wait">
        {!isAdding ? (
          <motion.div 
            key="list"
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
            className="space-y-4"
          >
            {/* Workspaces List */}
            {workspaces.map(ws => (
              <div 
                key={ws.id} 
                className={`bg-theme-card rounded-3xl p-5 border shadow-premium transition-all relative overflow-hidden ${ws.archived ? 'opacity-60 border-theme-border-soft' : ws.id === activeWorkspaceId ? 'border-theme-accent ring-1 ring-theme-accent/20' : 'border-theme-border-soft'}`}
              >
                {ws.id === activeWorkspaceId && (
                  <div className="absolute top-0 right-0 bg-theme-accent text-white text-[9px] font-black uppercase px-3 py-1 rounded-bl-xl tracking-wider">
                    Active
                  </div>
                )}
                
                <div className="flex items-center justify-between">
                  <div 
                    className="flex items-center gap-4 cursor-pointer flex-1"
                    onClick={() => {
                      if (!ws.archived) setActiveWorkspace(ws.id);
                    }}
                  >
                    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 ${ws.id === activeWorkspaceId ? 'bg-theme-accent text-white shadow-lg shadow-theme-accent/30' : 'bg-theme-app text-theme-muted'}`}>
                      <Store className="w-6 h-6" />
                    </div>
                    <div>
                      <h3 className="font-extrabold text-theme-primary">{ws.name}</h3>
                      <p className="text-[11px] font-bold text-theme-muted capitalize">{ws.type} • {ws.enabledModules?.length || 0} Modules</p>
                    </div>
                  </div>
                  
                  <div className="flex items-center gap-2">
                    <button 
                      onClick={() => handleOpenEdit(ws)}
                      className="w-8 h-8 rounded-full bg-theme-app hover:bg-theme-surface flex items-center justify-center text-theme-muted transition-colors"
                    >
                      <Edit3 className="w-4 h-4" />
                    </button>
                    <button 
                      onClick={() => handleToggleArchive(ws)}
                      className={`w-8 h-8 rounded-full flex items-center justify-center transition-colors ${ws.archived ? 'bg-theme-success/10 text-theme-success hover:bg-theme-success/20' : 'bg-theme-danger/10 text-theme-danger hover:bg-theme-danger/20'}`}
                      title={ws.archived ? "Restore" : "Archive"}
                    >
                      <Archive className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              </div>
            ))}

            {/* Add Button */}
            <button
              onClick={handleOpenAdd}
              className="w-full mt-6 py-4 bg-[image:var(--accent-gradient)] text-white font-black rounded-2xl shadow-premium flex items-center justify-center gap-2 active:scale-[0.98] transition-transform"
            >
              <Plus className="w-5 h-5" /> Add New Workspace
            </button>
          </motion.div>
        ) : (
          <motion.div 
            key="form"
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 20 }}
            className="space-y-6"
          >
            <div className="bg-theme-card rounded-3xl p-6 border border-theme-border-soft shadow-premium space-y-5">
              <div>
                <label className="block text-xs font-black text-theme-muted uppercase tracking-wider mb-2">Workspace Name</label>
                <input 
                  type="text"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="e.g. Branch 2"
                  className="w-full bg-theme-app border border-theme-border-soft rounded-xl p-4 text-sm font-bold text-theme-primary focus:outline-none focus:border-theme-accent transition-colors min-h-[44px]"
                />
              </div>
              
              <div>
                <label className="block text-xs font-black text-theme-muted uppercase tracking-wider mb-2">Business Type</label>
                <select 
                  value={type}
                  onChange={(e) => setType(e.target.value)}
                  className="w-full bg-theme-app border border-theme-border-soft rounded-xl p-4 text-sm font-bold text-theme-primary focus:outline-none focus:border-theme-accent transition-colors min-h-[44px]"
                >
                  {BUSINESS_PRESETS.map(preset => (
                    <option key={preset.id} value={preset.id}>{preset.label}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-xs font-black text-theme-muted uppercase tracking-wider mb-3">Enabled Modules</label>
                <div className="space-y-2">
                  {ALL_MODULES.map(mod => (
                    <div 
                      key={mod.id} 
                      onClick={() => toggleModule(mod.id)}
                      className={`flex items-center justify-between p-4 rounded-xl border cursor-pointer transition-colors ${enabledModules.includes(mod.id) ? 'bg-theme-accent/5 border-theme-accent/30' : 'bg-theme-app border-theme-border-soft'}`}
                    >
                      <span className="font-bold text-sm text-theme-primary">{mod.name}</span>
                      {enabledModules.includes(mod.id) ? (
                        <CheckCircle2 className="w-5 h-5 text-theme-accent" />
                      ) : (
                        <Circle className="w-5 h-5 text-theme-muted" />
                      )}
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="flex gap-4">
              <button 
                onClick={() => setIsAdding(false)}
                className="flex-1 py-4 bg-theme-app text-theme-muted font-black rounded-2xl border border-theme-border-soft hover:text-theme-primary transition-colors"
              >
                Cancel
              </button>
              <button 
                onClick={handleSave}
                disabled={!name.trim()}
                className="flex-1 py-4 bg-[image:var(--accent-gradient)] text-white font-black rounded-2xl shadow-premium disabled:opacity-50 disabled:cursor-not-allowed transition-all"
              >
                Save Workspace
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
    </AnimatedPage>
  );
};

export default WorkspaceManager;

import React, { useState, useEffect, memo } from 'react';
import { motion } from 'framer-motion';
import { 
  Users, CreditCard, Activity, Crown, Cloud, IndianRupee, 
  ShieldAlert, CheckCircle2, TrendingUp, AlertTriangle, Layers, Building2, 
  UserPlus, FileWarning 
} from 'lucide-react';
import { adminEngine } from '../../services/adminEngine';
import { pageVariants } from '../../utils/animations';
import { KPISkeleton } from '../../components/PremiumSkeleton';

const AdminDashboard = () => {
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({
    totalUsers: 0, activeUsers: 0, premiumUsers: 0, freeUsers: 0, todayNewUsers: 0,
    totalWorkspaces: 0, activeWorkspaces: 0,
    monthlyRevenue: 0, pendingPayments: 0, pendingPaymentProofs: 0,
    failedSyncs: 0, cloudStorageUsage: '0 GB',
    systemHealth: 'Healthy',
    totalInvoices: 0, totalCustomers: 0, totalProducts: 0
  });
  const [recentActivities, setRecentActivities] = useState([]);

  useEffect(() => {
    const fetchStats = async () => {
      try {
        const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), 15000));

        // Wrap with timeout to ensure it doesn't hang
        const results = await Promise.race([
          Promise.all([
            adminEngine.getUsersList().catch(() => []),
            adminEngine.getPaymentProofs().catch(() => []),
            adminEngine.getRevenueStates().catch(() => []),
            adminEngine.getTotalStats().catch(() => ({ invoices: 0, customers: 0, products: 0 }))
          ]),
          timeoutPromise
        ]).catch(() => [[], [], [], { invoices: 0, customers: 0, products: 0 }]); // Fallback if timeout

        const [users, proofs, revs, extraStats] = results;

        const totalUsers = users.length;
        const premiumUsers = users.filter(u => u.planStatus === 'premium').length;
        const freeUsers = totalUsers - premiumUsers;

        let totalWorkspaces = 0;
        users.forEach(u => { totalWorkspaces += (u.workspacesCount || 1); });

        const activeWorkspaces = users.filter(u => !u.blocked).length || Math.floor(totalWorkspaces * 0.85);
        const activeUsers = users.filter(u => !u.blocked).length || Math.floor(totalUsers * 0.75);

        const today = new Date().toISOString().split('T')[0];
        const todayNewUsers = users.filter(u => (u.createdAt || '').startsWith(today)).length;

        const pendingPaymentProofs = proofs.filter(p => p.status === 'Pending').length;
        const pendingPayments = proofs.filter(p => p.status === 'Pending').reduce((acc, p) => acc + (parseFloat(p.amount) || 0), 0);

        const monthlyRevenue = revs.reduce((acc, r) => acc + (parseFloat(r.platformPaidAmount) || 0), 0);

        const activities = [];

        const sortedUsers = [...users].sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0)).slice(0, 5);
        sortedUsers.forEach(u => {
          activities.push({
            id: `usr_${u.id}`,
            type: 'user',
            title: 'New user registered',
            desc: `User ${u.email} created an account.`,
            date: new Date(u.createdAt || Date.now()),
            icon: UserPlus,
            color: 'text-emerald-500 bg-emerald-500/10 border-emerald-500/20'
          });
        });

        const sortedProofs = [...proofs].sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0)).slice(0, 5);
        sortedProofs.forEach(p => {
          activities.push({
            id: `prf_${p.id}`,
            type: 'payment',
            title: 'Payment Proof Uploaded',
            desc: `₹${p.amount} pending verification for workspace ${p.workspaceId || 'Unknown'}.`,
            date: new Date(p.createdAt || Date.now()),
            icon: CreditCard,
            color: 'text-amber-500 bg-amber-500/10 border-amber-500/20'
          });
        });

        activities.sort((a, b) => b.date - a.date);
        setRecentActivities(activities.slice(0, 8));

        setStats({
          totalUsers, activeUsers, premiumUsers, freeUsers, todayNewUsers,
          totalWorkspaces, activeWorkspaces, monthlyRevenue, pendingPayments, pendingPaymentProofs,
          failedSyncs: 0,
          cloudStorageUsage: `${(totalWorkspaces * 0.05).toFixed(2)} GB`,
          systemHealth: navigator.onLine ? 'Healthy' : 'Offline',
          totalInvoices: extraStats.invoices,
          totalCustomers: extraStats.customers,
          totalProducts: extraStats.products
        });
      } catch (e) {
        console.error('Admin stat error:', e);
      } finally {
        setLoading(false);
      }
    };

    fetchStats();
  }, []);

  if (loading) {
    return (
      <div className="space-y-8">
        <div className="mb-6"><h2 className="text-2xl font-black text-theme-primary">Dashboard Overview</h2></div>
        <KPISkeleton count={12} />
      </div>
    );
  }

  const kpiCards = [
    { label: 'Total Users', value: stats.totalUsers, icon: Users, color: 'text-blue-500', bg: 'bg-blue-500/10', border: 'border-blue-500/20' },
    { label: 'Premium Users', value: stats.premiumUsers, icon: Crown, color: 'text-amber-500', bg: 'bg-amber-500/10', border: 'border-amber-500/20' },
    { label: "Today's New", value: stats.todayNewUsers, icon: TrendingUp, color: 'text-emerald-500', bg: 'bg-emerald-500/10', border: 'border-emerald-500/20' },
    { label: 'Workspaces', value: stats.totalWorkspaces, icon: Building2, color: 'text-indigo-500', bg: 'bg-indigo-500/10', border: 'border-indigo-500/20' },
    { label: 'Total Invoices', value: stats.totalInvoices || 0, icon: Layers, color: 'text-purple-500', bg: 'bg-purple-500/10', border: 'border-purple-500/20' },
    { label: 'Total Revenue', value: `₹${stats.monthlyRevenue}`, icon: IndianRupee, color: 'text-emerald-500', bg: 'bg-emerald-500/10', border: 'border-emerald-500/20' },
    { label: 'Pending Dues', value: `₹${stats.pendingPayments}`, icon: AlertTriangle, color: 'text-amber-500', bg: 'bg-amber-500/10', border: 'border-amber-500/20' },
    { label: 'Payment Proofs', value: stats.pendingPaymentProofs, icon: CreditCard, color: 'text-rose-500', bg: 'bg-rose-500/10', border: 'border-rose-500/20' },
    { label: 'Storage Usage', value: stats.cloudStorageUsage, icon: Cloud, color: 'text-cyan-500', bg: 'bg-cyan-500/10', border: 'border-cyan-500/20' },
