import React, { useState, useEffect, memo } from 'react';
import { motion } from 'framer-motion';
import { ToggleRight, AlertTriangle, Loader2 } from 'lucide-react';
import { toast } from 'react-hot-toast';
import { adminEngine } from '../../services/adminEngine';
import { Card, CardContent } from '../../components/ui/Card';
import { Switch } from '../../components/ui/Switch';

const FeatureSwitchCenter = () => {
  const [features, setFeatures] = useState({
    liveLink: true,
    paymentProof: true,
    pdfTemplates: true,
    multiWorkspace: true,
    premiumFeatures: true,
    reports: true,
    dueLedger: true,
    demoMode: false,
    customerPortal: true,
    studentPortal: true,
    offlineMode: true,
    qrCode: true
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchFeatures = async () => {
      try {
        const settings = await adminEngine.getGlobalSettings();
        if (settings && settings.features) {
          setFeatures(prev => ({ ...prev, ...settings.features }));
        }
      } catch (e) {
        console.error('Failed to load global features', e);
      } finally {
        setLoading(false);
      }
    };
    fetchFeatures();
  }, []);

  const handleToggle = async (key) => {
    const nextState = { ...features, [key]: !features[key] };
    setFeatures(nextState);
    toast.success(`Feature ${key} ${nextState[key] ? 'enabled' : 'disabled'}`);
    
    try {
      await adminEngine.updateGlobalSettings({ features: nextState });
    } catch {
      toast.error('Failed to sync global settings to cloud.');
    }
  };

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-6 pb-32">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-8">
        <div>
          <h2 className="text-3xl font-black text-theme-primary tracking-tight flex items-center">
            <ToggleRight className="w-8 h-8 mr-3 text-theme-accent" /> Feature Switch Center
          </h2>
          <p className="text-sm text-theme-secondary mt-1">Globally enable or disable platform features.</p>
        </div>
      </div>

      <Card className="bg-theme-danger/10 border-theme-danger/20 shadow-none">
        <CardContent className="p-4 flex items-start gap-4">
          <AlertTriangle className="w-5 h-5 text-theme-danger shrink-0 mt-0.5" />
          <div>
            <p className="text-theme-danger text-sm font-bold">Disabling a feature will hide it for all users immediately.</p>
            <p className="text-theme-danger/80 text-xs mt-1">Users will see a polite message: "This feature is temporarily disabled by the platform owner."</p>
          </div>
        </CardContent>
      </Card>

      <Card className="overflow-hidden">
        {loading ? (
          <CardContent className="flex justify-center p-12">
            <Loader2 className="w-8 h-8 animate-spin text-theme-accent" />
          </CardContent>
        ) : (
          <CardContent className="p-6">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {Object.entries(features).map(([key, value]) => (
                <div key={key} className="flex items-center justify-between p-4 bg-theme-surface-elevated border border-theme-border-soft rounded-xl hover:border-theme-accent/30 transition-colors">
                  <span className="text-sm font-bold text-theme-primary capitalize">{key.replace(/([A-Z])/g, ' $1').trim()}</span>
                  <Switch checked={value} onChange={() => handleToggle(key)} />
                </div>
              ))}
            </div>
          </CardContent>
        )}
      </Card>
    </motion.div>
  );
};

export default memo(FeatureSwitchCenter);

import React, { useState, useEffect } from 'react';
import { Settings as SettingsIcon, Globe, ShieldAlert, Zap, Sliders, CreditCard } from 'lucide-react';
import { motion } from 'framer-motion';
import { adminEngine } from '../../services/adminEngine';
import { toast } from 'react-hot-toast';
import { pageVariants } from '../../utils/animations';
import { CardSkeleton } from '../../components/PremiumSkeleton';
import { Switch } from '../../components/ui/Switch';
import { Button } from '../../components/ui/Button';

const GlobalSettings = () => {
  const [loading, setLoading] = useState(true);
  const [premiumModeEnabled, setPremiumModeEnabled] = useState(true);
  const [payPerBillEnabled, setPayPerBillEnabled] = useState(true);
  const [freeBillLimit, setFreeBillLimit] = useState(10);
  const [chargePerBill, setChargePerBill] = useState(5);
  const [percentageChargeSetting, setPercentageChargeSetting] = useState(0);
  const [monthlyGraceLimit, setMonthlyGraceLimit] = useState(5);
  const [maxPendingDue, setMaxPendingDue] = useState(100);
  const [maxUnpaidBillCount, setMaxUnpaidBillCount] = useState(20);
  const [lockBehavior, setLockBehavior] = useState('bill_creation');
  const [upiId, setUpiId] = useState('khairul2052007@okaxis');
  const [payeeName, setPayeeName] = useState('BillQyro Platform');
  const [defaultTheme, setDefaultTheme] = useState('obsidian-gold');
  const [defaultTemplate, setDefaultTemplate] = useState('standard');
  const [defaultCurrency, setDefaultCurrency] = useState('₹');

  useEffect(() => {
    const fetchSettings = async () => {
      try {
        const s = await adminEngine.getRevenueSettings();
        setPremiumModeEnabled(s.premiumModeEnabled ?? true);
        setPayPerBillEnabled(s.payPerBillEnabled ?? true);
        setFreeBillLimit(s.freeBillLimit ?? 10);
        setChargePerBill(s.chargePerBill ?? 5);
        setPercentageChargeSetting(s.percentageChargeSetting ?? 0);
        setMonthlyGraceLimit(s.monthlyGraceLimit ?? 5);
        setMaxPendingDue(s.maxPendingDue ?? 100);
        setMaxUnpaidBillCount(s.maxUnpaidBillCount ?? 20);
        setLockBehavior(s.lockBehavior ?? 'bill_creation');
        setUpiId(s.upiId || 'khairul2052007@okaxis');
        setPayeeName(s.payeeName || 'BillQyro Platform');
        setDefaultTheme(s.defaultTheme || 'obsidian-gold');
        setDefaultTemplate(s.defaultTemplate || 'standard');
        setDefaultCurrency(s.defaultCurrency || '₹');
      } catch {
        toast.error('Failed to load global revenue settings');
      } finally {
        setLoading(false);
      }
    };
    fetchSettings();
  }, []);

  const handleSave = async () => {
    if (!window.confirm('Are you sure you want to overwrite global revenue settings? This will affect all users.')) return;
    setLoading(true);
    const payload = {
      premiumModeEnabled,
      payPerBillEnabled,
      freeBillLimit: parseInt(freeBillLimit) || 10,
      chargePerBill: parseFloat(chargePerBill) || 5,
      percentageChargeSetting: parseFloat(percentageChargeSetting) || 0,
      monthlyGraceLimit: parseInt(monthlyGraceLimit) || 5,
      maxPendingDue: parseFloat(maxPendingDue) || 100,
      maxUnpaidBillCount: parseInt(maxUnpaidBillCount) || 20,
      lockBehavior,
      upiId,
      payeeName,
      defaultTheme,
      defaultTemplate,
      defaultCurrency
    };

    try {
      const success = await adminEngine.saveRevenueSettings(payload);
      if (success) {
        toast.success('Global revenue settings saved successfully!');
      } else {
        toast.error('Failed to save settings to Firestore.');
      }
    } catch (err) {
      console.error(err);
      toast.error('Error saving settings.');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <motion.div variants={pageVariants} initial="initial" animate="animate" className="space-y-6">
        <div className="section-header">
          <div>
            <h2 className="text-2xl font-black text-theme-primary flex items-center tracking-tight">
              <Sliders className="w-6 h-6 mr-3 text-theme-accent" /> Revenue Settings (Owner)
            </h2>
            <p className="section-header-subtitle">Loading configuration...</p>
          </div>
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <CardSkeleton lines={4} />
          <CardSkeleton lines={4} />
          <div className="lg:col-span-2">
            <CardSkeleton lines={6} />
          </div>
        </div>
      </motion.div>
    );
  }

  return (
    <motion.div 
      variants={pageVariants}
      initial="initial"
      animate="animate"
      className="space-y-6"
    >
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-8">
        <div>
          <h2 className="text-3xl font-black text-theme-primary flex items-center tracking-tight">
            <Sliders className="w-8 h-8 mr-3 text-theme-accent" /> Revenue Settings (Owner)
          </h2>
          <p className="text-sm text-theme-secondary mt-1">Configure global monetization parameters and limits.</p>
        </div>
        <Button 
          onClick={handleSave}
          disabled={loading}
          variant="primary"
          className="shadow-premium"
        >
          {loading ? 'Saving...' : 'Save Changes'}
        </Button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        
        {/* Core Settings */}
        <div className="bg-theme-surface-elevated p-6 rounded-2xl border border-theme-border-soft space-y-6">
          <div className="border-b border-theme-border-soft pb-4 mb-0">
            <h3 className="text-lg font-bold text-theme-primary flex items-center">
              <Globe className="w-5 h-5 mr-2 text-theme-accent" /> Monetization Modes
            </h3>
          </div>
          <div className="flex items-center justify-between">
            <span className="text-sm font-bold text-theme-secondary">Enable Premium Subscriptions</span>
            <Switch checked={premiumModeEnabled} onChange={(checked) => setPremiumModeEnabled(checked)} />
          </div>
          <div className="flex items-center justify-between">
            <span className="text-sm font-bold text-theme-secondary">Enable Pay-Per-Bill Model</span>
            <Switch checked={payPerBillEnabled} onChange={(checked) => setPayPerBillEnabled(checked)} />
          </div>
        </div>

        {/* UPI Payments */}
        <div className="bg-theme-surface-elevated p-6 rounded-2xl border border-theme-border-soft space-y-5">
          <div className="border-b border-theme-border-soft pb-4 mb-0">
            <h3 className="text-lg font-bold text-theme-primary flex items-center">
              <CreditCard className="w-5 h-5 mr-2 text-theme-accent" /> UPI Payment Details
            </h3>
          </div>
          <div>
            <label className="block text-[10px] font-black text-theme-muted uppercase tracking-wider mb-2">Platform UPI ID</label>
            <input 
              type="text"
              value={upiId}
              onChange={(e) => setUpiId(e.target.value)}
              className="w-full bg-theme-app text-theme-primary border border-theme-border-soft rounded-xl px-4 py-3 focus:outline-none focus:border-theme-accent focus:ring-1 focus:ring-theme-accent transition-all font-mono text-sm"
            />
          </div>
          <div>
            <label className="block text-[10px] font-black text-theme-muted uppercase tracking-wider mb-2">Payee Name</label>
            <input 
              type="text"
              value={payeeName}
              onChange={(e) => setPayeeName(e.target.value)}
              className="w-full bg-theme-app text-theme-primary border border-theme-border-soft rounded-xl px-4 py-3 focus:outline-none focus:border-theme-accent focus:ring-1 focus:ring-theme-accent transition-all text-sm"
            />
          </div>
        </div>

        {/* Business Limits */}
        <div className="bg-theme-surface-elevated p-6 rounded-2xl border border-theme-border-soft lg:col-span-2 space-y-6">
          <div className="border-b border-theme-border-soft pb-4 mb-0">
            <h3 className="text-lg font-bold text-theme-primary flex items-center">
              <Zap className="w-5 h-5 mr-2 text-theme-warning" /> Pricing & Lock Parameters
            </h3>
          </div>
          
          <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
            <div>
              <label className="block text-[10px] font-black text-theme-muted uppercase tracking-wider mb-2">Free Bill Limit</label>
              <input 
                type="number" 
                value={freeBillLimit}
                onChange={(e) => setFreeBillLimit(e.target.value)}
                className="w-full bg-theme-app text-theme-primary border border-theme-border-soft rounded-xl px-4 py-3 focus:outline-none focus:border-theme-warning focus:ring-1 focus:ring-theme-warning transition-all text-sm"
              />
            </div>
            
            <div>
              <label className="block text-[10px] font-black text-theme-muted uppercase tracking-wider mb-2">Flat Charge Per Bill (₹)</label>
              <input 
                type="number" 
                value={chargePerBill}
                onChange={(e) => setChargePerBill(e.target.value)}
                className="w-full bg-theme-app text-theme-primary border border-theme-border-soft rounded-xl px-4 py-3 focus:outline-none focus:border-theme-warning focus:ring-1 focus:ring-theme-warning transition-all text-sm"
              />
            </div>

            <div>
              <label className="block text-[10px] font-black text-theme-muted uppercase tracking-wider mb-2">Percentage Charge (%)</label>
              <input 
                type="number" 
                value={percentageChargeSetting}
                onChange={(e) => setPercentageChargeSetting(e.target.value)}
                placeholder="e.g. 1% of bill value"
                className="w-full bg-theme-app text-theme-primary border border-theme-border-soft rounded-xl px-4 py-3 focus:outline-none focus:border-theme-warning focus:ring-1 focus:ring-theme-warning transition-all text-sm"
              />
            </div>

            <div>
              <label className="block text-[10px] font-black text-theme-muted uppercase tracking-wider mb-2">Grace Bills Count</label>
              <input 
                type="number" 
                value={monthlyGraceLimit}
                onChange={(e) => setMonthlyGraceLimit(e.target.value)}
                className="w-full bg-theme-app text-theme-primary border border-theme-border-soft rounded-xl px-4 py-3 focus:outline-none focus:border-theme-warning focus:ring-1 focus:ring-theme-warning transition-all text-sm"
              />
            </div>

            <div>
              <label className="block text-[10px] font-black text-theme-muted uppercase tracking-wider mb-2">Max Pending Dues (₹)</label>
              <input 
                type="number" 
                value={maxPendingDue}
                onChange={(e) => setMaxPendingDue(e.target.value)}
                className="w-full bg-theme-app text-theme-primary border border-theme-border-soft rounded-xl px-4 py-3 focus:outline-none focus:border-theme-warning focus:ring-1 focus:ring-theme-warning transition-all text-sm"
              />
            </div>

            <div>
              <label className="block text-[10px] font-black text-theme-muted uppercase tracking-wider mb-2">Max Unpaid Bills Count</label>
              <input 
                type="number" 
                value={maxUnpaidBillCount}
                onChange={(e) => setMaxUnpaidBillCount(e.target.value)}
                className="w-full bg-theme-app text-theme-primary border border-theme-border-soft rounded-xl px-4 py-3 focus:outline-none focus:border-theme-warning focus:ring-1 focus:ring-theme-warning transition-all text-sm"
              />
            </div>
          </div>

          <div className="pt-2">
            <label className="block text-[10px] font-black text-theme-muted uppercase tracking-wider mb-2">Lock Behavior After Limit Exceeded</label>
            <select
              value={lockBehavior}
              onChange={(e) => setLockBehavior(e.target.value)}
              className="w-full bg-theme-app text-theme-primary border border-theme-border-soft rounded-xl px-4 py-3 focus:outline-none focus:border-theme-warning focus:ring-1 focus:ring-theme-warning cursor-pointer text-sm"
            >
              <option value="bill_creation">Lock New Bill Creation Only</option>
              <option value="none">No Lock (Warning Only)</option>
            </select>
          </div>
        </div>

        {/* Platform Defaults */}
        <div className="bg-theme-surface-elevated p-6 rounded-2xl border border-theme-border-soft lg:col-span-2 space-y-6">
          <div className="border-b border-theme-border-soft pb-4 mb-0">
            <h3 className="text-lg font-bold text-theme-primary flex items-center">
              <SettingsIcon className="w-5 h-5 mr-2 text-theme-accent" /> Platform Defaults (New Users)
            </h3>
          </div>
          
          <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
            <div>
              <label className="block text-[10px] font-black text-theme-muted uppercase tracking-wider mb-2">Default Theme</label>
              <select
                value={defaultTheme}
                onChange={(e) => setDefaultTheme(e.target.value)}
                className="w-full bg-theme-app text-theme-primary border border-theme-border-soft rounded-xl px-4 py-3 focus:outline-none focus:border-theme-accent focus:ring-1 focus:ring-theme-accent cursor-pointer text-sm font-bold"
              >
                <option value="obsidian-gold">Obsidian Gold (Luxury)</option>
                <option value="arctic-teal">Arctic Teal (Corporate)</option>
                <option value="rose-gold">Rose Gold (Premium)</option>
                <option value="neon-cyber">Neon Cyber (Modern)</option>
              </select>
            </div>
            
            <div>
              <label className="block text-[10px] font-black text-theme-muted uppercase tracking-wider mb-2">Default Template</label>
              <select
                value={defaultTemplate}
                onChange={(e) => setDefaultTemplate(e.target.value)}
                className="w-full bg-theme-app text-theme-primary border border-theme-border-soft rounded-xl px-4 py-3 focus:outline-none focus:border-theme-accent focus:ring-1 focus:ring-theme-accent cursor-pointer text-sm font-bold"
              >
                <option value="standard">Standard Professional</option>
                <option value="modern">Modern Minimal</option>
                <option value="classic">Classic Corporate</option>
                <option value="elegant">Elegant Serif</option>
              </select>
            </div>

            <div>
              <label className="block text-[10px] font-black text-theme-muted uppercase tracking-wider mb-2">Default Currency Symbol</label>
              <input 
                type="text" 
                value={defaultCurrency}
                onChange={(e) => setDefaultCurrency(e.target.value)}
                placeholder="e.g. ₹, $, €"
                className="w-full bg-theme-app text-theme-primary border border-theme-border-soft rounded-xl px-4 py-3 focus:outline-none focus:border-theme-accent focus:ring-1 focus:ring-theme-accent transition-all text-sm font-numbers"
              />
            </div>
          </div>
        </div>

        {/* Info Control */}
        <div className="bg-theme-danger/5 border border-theme-danger/20 rounded-2xl p-6 lg:col-span-2 flex items-start space-x-4">
          <ShieldAlert className="w-6 h-6 text-theme-danger shrink-0 mt-0.5" />
          <div>
            <h4 className="text-theme-danger font-bold text-sm">Security & Enforcement Note</h4>
            <p className="text-theme-secondary text-xs mt-1 leading-relaxed">
              When lock enforcement is active, users exceeding their free bill limit, unpaid count, or max dues threshold will be restricted from saving new invoices. However, login, existing invoice viewing, downloads, and backups will remain fully operational.
            </p>
          </div>
        </div>

      </div>
    </motion.div>
  );
};

export default GlobalSettings;

import React, { useState, useEffect } from 'react';
import { Beaker, Users, FileText, RefreshCw, Loader, AlertTriangle, Trash2, Video, BarChart2, CheckCircle2, Play, ArrowLeft, Power, Box, ArrowRight, Eye, ShieldCheck, XCircle } from 'lucide-react';
import { toast } from 'react-hot-toast';
import { motion } from 'framer-motion';
import { generateSmartDemoData } from '../../utils/demoDataGenerator';
import { clearDemoData, generateFakeAdminData } from '../../utils/demoDataManager';

const OwnerTestLab = () => {
  const [isGenerating, setIsGenerating] = useState('');
  const [stats, setStats] = useState({
    customers: 0, invoices: 0, products: 0, reports: false, persona: 'None', videoCreator: false
  });
  const [demoActive, setDemoActive] = useState(false);
  const [demoPayments, setDemoPayments] = useState([]);
  const [adminSimActive, setAdminSimActive] = useState(false);

  const loadStats = () => {
    const customers = JSON.parse(localStorage.getItem('billqyro_demo_customers') || '[]');
    const invoices = JSON.parse(localStorage.getItem('billqyro_demo_invoices') || '[]');
    const products = JSON.parse(localStorage.getItem('billqyro_demo_products') || '[]');
    const reports = localStorage.getItem('billqyro_demo_reports') !== null;
    const persona = localStorage.getItem('billqyro_demo_session_persona') || 'None';
    const isActive = localStorage.getItem('billqyro_demo_session_active') === 'true';
    const videoCreator = localStorage.getItem('billqyro_demo_video_creator') === 'true';
    const payments = JSON.parse(localStorage.getItem('billqyro_demo_payments') || '[]');
    const adminData = localStorage.getItem('billqyro_demo_admin_data');

    setStats({ customers: customers.length, invoices: invoices.length, products: products.length, reports, persona, videoCreator });
    setDemoActive(isActive);
    setDemoPayments(payments);
    setAdminSimActive(!!adminData);
  };

  useEffect(() => {
    loadStats();
    const handleStorageChange = () => loadStats();
    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, []);

  const generateDemoData = async () => {
    setIsGenerating('all');
    await new Promise(resolve => setTimeout(resolve, 800));
    const { products, customers, invoices, payments } = generateSmartDemoData(stats.persona);
    localStorage.setItem('billqyro_demo_products', JSON.stringify(products));
    localStorage.setItem('billqyro_demo_customers', JSON.stringify(customers));
    localStorage.setItem('billqyro_demo_invoices', JSON.stringify(invoices));
    localStorage.setItem('billqyro_demo_payments', JSON.stringify(payments));

    let totalSales = 0, pendingDue = 0, paidAmount = 0;
    invoices.forEach(inv => { totalSales += inv.grandTotal; paidAmount += inv.amountPaid; pendingDue += inv.balanceDue; });
    const reportsPayload = { totalSales, pendingDue, paidAmount, customerCount: customers.length, invoiceCount: invoices.length, generatedAt: new Date().toISOString() };
    localStorage.setItem('billqyro_demo_reports', JSON.stringify(reportsPayload));

    loadStats();
    toast.success(`Complete realistic ${stats.persona} sandbox generated!`, { icon: '🧪' });
    setIsGenerating('');
  };

  const setPersona = (personaName) => {
    localStorage.setItem('billqyro_demo_session_persona', personaName);
    loadStats();
    toast.success(`${personaName} demo mode activated!`, { icon: '✨' });
  };

  const toggleVideoCreatorMode = () => {
    if (stats.videoCreator) {
      localStorage.removeItem('billqyro_demo_video_creator');
      toast.success('Video Creator Mode disabled.');
    } else {
      localStorage.setItem('billqyro_demo_video_creator', 'true');
      toast.success('Video Creator Mode enabled.', { icon: '🎥' });
    }
    loadStats();
  };

  const clearTestData = () => {
    if (window.confirm("Delete all demo sandbox data?")) {
      clearDemoData();
      localStorage.removeItem('billqyro_demo_session_persona');
      localStorage.removeItem('billqyro_demo_session_active');
      localStorage.removeItem('billqyro_demo_video_creator');
      loadStats();
      toast.success('Demo sandbox cleared.', { icon: '🧹' });
    }
  };

  const toggleDemoSession = () => {
    if (demoActive) {
      localStorage.removeItem('billqyro_demo_session_active');
      setDemoActive(false);
      toast.success('Demo session ended. Real data restored.', { icon: '🔒' });
    } else {
      localStorage.setItem('billqyro_demo_session_active', 'true');
      setDemoActive(true);
      toast.success('Demo session started. Real data hidden.', { icon: '🎬' });
    }
    window.dispatchEvent(new Event('storage'));
  };

  const startDemoJourney = () => {
    if (window.confirm("Start Full Demo Journey?")) {
      clearDemoData();
      localStorage.removeItem('billqyro_demo_settings');
      localStorage.removeItem('billqyro_demo_logged_in');
      localStorage.setItem('billqyro_demo_session_active', 'true');
      localStorage.setItem('billqyro_demo_journey_mode', 'true');
      toast.success('Starting Full Demo Journey...', { icon: '🚀' });
      window.location.href = '/';
    }
  };

  const handleAdminPanelSimulator = () => {
    if (adminSimActive) {
      localStorage.removeItem('billqyro_demo_admin_data');
      toast.success('Admin Panel Simulator Cleared');
      setAdminSimActive(false);
    } else {
      generateFakeAdminData();
      toast.success('Fake Admin Data Generated! See Dashboard.');
      setAdminSimActive(true);
    }
  };

  const personas = [
    { name: 'Doctor', icon: '🩺', color: 'bg-blue-500/10 text-blue-400 border-blue-500/20 hover:bg-blue-500/20' },
    { name: 'Teacher', icon: '📚', color: 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20 hover:bg-emerald-500/20' },
    { name: 'Embroidery', icon: '🧵', color: 'bg-purple-500/10 text-purple-400 border-purple-500/20 hover:bg-purple-500/20' },
    { name: 'Retail', icon: '🏪', color: 'bg-amber-500/10 text-amber-400 border-amber-500/20 hover:bg-amber-500/20' },
  ];

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-8 pb-10 max-w-[1200px] mx-auto">
      <div>
        <h2 className="text-3xl font-black text-theme-primary tracking-tight flex items-center gap-3">
          <div className="w-12 h-12 rounded-xl bg-theme-danger/10 text-theme-danger flex items-center justify-center border border-theme-danger/20 shadow-glass">
            <Beaker className="w-6 h-6" />
          </div>
          Premium Test Lab
        </h2>
        <p className="text-theme-secondary text-sm mt-2">Generate sandbox data, mock live links, and manage Demo Sessions safely with zero impact on production data.</p>
      </div>

      <div className="glass-panel border-theme-danger/30 bg-theme-danger/5 p-4 rounded-xl flex items-start gap-4">
        <div className="p-2 bg-theme-danger/20 rounded-lg shrink-0">
          <AlertTriangle className="w-5 h-5 text-theme-danger" />
        </div>
        <div>
          <h3 className="text-theme-danger font-black mb-1">Strict Isolation Enabled</h3>
          <p className="text-theme-danger/80 text-xs font-semibold">
            Everything modified here stays in temporary local memory. Production Firestore writes are fully disabled during demo mode.
          </p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

        {/* Step 1: Persona */}
        <div className="glass-panel p-6">
          <div className="glass-content">
            <h3 className="text-theme-primary font-black text-lg flex items-center mb-4">
              <span className="w-6 h-6 rounded-full bg-theme-accent/20 text-theme-accent text-xs flex items-center justify-center mr-2">1</span> Choose Demo Persona
            </h3>
            <div className="grid grid-cols-2 gap-3">
              {personas.map(persona => (
                <button 
                  key={persona.name} 
                  onClick={() => setPersona(persona.name)}
                  className={`flex items-center p-3 rounded-xl border transition-all ${
                    stats.persona === persona.name 
                      ? 'bg-theme-accent text-white border-theme-accent shadow-premium-sm scale-105' 
                      : `${persona.color}`
                  }`}
                >
                  <span className="text-xl mr-2">{persona.icon}</span>
                  <span className="font-bold text-xs">{persona.name}</span>
                  {stats.persona === persona.name && <CheckCircle2 className="w-3 h-3 ml-auto" />}
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Step 2: Generation */}
        <div className="glass-panel p-6">
          <div className="glass-content flex flex-col h-full">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-theme-primary font-black text-lg flex items-center">
                <span className="w-6 h-6 rounded-full bg-theme-accent/20 text-theme-accent text-xs flex items-center justify-center mr-2">2</span> Generate Sandbox Data
              </h3>
              <span className="bg-theme-success/10 text-theme-success border border-theme-success/20 px-2 py-1 rounded-full text-[10px] font-black">
                {stats.customers} Cust / {stats.invoices} Inv
              </span>
            </div>
            <p className="text-xs text-theme-secondary mb-4 flex-1">
              Instantly create realistic fake customers, products, and invoices to preview the dashboard exactly how users see it.
            </p>
            <button onClick={generateDemoData} disabled={isGenerating !== ''} className="btn-premium w-full text-sm">
              {isGenerating === 'all' ? <Loader className="w-4 h-4 animate-spin" /> : <><RefreshCw className="w-4 h-4" /> Generate Mock Dataset</>}
            </button>
          </div>
        </div>

        {/* Admin Panel Simulator */}
        <div className="glass-panel p-6">
          <div className="glass-content">
            <h3 className="text-theme-primary font-black text-lg flex items-center mb-4">
              <span className="w-6 h-6 rounded-full bg-theme-accent/20 text-theme-accent text-xs flex items-center justify-center mr-2">3</span> Admin Simulator
            </h3>
            <p className="text-xs text-theme-secondary mb-4">
              Generate fake users, massive revenue figures, and cloud sync logs to make the Admin Dashboard look busy.
            </p>
            <button onClick={handleAdminPanelSimulator} className={`w-full text-sm font-bold flex items-center justify-center gap-2 py-3 rounded-xl transition-all border ${adminSimActive ? 'bg-theme-danger/10 text-theme-danger border-theme-danger/30 hover:bg-theme-danger/20' : 'bg-theme-accent/10 text-theme-accent border-theme-accent/30 hover:bg-theme-accent/20'}`}>
              <BarChart2 className="w-4 h-4" /> {adminSimActive ? 'Clear Fake Admin Data' : 'Generate Fake Admin Stats'}
            </button>
            {adminSimActive && (
              <div className="mt-4 p-3 bg-theme-success/10 border border-theme-success/20 rounded-lg text-theme-success text-xs font-bold flex items-center">
                <CheckCircle2 className="w-4 h-4 mr-2" /> Admin metrics injected. Check Dashboard.
              </div>
            )}
          </div>
        </div>

        {/* Video Creator Mode */}
        <div className="glass-panel p-6">
          <div className="glass-content">
            <h3 className="text-theme-primary font-black text-lg flex items-center mb-4">
               <span className="w-6 h-6 rounded-full bg-theme-accent/20 text-theme-accent text-xs flex items-center justify-center mr-2">4</span> Video Creator Mode
            </h3>
            <p className="text-xs text-theme-secondary mb-4">
              Mask sensitive emails, phone numbers, and keys for recording demo videos or YouTube tutorials.
            </p>
            <button onClick={toggleVideoCreatorMode} className={`w-full text-sm font-bold flex items-center justify-center gap-2 py-3 rounded-xl transition-all border ${stats.videoCreator ? 'bg-theme-success text-white shadow-premium-sm border-theme-success/50' : 'bg-theme-surface-hover text-theme-primary border-theme-border-soft'}`}>
              <Video className="w-4 h-4" /> {stats.videoCreator ? 'Creator Mode Active' : 'Enable Creator Mode'}
            </button>
          </div>
        </div>

        {/* Clear Data */}
        <div className="glass-panel p-6 md:col-span-2 border-theme-danger/20 bg-theme-danger/5">
          <div className="glass-content flex flex-col md:flex-row items-center justify-between gap-4">
            <div>
              <h3 className="text-theme-danger font-black text-lg mb-1">Clear Sandbox Environment</h3>
              <p className="text-theme-danger/70 text-xs font-semibold">Deletes all fake data, payments, and generated reports from local memory.</p>
            </div>
            <button onClick={clearTestData} className="whitespace-nowrap bg-theme-danger text-white px-6 py-3 rounded-xl text-sm font-bold flex items-center justify-center gap-2 hover:bg-theme-danger/90 transition-all hover:-translate-y-[1px] shadow-lg shadow-theme-danger/30">
              <Trash2 className="w-4 h-4" /> Clear All Sandbox Data
            </button>
          </div>
        </div>

      </div>
    </motion.div>
  );
};

export default OwnerTestLab;

import React, { useState, useEffect, memo } from 'react';
import { CreditCard, CheckCircle, XCircle, Clock, ShieldCheck, Image as ImageIcon, Search, Loader2 } from 'lucide-react';
import { motion } from 'framer-motion';
import { adminEngine } from '../../services/adminEngine';
import { toast } from 'react-hot-toast';
import { Card, CardContent } from '../../components/ui/Card';
import { Badge } from '../../components/ui/Badge';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Modal } from '../../components/ui/Modal';

const PaymentProofCenter = () => {
  const [proofs, setProofs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('Pending');
  const [selectedProof, setSelectedProof] = useState(null);
  const [adminNotes, setAdminNotes] = useState({});
  const [processingId, setProcessingId] = useState(null);

  const fetchProofs = async () => {
    try {
      const [dues, premium] = await Promise.all([
        adminEngine.getPaymentProofs(),
        adminEngine.getPremiumRequests()
      ]);
      const mappedDues = dues.map(p => ({ ...p, proofType: 'Dues' }));
      const mappedPremium = premium.map(p => ({ ...p, proofType: 'Premium', amount: p.paidAmount || p.amount || 0 }));
      const allProofs = [...mappedDues, ...mappedPremium].sort((a,b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0));
      setProofs(allProofs);
    } catch (e) {
      console.error(e);
      toast.error('Failed to load payment proofs.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProofs();
  }, []);

  const getAdminNote = (proofId) => adminNotes[proofId] || '';
  const setAdminNoteFor = (proofId, value) => setAdminNotes(prev => ({ ...prev, [proofId]: value }));

  const handleAction = async (proof, status) => {
    setProcessingId(proof.id);
    const note = getAdminNote(proof.id);
    try {
      let success = false;
      if (proof.proofType === 'Premium') {
        success = await adminEngine.updatePremiumRequestStatus(proof.id, status, proof.userId, proof.plan, note);
      } else {
        success = await adminEngine.updatePaymentProofStatus(proof.id, status, note, []);
      }
      if (success !== false) { // updatePremiumRequestStatus doesn't return boolean on success, it throws on error, but returns undefined.
        toast.success(`${proof.proofType} proof successfully ${status.toLowerCase()}!`);
        setSelectedProof(null);
        setAdminNotes(prev => { const n = { ...prev }; delete n[proof.id]; return n; });
        fetchProofs();
      } else {
        toast.error('Failed to update payment proof status.');
      }
    } catch (e) {
      console.error(e);
      toast.error(e.message || 'Error processing proof status.');
    } finally {
      setProcessingId(null);
    }
  };

  const pendingCount = proofs.filter(p => p.status === 'Pending').length;
  const verifiedCount = proofs.filter(p => p.status === 'Approved' || p.status === 'Verified').length;
  const rejectedCount = proofs.filter(p => p.status === 'Rejected').length;

  const filteredProofs = proofs.filter(p => {
    const term = searchTerm.toLowerCase();
    const matchesSearch = 
      ((p.userEmail || '').toLowerCase().includes(term)) ||
      ((p.transactionId || '').toLowerCase().includes(term)) ||
      ((p.note || '').toLowerCase().includes(term));
    
    if (statusFilter === 'all') return matchesSearch;
    if (statusFilter === 'Verified') return (p.status === 'Approved' || p.status === 'Verified') && matchesSearch;
    return p.status === statusFilter && matchesSearch;
  });

  if (loading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <Loader2 className="w-8 h-8 text-theme-accent animate-spin" />
      </div>
    );
  }

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-6 pb-32">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
        <div>
          <h2 className="text-3xl font-black text-theme-primary tracking-tight flex items-center">
            <CreditCard className="w-8 h-8 mr-3 text-theme-accent" /> Payment Center
          </h2>
          <p className="text-sm text-theme-secondary mt-1">Review and verify user platform dues payments.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <Card className="overflow-hidden relative">
          <div className="absolute top-0 left-0 right-0 h-1 bg-theme-warning"></div>
          <CardContent className="p-6 flex flex-col items-center justify-center text-center pt-8">
            <Clock className="w-6 h-6 text-theme-warning mb-2" />
            <div className="text-theme-secondary text-sm font-bold mb-1">Pending Review</div>
            <div className="text-3xl font-black text-theme-primary">{pendingCount}</div>
          </CardContent>
        </Card>
        <Card className="overflow-hidden relative">
          <div className="absolute top-0 left-0 right-0 h-1 bg-theme-success"></div>
          <CardContent className="p-6 flex flex-col items-center justify-center text-center pt-8">
            <CheckCircle className="w-6 h-6 text-theme-success mb-2" />
            <div className="text-theme-secondary text-sm font-bold mb-1">Verified Proofs</div>
            <div className="text-3xl font-black text-theme-primary">{verifiedCount}</div>
          </CardContent>
        </Card>
        <Card className="overflow-hidden relative">
          <div className="absolute top-0 left-0 right-0 h-1 bg-theme-danger"></div>
          <CardContent className="p-6 flex flex-col items-center justify-center text-center pt-8">
            <XCircle className="w-6 h-6 text-theme-danger mb-2" />
            <div className="text-theme-secondary text-sm font-bold mb-1">Rejected Proofs</div>
            <div className="text-3xl font-black text-theme-primary">{rejectedCount}</div>
          </CardContent>
        </Card>
      </div>
      
      <div className="flex flex-col md:flex-row items-center justify-between gap-4 mt-8 mb-4">
        <div className="flex gap-2">
          {['Pending', 'Verified', 'Rejected', 'all'].map((filter) => (
            <Button
              key={filter}
              variant={statusFilter === filter ? 'primary' : 'ghost'}
              onClick={() => setStatusFilter(filter)}
              className={statusFilter === filter ? 'shadow-glass' : ''}
              size="sm"
            >
              {filter === 'all' ? 'All Proofs' : filter}
            </Button>
          ))}
        </div>
        
        <div className="w-full md:w-auto">
          <Input 
            icon={Search}
            type="text" 
            placeholder="Search email or UTR..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full md:w-64"
          />
        </div>
      </div>

      {filteredProofs.length === 0 ? (
        <Card className="p-12 text-center shadow-glass border-transparent">
          <div className="w-20 h-20 bg-theme-accent/10 rounded-full flex items-center justify-center mx-auto mb-6">
            <ShieldCheck className="w-10 h-10 text-theme-accent" />
          </div>
          <h3 className="text-xl font-bold text-theme-primary mb-2">Queue is Clear</h3>
          <p className="text-theme-secondary text-sm max-w-md mx-auto font-semibold">
            No payment proofs match your active filters.
          </p>
        </Card>
      ) : (
        <div className="space-y-4">
          {filteredProofs.map((proof) => (
            <Card key={proof.id} className="overflow-hidden flex flex-col md:flex-row border-transparent">
              <div className="md:w-64 h-48 md:h-auto bg-theme-surface-hover flex flex-col items-center justify-center border-r border-theme-border-soft p-4 shrink-0">
                {proof.screenshotBase64 ? (
                  <img 
                    src={proof.screenshotBase64} 
                    alt="Payment Proof" 
                    onClick={() => setSelectedProof(proof)}
                    className="w-full h-full object-contain cursor-pointer rounded-lg hover:scale-[1.02] transition-transform" 
                  />
                ) : (
                  <div className="flex flex-col items-center">
                    <ImageIcon className="w-12 h-12 text-theme-muted mb-2" />
                    <span className="text-xs text-theme-secondary font-bold tracking-widest uppercase">No Screenshot</span>
                  </div>
                )}
              </div>
              
              <div className="p-6 flex-1 flex flex-col justify-between bg-theme-surface-elevated">
                <div className="flex flex-col md:flex-row justify-between items-start gap-4 mb-4">
                  <div>
                    <div className="flex items-center gap-2 mb-1">
                      <Badge variant={proof.proofType === 'Premium' ? 'primary' : 'warning'} className="text-[9px] uppercase tracking-wider">
                        {proof.proofType} {proof.proofType === 'Premium' ? `(${proof.plan})` : ''}
                      </Badge>
                    </div>
                    <h4 className="text-theme-primary font-extrabold text-xl font-mono">₹{proof.amount?.toFixed(2) || proof.amount}</h4>
                    <p className="text-theme-primary text-sm font-semibold mt-1">User: {proof.userEmail || proof.userId}</p>
                    <p className="text-theme-secondary text-xs font-mono mt-1 select-all bg-theme-main px-2.5 py-1 rounded-lg border border-theme-border-soft inline-block">
                      UTR: {proof.transactionId}
                    </p>
                    {proof.note && (
                      <p className="text-theme-secondary text-xs italic mt-3 bg-theme-main p-2.5 rounded-lg border border-theme-border-soft">
                        "{proof.note}"
                      </p>
                    )}
                    {proof.adminNote && (
                      <p className="text-theme-danger text-xs font-semibold mt-2">
                        Admin Note: {proof.adminNote}
                      </p>
                    )}
                  </div>
                  <div className="flex flex-col items-end">
                    <span className="text-[10px] font-bold text-theme-muted uppercase mb-1">Status</span>
                    <Badge variant={
                      proof.status === 'Approved' || proof.status === 'Verified' ? 'success' :
                      proof.status === 'Rejected' ? 'danger' : 'warning'
                    }>
                      {proof.status === 'Approved' ? 'Verified' : proof.status}
                    </Badge>
                  </div>
                </div>
                
                {proof.status === 'Pending' && (
                  <div className="space-y-4 pt-4 border-t border-theme-border-soft mt-4">
                    <Input 
                      type="text" 
                      placeholder="Add admin review comments or note..."
                      value={getAdminNote(proof.id)}
                      onChange={(e) => setAdminNoteFor(proof.id, e.target.value)}
                    />
                    <div className="flex gap-3">
                      <Button 
                        disabled={processingId === proof.id}
                        onClick={() => handleAction(proof, 'Approved')}
                        variant="primary"
                        className="flex-1 bg-theme-success border-theme-success"
                        leftIcon={processingId === proof.id ? Loader2 : CheckCircle}
                      >
                        Verify & Credit
                      </Button>
                      <Button 
                        disabled={processingId === proof.id}
                        onClick={() => handleAction(proof, 'Rejected')}
                        variant="outline"
                        className="flex-1 border-theme-danger text-theme-danger hover:bg-theme-danger/10"
                        leftIcon={processingId === proof.id ? Loader2 : XCircle}
                      >
                        Reject Proof
                      </Button>
                    </div>
                  </div>
                )}
              </div>
            </Card>
          ))}
        </div>
      )}

      <Modal isOpen={!!selectedProof} onClose={() => setSelectedProof(null)} title={`UTR: ${selectedProof?.transactionId}`} className="max-w-2xl bg-theme-main">
        {selectedProof && (
          <div className="p-4 overflow-y-auto flex-1 flex items-center justify-center bg-theme-surface">
            <img 
              src={selectedProof.screenshotBase64} 
              alt="Payment Proof Screenshot Large" 
              className="max-w-full max-h-[60vh] object-contain rounded-xl shadow-glass border border-theme-border-soft" 
            />
          </div>
        )}
      </Modal>
    </motion.div>
  );
};

