    setLoading(true);
    try {
      const snap = await getDocs(collection(db, 'subscriptionPlans'));
      const fetched = snap.docs.map(d => ({ id: d.id, ...d.data() }));
      setPlans(fetched.sort((a, b) => a.price - b.price));
