                  </div>
                ))
              ) : (
                <div className="text-center py-10 text-theme-muted font-bold text-xs">No active feature suggestions submitted yet.</div>
              )}
            </div>
          )}
        </CardContent>
      </Card>
    </motion.div>
  );
};

