export const logAudit = async (action, entityType, entityId, before = null, after = null) => {
  try {
    const user = getAuthSession() || { uid: 'anonymous', email: 'unknown' };
    let deviceInfo = 'Unknown Device';
    try {
      deviceInfo = navigator.userAgent;
