  get AUTH() { return GLOBAL_KEYS.AUTH; },
  get SETTINGS() { return getScopedKey(GLOBAL_KEYS.SETTINGS); },
  get CUSTOMERS() { return getScopedKey(GLOBAL_KEYS.CUSTOMERS); },
