  // Sync / queue + syncStatus tracking
  let firebaseStatus = 'pending';
  const stamped = customers.find(c => c.id === customer.id);
  updateLocalCache(KEYS.CUSTOMERS, customers);
  await BillQyroDB.put('customers', stamped);

