  logAudit,
  getAuthSession,
  getRealUserId
} from './dbEngine';
import { BillQyroDB } from './localDb';

const ROLES = {
  OWNER: 'owner',
  ADMIN: 'admin',
  USER: 'user',
  VIEWER: 'viewer'
};

export const securityEngine = {
  ROLES,

  async verifyWorkspace(userId, workspaceId) {
    if (!firebaseReady) return { verified: false, reason: 'offline' };
    try {
      const settingsRef = doc(db, 'settings', userId);
      const snap = await getDoc(settingsRef);
      if (!snap.exists()) return { verified: false, reason: 'no_settings' };
      const data = snap.data();
      const activeWs = data.activeWorkspaceId || 'default';
      return { verified: activeWs === workspaceId, workspace: activeWs };
    } catch (e) {
      return { verified: false, reason: e.message };
    }
  },

  async getUserRole(userId) {
    if (!firebaseReady) return ROLES.USER;
    try {
      const snap = await getDoc(doc(db, 'usersList', userId));
      if (snap.exists()) {
        return snap.data().role || ROLES.USER;
      }
      return ROLES.USER;
    } catch {
      return ROLES.USER;
    }
  },

  async setUserRole(userId, role) {
    if (!firebaseReady) return false;
    try {
      await setDoc(doc(db, 'usersList', userId), { role }, { merge: true });
      logAudit('role_changed', 'user', userId, null, { newRole: role });
      return true;
    } catch (e) {
      console.error('securityEngine.setUserRole error:', e);
      return false;
    }
  },

  async getPermissions(userId) {
    const role = await this.getUserRole(userId);
    const permissions = {
      canCreateInvoice: false,
      canEditInvoice: false,
      canDeleteInvoice: false,
      canManageCustomers: false,
      canManageProducts: false,
      canViewReports: false,
      canAccessAdmin: false,
      canManageUsers: false,
      canManageWorkspace: false
    };
    switch (role) {
      case ROLES.OWNER:
        Object.keys(permissions).forEach(k => { permissions[k] = true; });
        break;
      case ROLES.ADMIN:
        permissions.canCreateInvoice = true;
        permissions.canEditInvoice = true;
        permissions.canDeleteInvoice = true;
        permissions.canManageCustomers = true;
        permissions.canManageProducts = true;
        permissions.canViewReports = true;
        break;
      case ROLES.USER:
        permissions.canCreateInvoice = true;
        permissions.canEditInvoice = true;
        permissions.canManageCustomers = true;
        permissions.canManageProducts = true;
        permissions.canViewReports = true;
        break;
      case ROLES.VIEWER:
        permissions.canViewReports = true;
        break;
    }
    return permissions;
  },

  async validateSession(userId) {
    const session = getAuthSession();
    if (!session || !session.userEmail) return false;
    try {
      if (auth?.currentUser) {
        const token = await auth.currentUser.getIdTokenResult(true);
        return token.auth_time > 0;
      }
      const storedUid = getRealUserId();
      return storedUid === userId;
    } catch {
      return false;
    }
  },

  checkFirestoreRules() {
    return firebaseReady;
  },

  async getAuditLogs(userId = null) {
    try {
      let logs = await BillQyroDB.getAll('auditLogs');
      if (userId) logs = logs.filter(l => l.userId === userId);
      return logs.sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0));
    } catch {
      return [];
    }
  },

  async logSecurityEvent(action, entityType, entityId, before, after) {
    return logAudit(action, entityType, entityId, before, after);
  },

  isOwner(session) {
    const adminEmail = 'khairul2052007@gmail.com';
    if (!session) return false;
    const email = session.userEmail || session.email || '';
    return email.toLowerCase() === adminEmail.toLowerCase();
  }
};

// This engine abstracts Firebase Storage or Local IndexedDB blobs.

class StorageEngine {
  constructor() {
    // In-memory mock for local storage quota limits if used purely offline
    this.maxQuota = 100 * 1024 * 1024; // 100 MB
  }

  async uploadFile(workspaceId, path, fileBlob, metadata = {}) {
    console.log(`[StorageEngine] Uploading file to ${workspaceId}/${path}`);

    // Check quota before upload
    const currentUsage = await this.getStorageUsage(workspaceId);
    if (currentUsage + fileBlob.size > this.maxQuota) {
      throw new Error('Storage quota exceeded');
    }

    // Mock implementation for offline mode. 
    // In production, this uploads to Firebase Storage or saves to IndexedDB
    return new Promise((resolve) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        // Save base64 string to a mock map or local storage
        try {
          localStorage.setItem(`storage_${workspaceId}_${path}`, reader.result);
        } catch {
          console.warn('Local storage full');
        }
        resolve({
          url: reader.result,
          path: `${workspaceId}/${path}`,
          size: fileBlob.size
        });
      };
      reader.readAsDataURL(fileBlob);
    });
  }

  async downloadFile(workspaceId, path) {
    console.log(`[StorageEngine] Downloading file from ${workspaceId}/${path}`);
    return localStorage.getItem(`storage_${workspaceId}_${path}`);
  }

  async deleteFile(workspaceId, path) {
    console.log(`[StorageEngine] Deleting file from ${workspaceId}/${path}`);
    localStorage.removeItem(`storage_${workspaceId}_${path}`);
    return true;
  }

  async getStorageUsage(workspaceId) {
    // In production, query Firebase Storage metadata or IndexedDB size
    let totalSize = 0;
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key && key.startsWith(`storage_${workspaceId}_`)) {
        const item = localStorage.getItem(key);
        if (item) totalSize += item.length; // Approximate size
      }
    }
    return totalSize;
  }
}

export const storageEngine = new StorageEngine();

